        changed.isInverted = true
        let error = await installError(service, .spa)
        XCTAssertEqual(error, .damaged)
        await fulfillment(of: [changed], timeout: 0.5)
        await settle()
        XCTAssertEqual(status.state(of: .spa), .failed(.damaged))
        XCTAssertEqual(files(in: packsFolder), [older.lastPathComponent])
        let packs = await service.installedPacks()
        XCTAssertEqual(packs, [InstalledPack(id: .spa, lang: "spa", version: "0123456789ab", usable: true)])
        let found = try await db.search(query: "casa")
        XCTAssertTrue(found.contains { $0.source == "wordnet-spa-eng" }, "the older version is still searchable")
    }

    /// A cancelled update goes back to "Update available", the older
    /// version still attached.
    func testCancelledUpdateKeepsTheOlderVersion() async throws {
        let older = try plantOlderSpanish()
        let service = try await downloadingService(.slow)
        let update = Task { try await service.install(.spa) }
        try await waitUntil("the update to download") { isDownloading(.spa) }
        await service.cancel(.spa)
        do {
            try await update.value
            XCTFail("cancelled")
        } catch {
            XCTAssertEqual(error as? PackError, .cancelled)
        }
        await settle()
        XCTAssertEqual(status.state(of: .spa), .updateAvailable)
        XCTAssertEqual(files(in: packsFolder), [older.lastPathComponent])
        XCTAssertEqual(files(in: downloadsFolder), [])
        let found = try await db.search(query: "casa")
        XCTAssertTrue(found.contains { $0.source == "wordnet-spa-eng" })
    }

    /// A cancelled update of a file of another format goes back to "Update
    /// required": the file stays, unread, and the stub stays attached.
    func testCancelledUpdateOfAnotherFormatIsUpdateRequired() async throws {
        let file = try XCTUnwrap(try PackFixtures.install([.spa], into: packsFolder)[.spa])
        let handle = try FileHandle(forWritingTo: file)
        try handle.seek(toOffset: 60)
        try handle.write(contentsOf: Data([0, 0, 0, 3]))
        try handle.close()
        let service = try await downloadingService(.slow)
        let update = Task { try await service.install(.spa) }
        try await waitUntil("the update to download") { isDownloading(.spa) }
        await service.cancel(.spa)
        do {
            try await update.value
            XCTFail("cancelled")
        } catch {
            XCTAssertEqual(error as? PackError, .cancelled)
        }
        await settle()
        XCTAssertEqual(status.state(of: .spa), .updateRequired)
        XCTAssertEqual(files(in: packsFolder), [file.lastPathComponent])
        XCTAssertEqual(files(in: downloadsFolder), [])
        let count = try await db.entryCount(source: "wordnet-spa-eng")
        XCTAssertEqual(count, 0, "the stub stays attached")
    }

    /// 0237, "Try again": the resumed request is refused (HTTP 403, an
    /// expired signed URL): the resume data goes and one fresh request on the
    /// catalog URL follows, from the first byte; the install completes.
    func testExpiredResumeDataStartsOver() async throws {
        let service = try await downloadingService(.expiredResume)
        let pack = try XCTUnwrap(try PackFixtures.catalog().pack(.arb))
        let error = await installError(service, .arb)
        XCTAssertEqual(error, .stopped)

        try await service.install(.arb)
        await settle()
        XCTAssertEqual(status.state(of: .arb), .installed)
        XCTAssertEqual(PackFixtureURLProtocol.requests, Array(repeating: try XCTUnwrap(pack.url), count: 3))
        let ranges = PackFixtureURLProtocol.ranges
        guard ranges.count == 3 else { return XCTFail("three requests: \(ranges)") }
        XCTAssertNil(ranges[0])
        XCTAssertNotNil(ranges[1], "Try again resumes")
        XCTAssertNil(ranges[2], "the fresh request starts from the first byte")
        XCTAssertEqual(files(in: packsFolder), [pack.fileName])
        XCTAssertEqual(files(in: downloadsFolder), [])
    }

    /// The fresh request after a refused resume is the only retry: when it
    /// fails too, Try again shows the error.
    func testRefusedFreshRequestIsNotRetried() async throws {
        let service = try await downloadingService(.failOnce)
        let stopped = await installError(service, .arb)
        XCTAssertEqual(stopped, .stopped)
        await service.useFixtureDownloads(.http404)
        let error = await installError(service, .arb)
        XCTAssertEqual(error, .unavailable)
        let ranges = PackFixtureURLProtocol.ranges
        guard ranges.count == 2 else { return XCTFail("the resumed request and one fresh one: \(ranges)") }
        XCTAssertNotNil(ranges[0], "Try again resumes")
        XCTAssertNil(ranges[1], "the fresh one from the first byte")
    }

    /// 0237, "Crash safety": an install cut off after its rename (step 5),
    /// its re-attach (step 6) or the imports it covers (step 7) lacks its id
    /// in `packs_installed`. The next launch attaches the file, deletes the
    /// covered import, enables and orders the pack's dictionaries and adds
    /// the id; a launch after that changes nothing.
    func testCrashAfterCommitFinishesTheInstall() async throws {
        let catalog = try PackFixtures.catalog()
        let pack = try XCTUnwrap(catalog.pack(.spa))
        let spanish = catalog.sources(of: .spa).map(\.source)
        let wordCount = try XCTUnwrap(catalog.sources.first { $0.source == "wordnet-spa-eng" }).wordCount
        let json = tempDir.appendingPathComponent("wordnet-spa-eng.json")
        try Data(#"[{"word": "casa", "definition": "x"}, {"word": "casaqzx", "definition": "y"}]"#.utf8).write(to: json)
        for point in [PackService.CrashPoint.afterCommit, .afterAttach, .afterImports] {
            try? FileManager.default.removeItem(at: packsFolder)
            settings = SettingsService(store: InMemoryKeyValueStore())
            settings.dictionaryOrder = ["wordnet"]
            settings.enabledSources = ["wordnet"]
            let service = try await downloadingService(.ok)
            try await db.clearEntries(fromSource: "wordnet-spa-eng")
            _ = try await db.importJSON(at: json, source: "wordnet-spa-eng")
            await service.crash(at: point)
            do {
                try await service.install([.spa], fromAssetsIn: PackFixtures.assets)
                XCTFail("\(point): the install stops")
            } catch {
                XCTAssertTrue(error is PackService.SimulatedCrash, "\(point): \(error)")
            }
            XCTAssertEqual(settings.packsInstalled, [], "\(point): cut off before the final write")
            XCTAssertEqual(settings.enabledSources, ["wordnet"], "\(point)")
            XCTAssertEqual(files(in: packsFolder), [pack.fileName], "\(point): committed")

            let next = makeService()
            try await relaunch(next)
            await settle()
            XCTAssertEqual(settings.packsInstalled, [.spa], "\(point)")
            XCTAssertEqual(settings.enabledSources, Set(["wordnet"] + spanish), "\(point)")
            XCTAssertEqual(Set(settings.dictionaryOrder ?? []), Set(["wordnet"] + spanish), "\(point): ordered")
            let count = try await db.entryCount(source: "wordnet-spa-eng")
            XCTAssertEqual(count, wordCount + 1, "\(point): only the import the pack lacks stays")
            let found = try await db.search(query: "casa", enabledSources: ["wordnet-spa-eng"])
            XCTAssertTrue(found.contains { $0.word == "casa" }, "\(point): attached")
            XCTAssertEqual(status.state(of: .spa), .installed, "\(point)")

            // The user turns Spanish off; the next launch replays nothing.
            settings.enabledSources = ["wordnet"]
            try await relaunch(makeService())
            XCTAssertEqual(settings.enabledSources, ["wordnet"], "\(point): a second launch changes nothing")
            XCTAssertEqual(settings.packsInstalled, [.spa], "\(point)")
        }
    }

    /// 0237, "Crash safety": a removal cut off after its marker, or after
    /// the stub's re-attach, is finished by the next launch: the stub, the
    /// file deleted, the id dropped from `packs_installed`, then the marker.
    func testCrashDuringRemovalFinishesIt() async throws {
        for point in [PackService.CrashPoint.afterMarker, .afterReattach] {
            let service = try await downloadingService(.ok)
            try await service.install([.arb], fromAssetsIn: PackFixtures.assets)
            XCTAssertEqual(settings.packsInstalled, [.arb], "\(point)")
            await service.crash(at: point)
            do {
                try await service.remove(.arb)
                XCTFail("\(point): the removal stops")
            } catch {
                XCTAssertTrue(error is PackService.SimulatedCrash, "\(point): \(error)")
            }
            XCTAssertTrue(files(in: packsFolder).contains("arb.removing"), "\(point): the marker is there")
            XCTAssertEqual(settings.packsInstalled, [.arb], "\(point)")

            let next = makeService()
            try await relaunch(next)
            await settle()
            XCTAssertEqual(files(in: packsFolder), [], "\(point): the file and the marker are deleted")
            XCTAssertEqual(settings.packsInstalled, [], "\(point)")
            let count = try await db.entryCount(source: "wordnet-arb-eng")
            XCTAssertEqual(count, 0, "\(point): the stub is attached")
            let installed = await next.installedPacks()
            XCTAssertEqual(installed, [], "\(point)")
            XCTAssertEqual(status.state(of: .arb), .notInstalled, "\(point)")
        }
    }

    /// 0237, "Crash safety": `packs_installed` names a pack with no file (a
    /// restore from a backup): nothing is replayed or deleted, the stub is
    /// attached, and the id stays for the missing sheet (#244).
    func testRestoredBackupOffersTheMissingPack() async throws {
        settings.packsInstalled = [.ell]
        settings.dictionaryOrder = ["wordnet"]
        let service = try await downloadingService(.ok)
        await settle()
        XCTAssertEqual(settings.packsInstalled, [.ell], "kept for the offer")
        XCTAssertEqual(settings.dictionaryOrder, ["wordnet"], "no preference is written")
        let installed = await service.installedPacks()
        XCTAssertEqual(installed, [])
        XCTAssertEqual(status.state(of: .ell), .notInstalled)
        let greek = try await db.search(query: "νερό", enabledSources: ["freedict-ell-eng"])
        XCTAssertEqual(greek, [])
        XCTAssertEqual(PackFixtureURLProtocol.requests, [])
    }

    /// Remove mid-download cancels the download: nothing installed, no file
    /// left, "not installed", no `didChange`.
    func testRemoveDuringDownloadCancelsIt() async throws {
        let service = try await downloadingService(.slow)
        let changed = expectation(forNotification: PackService.didChange, object: service)
        changed.isInverted = true
        let install = Task { try await service.install(.arb) }
        try await waitUntil("the download to start") { isDownloading(.arb) }
        try await service.remove(.arb)
        do {
            try await install.value
            XCTFail("cancelled")
        } catch {
            XCTAssertEqual(error as? PackError, .cancelled)
        }
        await fulfillment(of: [changed], timeout: 0.5)
        await settle()
        XCTAssertEqual(status.state(of: .arb), .notInstalled)
        XCTAssertEqual(files(in: packsFolder), [])
        XCTAssertEqual(files(in: downloadsFolder), [])
        XCTAssertEqual(settings.packsInstalled, [])
    }

    /// Removing a pack that is not installed changes nothing: no re-attach,
    /// no `didChange`, `packs_installed` and the preferences untouched.
    func testRemoveWhatIsNotInstalledChangesNothing() async throws {
        let service = try await downloadingService(.ok)
        settings.dictionaryOrder = ["wordnet"]
        let reopens = await db.dictionaryReopenCount
        let changed = expectation(forNotification: PackService.didChange, object: service)
        changed.isInverted = true
        try await service.remove(.ell)
        await fulfillment(of: [changed], timeout: 0.5)
        let after = await db.dictionaryReopenCount
        XCTAssertEqual(after, reopens)
        XCTAssertEqual(settings.dictionaryOrder, ["wordnet"])
        XCTAssertEqual(settings.packsInstalled, [])
        XCTAssertEqual(PackFixtureURLProtocol.requests, [])
    }
}

/// #237: no network access outside a download the user started (0237,
/// "Test plan"). Reads the app's sources through `#filePath`.
final class NetworkAuditTests: XCTestCase {
    /// `URLSession`, `URLRequest`, `NWConnection` and `NWPathMonitor` appear
    /// only in `PackService.swift`, which uses them only for a download.
    func testOnlyPackServiceUsesTheNetwork() throws {
        let sources = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("DictApp", isDirectory: true)
        let enumerator = try XCTUnwrap(FileManager.default.enumerator(at: sources, includingPropertiesForKeys: nil))
        let files = enumerator.compactMap { $0 as? URL }.filter { $0.pathExtension == "swift" }
        XCTAssertGreaterThan(files.count, 20, "the audit reads the app's sources")
        var uses: [String] = []
        var packServiceUses = false
        for file in files {
            let text = try String(contentsOf: file, encoding: .utf8)
            let found = ["URLSession", "URLRequest", "NWConnection", "NWPathMonitor", "import Network"]
                .filter(text.contains)
            if file.lastPathComponent == "PackService.swift" {
                packServiceUses = found.contains("URLSession")
            } else {
                uses += found.map { "\(file.lastPathComponent): \($0)" }
            }
        }
        XCTAssertEqual(uses, [], "network code outside PackService.swift")
        XCTAssertTrue(packServiceUses, "PackService.swift holds the download")
    }
}

// MARK: - Issue #242 QA: the download's edge cases

/// Records the `userInfo["packs"]` of every `PackService.didChange` one
/// service posts.
final class DidChangeRecorder: @unchecked Sendable {
    private let lock = NSLock()
    private var posts: [[PackID]] = []
    private var observer: NSObjectProtocol?

    init(_ service: PackService) {
        observer = NotificationCenter.default.addObserver(forName: PackService.didChange, object: service,
                                                          queue: nil) { [weak self] note in
            let ids = note.userInfo?["packs"] as? [PackID] ?? []
            self?.lock.withLock { self?.posts.append(ids) }
        }
    }

    var packs: [[PackID]] {
        lock.withLock { posts }
    }

    func stop() {
        if let observer {
            NotificationCenter.default.removeObserver(observer)
        }
    }
}

/// A scripted server for `PackDownloader`: the answers
/// `PackFixtureURLProtocol` has no mode for (a server that ignores `Range`,
/// HTTP 5xx, GitHub's redirect to its CDN). It serves the committed assets
/// by the URL's last path component, never the network, and records each
/// request's URL and `Range` header.
final class ScriptedAssetProtocol: URLProtocol {
    enum Behaviour: Equatable {
        /// 200 and the asset, or 206 and the rest for a `Range` request.
        case serve
        /// The first request stops after half the asset with
        /// `NSURLErrorNetworkConnectionLost`; later ones are served.
        case dropHalfOnce
        /// As `dropHalfOnce`, but the server ignores `Range`: 200 and the
        /// whole asset again.
        case dropHalfOnceNoRanges
        /// This status with a small HTML page.
        case status(Int)
        /// A 302 to the CDN host, which serves the asset.
        case redirectToCDN
    }

    struct Request: Equatable {
        let url: URL
        let range: String?
    }

    static let cdnHost = "objects.githubusercontent.com"

    private static let lock = NSLock()
    private static var behaviour = Behaviour.serve
    private static var dropped = false
    private static var seen: [Request] = []

    static func configure(_ behaviour: Behaviour) {
        lock.withLock {
            self.behaviour = behaviour
            dropped = false
            seen = []
        }
    }

    static var requests: [Request] {
        lock.withLock { seen }
    }

    override class func canInit(with request: URLRequest) -> Bool { true }

    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    override func startLoading() {
        guard let url = request.url else {
            client?.urlProtocol(self, didFailWithError: URLError(.badURL))
            return
        }
        let range = request.value(forHTTPHeaderField: "Range")
        let (behaviour, dropNow) = Self.lock.withLock { () -> (Behaviour, Bool) in
            Self.seen.append(Request(url: url, range: range))
            let drops = [Behaviour.dropHalfOnce, .dropHalfOnceNoRanges].contains(Self.behaviour) && !Self.dropped
            if drops { Self.dropped = true }
            return (Self.behaviour, drops)
        }
        if case .status(let code) = behaviour {
            respond(url, status: code, headers: ["Content-Type": "text/html"])
            client?.urlProtocol(self, didLoad: Data("<html>error \(code)</html>".utf8))
            client?.urlProtocolDidFinishLoading(self)
            return
        }
        if behaviour == .redirectToCDN, url.host != Self.cdnHost {
            var components = URLComponents()
            components.scheme = "https"
            components.host = Self.cdnHost
            components.path = "/release-assets/" + url.lastPathComponent
            guard let cdn = components.url,
                  let response = HTTPURLResponse(url: url, statusCode: 302, httpVersion: "HTTP/1.1",
                                                 headerFields: ["Location": cdn.absoluteString]) else { return }
            client?.urlProtocol(self, wasRedirectedTo: URLRequest(url: cdn), redirectResponse: response)
            client?.urlProtocol(self, didFailWithError: NSError(domain: NSCocoaErrorDomain, code: NSUserCancelledError))
            return
        }
        guard var asset = try? Data(contentsOf: PackFixtures.assets.appendingPathComponent(url.lastPathComponent)) else {
            respond(url, status: 404, headers: [:])
            client?.urlProtocolDidFinishLoading(self)
            return
        }
        var status = 200
        var headers = ["Content-Type": "application/octet-stream", "Accept-Ranges": "bytes",
                       "ETag": "\"\(url.lastPathComponent)\""]
        if behaviour != .dropHalfOnceNoRanges, let range, range.hasPrefix("bytes="),
           let start = Int(range.dropFirst("bytes=".count).prefix { $0.isNumber }), start > 0, start < asset.count {
            headers["Content-Range"] = "bytes \(start)-\(asset.count - 1)/\(asset.count)"
            asset = asset.subdata(in: start..<asset.count)
            status = 206
        }
        headers["Content-Length"] = String(asset.count)
        respond(url, status: status, headers: headers)
        if dropNow {
            let half = asset.prefix(asset.count / 2)
            client?.urlProtocol(self, didLoad: half)
            dropOnceReceived(Int64(half.count))
        } else {
            client?.urlProtocol(self, didLoad: asset)
            client?.urlProtocolDidFinishLoading(self)
        }
    }

    private var timer: Timer?

    /// Drops the connection once the session has taken the `bytes` sent
    /// (QA #245): reported while they are still in flight, the drop leaves
    /// resume data that counts fewer of them, down to none ("bytes=0-").
    /// Polls on this thread's run loop, where the client expects its calls;
    /// gives up waiting after 5 s.
    private func dropOnceReceived(_ bytes: Int64) {
        let deadline = Date().addingTimeInterval(5)
        let timer = Timer(timeInterval: 0.005, repeats: true) { [weak self] timer in
            guard let self else {
                timer.invalidate()
                return
            }
            guard (task?.countOfBytesReceived ?? bytes) >= bytes || Date() >= deadline else { return }
            timer.invalidate()
            client?.urlProtocol(self, didFailWithError: URLError(.networkConnectionLost))
        }
        RunLoop.current.add(timer, forMode: .common)
        self.timer = timer
    }

    override func stopLoading() {
        timer?.invalidate()
        timer = nil
    }

    private func respond(_ url: URL, status: Int, headers: [String: String]) {
        guard let response = HTTPURLResponse(url: url, statusCode: status, httpVersion: "HTTP/1.1",
                                             headerFields: headers) else { return }
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
    }
}

/// `PackDownloader`, the session of 0237's "Download and install", step 1,
/// against `ScriptedAssetProtocol`: resume data, ranges, server errors and
/// the redirect. No test touches the network.
@MainActor
final class PackDownloaderTests: XCTestCase {
    private var tempDir: URL!
    private var downloader: PackDownloader!
    private var pack: CatalogPack!

    override func setUp() async throws {
        try await super.setUp()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        let configuration = PackDownloader.configuration()
        configuration.protocolClasses = [ScriptedAssetProtocol.self]
        downloader = PackDownloader(configuration: configuration)
        pack = try XCTUnwrap(try PackFixtures.catalog().pack(.arb))
    }

    override func tearDown() async throws {
        downloader.invalidate()
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    private var destination: URL {
        tempDir.appendingPathComponent("Downloads", isDirectory: true).appendingPathComponent(pack.assetName)
    }

    /// Every `progress` value, in order.
    private final class Progress: @unchecked Sendable {
        private let lock = NSLock()
        private var received: [Int64] = []
        func add(_ value: Int64) { lock.withLock { received.append(value) } }
        var values: [Int64] { lock.withLock { received } }
    }

    /// The download of the Arabic asset, or how it failed.
    private func download(resumeData: Data? = nil, progress: Progress = Progress()) async throws
        -> Result<URL, PackDownloader.Failure> {
        let url = try XCTUnwrap(pack.url)
        do {
            return .success(try await downloader.download(url, resumeData: resumeData, to: destination) {
                progress.add($0)
            })
        } catch let failure as PackDownloader.Failure {
            return .failure(failure)
        }
    }

    /// The file at `url` is the catalog's asset, byte for byte.
    private func assertIsTheAsset(_ url: URL, file: StaticString = #filePath, line: UInt = #line) throws {
        let (sha, size) = try PackFiles.sha256(of: url)
        XCTAssertEqual(sha, pack.sha256, file: file, line: line)
        XCTAssertEqual(size, pack.size, file: file, line: line)
    }

    /// The asset lands at the destination; progress grows to its size; one
    /// request, for all of it.
    func testDownloadsTheAssetWithProgress() async throws {
        ScriptedAssetProtocol.configure(.serve)
        let progress = Progress()
        let file = try await download(progress: progress).get()
        XCTAssertEqual(file, destination)
        try assertIsTheAsset(file)
        XCTAssertEqual(progress.values.last, pack.size)
        XCTAssertEqual(progress.values, progress.values.sorted(), "progress only grows")
        XCTAssertEqual(ScriptedAssetProtocol.requests, [.init(url: try XCTUnwrap(pack.url), range: nil)])
    }

    /// A dropped connection fails with `.stopped` and the session's resume
    /// data; the download from it asks for the rest only and joins a file
    /// equal to the asset. Progress resumes from the bytes already there.
    func testDroppedConnectionResumesWhereItStopped() async throws {
        ScriptedAssetProtocol.configure(.dropHalfOnce)
        let failure: PackDownloader.Failure
        switch try await download() {
        case .success: return XCTFail("the connection dropped")
        case .failure(let error): failure = error
        }
        XCTAssertEqual(failure.error, .stopped)
        let resumeData = try XCTUnwrap(failure.resumeData, "the session left resume data")
        XCTAssertFalse(FileManager.default.fileExists(atPath: destination.path), "nothing at the destination")

        let progress = Progress()
        let file = try await download(resumeData: resumeData, progress: progress).get()
        try assertIsTheAsset(file)
        let ranges = ScriptedAssetProtocol.requests.map(\.range)
        XCTAssertEqual(ranges, [nil, "bytes=\(pack.size / 2)-"])
        XCTAssertGreaterThanOrEqual(progress.values.first ?? 0, pack.size / 2, "progress continues from the drop")
    }

    /// A server that ignores the range (a new CDN URL) answers 200 with the
    /// whole asset: the download starts over and the file is still the asset.
    func testResumeAgainstAServerWithoutRangesStartsOver() async throws {
        ScriptedAssetProtocol.configure(.dropHalfOnceNoRanges)
        guard case .failure(let failure) = try await download() else { return XCTFail("the connection dropped") }
        let resumeData = try XCTUnwrap(failure.resumeData)
        let file = try await download(resumeData: resumeData).get()
        try assertIsTheAsset(file)
    }

    /// HTTP 4xx and 5xx are "not available right now", with no resume data;
    /// the error page is not kept.
    func testServerErrorsAreUnavailable() async throws {
        for code in [403, 404, 500, 503] {
            ScriptedAssetProtocol.configure(.status(code))
            guard case .failure(let failure) = try await download() else {
                XCTFail("HTTP \(code) is a failure")
                continue
            }
            XCTAssertEqual(failure.error, .unavailable, "HTTP \(code)")
            XCTAssertNil(failure.resumeData, "HTTP \(code)")
            XCTAssertFalse(FileManager.default.fileExists(atPath: destination.path), "HTTP \(code)")
        }
    }

    /// GitHub answers the release URL with a redirect to its CDN, which the
    /// session follows (0237, step 1).
    func testRedirectToTheCDNIsFollowed() async throws {
        ScriptedAssetProtocol.configure(.redirectToCDN)
        let file = try await download().get()
        try assertIsTheAsset(file)
        XCTAssertEqual(ScriptedAssetProtocol.requests.map(\.url.host), [pack.url?.host, ScriptedAssetProtocol.cdnHost])
    }

    /// The session (0237, step 1): ephemeral, no cookies, cache or
    /// credentials, no waiting for connectivity, every network allowed, not
    /// a background session.
    func testSessionConfiguration() {
        let configuration = PackDownloader.configuration()
        XCTAssertNil(configuration.identifier, "not a background session")
        XCTAssertNil(configuration.httpCookieStorage)
        XCTAssertFalse(configuration.httpShouldSetCookies)
        XCTAssertNil(configuration.urlCredentialStorage)
        XCTAssertNil(configuration.urlCache)
        XCTAssertEqual(configuration.requestCachePolicy, .reloadIgnoringLocalCacheData)
        XCTAssertFalse(configuration.waitsForConnectivity)
        XCTAssertTrue(configuration.allowsCellularAccess)
        XCTAssertTrue(configuration.allowsExpensiveNetworkAccess)
        XCTAssertTrue(configuration.allowsConstrainedNetworkAccess)
    }

    /// What the user sees for each session error (0237, "Offline and errors").
    func testErrorMapping() {
        let cases: [(Error, PackError)] = [
            (URLError(.notConnectedToInternet), .offline),
            (URLError(.dataNotAllowed), .offline),
            (URLError(.networkConnectionLost), .stopped),
            (URLError(.timedOut), .stopped),
            (URLError(.cancelled), .cancelled),
            (URLError(.cannotWriteToFile), .noSpace),
            (URLError(.badServerResponse), .unavailable),
            (URLError(.fileDoesNotExist), .unavailable),
            (POSIXError(.ENOSPC), .noSpace),
            (NSError(domain: NSCocoaErrorDomain, code: NSFileWriteUnknownError,
                     userInfo: [NSUnderlyingErrorKey: NSError(domain: NSCocoaErrorDomain,
                                                              code: NSFileWriteOutOfSpaceError)]), .noSpace),
            (NSError(domain: NSCocoaErrorDomain, code: NSFileWriteUnknownError), .stopped),
        ]
        for (error, expected) in cases {
            XCTAssertEqual(PackDownloader.packError(for: error), expected, "\(error)")
        }
    }
}

/// `PackStatusModel`: what the views read, in every window.
@MainActor
final class PackStatusModelTests: XCTestCase {
    /// A pack nobody has set is not installed.
    func testUnsetPackIsNotInstalled() {
        XCTAssertEqual(PackStatusModel().state(of: .ell), .notInstalled)
    }

    /// Progress moves in 100 kB steps ("3.1 of 6.9 MB"), never past the
    /// total, and only while the pack downloads: a late callback never
    /// overwrites a later state.
    func testProgressOnlyWhileDownloading() {
        let model = PackStatusModel()
        model.progress(.arb, received: 500_000)
        XCTAssertEqual(model.state(of: .arb), .notInstalled, "not downloading: ignored")

        model.set(.downloading(received: 0, total: 1_000_000), for: .arb)
        model.progress(.arb, received: 50_000)
        XCTAssertEqual(model.state(of: .arb), .downloading(received: 0, total: 1_000_000), "within the first step")
        model.progress(.arb, received: 150_000)
        XCTAssertEqual(model.state(of: .arb), .downloading(received: 150_000, total: 1_000_000))
        model.progress(.arb, received: 199_999)
        XCTAssertEqual(model.state(of: .arb), .downloading(received: 150_000, total: 1_000_000), "same step")
        model.progress(.arb, received: 2_000_000)
        XCTAssertEqual(model.state(of: .arb), .downloading(received: 1_000_000, total: 1_000_000), "at most the total")

        model.set(.installing, for: .arb)
        model.progress(.arb, received: 1_000_000)
        XCTAssertEqual(model.state(of: .arb), .installing, "a late callback is ignored")
        XCTAssertEqual(model.state(of: .rus), .notInstalled, "other packs untouched")
    }
}

/// The Languages screen (Issue #243, 0237 "Settings → Dictionaries"): its
/// rows, the texts of each `PackState` and the remove alert, on the host
/// app's catalog read as the app reads it. Nothing is downloaded.
@MainActor
final class LanguagesViewModelTests: XCTestCase {
    private let en = Locale(identifier: "en")
    private let base = "Its dictionaries, word forms and word lists are deleted. "
        + "Your History, My words and learning progress stay."
    /// #245: the first sentence names only what the pack holds.
    private let dictionariesOnly = "Its dictionaries are deleted. Your History, My words and learning progress stay."
    private let dictionariesAndForms = "Its dictionaries and word forms are deleted. "
        + "Your History, My words and learning progress stay."
    private let listsOnly = "The word lists are deleted. Your History, My words and learning progress stay."
    private let greekLearned = "You can go on learning the words you have. "
        + "Greek lists come back when you download Greek again."
    private let englishViaGreek = "English via Greek shows no meanings until you download Greek again."

    /// "You can go on learning the words you have." alone: a learned
    /// language with no built-in lists (PM, #243).
    private let learnedWithoutLists = "You can go on learning the words you have."

    /// The bundled catalog with one built-in list in each lists pack (`ell`,
    /// `eng-lists`), as E3's data gives it, so `hasBuiltInLists` holds for
    /// Greek and English only. The bundled catalog has Greek's lists (#152)
    /// but none in `eng-lists` yet.
    private func catalogWithLists() throws -> PackCatalog {
        var catalog = try PackFixtures.catalog()
        catalog.lists = [CatalogList(packID: .ell, id: "ell-a1", lang: "ell", level: "A1", wordCount: 1),
                         CatalogList(packID: .engLists, id: "eng-a1", lang: "eng", level: "A1", wordCount: 1)]
        XCTAssertEqual(catalog.languages.filter(\.hasBuiltInLists).map(\.lang).sorted(), ["ell", "eng"],
                       "precondition: Greek and English have built-in lists")
        return catalog
    }

    /// A model in the `code` UI language over the bundled catalog (with
    /// Greek and English lists), with `learned` as E4's
    /// `learning_languages` and `learning_via`.
    private func model(_ code: String = "en", status: PackStatusModel? = nil,
                       learned: @escaping @MainActor () -> (languages: [String], via: [String: String])
                           = { ([], [:]) }) throws -> LanguagesViewModel {
        let catalog = try catalogWithLists()
        let settings = SettingsService(store: InMemoryKeyValueStore())
        settings.selectedUILanguageCode = code
        let localization = LocalizationManager(settingsService: settings, bundle: .main)
        XCTAssertEqual(localization.currentLanguage.code, code, "precondition: the in-app language")
        return LanguagesViewModel(status: status ?? PackStatusModel(), localization: localization,
                                  settings: settings, catalog: { catalog }, learning: learned)
    }

    /// `s` without U+200F (RLM) and Foundation's U+2068/U+2069 isolates.
    private static func visible(_ s: String?) -> String? {
        let marks: Set<Unicode.Scalar> = ["\u{200F}", "\u{2068}", "\u{2069}"]
        return s.map { String($0.unicodeScalars.filter { !marks.contains($0) }) }
    }

    /// 0237 Test plan: Greek's alert with English via Greek learned has the
    /// pair sentence; with Greek via English only, the learning sentence
    /// alone. A pair names a pack only when its meanings come from it: the
    /// limited Greek via Russian needs Greek, never Russian.
    func testRemoveAlertNamesTheLearnedPair() throws {
        var learned: (languages: [String], via: [String: String]) = (["ell", "eng"], ["ell": "eng", "eng": "ell"])
        let model = try model(learned: { learned })

        model.requestRemove(.ell)
        XCTAssertEqual(model.removal?.pack, .ell)
        XCTAssertEqual(model.removal?.title, "Remove Greek?")
        XCTAssertEqual(model.removal?.message, [base, greekLearned, englishViaGreek].joined(separator: " "))

        learned = (["ell"], ["ell": "eng"])
        model.requestRemove(.ell)
        XCTAssertEqual(model.removal?.message, [base, greekLearned].joined(separator: " "),
                       "Greek via English only: the learning sentence alone")

        learned = (["eng"], ["eng": "ell"])
        model.requestRemove(.ell)
        XCTAssertEqual(model.removal?.message, [base, englishViaGreek].joined(separator: " "),
                       "Greek not learned: the pair sentence alone")
        model.requestRemove(.spa)
        XCTAssertEqual(model.removal?.message, dictionariesOnly, "English via Greek needs nothing from Spanish")
        model.requestRemove(.engLists)
        XCTAssertEqual(model.removal?.title, "Remove English word lists?")
        XCTAssertEqual(model.removal?.message, listsOnly + " You can go on learning the words you have. "
                       + "English lists come back when you download English again.",
                       "English's own pair is the learning sentence, never the pair sentence")

        learned = (["eng", "ell"], ["eng": "spa", "ell": "rus"])
        model.requestRemove(.spa)
        XCTAssertEqual(model.removal?.message,
                       dictionariesOnly + " English via Spanish shows no meanings until you download Spanish again.")
        model.requestRemove(.rus)
        XCTAssertEqual(model.removal?.message, dictionariesOnly,
                       "Greek via Russian takes its meanings from the Greek pack")
        model.requestRemove(.ell)
        XCTAssertEqual(model.removal?.message, [base, greekLearned].joined(separator: " "))

        learned = ([], [:])
        model.requestRemove(.ell)
        XCTAssertEqual(model.removal?.message, base, "nothing learned: what goes and what stays")
    }

    /// PM, #243: a learned language without built-in lists (Spanish,
    /// Russian, Arabic) gets "You can go on learning the words you have."
    /// alone, never a promise of lists that do not exist. The catalog
    /// decides: with no `catalog_list` rows, Greek and English promise none
    /// either.
    func testRemoveAlertPromisesListsOnlyForALanguageWithBuiltInLists() throws {
        let catalog = try catalogWithLists()
        func message(_ id: PackID, learned: [String], via: [String: String] = [:], in catalog: PackCatalog,
                     locale: Locale? = nil) -> String? {
            LanguagesViewModel.removal(of: id, catalog: catalog, learned: learned, via: via, uiLanguage: "en",
                                       locale: locale ?? en)?.message
        }
        for (id, lang) in [(PackID.spa, "spa"), (.rus, "rus"), (.arb, "arb")] {
            XCTAssertEqual(message(id, learned: [lang], in: catalog),
                           [dictionariesOnly, learnedWithoutLists].joined(separator: " "),
                           "\(lang) has no built-in lists")
        }
        XCTAssertEqual(message(.ell, learned: ["ell"], in: catalog), [base, greekLearned].joined(separator: " "))
        XCTAssertEqual(message(.spa, learned: ["spa", "eng"], via: ["eng": "spa"], in: catalog),
                       [dictionariesOnly, learnedWithoutLists,
                        "English via Spanish shows no meanings until you download Spanish again."]
                        .joined(separator: " "),
                       "Spanish learned and needed by English via Spanish: both sentences")

        var noLists = catalog
        noLists.lists = []
        XCTAssertEqual(message(.ell, learned: ["ell"], in: noLists),
                       [dictionariesAndForms, learnedWithoutLists].joined(separator: " "),
                       "no Greek lists in the catalog: none come back, none are named")
        XCTAssertEqual(message(.engLists, learned: ["eng"], in: noLists),
                       [listsOnly, learnedWithoutLists].joined(separator: " "))

        // Its own sentence in every UI language: no raw key, no English, no list.
        for code in ["ru", "es", "ar", "el"] {
            let locale = Locale(identifier: code)
            let sentence = SettingsViewModel.localizedString("languages.remove.learning.noLists", locale: locale)
            XCTAssertNotEqual(sentence, "languages.remove.learning.noLists", code)
            XCTAssertNotEqual(sentence, learnedWithoutLists, code)
            let spanish = try XCTUnwrap(message(.spa, learned: ["spa"], in: catalog, locale: locale))
            XCTAssertTrue(spanish.hasSuffix(" " + sentence), "\(code): \(spanish)")
            let greek = try XCTUnwrap(message(.ell, learned: ["ell"], in: catalog, locale: locale))
            XCTAssertFalse(greek.hasSuffix(" " + sentence), "\(code): Greek's lists come back: \(greek)")
        }
    }

    /// A learned language with no stored via, or one no longer offered,
    /// takes its default (0131): the UI language's pair, else English.
    func testLearnedLanguageWithoutAViaTakesItsDefault() throws {
        let catalog = try PackFixtures.catalog()
        func message(ui: String) -> String? {
            LanguagesViewModel.removal(of: .ell, catalog: catalog, learned: ["eng"], via: [:], uiLanguage: ui,
                                       locale: en)?.message
        }
        XCTAssertEqual(message(ui: "el"), [base, englishViaGreek].joined(separator: " "),
                       "a Greek UI learns English via Greek")
        XCTAssertEqual(message(ui: "en"), base, "an English UI learns English via English")

        func via(_ lang: String, stored: [String: String] = [:], ui: String) -> String? {
            LanguagesViewModel.via(of: lang, stored: stored, pairs: catalog.pairs, uiLanguage: ui)
        }
        XCTAssertEqual(via("eng", stored: ["eng": "spa"], ui: "el"), "spa", "the stored via while offered")
        XCTAssertEqual(via("eng", stored: ["eng": "rus"], ui: "es"), "spa", "no English via Russian: the default")
        XCTAssertEqual(via("ell", ui: "ru"), "rus", "a Russian UI learns Greek via Russian, the limited pair")
        XCTAssertEqual(via("ell", ui: "ar"), "eng", "no Greek via Arabic: English")
        XCTAssertNil(via("und", ui: "en"), "no pair")
    }

    /// #245: the alert names only what the pack holds: dictionaries for
    /// Spanish, Russian and Arabic, word forms for Greek, word lists only
    /// when the catalog has them; the English lists pack names its lists.
    /// Each sentence in every UI language.
    func testRemoveMessageNamesWhatThePackHolds() throws {
        let bundled = try PackFixtures.catalog()
        let withLists = try catalogWithLists()
        var noLists = bundled
        noLists.lists = []
        func message(_ id: PackID, _ catalog: PackCatalog, _ code: String = "en") -> String? {
            LanguagesViewModel.removal(of: id, catalog: catalog, learned: [], via: [:], uiLanguage: code,
                                       locale: Locale(identifier: code))?.message
        }
        for id in [PackID.spa, .rus, .arb] {
            XCTAssertEqual(message(id, bundled), dictionariesOnly, "\(id): no lists of its own")
            XCTAssertEqual(message(id, withLists), dictionariesOnly, "\(id): lists of other packs are not its own")
        }
        XCTAssertTrue(bundled.lists.contains { $0.packID == .ell }, "precondition: the Greek pack has lists (#152)")
        XCTAssertEqual(message(.ell, bundled), base)
        XCTAssertEqual(message(.ell, withLists), base)
        XCTAssertEqual(message(.ell, noLists), dictionariesAndForms, "no Greek lists in the catalog: none named")
        XCTAssertEqual(message(.engLists, bundled), listsOnly)
        XCTAssertEqual(message(.engLists, withLists), listsOnly)

        let keys = ["languages.remove.message", "languages.remove.message.forms",
                    "languages.remove.message.dictionaries", "languages.remove.message.lists"]
        for code in ["en", "ru", "es", "ar", "el"] {
            let locale = Locale(identifier: code)
            let sentences = keys.map { SettingsViewModel.localizedString($0, locale: locale) }
            XCTAssertEqual(Set(sentences).count, keys.count, "\(code): four different sentences")
            XCTAssertFalse(sentences.contains(where: keys.contains), "\(code): no raw key")
            XCTAssertEqual(message(.spa, bundled, code), sentences[2], code)
            XCTAssertEqual(message(.ell, noLists, code), sentences[1], code)
            XCTAssertEqual(message(.ell, bundled, code), sentences[0], code)
            XCTAssertEqual(message(.engLists, bundled, code), sentences[3], code)
        }
    }

    /// English first ("Included", WordNet), its lists, then every pack by
    /// its name in the UI language, with what it holds and its sizes.
    func testRowsListEnglishFirstThenByName() throws {
        let catalog = try PackFixtures.catalog()
        let rows = LanguagesViewModel.rows(catalog: catalog, locale: en)
        XCTAssertEqual(rows.map(\.id), ["eng", "eng-lists", "arb", "ell", "rus", "spa"])
        XCTAssertEqual(rows.map(\.name), ["English", "English word lists", "Arabic", "Greek", "Russian", "Spanish"])
        XCTAssertNil(rows[0].pack, "English is in the bundle")
        XCTAssertEqual(rows[0].contents, "WordNet")
        XCTAssertEqual(rows.dropFirst().map(\.pack), [.engLists, .arb, .ell, .rus, .spa])

        let row = Dictionary(uniqueKeysWithValues: rows.map { ($0.id, $0) })
        let greekLists = catalog.lists.contains { $0.packID == .ell }
        XCTAssertEqual(row["ell"]?.contents, "4 dictionaries · word forms" + (greekLists ? " · word lists" : ""))
        XCTAssertEqual(row["spa"]?.contents, "2 dictionaries")
        XCTAssertEqual(row["rus"]?.contents, "1 dictionary")
        XCTAssertEqual(row["arb"]?.contents, "1 dictionary")
        XCTAssertEqual(row["eng-lists"]?.contents,
                       catalog.lists.contains { $0.packID == .engLists } ? "word lists" : nil,
                       "the English lists pack holds lists only, none until E3 fills it")
        for id in PackID.all {
            let pack = try XCTUnwrap(catalog.pack(id))
            XCTAssertEqual(row[id.rawValue]?.downloadSize, pack.size, "\(id)")
            XCTAssertEqual(row[id.rawValue]?.installedSize, pack.fileSize, "\(id)")
        }

        let ru = LanguagesViewModel.rows(catalog: catalog, locale: Locale(identifier: "ru"))
        XCTAssertEqual(ru.map(\.id), ["eng", "eng-lists", "arb", "ell", "spa", "rus"], "by the Russian names")
        XCTAssertEqual(ru.map(\.name), ["Английский", "Списки слов (английский)", "Арабский", "Греческий",
                                        "Испанский", "Русский"])
        XCTAssertEqual(ru.first { $0.id == "spa" }?.contents.map(Self.visible), "2 словаря")
        let el = LanguagesViewModel.rows(catalog: catalog, locale: Locale(identifier: "el"))
        XCTAssertEqual(el.map(\.id), ["eng", "eng-lists", "arb", "ell", "spa", "rus"], "by the Greek names")
        XCTAssertEqual(el.first { $0.id == "ell" }.flatMap(\.contents).map(Self.visible),
                       "4 λεξικά · μορφές λέξεων" + (greekLists ? " · λίστες λέξεων" : ""))
    }

    /// Each state's text (0237, "Settings → Dictionaries" and "Offline and
    /// errors"), with sizes in the file style of the in-app locale.
    func testStateTexts() throws {
        XCTAssertEqual(Self.visible(PackTexts.download(6_889_888, locale: en)), "Download · 6.9 MB")
        XCTAssertEqual(Self.visible(PackTexts.installed(26_177_536, locale: en)), "Installed · 26.2 MB")
        XCTAssertEqual(Self.visible(PackTexts.update(6_889_888, locale: en)), "Update · 6.9 MB")
        XCTAssertEqual(Self.visible(PackTexts.updateRequired(6_889_888, locale: en)), "Update required · 6.9 MB")
        XCTAssertEqual(Self.visible(PackTexts.progress(received: 3_100_000, total: 6_889_888, locale: en)),
                       "3.1 of 6.9 MB", "the received bytes in the total's unit")
        XCTAssertEqual(Self.visible(PackTexts.progress(received: 0, total: 10_707_004, locale: en)), "0.0 of 10.7 MB")
        XCTAssertEqual(Self.visible(PackTexts.progress(received: 9_000_000, total: 6_889_888, locale: en)),
                       "6.9 of 6.9 MB", "never past the total")
        XCTAssertEqual(Self.visible(PackTexts.progress(received: 1_000, total: 3_484, locale: en)), "1 of 3 kB")

        let space: Int64 = 10_707_004 + 56_336_384
        XCTAssertEqual(PackTexts.error(.offline, name: "Greek", space: space, locale: en), "No internet connection.")
        XCTAssertEqual(PackTexts.error(.stopped, name: "Greek", space: space, locale: en),
                       "The download stopped. Check your connection and try again.")
        XCTAssertEqual(PackTexts.error(.unavailable, name: "Greek", space: space, locale: en),
                       "This download is not available right now. Try again later.")
        XCTAssertEqual(PackTexts.error(.damaged, name: "Greek", space: space, locale: en),
                       "The download was damaged. Try again.")
        XCTAssertEqual(Self.visible(PackTexts.error(.noSpace, name: "Greek", space: space, locale: en)),
                       "Not enough storage. Greek needs 67 MB free.")
        XCTAssertNil(PackTexts.error(.cancelled, name: "Greek", space: space, locale: en), "a cancel shows no error")

        let ru = Locale(identifier: "ru")
        XCTAssertEqual(Self.visible(PackTexts.progress(received: 3_100_000, total: 6_889_888, locale: ru)),
                       "3,1 из 6,9 МБ")
        XCTAssertEqual(Self.visible(PackTexts.download(6_889_888, locale: ru)), "Скачать · 6,9 МБ")

        // Arabic (#119): composed strings start with U+200F; the size is one
        // number run, in Western or Arabic-Indic digits.
        let ar = Locale(identifier: "ar")
        for text in [PackTexts.download(6_889_888, locale: ar), PackTexts.installed(26_177_536, locale: ar),
                     PackTexts.progress(received: 3_100_000, total: 6_889_888, locale: ar),
                     PackTexts.name(of: try XCTUnwrap(PackFixtures.catalog().pack(.engLists)), locale: ar)] {
            XCTAssertEqual(text.unicodeScalars.first, "\u{200F}", text)
        }
        let arabicDownload = PackTexts.download(6_889_888, locale: ar)
        XCTAssertTrue(arabicDownload.contains("6.9") || arabicDownload.contains("٦٫٩"), arabicDownload)
        XCTAssertTrue(Self.visible(arabicDownload)?.hasPrefix("تنزيل · ") == true, arabicDownload)
    }

    /// Swipe or Edit removes an installed pack only, not one in progress
    /// and never the bundled English. The rows read `PackStatusModel`.
    func testOnlyAnInstalledPackCanBeRemoved() throws {
        let status = PackStatusModel()
        let model = try model(status: status)
        let english = try XCTUnwrap(model.rows.first { $0.id == "eng" })
        let greek = try XCTUnwrap(model.rows.first { $0.id == "ell" })
        XCTAssertNil(model.state(of: english))
        XCTAssertFalse(model.canRemove(english))
        XCTAssertFalse(model.hasRemovable)

        let cases: [(PackState, Bool)] = [
            (.notInstalled, false), (.waiting, false), (.downloading(received: 1, total: 2), false),
            (.installing, false), (.installed, true), (.updateAvailable, true), (.updateRequired, true),
            (.failed(.offline), false),
        ]
        for (state, removable) in cases {
            status.set(state, for: .ell)
            XCTAssertEqual(model.state(of: greek), state)
            XCTAssertEqual(model.canRemove(greek), removable, "\(state)")
            XCTAssertEqual(model.hasRemovable, removable, "\(state)")
        }
    }
}

extension PackFileTests {
    /// 0237, step 4: an asset that matches the catalog but decompresses to
    /// another file is damaged; nothing is renamed into the folder and no
    /// partial file stays.
    func testFileMismatchAfterDecompressIsDamaged() throws {
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("filesha-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: folder) }
        let real = try XCTUnwrap(try PackFixtures.catalog().pack(.engLists))
        let pack = CatalogPack(id: real.id, ord: real.ord, lang: real.lang, kind: real.kind, version: real.version,
                               url: real.url, sha256: real.sha256, size: real.size,
                               fileSHA256: String(repeating: "0", count: 64), fileSize: real.fileSize)
        XCTAssertThrowsError(try PackFiles.install(asset: PackFixtures.assets.appendingPathComponent(pack.assetName),
                                                   pack: pack, into: folder)) { error in
            XCTAssertEqual(error as? PackError, .damaged)
        }
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: folder.path), [])
    }

    /// An asset whose sha256 matches but which is no xz stream (a bad
    /// catalog row) is damaged, with no partial file left.
    func testUnreadableStreamIsDamaged() throws {
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("notxz-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: folder) }
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let asset = folder.appendingPathComponent("garbage.xz")
        try Data(repeating: 0x5A, count: 3 << 20).write(to: asset)
        let (sha, size) = try PackFiles.sha256(of: asset)
        let real = try XCTUnwrap(try PackFixtures.catalog().pack(.arb))
        let pack = CatalogPack(id: real.id, ord: real.ord, lang: real.lang, kind: real.kind, version: real.version,
                               url: real.url, sha256: sha, size: size, fileSHA256: real.fileSHA256,
                               fileSize: real.fileSize)
        XCTAssertThrowsError(try PackFiles.install(asset: asset, pack: pack, into: folder)) { error in
            XCTAssertEqual(error as? PackError, .damaged)
        }
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: folder.path), ["garbage.xz"])
    }
}

// MARK: - Issue #138: test dictionary files

/// Dictionary files for unit tests: the bundled dictionary file's schema
/// (copied from its `sqlite_master`) holding only the given rows, so a test
/// controls exactly what Search sees. Rollback journal, like the bundled
/// file, and no triggers: the FTS index is rebuilt once after the inserts.
/// `DatabaseService.setup(userPath:dictionaryURL:)` attaches the result.
enum TestDictionary {
    struct Row {
        var word: String
        var wordNormalized: String
        var definition: String
        var phonetic: String
        var pos: String
        var source: String

        /// `normalized` defaults to `word`, as for every en, ru and es source.
        init(word: String, normalized: String? = nil, definition: String,
             phonetic: String = "", pos: String = "", source: String) {
            self.word = word
            self.wordNormalized = normalized ?? word
            self.definition = definition
            self.phonetic = phonetic
            self.pos = pos
            self.source = source
        }
    }

    /// One `dict_metadata` row. A source without one gets its ID as the
    /// display name, an empty license and version, and `eng` → `eng`.
    struct Metadata {
        var source: String
        var displayName: String
        var license = ""
        var version = ""
        var fromLang = "eng"
        var toLang = "eng"
    }

    /// `count` distinct rows for `source` (`<source>-w<i>`, "def <i>").
    static func rows(source: String, count: Int) -> [Row] {
        (0..<count).map { Row(word: "\(source)-w\($0)", definition: "def \($0)", pos: "noun", source: source) }
    }

    /// The bundled dictionary file of the host app.
    static func bundledURL() throws -> URL {
        let hostBundle: Bundle = {
            if let url = Bundle.main.url(forResource: "DictApp", withExtension: "app") {
                return Bundle(url: url) ?? .main
            }
            return .main
        }()
        let name = DictionaryFile.resourceName, ext = DictionaryFile.resourceExtension
        return try XCTUnwrap(
            hostBundle.url(forResource: name, withExtension: ext)
                ?? Bundle.main.url(forResource: name, withExtension: ext),
            "Bundled \(name).\(ext) is missing from the app bundle")
    }

    /// Writes a dictionary file with `rows` (in this order, `INSERT OR
    /// IGNORE` as the build does) and one `dict_metadata` row per source:
    /// `metadata` where given, else the default, with `word_count` = its
    /// rows. Returns its URL: `url`, or a new temp file.
    @discardableResult
    static func make(rows: [Row], metadata: [Metadata] = [], at url: URL? = nil) throws -> URL {
        let url = url ?? FileManager.default.temporaryDirectory
            .appendingPathComponent("dictionary-\(UUID().uuidString).sqlite")
        let schema = try BundledDictionary().read { db in
            try GRDB.Row.fetchAll(db, sql: """
                SELECT type, name, sql FROM sqlite_master
                WHERE sql IS NOT NULL AND type IN ('table', 'index') AND name NOT LIKE 'sqlite%'
                ORDER BY rowid
                """)
        }
        // A virtual table creates its own shadow tables (`entries_fts_data`, …).
        let virtualTables = schema.filter { ($0["sql"] as String).hasPrefix("CREATE VIRTUAL TABLE") }
            .map { $0["name"] as String }
        let statements = schema.filter { row in
            let name: String = row["name"]
            let sql: String = row["sql"]
            return sql.hasPrefix("CREATE VIRTUAL TABLE") || !virtualTables.contains { name.hasPrefix($0 + "_") }
        }.map { $0["sql"] as String }

        try? FileManager.default.removeItem(at: url)
        let queue = try DatabaseQueue(path: url.path)
        try queue.write { db in
            for sql in statements { try db.execute(sql: sql) }
            // The bundle's format, so a test file can be attached as a pack too (#237).
            try db.execute(sql: "PRAGMA user_version = \(DictionaryFile.formatVersion)")
            let insert = try db.makeStatement(sql: """
                INSERT OR IGNORE INTO entries(word, word_normalized, definition, phonetic, pos, source)
                VALUES (?, ?, ?, ?, ?, ?)
                """)
            for row in rows {
                try insert.execute(arguments: [row.word, row.wordNormalized, row.definition,
                                               row.phonetic, row.pos, row.source])
            }
            try db.execute(sql: "INSERT INTO entries_fts(entries_fts) VALUES('rebuild')")

            let counts = try GRDB.Row.fetchAll(db, sql: """
                SELECT source, COUNT(*) AS n FROM entries GROUP BY source ORDER BY MIN(id)
                """).map { ($0["source"] as String, $0["n"] as Int) }
            var sources = counts.map(\.0)
            sources += metadata.map(\.source).filter { !sources.contains($0) }
            for source in sources {
                let entry = metadata.first { $0.source == source } ?? Metadata(source: source, displayName: source)
                try db.execute(
                    sql: """
                        INSERT INTO dict_metadata(source, display_name, license, version, word_count, from_lang, to_lang)
                        VALUES (?, ?, ?, ?, ?, ?, ?)
                        """,
                    arguments: [source, entry.displayName, entry.license, entry.version,
                                counts.first { $0.0 == source }?.1 ?? 0, entry.fromLang, entry.toLang])
            }
        }
        return url
    }
}

/// A dictionary file that unit tests read directly, outside
/// `DatabaseService`: by default the host app's bundled file. Every read
/// opens a new read-only connection. An install can invalidate the open
/// bundled file while the tests run (#213, 0000-overview "Known gotchas"),
/// so a read that fails with SQLITE_IOERR runs once more on a new
/// connection, as the app's own reads do. A closure that asserts inside the
/// read hides the error from this retry (`XCTAssert` catches it): read
/// first, assert after.
struct BundledDictionary {
    let url: URL
    /// Since #237: more files whose `entries` and `dict_metadata` rows the
    /// reads see too (`shipped()`).
    private(set) var packs: [URL] = []

    init() throws {
        url = try TestDictionary.bundledURL()
    }

    init(url: URL) {
        self.url = url
    }

    /// Every shipped dictionary as one (#237): the bundle and every pack,
    /// installed from the committed assets. `entries` and `dict_metadata`
    /// are TEMP views over all the files; FTS, `sqlite_master` and the other
    /// tables need the one file (`BundledDictionary(url: PackFixtures.file(…))`).
    static func shipped() throws -> BundledDictionary {
        var dictionary = try BundledDictionary()
        let files = try PackFixtures.all()
        dictionary.packs = PackID.all.compactMap { files[$0] }
        return dictionary
    }

    func read<T>(_ value: (Database) throws -> T) throws -> T {
        do {
            return try open().read(value)
        } catch let error as DatabaseError where error.resultCode == .SQLITE_IOERR {
            return try open().read(value)
        }
    }

    func read<T>(_ value: @Sendable @escaping (Database) throws -> T) async throws -> T {
        do {
            return try await open().read(value)
        } catch let error as DatabaseError where error.resultCode == .SQLITE_IOERR {
            return try await open().read(value)
        }
    }

    private func open() throws -> DatabaseQueue {
        guard !packs.isEmpty else {
            var config = Configuration()
            config.readonly = true
            return try DatabaseQueue(path: url.path, configuration: config)
        }
        // In memory, every file attached read-only as the app attaches them.
        let queue = try DatabaseQueue()
        let files = [url] + packs
        try queue.writeWithoutTransaction { db in
            for (index, file) in files.enumerated() {
                try db.execute(sql: "ATTACH DATABASE ? AS f\(index)", arguments: [DatabaseService.dictionaryURI(file)])
            }
            for table in ["entries", "dict_metadata"] {
                try db.execute(sql: "CREATE TEMP VIEW \(table) AS "
                               + files.indices.map { "SELECT * FROM f\($0).\(table)" }.joined(separator: " UNION ALL "))
            }
        }
        return queue
    }
}

// MARK: - Issue #237: the committed pack assets

/// The language packs for unit tests (0237, "For E3 and E4"): the committed
/// assets in `Packs/`, read from the source tree through `#filePath` like
/// the search probe, and installed through the app's install path
/// (`PackFiles.install`: verify, decompress, rename). A test attaches them
/// with `setup(userPath:dictionaryURL:packFiles:)`.
enum PackFixtures {
    /// `Packs/` at the repository root.
    static let assets = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("Packs", isDirectory: true)

    /// The catalog of the host app's bundled file, read as the app reads it
    /// (`PackCatalog.read`), on a test connection that attaches the bundle.
    static func catalog() throws -> PackCatalog {
        let bundle = try TestDictionary.bundledURL()
        return try DatabaseQueue().inDatabase { db in
            try db.execute(sql: "ATTACH DATABASE ? AS dict", arguments: [DatabaseService.dictionaryURI(bundle)])
            return try PackCatalog.read(db)
        }
    }

    /// Installs `ids` from the committed assets into `folder`, and returns
    /// each pack's installed file.
    @discardableResult
    static func install(_ ids: [PackID], into folder: URL) throws -> [PackID: URL] {
        let catalog = try catalog()
        var files: [PackID: URL] = [:]
        for id in ids {
            let pack = try XCTUnwrap(catalog.pack(id), "the catalog lists \(id)")
            files[id] = try PackFiles.install(asset: assets.appendingPathComponent(pack.assetName), pack: pack,
                                              into: folder)
        }
        return files
    }

    private static var installed: [PackID: URL]?

    /// Every pack, installed once per test run into a temp folder the tests
    /// share: an attached file is never written.
    static func all() throws -> [PackID: URL] {
        if let installed, installed.values.allSatisfy({ FileManager.default.fileExists(atPath: $0.path) }) {
            return installed
        }
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("PackFixtures-\(UUID().uuidString)")
        let files = try install(PackID.all, into: folder)
        installed = files
        return files
    }

    /// The installed file of one pack.
    static func file(_ id: PackID) throws -> URL {
        try XCTUnwrap(try all()[id], "pack \(id)")
    }
}

/// The dictionary a unit test searches, on `DatabaseService.shared`. An
/// attached dictionary file is immutable, so every change writes a new file
/// with all rows so far and reopens the service on it. The user database
/// (`user.sqlite` in `directory`) carries over: History, My words and
/// imports survive a change.
final class TestDictionaryFixture {
    let directory: URL
    private(set) var rows: [TestDictionary.Row] = []
    private var metadata: [TestDictionary.Metadata] = []
    /// The file the service has attached, once `open()` ran.
    private(set) var dictionaryURL: URL?
    private var generation = 0

    var userPath: String { directory.appendingPathComponent("user.sqlite").path }

    init(directory: URL) {
        self.directory = directory
    }

    /// Writes the current rows into a new file and reopens the service on it.
    func open() async throws {
        generation += 1
        let url = try TestDictionary.make(
            rows: rows, metadata: metadata,
            at: directory.appendingPathComponent("dictionary-\(generation).sqlite"))
        dictionaryURL = url
        try await DatabaseService.shared.setup(userPath: userPath, dictionaryURL: url)
    }

    func add(_ newRows: [TestDictionary.Row]) async throws {
        rows += newRows
        try await open()
    }

    func setMetadata(_ entry: TestDictionary.Metadata) async throws {
        metadata.removeAll { $0.source == entry.source }
        metadata.append(entry)
        try await open()
    }
}

// MARK: - Issue #138: user database and the attached dictionary file
//
// The spec's #138 tests (0129-dictionary-file.md, Test plan), plus the
// import, preferred-mode and My words cases around them.

/// The user database with a `TestDictionary` file attached as `dict`, on
/// `DatabaseService.shared`. Each test opens a fresh user database in its own
/// folder. A test that swaps the dictionary file reopens the service on the
/// same user database, as an app update does.
@MainActor
final class UserDatabaseTests: XCTestCase {
    private var tempDir: URL!
    private var db: DatabaseService { .shared }
    /// The source ID an import of the bundled fixtures gets (their file name).
    private let fixtureSource = "test_import_fixture"
    /// Imported ids start here; dictionary file ids stay below.
    private static let firstImportedID: Int64 = 1 << 40

    /// "dog" in two bundled sources. `wordnet` has the lower id, so 1.4.0's
    /// lookup in any source opened every "dog" History row from WordNet.
    private static let dogRows = [
        TestDictionary.Row(word: "dog", definition: "**noun**\n1. a member of the genus Canis", pos: "noun",
                           source: "wordnet"),
        TestDictionary.Row(word: "dog", definition: "**noun**\n1. perro, can", pos: "noun",
                           source: "freedict-eng-spa"),
        TestDictionary.Row(word: "cat", definition: "**noun**\n1. a feline mammal", pos: "noun", source: "wordnet"),
    ]

    override func setUp() async throws {
        try await super.setUp()
        await DictAppTests.waitForHostAppLaunch()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
    }

    override func tearDown() async throws {
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    private var userPath: String { tempDir.appendingPathComponent("user.sqlite").path }

    /// Writes `rows` into the dictionary file `name` and opens the service on
    /// it. The user database carries over.
    @discardableResult
    private func open(_ rows: [TestDictionary.Row], name: String = "dictionary-a.sqlite") async throws -> URL {
        let url = try TestDictionary.make(rows: rows, at: tempDir.appendingPathComponent(name))
        try await db.setup(userPath: userPath, dictionaryURL: url)
        return url
    }

    private func fixture(_ ext: String) throws -> URL {
        try XCTUnwrap(Bundle.main.url(forResource: "test_import_fixture", withExtension: ext),
                      "the bundled import fixture .\(ext)")
    }

    /// Writes `rows` as an import file named `name` (its source ID).
    private func importFile(_ name: String, _ rows: [[String: String]]) throws -> URL {
        let url = tempDir.appendingPathComponent(name + ".json")
        try JSONSerialization.data(withJSONObject: rows).write(to: url)
        return url
    }

    /// A read-only connection of the test's own, outside the service.
    private func inspect(_ path: String) throws -> DatabaseQueue {
        var config = Configuration()
        config.readonly = true
        return try DatabaseQueue(path: path, configuration: config)
    }

    /// The files SQLite would create next to a database it writes.
    private func sidecars(of url: URL) -> [String] {
        ["-journal", "-wal", "-shm"].map { url.path + $0 }.filter { FileManager.default.fileExists(atPath: $0) }
    }

    private func historyItem(_ word: String, file: StaticString = #filePath,
                             line: UInt = #line) async throws -> HistoryItem {
        let items = try await db.fetchHistory()
        return try XCTUnwrap(items.first { $0.word == word }, "History row '\(word)'", file: file, line: line)
    }

    private static func keys(_ entries: [DictionaryEntry]) -> [EntryKey] {
        entries.map { EntryKey($0) }
    }

    // MARK: Dictionary file and user database

    /// Every kind of write to `dict.*` fails with SQLITE_READONLY on the
    /// writer, the one connection that writes. `dict` is the test's file
    /// itself, so iOS SQLite honours the URI (`mode=ro&immutable=1`). The
    /// file stays byte-identical with no journal next to it, and the writer
    /// keeps serving the user database.
    func testDictionaryFileIsReadOnly() async throws {
        let url = try await open(Self.dogRows)
        let bytes = try Data(contentsOf: url)

        let (files, readOnly) = try await db.writeForTesting { conn in
            let files = try Row.fetchAll(conn, sql: "PRAGMA database_list")
                .map { ($0["name"] as String, $0["file"] as String) }
            return (Dictionary(uniqueKeysWithValues: files), sqlite3_db_readonly(conn.sqliteConnection, "dict"))
        }
        let attached = try XCTUnwrap(files["dict"], "dict is attached on the writer: \(files)")
        XCTAssertEqual(URL(fileURLWithPath: attached).resolvingSymlinksInPath().path,
                       url.resolvingSymlinksInPath().path,
                       "dict is the dictionary file, not a new file named after the URI")
        XCTAssertEqual(readOnly, 1, "SQLite opened dict read-only")

        let writes = [
            "INSERT INTO dict.entries(word, word_normalized, definition, source) VALUES ('wolf', 'wolf', 'x', 'wordnet')",
            "UPDATE dict.entries SET definition = 'changed' WHERE word = 'dog'",
            "DELETE FROM dict.entries",
            "UPDATE dict.dict_metadata SET word_count = 0",
            "INSERT INTO dict.entries_fts(entries_fts) VALUES('rebuild')",
            "CREATE TABLE dict.scratch(x)",
            "DROP TABLE dict.dict_metadata",
        ]
        for sql in writes {
            do {
                try await db.writeForTesting { conn in try conn.execute(sql: sql) }
                XCTFail("'\(sql)' must fail: the dictionary file is read-only")
            } catch let error as DatabaseError {
                XCTAssertEqual(error.resultCode, .SQLITE_READONLY, "'\(sql)': \(error)")
            }
        }

        XCTAssertEqual(try Data(contentsOf: url), bytes, "the dictionary file is byte-identical")
        XCTAssertEqual(sidecars(of: url), [], "no journal, WAL or SHM next to the dictionary file")
        let dog = try await db.entry(for: EntryKey(source: "freedict-eng-spa", word: "dog"))
        XCTAssertEqual(dog?.definition, "**noun**\n1. perro, can", "readers see the original rows")
        let rows = try await db.entryCount()
        XCTAssertEqual(rows, 3)
        let found = try await db.search(query: "dog")
        XCTAssertEqual(found.count, 2)

        // The failed writes rolled back; the writer still serves the user database.
        try await db.addToHistory(word: "dog", source: "wordnet")
        let history = try await db.historyCount()
        XCTAssertEqual(history, 1)
    }

    /// History, My words and an import are written to `user.sqlite` only.
    /// The dictionary file stays byte-identical (its leftover 1.x `history`
    /// and `bookmarks` tables stay empty), and a connection of the test's
    /// own finds every row in the user tables. Removing them touches only the
    /// user database too.
    func testUserWritesLandInUserDatabase() async throws {
        let url = try await open(Self.dogRows)
        let bytes = try Data(contentsOf: url)

        try await db.addToHistory(word: "dog", source: "freedict-eng-spa")
        try await db.addToMyWords(EntryKey(source: "wordnet", word: "dog"))
        let read = try await db.importJSON(at: fixture("json"), source: fixtureSource)
        XCTAssertEqual(read, 10)

        XCTAssertEqual(try Data(contentsOf: url), bytes, "the dictionary file is never written")
        XCTAssertEqual(sidecars(of: url), [])
        let dictionaryCounts = try await inspect(url.path).read { conn -> [String: Int] in
            var counts: [String: Int] = [:]
            for table in ["entries", "history", "bookmarks"] {
                if try conn.tableExists(table) {
                    counts[table] = try Int.fetchOne(conn, sql: "SELECT COUNT(*) FROM \(table)")
                }
            }
            return counts
        }
        XCTAssertEqual(dictionaryCounts["entries"], 3)
        XCTAssertEqual(dictionaryCounts["history", default: 0], 0, "History is not written to the dictionary file")
        XCTAssertEqual(dictionaryCounts["bookmarks", default: 0], 0, "My words are not written to the dictionary file")

        let user = try await inspect(userPath).read { conn in
            (hasEntries: try conn.tableExists("entries"),
             history: try Row.fetchAll(conn, sql: "SELECT source, word FROM history")
                .map { "\($0["source"] as String)/\($0["word"] as String)" },
             myWords: try Row.fetchAll(conn, sql: "SELECT source, word FROM my_words")
                .map { "\($0["source"] as String)/\($0["word"] as String)" },
             importedSources: try String.fetchAll(conn, sql: "SELECT DISTINCT source FROM imported_entries"),
             importedCount: try Int.fetchOne(conn, sql: "SELECT COUNT(*) FROM imported_entries") ?? 0,
             lowestImportedID: try Int64.fetchOne(conn, sql: "SELECT MIN(id) FROM imported_entries") ?? 0,
             registered: try String.fetchAll(conn, sql: "SELECT source FROM imported_sources"),
             indexed: try Int.fetchOne(conn, sql: "SELECT COUNT(*) FROM imported_fts WHERE imported_fts MATCH 'qaflux'") ?? 0)
        }
        XCTAssertFalse(user.hasEntries, "the user database has no table named like a dictionary table")
        XCTAssertEqual(user.history, ["freedict-eng-spa/dog"])
        XCTAssertEqual(user.myWords, ["wordnet/dog"])
        XCTAssertEqual(user.importedSources, [fixtureSource])
        XCTAssertEqual(user.importedCount, 10)
        XCTAssertGreaterThanOrEqual(user.lowestImportedID, Self.firstImportedID, "imported ids start at 2^40")
        XCTAssertEqual(user.registered, [fixtureSource])
        XCTAssertEqual(user.indexed, 1, "the trigger indexed the import")

        try await db.clearHistory()
        try await db.removeFromMyWords(EntryKey(source: "wordnet", word: "dog"))
        try await db.clearEntries(fromSource: fixtureSource)
        let left = try await inspect(userPath).read { conn in
            try Int.fetchOne(conn, sql: """
                SELECT (SELECT COUNT(*) FROM history) + (SELECT COUNT(*) FROM my_words)
                     + (SELECT COUNT(*) FROM imported_entries) + (SELECT COUNT(*) FROM imported_sources)
                """) ?? -1
        }
        XCTAssertEqual(left, 0)
        XCTAssertEqual(try Data(contentsOf: url), bytes)
        let bundledLeft = try await db.entryCount()
        XCTAssertEqual(bundledLeft, 3)
    }

    /// An app update brings a new dictionary file with reshuffled ids (a new
    /// source first, rows reversed, one headword dropped). Both imports stay
    /// searchable in both modes with their ids, Settings still counts them,
    /// My words keys resolve to the new rows, and the key of the dropped
    /// headword stays stored but is skipped (#137 rule).
    func testImportSurvivesDictionaryFileReplacement() async throws {
        let alpha = (0..<6).map {
            TestDictionary.Row(word: "alpha\($0)", definition: "alpha word \($0)", source: "alpha")
        }
        try await open(alpha + Self.dogRows, name: "dictionary-a.sqlite")
        let json = try await db.importJSON(at: fixture("json"), source: fixtureSource)
        let sqlite = try await db.importSQLite(at: fixture("sqlite"), source: "sqlite_fixture")
        XCTAssertEqual([json, sqlite], [10, 10])

        let kept = EntryKey(source: "alpha", word: "alpha3")
        let dropped = EntryKey(source: "alpha", word: "alpha5")
        let imported = EntryKey(source: fixtureSource, word: "qaflux")
        for key in [kept, dropped, imported] {
            try await db.addToMyWords(key)
        }
        try await db.addToHistory(word: "alpha3", source: "alpha")
        let idInA = try await db.entry(for: kept)?.id
        let importedIDs = try await db.search(query: "qaflux").map(\.id)

        let fileB = [TestDictionary.Row(word: "zeta", definition: "a new source", source: "zeta")]
            + (alpha + Self.dogRows).reversed().filter { $0.word != dropped.word }
        try await open(fileB, name: "dictionary-b.sqlite")

        let keptInB = try await db.entry(for: kept)
        XCTAssertEqual(keptInB?.definition, "alpha word 3")
        XCTAssertNotNil(keptInB?.id)
        XCTAssertNotEqual(keptInB?.id, idInA, "precondition: the new file reshuffled the ids")

        let qaflux = try await db.search(query: "qaflux")
        XCTAssertEqual(Self.keys(qaflux), [imported])
        XCTAssertEqual(qaflux.map(\.id), importedIDs, "an imported row keeps its id")
        let zarboom = try await db.search(query: "zarboom")
        XCTAssertEqual(Self.keys(zarboom), [EntryKey(source: "sqlite_fixture", word: "zarboom")])
        let groups = [["alpha"], ["zeta"], ["wordnet"], ["freedict-eng-spa"], [fixtureSource], ["sqlite_fixture"]]
        let preferred = try await db.searchPreferred(query: "qaflux", groups: groups,
                                                     enabledSources: Set(groups.joined()))
        XCTAssertEqual(Self.keys(preferred), [imported], "preferred mode finds the import too")
        let jsonRows = try await db.entryCount(source: fixtureSource)
        XCTAssertEqual(jsonRows, 10)

        let stats = Dictionary(uniqueKeysWithValues: try await db.fetchSourceStats().map { ($0.source, $0.count) })
        XCTAssertEqual(stats[fixtureSource], 10)
        XCTAssertEqual(stats["sqlite_fixture"], 10)
        XCTAssertEqual(stats["alpha"], 5, "the bundled count comes from the new file")
        XCTAssertEqual(stats["zeta"], 1)

        let myWords = try await db.fetchMyWords()
        XCTAssertEqual(Set(Self.keys(myWords)), [kept, imported])
        XCTAssertEqual(myWords.first { EntryKey($0) == kept }?.id, keptInB?.id, "the key resolves to the new row")
        let droppedStored = try await db.isInMyWords(dropped)
        XCTAssertTrue(droppedStored, "a key that no longer resolves stays stored")

        let opened = await HistoryDestination.entry(for: try await historyItem("alpha3"))
        XCTAssertEqual(opened?.id, keptInB?.id, "History reopens the row of the new file")
    }

    /// A file named like a bundled source (`freedict-eng-spa.json`) adds only
    /// the words that source lacks, case-insensitively, as 1.4.0 did. They
    /// are searched, opened and counted under the bundled ID. A file whose
    /// words are all bundled stores nothing and registers no dictionary.
    func testImportNamedLikeBundledSourceAddsOnlyMissingWords() async throws {
        try await open(Self.dogRows)
        let file = try importFile("freedict-eng-spa", [
            ["word": "DOG", "definition": "imported perro"],
            ["word": "kennel", "definition": "perrera"],
            ["word": "puppy", "definition": "cachorro"],
        ])
        let read = try await db.importJSON(at: file, source: "freedict-eng-spa")
        XCTAssertEqual(read, 3, "the message counts the rows read, as in 1.4.0")

        let dog = try await db.entry(for: EntryKey(source: "freedict-eng-spa", word: "dog"))
        XCTAssertEqual(dog?.definition, "**noun**\n1. perro, can", "the bundled row wins over 'DOG'")
        let dogs = try await db.search(query: "dog")
        XCTAssertEqual(Set(Self.keys(dogs)), [EntryKey(source: "wordnet", word: "dog"),
                                               EntryKey(source: "freedict-eng-spa", word: "dog")])
        let kennel = try await db.search(query: "kennel")
        XCTAssertEqual(Self.keys(kennel), [EntryKey(source: "freedict-eng-spa", word: "kennel")])
        XCTAssertGreaterThanOrEqual(kennel.first?.id ?? 0, Self.firstImportedID)
        let puppy = try await db.entry(for: EntryKey(source: "freedict-eng-spa", word: "Puppy"))
        XCTAssertEqual(puppy?.definition, "cachorro", "an imported key resolves, case-insensitively")
        let disabled = try await db.search(query: "kennel", enabledSources: ["wordnet"])
        XCTAssertEqual(disabled, [], "the import follows its pair's enabled state")

        let stats = try await db.fetchSourceStats().filter { $0.source == "freedict-eng-spa" }
        XCTAssertEqual(stats.map(\.count), [3], "one Settings row: 1 bundled + 2 imported")

        let allBundled = try importFile("wordnet", [["word": "Cat", "definition": "another cat"]])
        _ = try await db.importJSON(at: allBundled, source: "wordnet")
        let cats = try await db.entryCount(source: "wordnet")
        XCTAssertEqual(cats, 2, "nothing stored")
        let registered = try await inspect(userPath).read { conn in
            try String.fetchAll(conn, sql: "SELECT source FROM imported_sources ORDER BY source")
        }
        XCTAssertEqual(registered, ["freedict-eng-spa"], "a file that stored nothing registers no dictionary")
    }

    /// Preferred mode with imports enabled: an import named like a bundled
    /// source ranks inside its pair's bucket (exact matches before prefix
    /// matches across both stores, one top 4), a custom import is its own
    /// bucket in Dictionary Order, and the relevance tail takes the rest.
    func testPreferredModeRanksImportsInTheirBuckets() async throws {
        try await open([
            TestDictionary.Row(word: "dog", definition: "a canine", source: "wordnet"),
            TestDictionary.Row(word: "dog", definition: "perro", source: "freedict-eng-spa"),
            TestDictionary.Row(word: "dogma", definition: "dogma", source: "freedict-eng-spa"),
            TestDictionary.Row(word: "dogo", definition: "mastiff", source: "wordnet-spa-eng"),
        ])
        _ = try await db.importJSON(at: try importFile("wordnet-spa-eng", [
            ["word": "dog", "definition": "imported perro"],
            ["word": "doggerel", "definition": "ripio"],
        ]), source: "wordnet-spa-eng")
        _ = try await db.importJSON(at: try importFile("my_dogs", [
            ["word": "dogcart", "definition": "a cart"],
            ["word": "dog", "definition": "my dog"],
        ]), source: "my_dogs")

        let groups = [["wordnet"], ["freedict-eng-spa", "wordnet-spa-eng"], ["my_dogs"]]
        let rows = Self.keys(try await db.searchPreferred(query: "dog", groups: groups,
                                                          enabledSources: Set(groups.joined())))
        let prefixRows: Set = [EntryKey(source: "freedict-eng-spa", word: "dogma"),
                               EntryKey(source: "wordnet-spa-eng", word: "dogo"),
                               EntryKey(source: "wordnet-spa-eng", word: "doggerel")]
        XCTAssertEqual(rows.count, 8, "every match once: \(rows)")
        XCTAssertEqual(Set(rows).count, 8)
        guard rows.count == 8 else { return }
        XCTAssertEqual(rows[0], EntryKey(source: "wordnet", word: "dog"))
        XCTAssertEqual(Set(rows[1...2]), [EntryKey(source: "freedict-eng-spa", word: "dog"),
                                          EntryKey(source: "wordnet-spa-eng", word: "dog")],
                       "the pair's exact matches lead its bucket, the imported one included")
        XCTAssertTrue(Set(rows[3...4]).isSubset(of: prefixRows), "then two prefix matches (top 4): \(rows)")
        XCTAssertEqual(Array(rows[5...6]), [EntryKey(source: "my_dogs", word: "dog"),
                                            EntryKey(source: "my_dogs", word: "dogcart")],
                       "the custom import's own bucket, in Dictionary Order")
        XCTAssertTrue(prefixRows.contains(rows[7]), "the tail takes the pair's fifth match")

        let relevance = Self.keys(try await db.search(query: "dog"))
        XCTAssertEqual(Set(relevance.prefix(4)), [EntryKey(source: "wordnet", word: "dog"),
                                                  EntryKey(source: "freedict-eng-spa", word: "dog"),
                                                  EntryKey(source: "wordnet-spa-eng", word: "dog"),
                                                  EntryKey(source: "my_dogs", word: "dog")],
                       "relevance mode: exact matches from both stores first")
    }

    /// The interim Bookmarks tab and star (until #158) read and write My
    /// words by `(source, word)`: the same headword in another source keeps
    /// its own star, the tab skips a key whose entry is gone, and removing a
    /// word on the tab clears its star.
    @MainActor
    func testStarAndBookmarksTabUseMyWords() async throws {
        try await open(Self.dogRows)
        let freeDictEntry = try await db.entry(for: EntryKey(source: "freedict-eng-spa", word: "dog"))
        let wordNetEntry = try await db.entry(for: EntryKey(source: "wordnet", word: "dog"))
        let freeDictDog = try XCTUnwrap(freeDictEntry)
        let wordNetDog = try XCTUnwrap(wordNetEntry)

        let star = DefinitionViewModel(entry: freeDictDog, hasVoice: { _ in false })
        await star.onAppear()
        XCTAssertFalse(star.isBookmarked)
        await star.toggleBookmark()
        XCTAssertTrue(star.isBookmarked)
        XCTAssertNil(star.errorMessage)
        let stored = try await db.isInMyWords(EntryKey(source: "freedict-eng-spa", word: "dog"))
        XCTAssertTrue(stored)

        let otherStar = DefinitionViewModel(entry: wordNetDog, hasVoice: { _ in false })
        await otherStar.onAppear()
        XCTAssertFalse(otherStar.isBookmarked, "the key is (source, word), not the word")
        let viewed = try await historyItem("dog")
        XCTAssertEqual(viewed.source, "wordnet", "opening a definition records its source")

        try await db.addToMyWords(EntryKey(source: "freedict-eng-spa", word: "wolf"))
        let tab = BookmarksViewModel()
        await tab.load()
        XCTAssertEqual(Self.keys(tab.entries), [EntryKey(freeDictDog)], "a key that does not resolve is skipped")
        XCTAssertNil(tab.errorMessage)
        let wolfStored = try await db.isInMyWords(EntryKey(source: "freedict-eng-spa", word: "wolf"))
        XCTAssertTrue(wolfStored, "and stays stored")

        await tab.remove(freeDictDog)
        XCTAssertEqual(tab.entries, [])
        let reopened = DefinitionViewModel(entry: freeDictDog, hasVoice: { _ in false })
        await reopened.onAppear()
        XCTAssertFalse(reopened.isBookmarked, "removing on the tab clears the star")
    }

    /// No user table shares a name with a table of the bundled dictionary
    /// file, so an unqualified name can never reach the wrong store. #140's
    /// `dictionaries.sqlite` no longer carries the 1.x seed's empty
    /// `history` and `bookmarks` tables.
    func testUserSchemaSharesNoTableNameWithTheDictionaryFile() async throws {
        try await db.setup(userPath: userPath, dictionaryURL: try TestDictionary.bundledURL(), packFiles: try PackFixtures.all())
        let (user, dictionary) = try await db.writeForTesting { conn in
            let tables = "type IN ('table', 'view') AND name NOT LIKE 'sqlite%'"
            return (try String.fetchAll(conn, sql: "SELECT name FROM main.sqlite_master WHERE \(tables)"),
                    try String.fetchAll(conn, sql: "SELECT name FROM dict.sqlite_master WHERE \(tables)"))
        }
        XCTAssertTrue(user.contains("imported_entries") && dictionary.contains("entries"), "\(user) / \(dictionary)")
        XCTAssertEqual(Set(user).intersection(dictionary), [])
    }

    // MARK: History rows (Kirill, 2026-10-27)

    /// A History row opens the entry of its stored source, not the first
    /// source that has the word (1.4.0 opened WordNet). The last viewed
    /// source wins, the key matches case-insensitively, an imported row
    /// opens from the user database, and a Recent word on Search carries the
    /// same source.
    @MainActor
    func testHistoryOpensStoredSource() async throws {
        try await open(Self.dogRows)
        try await db.addToHistory(word: "dog", source: "freedict-eng-spa")

        let item = try await historyItem("dog")
        XCTAssertEqual(item.source, "freedict-eng-spa")
        let opened = await HistoryDestination.entry(for: item)
        XCTAssertEqual(opened.map { EntryKey($0) }, EntryKey(source: "freedict-eng-spa", word: "dog"))
        XCTAssertEqual(opened?.definition, "**noun**\n1. perro, can")

        let search = SearchViewModel(settings: SettingsService(store: InMemoryKeyValueStore()))
        await search.loadRecent()
        let recent = try XCTUnwrap(search.recentWords.first)
        XCTAssertEqual(recent, item, "a Recent word carries the History row")
        let fromRecent = await HistoryDestination.entry(for: recent)
        XCTAssertEqual(fromRecent?.source, "freedict-eng-spa")

        try await db.addToHistory(word: "dog", source: "wordnet")
        let reread = await HistoryDestination.entry(for: try await historyItem("dog"))
        XCTAssertEqual(reread?.definition, "**noun**\n1. a member of the genus Canis", "the last viewed source wins")

        let upper = await HistoryDestination.entry(for: HistoryItem(word: "DOG", source: "freedict-eng-spa"))
        XCTAssertEqual(upper?.word, "dog", "the word matches case-insensitively")

        _ = try await db.importJSON(at: fixture("json"), source: fixtureSource)
        try await db.addToHistory(word: "qaflux", source: fixtureSource)
        let importedEntry = await HistoryDestination.entry(for: try await historyItem("qaflux"))
        XCTAssertEqual(importedEntry?.source, fixtureSource)
        XCTAssertGreaterThanOrEqual(importedEntry?.id ?? 0, Self.firstImportedID)
        XCTAssertTrue(importedEntry?.definition.hasPrefix("JSON-FIXTURE") ?? false)
    }

    /// The enabled sources only filter Search: a History row of a disabled
    /// source (or with every source off) still opens that source's entry.
    func testHistoryOpensDisabledSource() async throws {
        try await open(Self.dogRows)
        try await db.addToHistory(word: "dog", source: "freedict-eng-spa")
        let settings = SettingsService.shared
        let saved = settings.enabledSources
        defer { settings.enabledSources = saved }

        for enabled: Set<String> in [["wordnet"], []] {
            settings.enabledSources = enabled
            let visible = try await db.search(query: "dog", enabledSources: settings.enabledSources)
            XCTAssertFalse(visible.contains { $0.source == "freedict-eng-spa" },
                           "precondition: Search hides the disabled source (\(enabled))")
            let opened = await HistoryDestination.entry(for: try await historyItem("dog"))
            XCTAssertEqual(opened.map { EntryKey($0) }, EntryKey(source: "freedict-eng-spa", word: "dog"),
                           "enabled \(enabled)")
        }
    }

    /// A History row whose entry is gone shows "not found" (`nil`), with no
    /// lookup in other sources, and stays in History: a headword a
    /// dictionary update dropped (another source still has it), an imported
    /// dictionary that was removed, a source the app never had.
    func testHistoryShowsNotFoundWhenEntryMissing() async throws {
        let kennels = [TestDictionary.Row(word: "kennel", definition: "perrera", source: "freedict-eng-spa"),
                       TestDictionary.Row(word: "kennel", definition: "a dog house", source: "wordnet")]
        try await open(Self.dogRows + kennels, name: "dictionary-a.sqlite")
        try await db.addToHistory(word: "kennel", source: "freedict-eng-spa")
        _ = try await db.importJSON(at: fixture("json"), source: fixtureSource)
        try await db.addToHistory(word: "qaflux", source: fixtureSource)

        try await open(Self.dogRows + [kennels[1]], name: "dictionary-b.sqlite")
        try await db.clearEntries(fromSource: fixtureSource)

        let wordNetKennel = try await db.entry(for: EntryKey(source: "wordnet", word: "kennel"))
        XCTAssertNotNil(wordNetKennel, "precondition: another source still has the word")
        let dropped = await HistoryDestination.entry(for: try await historyItem("kennel"))
        XCTAssertNil(dropped, "a dropped headword is not found, not opened from WordNet")
        let removedImport = await HistoryDestination.entry(for: try await historyItem("qaflux"))
        XCTAssertNil(removedImport, "a removed import is not found")
        let unknown = await HistoryDestination.entry(for: HistoryItem(word: "dog", source: "freedict-deu-eng"))
        XCTAssertNil(unknown, "a source the app never had is not found")

        let words = try await db.fetchHistory().map(\.word)
        XCTAssertEqual(Set(words), ["kennel", "qaflux"], "the rows stay in History")
    }

    /// A row from before 1.3.0 has no source (`''`): it shows "not found"
    /// even though two sources have the word, and it stays in History.
    func testHistoryShowsNotFoundForEmptySource() async throws {
        try await open(Self.dogRows)
        try await db.addToHistory(word: "dog", source: "")

        let item = try await historyItem("dog")
        XCTAssertEqual(item.source, "")
        let found = try await db.search(query: "dog")
        XCTAssertEqual(found.count, 2, "precondition: both sources have the word")
        let opened = await HistoryDestination.entry(for: item)
        XCTAssertNil(opened, "no lookup in other sources")
        let words = try await db.fetchHistory().map(\.word)
        XCTAssertEqual(words, ["dog"], "the row stays in History")
    }
}

// MARK: - Issue #138: search probe against 1.4.0

/// Search on the bundled dictionary file against 1.4.0 (0129 Test plan).
/// `search-probe-1.4.0.json`, next to this file, holds the top 50
/// `(source, word)` of each probe query as 1.4.0 ranked them; it is written
/// by `Scripts/make_search_probe.py`. The test reads it from the source tree
/// (the simulator shares the Mac's file system), so it needs no target
/// membership. A PR that changes the bundled entries regenerates it.
@MainActor
final class SearchProbeTests: XCTestCase {
    private struct Probe: Decodable {
        struct Query: Decodable {
            let query: String
            let groups: [[String]]?
            let results: [[String]]
        }
        let tag: String
        let limit: Int
        let topN: Int
        let relevance: [Query]
        let preferred: [Query]
    }

    private var tempDir: URL!
    private var db: DatabaseService { .shared }
    private let jsonSource = "test_import_fixture"
    private let sqliteSource = "test_import_fixture_sqlite"

    override func setUp() async throws {
        try await super.setUp()
        await DictAppTests.waitForHostAppLaunch()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        try await db.setup(userPath: tempDir.appendingPathComponent("user.sqlite").path,
                           dictionaryURL: try TestDictionary.bundledURL(), packFiles: try PackFixtures.all())
    }

    override func tearDown() async throws {
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    /// A golden file: the 2.0 lists by default (`make_search_probe.py
    /// --packs`, #237), or 1.4.0's.
    private static func loadProbe(_ name: String = "search-probe-2.0.json", tag: String = "2.0") throws -> Probe {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .appendingPathComponent(name)
        let data = try XCTUnwrap(try? Data(contentsOf: url),
                                 "golden file missing at \(url.path); run Scripts/make_search_probe.py")
        let probe = try JSONDecoder().decode(Probe.self, from: data)
        XCTAssertEqual(probe.tag, tag)
        XCTAssertEqual(probe.limit, 50)
        XCTAssertEqual(probe.topN, Search.preferredDictionaryTopN)
        XCTAssertGreaterThanOrEqual(probe.relevance.count, 20)
        XCTAssertEqual(probe.preferred.count, 3)
        let sources = Set((probe.relevance + probe.preferred).flatMap { $0.results.map { $0[0] } })
        XCTAssertEqual(sources.count, 9, "the probe reaches every bundled dictionary: \(sources.sorted())")
        return probe
    }

    private static func keys(_ entries: [DictionaryEntry]) -> [[String]] {
        entries.map { [$0.source, $0.word] }
    }

    /// Fails with the first position where `got` leaves the golden list.
    private func assertSameList(_ got: [[String]], _ expected: [[String]], _ label: String,
                                file: StaticString = #filePath, line: UInt = #line) {
        guard got != expected else { return }
        let index = zip(got, expected).enumerated().first { $0.element.0 != $0.element.1 }?.offset
            ?? min(got.count, expected.count)
        let gotRow = index < got.count ? got[index].joined(separator: "/") : "end"
        let expectedRow = index < expected.count ? expected[index].joined(separator: "/") : "end"
        XCTFail("\(label): row \(index + 1) is \(gotRow), the golden file has \(expectedRow) "
                + "(\(got.count) rows against \(expected.count))", file: file, line: line)
    }

    /// The rows of `rows` that match the query exactly: their
    /// `word_normalized` is its folded or raw key, as `is_exact` ranks them.
    private static func exactRows(_ rows: [[String]], query: String, in shipped: BundledDictionary) throws -> [[String]] {
        let fts = Search.ftsQuery(sanitized: query.trimmingCharacters(in: .whitespaces))
        return try shipped.read { db in
            try rows.filter { row in
                try Bool.fetchOne(db, sql: """
                    SELECT EXISTS (SELECT 1 FROM entries WHERE source = ? AND word = ? COLLATE NOCASE AND word = ?
                        AND (word_normalized = ? COLLATE NOCASE OR word_normalized = ? COLLATE NOCASE))
                    """, arguments: [row[0], row[1], row[1], fts.rankKey, fts.rawKey]) ?? false
            }
        }
    }

    private func fixture(_ ext: String) throws -> URL {
        try XCTUnwrap(Bundle.main.url(forResource: "test_import_fixture", withExtension: ext))
    }

    /// #237 (0237, "Search ranking"): with every pack installed, every probe
    /// list, relevance and preferred mode, equals the 2.0 golden list, which
    /// `make_search_probe.py --packs` writes with the same SQL.
    func testProbeMatches20() async throws {
        let probe = try Self.loadProbe()
        for item in probe.relevance {
            let got = try await db.search(query: item.query, limit: probe.limit)
            assertSameList(Self.keys(got), item.results, "relevance '\(item.query)'")
        }
        for item in probe.preferred {
            let groups = try XCTUnwrap(item.groups)
            let got = try await db.searchPreferred(query: item.query, groups: groups,
                                                   enabledSources: Set(groups.joined()),
                                                   topN: probe.topN, limit: probe.limit)
            assertSameList(Self.keys(got), item.results, "preferred '\(item.query)'")
        }
    }

    /// #237 (Kirill, 2026-11-04): across the files, every relevance query
    /// keeps 1.4.0's exact-match rows; only the order of the prefix and FTS
    /// tiers changes.
    func testExactRowsMatch140() async throws {
        let probe = try Self.loadProbe("search-probe-1.4.0.json", tag: "v1.4.0")
        let shipped = try BundledDictionary.shipped()
        for item in probe.relevance {
            let got = Self.keys(try await db.search(query: item.query, limit: probe.limit))
            let exactGot = try Self.exactRows(got, query: item.query, in: shipped)
            let exactExpected = try Self.exactRows(item.results, query: item.query, in: shipped)
            XCTAssertEqual(Set(exactGot.map { $0.joined(separator: "/") }),
                           Set(exactExpected.map { $0.joined(separator: "/") }), "exact rows of '\(item.query)'")
        }
    }

    /// #241 (0237, "Reading across files"): the per-branch `ORDER BY …
    /// LIMIT` keeps every probe list, relevance and preferred mode, the same
    /// as one ORDER BY over every matching row. The seam really drops the
    /// branch sorts: the plan has one sort per branch more with them.
    func testBranchLimitKeepsTheLists() async throws {
        let probe = try Self.loadProbe()
        defer { DatabaseService.branchLimitEnabled = true }
        for item in probe.relevance {
            DatabaseService.branchLimitEnabled = true
            let limited = Self.keys(try await db.search(query: item.query, limit: probe.limit))
            DatabaseService.branchLimitEnabled = false
            let unlimited = Self.keys(try await db.search(query: item.query, limit: probe.limit))
            assertSameList(limited, unlimited, "relevance '\(item.query)' with and without the branch limit")
            XCTAssertEqual(limited.count, item.results.count, "relevance '\(item.query)'")
        }
        for item in probe.preferred {
            let groups = try XCTUnwrap(item.groups)
            var lists: [[[String]]] = []
            for enabled in [true, false] {
                DatabaseService.branchLimitEnabled = enabled
                lists.append(Self.keys(try await db.searchPreferred(query: item.query, groups: groups,
                                                                    enabledSources: Set(groups.joined()),
                                                                    topN: probe.topN, limit: probe.limit)))
            }
            assertSameList(lists[0], lists[1], "preferred '\(item.query)' with and without the branch limit")
        }

        let sorts: (Bool) async throws -> Int = { enabled in
            DatabaseService.branchLimitEnabled = enabled
            return try await self.db.searchFilesForTesting(query: "casa").plan
                .filter { $0.contains("TEMP B-TREE") }.count
        }
        let withLimit = try await sorts(true)
        let withoutLimit = try await sorts(false)
        XCTAssertEqual(withLimit - withoutLimit, 5, "one sort per file: the bundle and four language packs")
    }

    /// #241 (0237, "Reading across files"): a search reads only the files
    /// that hold an enabled source; `nil` reads every file with a
    /// dictionary (not `eng_lists`). The bytecode's `OpenRead`s name the
    /// files; the plan has one FTS scan per file.
    func testOnlyEnabledFilesAreSearched() async throws {
        let cases: [(enabled: Set<String>?, files: Set<String>)] = [
            (["wordnet-spa-eng"], ["spa"]),
            (["freedict-eng-spa", "wordnet-spa-eng"], ["spa"]),
            (["wordnet"], ["dict"]),
            (["openrussian", "wordnet-arb-eng"], ["rus", "arb"]),
            (["wordnet", "wordnet-ell-eng", "freedict-eng-ell"], ["dict", "ell"]),
            (nil, ["dict", "spa", "rus", "arb", "ell"]),
        ]
        for (enabled, files) in cases {
            let read = try await db.searchFilesForTesting(query: "casa", enabledSources: enabled)
            let label = enabled.map { $0.sorted().joined(separator: ",") } ?? "nil"
            XCTAssertEqual(read.files, files, "enabled \(label)")
            XCTAssertEqual(read.plan.filter { $0.contains("VIRTUAL TABLE") }.count, files.count,
                           "enabled \(label): one FTS scan per file: \(read.plan)")
        }

        // An enabled import adds the user database's branch. Known deviation
        // (#241): a source no file claims reads from the bundle, so the
        // bundle's FTS is scanned too, finding nothing of the import's.
        _ = try await db.importJSON(at: fixture("json"), source: jsonSource)
        let imported = try await db.searchFilesForTesting(query: "json", enabledSources: [jsonSource])
        XCTAssertEqual(imported.files, ["dict", "main"])
        let both = try await db.searchFilesForTesting(query: "json", enabledSources: [jsonSource, "openrussian"])
        XCTAssertEqual(both.files, ["dict", "rus", "main"])

        // With only the Spanish pack attached, Russian reads no file at all.
        try await db.setup(userPath: tempDir.appendingPathComponent("spa-user.sqlite").path,
                           dictionaryURL: try TestDictionary.bundledURL(),
                           packFiles: [.spa: try PackFixtures.file(.spa)])
        let missing = try await db.searchFilesForTesting(query: "дом", enabledSources: ["openrussian"])
        XCTAssertEqual(missing.files, [])
        XCTAssertEqual(missing.plan, [])
        let everything = try await db.searchFilesForTesting(query: "casa")
        XCTAssertEqual(everything.files, ["dict", "spa"], "nil: the installed files only")
    }

    /// Ids never collide across files: a search over every file returns
    /// each id once, and each row's id lies in its file's `ord << 32` range.
    func testIdsAreUniqueAcrossFiles() async throws {
        let catalog = try PackFixtures.catalog()
        let ord = Dictionary(uniqueKeysWithValues: catalog.sources.map { source in
            (source.source, Int64(catalog.pack(source.packID)?.ord ?? -1))
        })
        for query in ["a", "casa", "νερο", "дом", "ماء"] {
            let rows = try await db.search(query: query, limit: 200)
            let ids = rows.compactMap(\.id)
            XCTAssertEqual(ids.count, rows.count, "'\(query)': every row has an id")
            XCTAssertEqual(Set(ids).count, ids.count, "'\(query)': ids are unique across files")
            for row in rows {
                let id = try XCTUnwrap(row.id)
                XCTAssertEqual(id >> 32, ord[row.source] ?? 0, "\(row.source) '\(row.word)': id \(id) in its file's range")
                XCTAssertLessThan(id, Int64(1) << 40)
            }
        }
    }

    /// With both fixtures imported: the bundled rows of every list keep
    /// the golden order (imported rows only interleave), each list holds every
    /// imported match up to the limit, `qaflux` and `zarboom` come first and
    /// `json` returns exactly the 10 JSON fixture rows.
    func testProbeWithFixtureImports() async throws {
        let probe = try Self.loadProbe()
        let read = [try await db.importJSON(at: fixture("json"), source: jsonSource),
                    try await db.importSQLite(at: fixture("sqlite"), source: sqliteSource)]
        XCTAssertEqual(read, [10, 10])
        let imported: Set = [jsonSource, sqliteSource]

        for item in probe.relevance {
            let got = try await db.search(query: item.query, limit: probe.limit)
            let bundled = got.filter { !imported.contains($0.source) }
            assertSameList(Self.keys(bundled), Array(item.results.prefix(bundled.count)),
                           "relevance '\(item.query)', bundled rows")
            let importedMatches = try await db.search(query: item.query, limit: 1_000, enabledSources: imported).count
            XCTAssertEqual(got.count, min(probe.limit, item.results.count + importedMatches),
                           "relevance '\(item.query)': imports add rows, never hide one below the limit")
        }
        for item in probe.preferred {
            let groups = try XCTUnwrap(item.groups) + [[jsonSource], [sqliteSource]]
            let got = try await db.searchPreferred(query: item.query, groups: groups,
                                                   enabledSources: Set(groups.joined()),
                                                   topN: probe.topN, limit: probe.limit)
            let bundled = got.filter { !imported.contains($0.source) }
            assertSameList(Self.keys(bundled), Array(item.results.prefix(bundled.count)),
                           "preferred '\(item.query)', bundled rows")
            XCTAssertEqual(got.count, probe.limit, "preferred '\(item.query)'")
        }

        let qaflux = try await db.search(query: "qaflux")
        XCTAssertEqual(Self.keys(qaflux).first, [jsonSource, "qaflux"])
        let zarboom = try await db.search(query: "zarboom")
        XCTAssertEqual(Self.keys(zarboom).first, [sqliteSource, "zarboom"])

        let fixtureWords = try JSONDecoder().decode([[String: String]].self, from: Data(contentsOf: fixture("json")))
            .compactMap { $0["word"] }
        let json = try await db.search(query: "json")
        XCTAssertEqual(json.count, 10)
        XCTAssertEqual(Set(Self.keys(json)), Set(fixtureWords.map { [jsonSource, $0] }))
        XCTAssertTrue(json.allSatisfy { ($0.id ?? 0) >= 1 << 40 }, "imported ids start at 2^40")
    }
}

// MARK: - Issue #139: 1.x migration

/// The move of a 1.x database into the user database (0129, "1.x
/// migration"). The fixtures next to this file (`legacy-1.2.0.sqlite`,
/// `legacy-1.3.0.sqlite`, `legacy-1.4.0.sqlite`) are 1.x databases written by
/// `Scripts/make_legacy_fixtures.py`: a subset of each release's bundled rows,
/// two imports, bookmarks and History. The tests read them from the source
/// tree through `#filePath`, like the search probe, so the target needs no
/// resource. Each test copies one into a simulated `Application
/// Support/DictApp` folder and attaches the bundled dictionary file, so the
/// 1.x copy of the bundled rows is recognised and dropped.
@MainActor
final class LegacyMigrationTests: XCTestCase {
    /// What a fixture holds, as the script writes it.
    private struct Fixture {
        let name: String
        /// The import named like a bundled source.
        let named: String
        /// Bookmark keys in bookmark order, dated `bookmarkedAt(i)`.
        let bookmarks: [EntryKey]
        let historyCount: Int
    }

    private static let glossary = "my_glossary"
    private static let glossaryWords = ["house", "housesitter", "zorblat", "quindle", "flumox", "brantoor", "wexley"]
    /// The named import also had "dog", which 1.x skipped: the bundle has it.
    private static let namedWords = ["doomscroll", "photobomb", "dogsitter"]

    private static let v140 = Fixture(
        name: "legacy-1.4.0.sqlite", named: "freedict-eng-spa",
        bookmarks: [EntryKey(source: "wordnet", word: "dog"), EntryKey(source: "freedict-eng-spa", word: "house"),
                    EntryKey(source: "openrussian", word: "дом"), EntryKey(source: "wordnet-arb-eng", word: "كِتاب"),
                    EntryKey(source: "freedict-ell-eng", word: "σπίτι"), EntryKey(source: glossary, word: "zorblat"),
                    EntryKey(source: "freedict-eng-spa", word: "dogsitter")],
        historyCount: 8)
    private static let v130 = Fixture(
        name: "legacy-1.3.0.sqlite", named: "freedict-eng-spa",
        bookmarks: v140.bookmarks.filter { $0.source != "freedict-ell-eng" },
        historyCount: 7)
    /// The 1.1/1.2 shape: no `history.source`, WordNet and OpenRussian only.
    private static let v120 = Fixture(
        name: "legacy-1.2.0.sqlite", named: "wordnet",
        bookmarks: [EntryKey(source: "wordnet", word: "dog"), EntryKey(source: "openrussian", word: "дом"),
                    EntryKey(source: glossary, word: "zorblat"), EntryKey(source: "wordnet", word: "dogsitter")],
        historyCount: 5)

    private static func bookmarkedAt(_ index: Int) -> String {
        String(format: "2026-06-01 %02d:00:00", 9 + index)
    }

    private var tempDir: URL!
    private var db: DatabaseService { .shared }
    /// The simulated `Application Support/DictApp` folder.
    private var appSupport: URL { tempDir.appendingPathComponent("DictApp") }
    private var legacyURL: URL { appSupport.appendingPathComponent("dict.sqlite") }
    private var userPath: String { appSupport.appendingPathComponent("user.sqlite").path }
    private static let userFiles: Set = ["user.sqlite", "user.sqlite-wal", "user.sqlite-shm"]

    override func setUp() async throws {
        try await super.setUp()
        executionTimeAllowance = 60
        await DictAppTests.waitForHostAppLaunch()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: appSupport, withIntermediateDirectories: true)
        try await db.setup(userPath: userPath, dictionaryURL: try TestDictionary.bundledURL(), packFiles: try PackFixtures.all())
    }

    override func tearDown() async throws {
        LegacyMigration.failBeforeCommit = false
        LegacyMigration.failBeforeDelete = false
        LegacyMigration.beforeCopy = nil
        try? FileManager.default.setAttributes([.posixPermissions: 0o644], ofItemAtPath: legacyURL.path)
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    // MARK: Helpers

    private static func fixtureURL(_ name: String) -> URL {
        URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent(name)
    }

    /// Copies the fixture `name` into the app folder as the 1.x `dict.sqlite`.
    private func install(_ name: String) throws {
        let source = Self.fixtureURL(name)
        XCTAssertTrue(FileManager.default.fileExists(atPath: source.path),
                      "fixture missing at \(source.path); run Scripts/make_legacy_fixtures.py")
        try? FileManager.default.removeItem(at: legacyURL)
        try FileManager.default.copyItem(at: source, to: legacyURL)
    }

    /// Copies the fixture `name` into the app folder and edits it with
    /// `edit`, in one transaction, for rows the fixtures do not hold.
    /// Foreign keys are off, so a test can leave a bookmark without its entry.
    private func install(_ name: String, editedBy edit: (Database) throws -> Void) throws {
        try install(name)
        var config = Configuration()
        config.foreignKeysEnabled = false
        let queue = try DatabaseQueue(path: legacyURL.path, configuration: config)
        try queue.write(edit)
        try queue.close()
    }

    /// Holds the move on the writer, inside its transaction, until `release`
    /// is signalled (30 s at most).
    private final class MoveGate: @unchecked Sendable {
        private let lock = NSLock()
        private var isEntered = false
        let release = DispatchSemaphore(value: 0)
        var entered: Bool { lock.withLock { isEntered } }
        func enter() { lock.withLock { isEntered = true } }
    }

    /// Starts moving the installed 1.x file and returns once the move waits
    /// inside its transaction (the `beforeCopy` seam), before the copy.
    private func startHeldMove(file: StaticString = #filePath,
                               line: UInt = #line) async throws -> (move: Task<Void, Never>, gate: MoveGate) {
        let gate = MoveGate()
        LegacyMigration.beforeCopy = {
            gate.enter()
            _ = gate.release.wait(timeout: .now() + 30)
        }
        let task = await db.startLegacyMigration(legacyURL: legacyURL)
        let move = try XCTUnwrap(task, file: file, line: line)
        let deadline = Date().addingTimeInterval(10)
        while !gate.entered, Date() < deadline {
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        XCTAssertTrue(gate.entered, "the move is inside its transaction", file: file, line: line)
        return (move, gate)
    }

    /// `datetime('now')` as SQLite writes it (UTC), for comparing dates the
    /// move stamps.
    private static func sqliteNow() -> String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(identifier: "UTC")
        formatter.dateFormat = "yyyy-MM-dd HH:mm:ss"
        return formatter.string(from: Date())
    }

    /// Runs the move to its end and returns how long it took.
    @discardableResult
    private func move(file: StaticString = #filePath, line: UInt = #line) async throws -> TimeInterval {
        let started = Date()
        let task = await db.startLegacyMigration(legacyURL: legacyURL)
        let move = try XCTUnwrap(task, "a 1.x file is there, so a move starts", file: file, line: line)
        await move.value
        return Date().timeIntervalSince(started)
    }

    private func exists(_ path: String) -> Bool { FileManager.default.fileExists(atPath: path) }

    /// The 1.x file and its sidecars that are still on disk.
    private func legacyFiles() -> [String] {
        ["", "-wal", "-shm", "-journal"].map { legacyURL.path + $0 }.filter(exists)
    }

    /// A connection of the test's own on a copy of `url`: 1.x files are in
    /// WAL mode, which a read-only connection cannot open without its `-shm`.
    /// The `-wal` comes along, so rows not yet checkpointed are counted.
    private func inspectCopy(of url: URL) throws -> DatabaseQueue {
        let copy = tempDir.appendingPathComponent("inspect-\(UUID().uuidString).sqlite")
        try FileManager.default.copyItem(at: url, to: copy)
        if exists(url.path + "-wal") {
            try FileManager.default.copyItem(atPath: url.path + "-wal", toPath: copy.path + "-wal")
        }
        return try DatabaseQueue(path: copy.path)
    }

    /// History rows as `word|source|looked_at`, in id order. `source` is
    /// `''` where the table has no such column (1.1, 1.2); a NULL date reads
    /// `NULL`.
    nonisolated private static func historyRows(_ conn: Database) throws -> [String] {
        let hasSource = try Row.fetchAll(conn, sql: "PRAGMA table_info(history)")
            .contains { ($0["name"] as String?) == "source" }
        return try Row.fetchAll(conn, sql: """
            SELECT word, \(hasSource ? "source" : "''") AS source, looked_at FROM history ORDER BY id
            """).map { "\($0["word"] as String)|\($0["source"] as String)|\(($0["looked_at"] as String?) ?? "NULL")" }
    }

    /// The user database as a connection of the test's own reads it.
    private struct UserState {
        var history: [String] = []
        /// `source/word|added_at`, in insertion order.
        var myWords: [String] = []
        /// `source/word`, in id order.
        var imported: [String] = []
        var lowestImportedID: Int64 = 0
        /// `source|imported_at`.
        var importedSources: [String] = []
        var marker: String?
    }

    private func userState() throws -> UserState {
        var config = Configuration()
        config.readonly = true
        return try DatabaseQueue(path: userPath, configuration: config).read { conn in
            UserState(
                history: try Self.historyRows(conn),
                myWords: try Row.fetchAll(conn, sql: "SELECT source, word, added_at FROM my_words ORDER BY added_at")
                    .map { "\($0["source"] as String)/\($0["word"] as String)|\($0["added_at"] as String)" },
                imported: try Row.fetchAll(conn, sql: "SELECT source, word FROM imported_entries ORDER BY id")
                    .map { "\($0["source"] as String)/\($0["word"] as String)" },
                lowestImportedID: try Int64.fetchOne(conn, sql: "SELECT MIN(id) FROM imported_entries") ?? 0,
                importedSources: try Row.fetchAll(conn, sql: "SELECT source, imported_at FROM imported_sources ORDER BY source")
                    .map { "\($0["source"] as String)|\($0["imported_at"] as String)" },
                marker: try String.fetchOne(conn, sql: "SELECT value FROM user_meta WHERE key = ?",
                                            arguments: [LegacyMigration.markerKey]))
        }
    }

    /// `imported_fts` matches `imported_entries` exactly (FTS5 integrity-check
    /// on the writer), so a rolled-back move left no stray index rows.
    private func assertImportIndexIntact(file: StaticString = #filePath, line: UInt = #line) async {
        do {
            try await db.writeForTesting { conn in
                try conn.execute(sql: "INSERT INTO imported_fts(imported_fts) VALUES('integrity-check')")
            }
        } catch {
            XCTFail("imported_fts integrity-check: \(error)", file: file, line: line)
        }
    }

    private static func keys(_ entries: [DictionaryEntry]) -> [EntryKey] {
        entries.map { EntryKey($0) }
    }

    /// The imports of `fixture` after a move, in 1.x row order.
    private static func expectedImports(_ fixture: Fixture) -> [String] {
        glossaryWords.map { "\(glossary)/\($0)" } + namedWords.map { "\(fixture.named)/\($0)" }
    }

    /// Moves `fixture` and checks every kind of user data: each bookmark is
    /// a My words key that resolves, dated by the bookmark; History is equal
    /// row for row; exactly the two imports moved (none of the 1.x copy of
    /// the bundled rows), above 2^40, indexed, registered with their earliest
    /// date and searchable; the marker is set; the 1.x file is gone.
    private func assertMigrates(_ fixture: Fixture, file: StaticString = #filePath, line: UInt = #line) async throws {
        try install(fixture.name)
        let legacyHistory = try await inspectCopy(of: legacyURL).read { try Self.historyRows($0) }
        XCTAssertEqual(legacyHistory.count, fixture.historyCount, "precondition", file: file, line: line)

        let seconds = try await move(file: file, line: line)
        print("LegacyMigrationTests: \(fixture.name) moved in \(Int(seconds * 1000)) ms")

        let state = try userState()
        XCTAssertEqual(state.history, legacyHistory, "History is equal row for row", file: file, line: line)
        XCTAssertEqual(state.myWords, fixture.bookmarks.enumerated().map {
            "\($0.element.source)/\($0.element.word)|\(Self.bookmarkedAt($0.offset))"
        }, "each bookmark is a My words key, dated by the bookmark", file: file, line: line)
        let myWords = try await db.fetchMyWords()
        XCTAssertEqual(Self.keys(myWords), fixture.bookmarks.reversed(), "every key resolves, newest first",
                       file: file, line: line)

        XCTAssertEqual(state.imported, Self.expectedImports(fixture),
                       "exactly the two imports moved; the 1.x copy of the bundled rows did not", file: file, line: line)
        XCTAssertGreaterThanOrEqual(state.lowestImportedID, 1 << 40, file: file, line: line)
        XCTAssertEqual(state.importedSources, [
            "\(Self.glossary)|2026-05-10 12:00:00", "\(fixture.named)|2026-05-20 19:30:00",
        ].sorted(), "one row per import, dated by its earliest row", file: file, line: line)
        await assertImportIndexIntact(file: file, line: line)
        let zorblat = try await db.search(query: "zorblat")
        XCTAssertEqual(Self.keys(zorblat), [EntryKey(source: Self.glossary, word: "zorblat")], file: file, line: line)
        let dogsitter = try await db.search(query: "dogsitter")
        XCTAssertEqual(Self.keys(dogsitter), [EntryKey(source: fixture.named, word: "dogsitter")],
                       "the import named like a bundled source is searchable under its ID", file: file, line: line)
        let dog = try await db.entry(for: EntryKey(source: fixture.named, word: "dog"))
        XCTAssertNil(dog?.createdAt, "\"dog\" stays the bundled row", file: file, line: line)

        XCTAssertNotNil(state.marker, "the marker is set", file: file, line: line)
        XCTAssertEqual(legacyFiles(), [], "the 1.x file is gone", file: file, line: line)
    }

    /// `enabled_sources` and `dictionary_order`, as a 1.x install stored
    /// them, still apply after the move: the launch normalisation leaves
    /// them alone, Search filters and orders by them, and Dictionary Order
    /// lists the moved import where it stood, with the pair counts.
    @MainActor
    private func assertPreferencesStillApply(_ fixture: Fixture, file: StaticString = #filePath,
                                             line: UInt = #line) async throws {
        let bundled = try await db.fetchMetadata().map(\.source)
        let store = InMemoryKeyValueStore()
        let settings = SettingsService(store: store)
        settings.selectedUILanguageCode = "en"
        let order = DictionaryGrouping.groupedOrder([Self.glossary] + bundled)
        let enabled = Set(bundled + [Self.glossary]).subtracting(["wordnet-arb-eng"])
        settings.dictionaryOrder = order
        settings.enabledSources = enabled
        let writes = store.writeLog.count

        settings.normalizeDictionaryPreferences(knownSources: bundled)
        XCTAssertEqual(store.writeLog.count, writes, "the launch normalisation changes nothing", file: file, line: line)

        let house = Self.keys(try await db.search(query: "house", enabledSources: settings.enabledSources))
        XCTAssertTrue(house.contains(EntryKey(source: Self.glossary, word: "house")), "\(house)", file: file, line: line)
        XCTAssertTrue(house.contains(EntryKey(source: "wordnet", word: "house")), file: file, line: line)
        let arabic = try await db.search(query: "كتاب", enabledSources: settings.enabledSources)
        XCTAssertFalse(arabic.contains { $0.source == "wordnet-arb-eng" }, "a disabled pair stays off",
                       file: file, line: line)
        let preferred = try await db.searchPreferred(
            query: "house", groups: DictionaryGrouping.sourceGroups(order: try XCTUnwrap(settings.dictionaryOrder)),
            enabledSources: try XCTUnwrap(settings.enabledSources))
        XCTAssertEqual(Self.keys(Array(preferred.prefix(2))), [EntryKey(source: Self.glossary, word: "house"),
                                                               EntryKey(source: Self.glossary, word: "housesitter")],
                       "the import's bucket leads, as in the stored order", file: file, line: line)

        let localization = LocalizationManager(settingsService: settings, bundle: .main)
        let vm = SettingsViewModel(settingsService: settings, localization: localization)
        await vm.loadDictionaries()
        XCTAssertEqual(vm.dictionaries.first?.id, "custom:\(Self.glossary)", file: file, line: line)
        XCTAssertEqual(vm.dictionaries.first?.count, Self.glossaryWords.count, file: file, line: line)
        XCTAssertEqual(vm.dictionaries.first { $0.id == "arb-eng" }?.isEnabled, false, file: file, line: line)
        let metadata = try await db.fetchMetadata()
        let bundledSpanish = metadata.filter { ["freedict-eng-spa", "wordnet-spa-eng"].contains($0.source) }
            .reduce(0) { $0 + $1.wordCount }
        XCTAssertEqual(vm.dictionaries.first { $0.id == "eng-spa" }?.count, bundledSpanish + Self.namedWords.count,
                       "the pair counts the import named like its source", file: file, line: line)
        XCTAssertFalse(vm.dictionaries.contains { $0.id == "custom:\(fixture.named)" },
                       "the import named like a bundled source joins its pair, with no row of its own",
                       file: file, line: line)
        XCTAssertEqual(settings.dictionaryOrder, order, file: file, line: line)
        XCTAssertEqual(settings.enabledSources, enabled, file: file, line: line)
    }

    // MARK: Upgrades

    /// Upgrade from 1.4.0 keeps bookmarks (as My words), History, both
    /// imports and the preferences.
    @MainActor
    func testMigrates140Fixture() async throws {
        try await assertMigrates(Self.v140)
        try await assertPreferencesStillApply(Self.v140)
    }

    /// Upgrade from 1.3.0, before Greek: the same.
    @MainActor
    func testMigrates130Fixture() async throws {
        try await assertMigrates(Self.v130)
        try await assertPreferencesStillApply(Self.v130)
    }

    /// A 1.1 or 1.2 database has no `history.source` (and no
    /// `word_normalized`): History moves with `source = ''`, and such a row
    /// shows "not found" (#138). Bookmarks and imports move as from 1.4.0.
    func testMigratesDatabaseWithoutHistorySource() async throws {
        try install(Self.v120.name)
        let columns = try await inspectCopy(of: legacyURL).read { conn in
            (history: try Row.fetchAll(conn, sql: "PRAGMA table_info(history)").map { $0["name"] as String },
             entries: try Row.fetchAll(conn, sql: "PRAGMA table_info(entries)").map { $0["name"] as String })
        }
        XCTAssertFalse(columns.history.contains("source"), "precondition: \(columns.history)")
        XCTAssertFalse(columns.entries.contains("word_normalized"), "precondition: \(columns.entries)")

        try await assertMigrates(Self.v120)
        let history = try await db.fetchHistory()
        XCTAssertEqual(history.count, Self.v120.historyCount)
        XCTAssertTrue(history.allSatisfy { $0.source.isEmpty }, "\(history)")
        let dog = try XCTUnwrap(history.first { $0.word == "dog" })
        let opened = await HistoryDestination.entry(for: dog)
        XCTAssertNil(opened, "a row without a source shows \"not found\"")
    }

    // MARK: Crash safety

    /// Killed before the commit (the seam throws inside the transaction):
    /// the user database is unchanged, with no marker and no stray index
    /// rows, the 1.x file is intact, and the waiting calls go on. The next
    /// launch moves everything once, with exact counts.
    func testKilledBeforeCommitRetriesWithoutDuplicates() async throws {
        try install(Self.v140.name)
        let legacyCounts = try await inspectCopy(of: legacyURL).read { conn in
            try Int.fetchAll(conn, sql: """
                SELECT COUNT(*) FROM entries UNION ALL SELECT COUNT(*) FROM history
                UNION ALL SELECT COUNT(*) FROM bookmarks
                """)
        }

        LegacyMigration.failBeforeCommit = true
        try await move()
        let rolledBack = try userState()
        XCTAssertEqual(rolledBack.history + rolledBack.myWords + rolledBack.imported + rolledBack.importedSources, [])
        XCTAssertNil(rolledBack.marker)
        await assertImportIndexIntact()
        // SQLite may leave the 1.x `-wal` and `-shm` after the DETACH; the delete takes them too.
        XCTAssertTrue(exists(legacyURL.path), "the 1.x file stays")
        let stillThere = try await inspectCopy(of: legacyURL).read { conn in
            try Int.fetchAll(conn, sql: """
                SELECT COUNT(*) FROM entries UNION ALL SELECT COUNT(*) FROM history
                UNION ALL SELECT COUNT(*) FROM bookmarks
                """)
        }
        XCTAssertEqual(stillThere, legacyCounts, "the 1.x data is intact")
        let waiting = try await db.fetchHistory()
        XCTAssertEqual(waiting, [], "a call waiting for the failed move goes on with the user database")

        LegacyMigration.failBeforeCommit = false
        try await move()
        let state = try userState()
        XCTAssertEqual(state.history.count, Self.v140.historyCount)
        XCTAssertEqual(state.myWords.count, Self.v140.bookmarks.count)
        XCTAssertEqual(state.imported, Self.expectedImports(Self.v140))
        XCTAssertEqual(state.importedSources.count, 2)
        XCTAssertNotNil(state.marker)
        await assertImportIndexIntact()
        let zorblat = try await db.search(query: "zorblat")
        XCTAssertEqual(zorblat.count, 1, "indexed once")
        XCTAssertEqual(legacyFiles(), [])
    }

    /// Killed after the commit (the seam stops before the delete): the data
    /// is in and the marker set, and the 1.x file is still there. The next
    /// launch only deletes it: what the user changed in between stays
    /// changed, nothing is copied twice, and Search does not re-run.
    func testKilledAfterCommitOnlyDeletes() async throws {
        try install(Self.v140.name)
        let committed = expectation(forNotification: LegacyMigration.didCommit, object: nil)
        LegacyMigration.failBeforeDelete = true
        try await move()
        await fulfillment(of: [committed], timeout: 5)
        let first = try userState()
        let marker = try XCTUnwrap(first.marker)
        XCTAssertEqual(first.imported.count, 10)
        XCTAssertEqual(first.myWords.count, Self.v140.bookmarks.count)
        XCTAssertTrue(exists(legacyURL.path), "killed before the delete")

        try await db.removeFromMyWords(EntryKey(source: "wordnet", word: "dog"))
        try await db.clearEntries(fromSource: Self.glossary)
        try await db.addToHistory(word: "dog", source: "freedict-eng-spa")

        LegacyMigration.failBeforeDelete = false
        let noRerun = expectation(forNotification: LegacyMigration.didCommit, object: nil)
        noRerun.isInverted = true
        try await move()
        await fulfillment(of: [noRerun], timeout: 0.5)
        XCTAssertEqual(legacyFiles(), [], "the next launch deletes the file")
        let state = try userState()
        XCTAssertEqual(state.marker, marker, "the marker is not rewritten")
        XCTAssertEqual(state.myWords.count, Self.v140.bookmarks.count - 1, "a removed My word does not come back")
        XCTAssertEqual(state.imported, Self.namedWords.map { "\(Self.v140.named)/\($0)" },
                       "a removed import does not come back")
        XCTAssertEqual(state.history.count, Self.v140.historyCount)
        XCTAssertTrue(state.history.contains { $0.hasPrefix("dog|freedict-eng-spa|") },
                      "a later History view is kept: \(state.history)")
    }

    // MARK: Files

    /// A 1.x database the app was killed with, a History row still only in
    /// its WAL: the move replays the WAL (the file is attached read-write),
    /// so the row moves too. Then `dict.sqlite`, `-wal` and `-shm` are gone
    /// and only the user database is left in the folder.
    func testLegacyFilesDeletedAfterCommit() async throws {
        let original = tempDir.appendingPathComponent("1x/dict.sqlite")
        try FileManager.default.createDirectory(at: original.deletingLastPathComponent(), withIntermediateDirectories: true)
        try FileManager.default.copyItem(at: Self.fixtureURL(Self.v140.name), to: original)
        var writer: DatabaseQueue? = try DatabaseQueue(path: original.path)
        try await writer?.write { conn in
            try conn.execute(sql: """
                INSERT INTO history(word, source, looked_at) VALUES ('walonly', 'wordnet', '2026-06-03 08:00:00')
                """)
        }
        let walSize = (try? FileManager.default.attributesOfItem(atPath: original.path + "-wal")[.size] as? Int) ?? 0
        XCTAssertGreaterThan(walSize, 0, "precondition: the row is only in the WAL")
        // Copied while the writer is open, as a killed app leaves them.
        try FileManager.default.copyItem(atPath: original.path, toPath: legacyURL.path)
        try FileManager.default.copyItem(atPath: original.path + "-wal", toPath: legacyURL.path + "-wal")
        writer = nil
        XCTAssertEqual(legacyFiles(), [legacyURL.path, legacyURL.path + "-wal"])

        try await move()
        XCTAssertEqual(legacyFiles(), [], "dict.sqlite, -wal and -shm are deleted")
        let names = Set(try FileManager.default.contentsOfDirectory(atPath: appSupport.path))
        XCTAssertTrue(names.isSubset(of: Self.userFiles) && names.contains("user.sqlite"), "\(names)")
        let state = try userState()
        XCTAssertTrue(state.history.contains("walonly|wordnet|2026-06-03 08:00:00"), "the WAL was replayed")
        XCTAssertEqual(state.history.count, Self.v140.historyCount + 1)
    }

    /// An unreadable 1.x file is logged and kept as it is, and every launch
    /// tries again; the calls waiting for the move go on. Not a database at
    /// all: kept byte for byte, twice. A database the app cannot open
    /// (no permission): kept, then moved once it opens.
    func testUnreadableLegacyDatabaseIsKeptAndRetried() async throws {
        let garbage = Data(repeating: 0x5A, count: 8192)
        try garbage.write(to: legacyURL)
        for attempt in 1...2 {
            try await move()
            XCTAssertEqual(try Data(contentsOf: legacyURL), garbage, "attempt \(attempt): kept as it was")
            XCTAssertEqual(legacyFiles(), [legacyURL.path], "attempt \(attempt): no sidecars")
            XCTAssertNil(try userState().marker)
            let history = try await db.fetchHistory()
            XCTAssertEqual(history, [], "attempt \(attempt): waiting calls go on")
        }

        try install(Self.v140.name)
        try FileManager.default.setAttributes([.posixPermissions: 0], ofItemAtPath: legacyURL.path)
        try await move()
        XCTAssertTrue(exists(legacyURL.path), "an unopenable file is kept")
        XCTAssertNil(try userState().marker)
        // History used in between: a new word, a word the 1.x History has
        // older, and one it has newer.
        try await db.addToHistory(word: "cat", source: "wordnet")
        try await db.addToHistory(word: "house", source: "wordnet")
        try await db.writeForTesting { conn in
            try conn.execute(sql: """
                INSERT INTO history(word, source, looked_at) VALUES ('dog', 'wordnet-spa-eng', '2020-01-01 00:00:00')
                """)
        }

        try FileManager.default.setAttributes([.posixPermissions: 0o644], ofItemAtPath: legacyURL.path)
        try await move()
        XCTAssertEqual(legacyFiles(), [], "moved and deleted once it opens")
        let state = try userState()
        XCTAssertNotNil(state.marker)
        XCTAssertEqual(state.imported, Self.expectedImports(Self.v140))
        XCTAssertEqual(state.history.count, Self.v140.historyCount + 1, "one row per word")
        XCTAssertTrue(state.history.contains { $0.hasPrefix("cat|wordnet|") })
        XCTAssertTrue(state.history.contains { $0.hasPrefix("house|wordnet|") }, "the newer row wins: \(state.history)")
        XCTAssertTrue(state.history.contains("dog|wordnet|2026-06-02 08:00:00"), "the newer 1.x row wins")
    }

    /// Search answers from the dictionary file while the move runs (held
    /// inside its transaction by the delay seam), while History waits for the
    /// move rather than show a half-moved state. When the move commits, the
    /// current query re-runs and the moved import appears.
    @MainActor
    func testSearchDuringMigration() async throws {
        try install(Self.v140.name)
        let (move, gate) = try await startHeldMove()

        let historyDuringMove = Task { try await DatabaseService.shared.fetchHistory() }
        let vm = SearchViewModel(settings: SettingsService(store: InMemoryKeyValueStore()))
        vm.query = "house"
        let started = Date()
        vm.onQueryChanged()
        let during = try await results(of: vm) { !$0.isEmpty }
        print("LegacyMigrationTests: Search answered in \(Int(Date().timeIntervalSince(started) * 1000)) ms during the move")
        XCTAssertTrue(during.contains { EntryKey($0) == EntryKey(source: "wordnet", word: "house") },
                      "bundled results while the move runs")
        XCTAssertFalse(during.contains { $0.source == Self.glossary }, "the import is not in yet")

        gate.release.signal()
        await move.value
        let after = try await results(of: vm) { $0.contains { $0.source == Self.glossary } }
        XCTAssertTrue(Self.keys(after).contains(EntryKey(source: Self.glossary, word: "house")),
                      "the query re-ran when the move committed")
        let history = try await historyDuringMove.value
        XCTAssertEqual(history.count, Self.v140.historyCount, "History waited for the move")
    }

    /// Polls `vm.results` until `done` holds (5 s at most).
    @MainActor
    private func results(of vm: SearchViewModel, until done: ([DictionaryEntry]) -> Bool,
                         file: StaticString = #filePath, line: UInt = #line) async throws -> [DictionaryEntry] {
        let deadline = Date().addingTimeInterval(5)
        while !done(vm.results.map(\.entry)) || vm.isSearching {
            guard Date() < deadline else {
                XCTFail("Search results never matched: \(Self.keys(vm.results.map(\.entry)))", file: file, line: line)
                break
            }
            try await Task.sleep(nanoseconds: 20_000_000)
        }
        return vm.results.map(\.entry)
    }

    /// Installed size ≈ app bundle + user data (#129, #139): after the move
    /// the app folder holds only `user.sqlite` with its `-wal` and `-shm`,
    /// under 5 MB. The host app's own folder holds no more than that either
    /// (a 1.x file found there at launch has been moved).
    func testApplicationSupportHoldsOnlyTheUserDatabase() async throws {
        try install(Self.v140.name)
        try await move()
        let names = try FileManager.default.contentsOfDirectory(atPath: appSupport.path)
        XCTAssertTrue(Set(names).isSubset(of: Self.userFiles) && names.contains("user.sqlite"), "\(names)")
        let bytes = try names.reduce(0) { total, name in
            total + ((try FileManager.default.attributesOfItem(
                atPath: appSupport.appendingPathComponent(name).path)[.size] as? Int) ?? 0)
        }
        XCTAssertLessThan(bytes, 5_000_000)

        let host = DatabaseService.userDatabaseURL().deletingLastPathComponent()
        let deadline = Date().addingTimeInterval(10)
        while exists(host.appendingPathComponent("dict.sqlite").path), Date() < deadline {
            try await Task.sleep(nanoseconds: 100_000_000)
        }
        let hostNames = Set(try FileManager.default.contentsOfDirectory(atPath: host.path))
        XCTAssertTrue(hostNames.isSubset(of: Self.userFiles), "host app folder: \(hostNames.sorted())")
    }

    // MARK: Edge cases

    /// An import named like a bundled source whose words the bundle has, in
    /// another case (1.x kept such rows where the import landed before the
    /// bundled rows, as during the 1.4.0 background unpack): nothing moves
    /// and the source registers no import, so Dictionary Order counts only
    /// the bundled rows. A bookmark and a History row on such a word open
    /// today's bundled entry.
    func testImportWithOnlyBundledWordsRegistersNothing() async throws {
        try install(Self.v140.name) { conn in
            for word in ["CASA", "Perro", "MESA"] {
                try conn.execute(sql: """
                    INSERT INTO entries(word, word_normalized, definition, source, created_at)
                    VALUES (?, ?, '1.x import', 'wordnet-spa-eng', '2026-05-25 10:00:00')
                    """, arguments: [word, word])
            }
            try conn.execute(sql: """
                INSERT INTO bookmarks(entry_id, created_at)
                SELECT id, '2026-06-05 10:00:00' FROM entries WHERE word = 'CASA'
                """)
            try conn.execute(sql: """
                INSERT INTO history(word, source, looked_at) VALUES ('Perro', 'wordnet-spa-eng', '2026-06-05 11:00:00')
                """)
        }
        try await move()

        let state = try userState()
        XCTAssertEqual(state.imported, Self.expectedImports(Self.v140), "no row of the bundled words moved")
        XCTAssertFalse(state.importedSources.contains { $0.hasPrefix("wordnet-spa-eng|") }, "\(state.importedSources)")
        let stats = try await db.fetchSourceStats()
        let metadata = try await db.fetchMetadata()
        let bundledCount = try XCTUnwrap(metadata.first { $0.source == "wordnet-spa-eng" }?.wordCount)
        XCTAssertEqual(stats.first { $0.source == "wordnet-spa-eng" }?.count, bundledCount,
                       "only the bundled rows count")

        let myWords = try await db.fetchMyWords()
        let casa = try XCTUnwrap(myWords.first, "the bookmark resolves, newest first")
        XCTAssertEqual(EntryKey(casa), EntryKey(source: "wordnet-spa-eng", word: "casa"))
        XCTAssertNil(casa.createdAt, "the bookmark opens the bundled row")
        XCTAssertTrue(state.myWords.contains("wordnet-spa-eng/CASA|2026-06-05 10:00:00"), "\(state.myWords)")
        let history = try await db.fetchHistory()
        let perro = try XCTUnwrap(history.first { $0.word == "Perro" })
        let opened = await HistoryDestination.entry(for: perro)
        XCTAssertEqual(opened.map { EntryKey($0) }, EntryKey(source: "wordnet-spa-eng", word: "perro"))
        XCTAssertNil(opened?.createdAt, "the History row opens the bundled row")
    }

    /// A 1.x row of a bundled source that today's data lacks (a dictionary
    /// update dropped the headword; none today, measured) moves like a row
    /// of an import named like that source: the bookmark on it stays a My
    /// words key that resolves, its History row opens it, Search finds it
    /// and Dictionary Order counts it with its source.
    func testBookmarkOfARowTodaysDataLacksKeepsItsEntry() async throws {
        let dropped = EntryKey(source: "wordnet", word: "qadroppedheadword")
        let definition = "A headword a later dictionary update dropped."
        try install(Self.v140.name) { conn in
            try conn.execute(sql: """
                INSERT INTO entries(word, word_normalized, definition, phonetic, pos, source, created_at)
                VALUES (?, ?, ?, '', 'noun', ?, '2026-04-01 00:00:00')
                """, arguments: [dropped.word, dropped.word, definition, dropped.source])
            try conn.execute(sql: """
                INSERT INTO bookmarks(entry_id, created_at)
                SELECT id, '2026-06-05 10:00:00' FROM entries WHERE word = ?
                """, arguments: [dropped.word])
            try conn.execute(sql: """
                INSERT INTO history(word, source, looked_at) VALUES (?, ?, '2026-06-05 11:00:00')
                """, arguments: [dropped.word, dropped.source])
        }
        let metadata = try await db.fetchMetadata()
        let wordCount = try XCTUnwrap(metadata.first { $0.source == dropped.source }?.wordCount)
        try await move()

        let state = try userState()
        XCTAssertEqual(state.imported, Self.expectedImports(Self.v140) + ["wordnet/\(dropped.word)"])
        XCTAssertTrue(state.importedSources.contains("wordnet|2026-04-01 00:00:00"), "\(state.importedSources)")
        let myWords = try await db.fetchMyWords()
        XCTAssertEqual(myWords.first.map { EntryKey($0) }, dropped, "the bookmark resolves, newest first")
        XCTAssertEqual(myWords.count, Self.v140.bookmarks.count + 1)
        let history = try await db.fetchHistory()
        let row = try XCTUnwrap(history.first { $0.word == dropped.word })
        let opened = await HistoryDestination.entry(for: row)
        XCTAssertEqual(opened.map { EntryKey($0) }, dropped)
        XCTAssertEqual(opened?.definition, definition)
        let found = try await db.search(query: dropped.word)
        XCTAssertEqual(Self.keys(found), [dropped])
        let stats = try await db.fetchSourceStats()
        XCTAssertEqual(stats.first { $0.source == dropped.source }?.count, wordCount + 1)
    }

    /// Rows a 1.x database can hold that the fixtures do not: an import row
    /// with NULL phonetic, part of speech and date, a bookmark whose entry
    /// is gone, a bookmark and a History row without a date. None of them
    /// fails the move: NULL text becomes '', a missing date becomes the
    /// move's time (a History date stays NULL and sorts last), and the
    /// orphan bookmark is skipped.
    func testLegacyRowsWithNullsAndAnOrphanBookmarkMove() async throws {
        try install(Self.v140.name) { conn in
            try conn.execute(sql: """
                INSERT INTO entries(word, word_normalized, definition, phonetic, pos, source, created_at)
                VALUES ('nullish', 'nullish', 'A row with NULL columns.', NULL, NULL, 'null_import', NULL)
                """)
            try conn.execute(sql: "INSERT INTO bookmarks(entry_id, created_at) VALUES (999999, '2026-06-05 10:00:00')")
            try conn.execute(sql: """
                INSERT INTO bookmarks(entry_id, created_at) SELECT id, NULL FROM entries WHERE word = 'nullish'
                """)
            try conn.execute(sql: "INSERT INTO history(word, source, looked_at) VALUES ('undated', 'wordnet', NULL)")
        }
        let before = Self.sqliteNow()
        try await move()
        let after = Self.sqliteNow()

        let state = try userState()
        XCTAssertNotNil(state.marker)
        XCTAssertEqual(legacyFiles(), [])
        XCTAssertEqual(state.imported, Self.expectedImports(Self.v140) + ["null_import/nullish"])
        let importedAt = try XCTUnwrap(state.importedSources.first { $0.hasPrefix("null_import|") })
            .replacingOccurrences(of: "null_import|", with: "")
        XCTAssertTrue((before...after).contains(importedAt), "dated by the move: \(importedAt)")
        let entry = try await db.entry(for: EntryKey(source: "null_import", word: "nullish"))
        XCTAssertEqual(entry?.phonetic, "")
        XCTAssertEqual(entry?.pos, "")

        XCTAssertEqual(state.myWords.count, Self.v140.bookmarks.count + 1, "the orphan bookmark is skipped")
        let addedAt = try XCTUnwrap(state.myWords.first { $0.hasPrefix("null_import/nullish|") })
            .replacingOccurrences(of: "null_import/nullish|", with: "")
        XCTAssertTrue((before...after).contains(addedAt), "dated by the move: \(addedAt)")

        XCTAssertTrue(state.history.contains("undated|wordnet|NULL"), "\(state.history)")
        let history = try await db.fetchHistory()
        XCTAssertEqual(history.count, Self.v140.historyCount + 1)
        XCTAssertEqual(history.last?.word, "undated")
        XCTAssertNil(history.last?.lookedAt)
    }

    /// History word conflicts on a retried move (the user database has
    /// History from launches whose move failed): the newer `looked_at` wins
    /// and brings its source; on a tie the row already there stays.
    func testHistoryConflictsKeepTheNewerRow() async throws {
        try install(Self.v140.name)
        // The fixture has dog|wordnet at 08:00, house|freedict-eng-spa at
        // 09:00 and дом|openrussian at 10:00 on 2026-06-02.
        try await db.writeForTesting { conn in
            try conn.execute(sql: """
                INSERT INTO history(word, source, looked_at) VALUES
                    ('dog', 'freedict-eng-spa', '2026-06-02 08:00:00'),
                    ('house', 'wordnet', '2026-06-02 09:00:01'),
                    ('дом', '', '2026-06-02 09:59:59')
                """)
        }
        try await move()

        let history = try userState().history
        XCTAssertEqual(history.count, Self.v140.historyCount, "one row per word: \(history)")
        XCTAssertTrue(history.contains("dog|freedict-eng-spa|2026-06-02 08:00:00"), "a tie keeps the row: \(history)")
        XCTAssertTrue(history.contains("house|wordnet|2026-06-02 09:00:01"), "a newer row stays: \(history)")
        XCTAssertTrue(history.contains("дом|openrussian|2026-06-02 10:00:00"),
                      "the newer 1.x row wins with its source: \(history)")
    }

    /// User-data writes that come while the move runs (History, My words, an
    /// import) wait for it and land after it: none is lost or undone by the
    /// move, the user's later action wins, and nothing is stored twice.
    func testWritesDuringTheMoveLandAfterIt() async throws {
        try install(Self.v140.name)
        let json = tempDir.appendingPathComponent("my_glossary.json")
        try Data("""
            [{"word": "zorblat", "definition": "a second zorblat"},
             {"word": "midmove", "definition": "imported while the move ran"}]
            """.utf8).write(to: json)
        let (move, gate) = try await startHeldMove()

        let writes = Task {
            async let history: Void = DatabaseService.shared.addToHistory(word: "house", source: "wordnet")
            async let removed: Void = DatabaseService.shared.removeFromMyWords(
                EntryKey(source: Self.glossary, word: "zorblat"))
            async let added: Void = DatabaseService.shared.addToMyWords(EntryKey(source: "wordnet", word: "dog"))
            async let imported = DatabaseService.shared.importJSON(at: json, source: Self.glossary)
            _ = try await (history, removed, added, imported)
        }
        try await Task.sleep(nanoseconds: 300_000_000)
        let held = try userState()
        XCTAssertEqual(held.history + held.myWords + held.imported, [], "nothing lands before the move commits")

        gate.release.signal()
        await move.value
        try await writes.value

        let state = try userState()
        XCTAssertNotNil(state.marker)
        XCTAssertEqual(state.history.count, Self.v140.historyCount)
        XCTAssertTrue(state.history.contains { $0.hasPrefix("house|wordnet|") },
                      "the later view wins: \(state.history)")
        XCTAssertEqual(state.myWords.count, Self.v140.bookmarks.count - 1, "\(state.myWords)")
        XCTAssertFalse(state.myWords.contains { $0.hasPrefix("\(Self.glossary)/zorblat|") }, "the removal applies")
        XCTAssertTrue(state.myWords.contains("wordnet/dog|2026-06-01 09:00:00"), "kept once, with its bookmark date")
        XCTAssertEqual(state.imported, Self.expectedImports(Self.v140) + ["\(Self.glossary)/midmove"],
                       "the moved row wins over the import's copy")
        XCTAssertEqual(state.importedSources.first { $0.hasPrefix("\(Self.glossary)|") },
                       "\(Self.glossary)|2026-05-10 12:00:00", "the import keeps its 1.x date")
        let zorblat = try await db.search(query: "zorblat")
        XCTAssertEqual(zorblat.map(\.definition), ["A made-up word of the legacy fixture."])
    }

    /// No 1.x file (a fresh install, or the move is done): no move starts,
    /// nothing is posted, and user data works at once.
    func testNoLegacyDatabaseStartsNoMove() async throws {
        let posted = expectation(forNotification: LegacyMigration.didCommit, object: nil)
        posted.isInverted = true
        let task = await db.startLegacyMigration(legacyURL: legacyURL)
        XCTAssertNil(task)
        try await db.addToHistory(word: "dog", source: "wordnet")
        let history = try await db.fetchHistory()
        XCTAssertEqual(history.map(\.word), ["dog"])
        await fulfillment(of: [posted], timeout: 0.5)
        XCTAssertNil(try userState().marker)
        XCTAssertEqual(legacyFiles(), [])
    }

    /// A 1.x database with no user data (no import, History or bookmark;
    /// here not even the bundled copy) moves nothing, sets the marker,
    /// posts the commit and is deleted.
    func testLegacyDatabaseWithoutUserDataIsDeleted() async throws {
        try install(Self.v140.name) { conn in
            try conn.execute(sql: "DELETE FROM bookmarks; DELETE FROM history; DELETE FROM entries")
        }
        let committed = expectation(forNotification: LegacyMigration.didCommit, object: nil)
        try await move()
        await fulfillment(of: [committed], timeout: 5)

        let state = try userState()
        XCTAssertEqual(state.history + state.myWords + state.imported + state.importedSources, [])
        XCTAssertNotNil(state.marker)
        XCTAssertEqual(legacyFiles(), [])
    }

    /// A zero-byte `dict.sqlite` (1.x killed before it wrote its schema) has
    /// no 1.x tables: it is kept like an unreadable file, nothing is created
    /// next to it, and user data works.
    func testZeroByteLegacyFileIsKept() async throws {
        XCTAssertTrue(FileManager.default.createFile(atPath: legacyURL.path, contents: Data()))
        try await move()
        XCTAssertEqual(legacyFiles(), [legacyURL.path], "kept, with no sidecar")
        XCTAssertEqual(try Data(contentsOf: legacyURL), Data())
        XCTAssertNil(try userState().marker)
        try await db.addToMyWords(EntryKey(source: "wordnet", word: "dog"))
        let myWords = try await db.fetchMyWords()
        XCTAssertEqual(Self.keys(myWords), [EntryKey(source: "wordnet", word: "dog")])
    }

    /// A real 1.x database, local only: never committed. Run with
    /// `TEST_RUNNER_LIBREDICT_LEGACY_DB=/path/to/dict.sqlite xcodebuild test …`
    /// (xcodebuild hands `TEST_RUNNER_` variables to the tests without the
    /// prefix). The file, and its `-wal` if there is one, is copied, never
    /// changed. Skipped when the variable is absent.
    func testMigratesLocalLegacyDatabase() async throws {
        guard let path = ProcessInfo.processInfo.environment["LIBREDICT_LEGACY_DB"], !path.isEmpty else {
            throw XCTSkip("LIBREDICT_LEGACY_DB is not set")
        }
        try FileManager.default.copyItem(atPath: path, toPath: legacyURL.path)
        if exists(path + "-wal") {
            try FileManager.default.copyItem(atPath: path + "-wal", toPath: legacyURL.path + "-wal")
        }
        let bundledURL = try TestDictionary.bundledURL()
        let packs = try PackFixtures.all()
        let inFiles = DictionarySchemas.all.map { schema in
            "NOT EXISTS (SELECT 1 FROM \(schema).entries d WHERE d.word = l.word COLLATE NOCASE AND d.source = l.source)"
        }.joined(separator: " AND ")
        let expected = try await inspectCopy(of: legacyURL).writeWithoutTransaction { conn in
            try conn.execute(sql: "ATTACH DATABASE ? AS dict", arguments: [DatabaseService.dictionaryURI(bundledURL)])
            for pack in PackID.all {
                try conn.execute(sql: "ATTACH DATABASE ? AS \(pack.schema)",
                                 arguments: [DatabaseService.dictionaryURI(try XCTUnwrap(packs[pack]))])
            }
            return (history: try Int.fetchOne(conn, sql: "SELECT COUNT(*) FROM history") ?? 0,
                    bookmarks: Set(try Row.fetchAll(conn, sql: """
                        SELECT e.source, e.word FROM bookmarks b JOIN entries e ON e.id = b.entry_id
                        """).map { EntryKey(source: $0["source"], word: $0["word"]) }),
                    rows: try Int.fetchOne(conn, sql: "SELECT COUNT(*) FROM entries") ?? 0,
                    imported: try Int.fetchOne(conn, sql: "SELECT COUNT(*) FROM entries l WHERE \(inFiles)") ?? 0)
        }

        let seconds = try await move()
        print("LegacyMigrationTests: \(path) (\(expected.rows) rows) moved in \(Int(seconds * 1000)) ms")
        XCTAssertEqual(legacyFiles(), [], "moved and deleted")
        let state = try userState()
        XCTAssertEqual(state.history.count, expected.history)
        XCTAssertEqual(state.imported.count, expected.imported)
        let myWords = try await db.fetchMyWords()
        XCTAssertEqual(Set(Self.keys(myWords)), expected.bookmarks, "every bookmark is a My words key that resolves")
    }
}

// MARK: - Issue #244: the update from 1.x with packs missing (0237, "Update from 1.x")

/// The 1.x move on an English-only bundle with no pack installed, as on a
/// real update to 2.0: a pack's dictionary is decided by its row count.
extension LegacyMigrationTests {
    /// The date `Scripts/make_legacy_fixtures.py` gives the seed rows it copies.
    nonisolated private static let seedRowsDate = "2026-04-01 00:00:00"

    /// The dictionaries of the four language packs.
    private static var packSources: Set<String> {
        get throws { Set(try PackFixtures.catalog().sources.map(\.source)) }
    }

    /// Opens the shared service on an English-only bundle made for the 1.x
    /// file in place: its WordNet seed rows, and the host app's catalog
    /// with each pack dictionary's `word_count` set to the file's seed rows
    /// of it, so every dictionary 1.x shipped reads as unchanged, then
    /// changed by `adjust`. Only `installed` packs are attached: each other
    /// one is the stub. Returns the bundle.
    @discardableResult
    private func openEnglishOnlyBundle(installed: [PackID] = [],
                                       adjust: (inout [String: Int]) -> Void = { _ in }) async throws -> URL {
        let seed = try await inspectCopy(of: legacyURL).read { conn in
            (wordnet: try Row.fetchAll(conn, sql: """
                SELECT word, definition, COALESCE(phonetic, '') AS phonetic, COALESCE(pos, '') AS pos
                FROM entries WHERE source = 'wordnet' AND created_at = ? ORDER BY id
                """, arguments: [Self.seedRowsDate]).map {
                    TestDictionary.Row(word: $0["word"], definition: $0["definition"], phonetic: $0["phonetic"],
                                       pos: $0["pos"], source: "wordnet")
                },
             counts: try Row.fetchAll(conn, sql: """
                SELECT source, COUNT(*) AS n FROM entries WHERE created_at = ? GROUP BY source
                """, arguments: [Self.seedRowsDate]).map { (source: $0["source"] as String, count: $0["n"] as Int) })
        }
        let bundle = try TestDictionary.make(
            rows: seed.wordnet, metadata: [TestDictionary.Metadata(source: "wordnet", displayName: "WordNet")],
            at: tempDir.appendingPathComponent("english-only.sqlite"))
        var counts = Dictionary(uniqueKeysWithValues: seed.counts.map { ($0.source, $0.count) })
        adjust(&counts)
        let wordCounts = counts
        let catalogSource = try TestDictionary.bundledURL()
        let queue = try DatabaseQueue(path: bundle.path)
        try await queue.writeWithoutTransaction { conn in
            try conn.execute(sql: "ATTACH DATABASE ? AS shipped", arguments: [DatabaseService.dictionaryURI(catalogSource)])
            try conn.inTransaction {
                try conn.execute(sql: "INSERT INTO catalog_pack SELECT * FROM shipped.catalog_pack")
                try conn.execute(sql: "INSERT INTO catalog_source SELECT * FROM shipped.catalog_source")
                for (source, count) in wordCounts {
                    try conn.execute(sql: "UPDATE catalog_source SET word_count = ? WHERE source = ?",
                                     arguments: [count, source])
                }
                return .commit
            }
            try conn.execute(sql: "DETACH DATABASE shipped")
        }
        try queue.close()
        let packFiles = try Dictionary(uniqueKeysWithValues: installed.map { ($0, try PackFixtures.file($0)) })
        try await db.setup(userPath: userPath, dictionaryURL: bundle, packFiles: packFiles)
        return bundle
    }

    /// The rows of each source in the 1.x file in place.
    private func legacyCounts() async throws -> [String: Int] {
        try await inspectCopy(of: legacyURL).read { conn in
            Dictionary(uniqueKeysWithValues: try Row.fetchAll(conn, sql: """
                SELECT source, COUNT(*) AS n FROM entries GROUP BY source
                """).map { ($0["source"] as String, $0["n"] as Int) })
        }
    }

    /// The rows of each source in `imported_entries`.
    private func importedCounts() throws -> [String: Int] {
        var config = Configuration()
        config.readonly = true
        return try DatabaseQueue(path: userPath, configuration: config).read { conn in
            Dictionary(uniqueKeysWithValues: try Row.fetchAll(conn, sql: """
                SELECT source, COUNT(*) AS n FROM imported_entries GROUP BY source
                """).map { ($0["source"] as String, $0["n"] as Int) })
        }
    }

    /// Update from 1.4.0 with no pack installed: History and My words move
    /// as in #139; the rows of each pack dictionary whose count is the
    /// catalog's are dropped, not imported; `my_glossary` is imported, and
    /// so is every row of `freedict-eng-spa`, which holds an import too
    /// (its count is above the catalog's). My words of a missing pack stay
    /// stored and resolve once it is installed.
    func testMoveWithPacksMissing() async throws {
        try install(Self.v140.name)
        let legacyHistory = try await inspectCopy(of: legacyURL).read { try Self.historyRows($0) }
        let counts = try await legacyCounts()
        try await openEnglishOnlyBundle()

        try await move()

        let state = try userState()
        XCTAssertEqual(state.history, legacyHistory, "History is equal row for row")
        XCTAssertEqual(state.myWords, Self.v140.bookmarks.enumerated().map {
            "\($0.element.source)/\($0.element.word)|\(Self.bookmarkedAt($0.offset))"
        }, "every bookmark is a My words key, its pack installed or not")
        let imported = try importedCounts()
        XCTAssertEqual(imported, [Self.glossary: Self.glossaryWords.count,
                                  "freedict-eng-spa": try XCTUnwrap(counts["freedict-eng-spa"])],
                       "the pack dictionaries' rows are dropped; the import and the source holding one move")
        let dropped = try Self.packSources.subtracting(["freedict-eng-spa"])
        XCTAssertEqual(dropped.filter { counts[$0] != nil }.count, 7, "precondition: the fixture has every pack dictionary")
        XCTAssertTrue(dropped.isDisjoint(with: imported.keys), "\(imported)")
        XCTAssertEqual(Set(state.importedSources.map { $0.components(separatedBy: "|")[0] }),
                       [Self.glossary, "freedict-eng-spa"])
        await assertImportIndexIntact()

        let resolving: Set<String> = ["wordnet", Self.glossary, "freedict-eng-spa"]
        let myWords = try await db.fetchMyWords()
        XCTAssertEqual(Self.keys(myWords), Self.v140.bookmarks.filter { resolving.contains($0.source) }.reversed(),
                       "the keys of a missing pack resolve once it is installed")
        let zorblat = try await db.search(query: "zorblat")
        XCTAssertEqual(Self.keys(zorblat), [EntryKey(source: Self.glossary, word: "zorblat")])
        let dog = try await db.entry(for: EntryKey(source: "wordnet", word: "dog"))
        XCTAssertNil(dog?.createdAt, "WordNet's 1.x copy is dropped by the key check, as before")
        XCTAssertNotNil(dog)
        XCTAssertNotNil(try userState().marker)
        XCTAssertEqual(legacyFiles(), [])
    }

    /// A pack dictionary whose 1.x count is above the catalog's holds an
    /// import (#105): all its rows move, then the pack's install deletes
    /// the rows it has, leaving only the imported keys. A My words key on a
    /// pack row opens the pack's row from then on.
    func testImportUnderAPackSourceMovesUntilThePackArrives() async throws {
        try install(Self.v140.name)
        let counts = try await legacyCounts()
        try await openEnglishOnlyBundle()
        try await move()
        let spanish = "freedict-eng-spa"
        XCTAssertEqual(try importedCounts()[spanish], try XCTUnwrap(counts[spanish]), "precondition: every row moved")
        let houseBefore = try await db.entry(for: EntryKey(source: spanish, word: "house"))
        XCTAssertNotNil(houseBefore?.createdAt, "precondition: the bookmark opens the moved row")

        // The pack's install, from the committed asset, through the app's
        // install path (step 7 deletes the imported rows it covers).
        let catalog = PackCatalog.shared
        defer { PackCatalog.shared = catalog }
        let service = PackService(folder: tempDir.appendingPathComponent("Packs", isDirectory: true),
                                  downloads: tempDir.appendingPathComponent("Downloads", isDirectory: true),
                                  database: db, settings: SettingsService(store: InMemoryKeyValueStore()),
                                  status: PackStatusModel())
        try await service.prepare()
        try await service.install([.spa], fromAssetsIn: PackFixtures.assets)

        let state = try userState()
        XCTAssertEqual(state.imported, Self.expectedImports(Self.v140), "only the imported keys stay")
        XCTAssertTrue(state.importedSources.contains { $0.hasPrefix("\(spanish)|") }, "the import keeps its row")
        await assertImportIndexIntact()
        let house = try await db.entry(for: EntryKey(source: spanish, word: "house"))
        XCTAssertNotNil(house)
        XCTAssertNil(house?.createdAt, "the bookmark opens the pack's row")
        let dogsitter = try await db.search(query: "dogsitter")
        XCTAssertEqual(Self.keys(dogsitter), [EntryKey(source: spanish, word: "dogsitter")])
        XCTAssertNotNil(dogsitter.first?.createdAt, "an imported key stays the import")
    }

    /// The signs of an earlier install that the first-launch offer reads:
    /// none on a new user database; user rows (the 2.0 alpha); the marker
    /// of a committed 1.x move, even one that moved no user data.
    func testEarlierInstallSigns() async throws {
        var signs = try await db.earlierInstallSigns()
        XCTAssertFalse(signs.legacyMarker)
        XCTAssertFalse(signs.userRows, "a new user database")

        try await db.addToMyWords(EntryKey(source: "wordnet", word: "dog"))
        signs = try await db.earlierInstallSigns()
        XCTAssertTrue(signs.userRows, "My words")
        try await db.clearMyWords()

        try install(Self.v140.name) { conn in
            try conn.execute(sql: "DELETE FROM bookmarks; DELETE FROM history; DELETE FROM entries")
        }
        try await move()
        signs = try await db.earlierInstallSigns()
        XCTAssertTrue(signs.legacyMarker, "the move's marker")
        XCTAssertFalse(signs.userRows)

        try await db.addToHistory(word: "dog", source: "wordnet")
        signs = try await db.earlierInstallSigns()
        XCTAssertTrue(signs.userRows, "History")
    }

    /// QA #244: a pack dictionary with fewer 1.x rows than the catalog's
    /// `word_count` (rows gone after the seed) is no copy of the pack: all
    /// its rows move as an import, and its bookmark opens the moved row
    /// until the pack arrives. The other pack dictionaries are still dropped.
    func testCountBelowTheCatalogMovesEveryRow() async throws {
        try install(Self.v140.name)
        try await openEnglishOnlyBundle()
        let arabic = "wordnet-arb-eng"
        let queue = try DatabaseQueue(path: legacyURL.path)
        try await queue.write { conn in
            try conn.execute(sql: """
                DELETE FROM entries WHERE id = (SELECT MIN(id) FROM entries
                    WHERE source = ? AND id NOT IN (SELECT entry_id FROM bookmarks))
                """, arguments: [arabic])
            XCTAssertEqual(conn.changesCount, 1, "precondition: one Arabic seed row deleted")
        }
        try queue.close()
        let counts = try await legacyCounts()

        try await move()

        let imported = try importedCounts()
        XCTAssertEqual(imported, [Self.glossary: Self.glossaryWords.count,
                                  "freedict-eng-spa": try XCTUnwrap(counts["freedict-eng-spa"]),
                                  arabic: try XCTUnwrap(counts[arabic])],
                       "every row of the Arabic dictionary moves; the exact copies are dropped")
        XCTAssertEqual(Set(try userState().importedSources.map { $0.components(separatedBy: "|")[0] }),
                       [Self.glossary, "freedict-eng-spa", arabic])
        await assertImportIndexIntact()
        let book = try await db.entry(for: EntryKey(source: arabic, word: "كِتاب"))
        XCTAssertNotNil(book?.createdAt, "the bookmark opens the moved row")
        let greek = try await db.entry(for: EntryKey(source: "freedict-ell-eng", word: "σπίτι"))
        XCTAssertNil(greek, "Greek was an exact copy: dropped, its pack is not installed")
    }

    /// QA #244: the count rule is for packs that are not installed at the
    /// move. With Spanish installed, its dictionaries take the key check even
    /// when a 1.x count equals the catalog's: the keys the pack lacks (the
    /// import named like its source) move, the rest are the pack's. The
    /// packs that are not installed are still dropped by their count.
    func testInstalledPackTakesTheKeyCheckNotTheCount() async throws {
        try install(Self.v140.name)
        let counts = try await legacyCounts()
        let spanish = "freedict-eng-spa"
        let all = try XCTUnwrap(counts[spanish])
        try await openEnglishOnlyBundle(installed: [.spa]) { $0[spanish] = all }

        try await move()

        let state = try userState()
        XCTAssertEqual(state.imported, Self.expectedImports(Self.v140),
                       "only the import's keys move, though the count is the catalog's")
        XCTAssertEqual(try importedCounts().keys.sorted(), [spanish, Self.glossary].sorted())
        await assertImportIndexIntact()
        let house = try await db.entry(for: EntryKey(source: spanish, word: "house"))
        XCTAssertNotNil(house)
        XCTAssertNil(house?.createdAt, "the bookmark opens the installed pack's row")
        let dom = try await db.entry(for: EntryKey(source: "openrussian", word: "дом"))
        XCTAssertNil(dom, "Russian is not installed: dropped by its count")
        XCTAssertEqual(state.myWords.count, Self.v140.bookmarks.count, "every bookmark is kept")
    }

    /// QA #245 (0237, "Update from 1.x"): the count rule decides what a
    /// moved word opens until its pack arrives. An exact copy is dropped, so
    /// σπίτι, дом and كِتاب open the "not downloaded" view of their pack and
    /// wait in My words; the Spanish dictionary held an import, so its rows
    /// moved and `house` opens the moved row. The next launch offers the
    /// upgrade sheet with every language checked.
    func testMovedWordsOfAMissingPackWaitForIt() async throws {
        try install(Self.v140.name)
        try await openEnglishOnlyBundle()
        try await move()
        let catalog = try PackFixtures.catalog()

        let waiting: [(EntryKey, PackID)] = [(EntryKey(source: "freedict-ell-eng", word: "σπίτι"), .ell),
                                             (EntryKey(source: "openrussian", word: "дом"), .rus),
                                             (EntryKey(source: "wordnet-arb-eng", word: "كِتاب"), .arb)]
        for (key, id) in waiting {
            let lookup = await EntryDestination.lookup(key, catalog: catalog)
            XCTAssertEqual(lookup, .notDownloaded(try XCTUnwrap(catalog.pack(id))), "\(key)")
        }
        let house = await EntryDestination.lookup(EntryKey(source: "freedict-eng-spa", word: "house"), catalog: catalog)
        guard case .entry(let moved) = house else { return XCTFail("a dictionary holding an import moves: \(house)") }
        XCTAssertNotNil(moved.createdAt, "the moved row")

        let rows = try await db.fetchMyWordRows()
        XCTAssertEqual(rows.map(\.key), Self.v140.bookmarks.reversed(), "every bookmark is listed, newest first")
        XCTAssertEqual(Set(rows.filter { $0.entry == nil }.map(\.key)), Set(waiting.map(\.0)),
                       "the dropped ones wait for their pack")

        let shared = PackCatalog.shared
        defer { PackCatalog.shared = shared }
        let settings = SettingsService(store: InMemoryKeyValueStore())
        settings.selectedUILanguageCode = "en"
        let localization = LocalizationManager(settingsService: settings, bundle: .main)
        let packs = PackService(folder: tempDir.appendingPathComponent("Packs", isDirectory: true),
                                downloads: tempDir.appendingPathComponent("Downloads", isDirectory: true),
                                database: db, settings: settings, status: PackStatusModel(), localization: localization)
        try await packs.prepare()
        let sheet = try await PackOffer.atLaunch(legacyDatabaseFound: false, settings: settings, database: db,
                                                 packs: packs, localization: localization)
        XCTAssertEqual(sheet, PackOffer.Sheet(kind: .upgrade, checked: [.spa, .rus, .arb, .ell]))
    }
}

// MARK: - Issue #244: the first-launch offer (0237, "Launch")

/// `PackOffer.decide`: which sheet launch shows and which packs it checks.
/// Pure, on the host app's catalog.
final class PackOfferTests: XCTestCase {
    private var catalog: PackCatalog!
    /// The four language packs, in catalog order; never the English lists.
    private let languagePacks: [PackID] = [.spa, .rus, .arb, .ell]

    override func setUpWithError() throws {
        try super.setUpWithError()
        catalog = try PackFixtures.catalog()
    }

    private func decide(_ signals: PackOffer.Signals) -> PackOffer.Sheet? {
        PackOffer.decide(signals, catalog: catalog)
    }

    private func fresh(ui: String, device: [String]) -> PackOffer.Sheet? {
        decide(PackOffer.Signals(uiLanguageCode: ui, preferredLanguages: device))
    }

    /// A fresh install checks the UI language's pack and those of the
    /// device's preferred languages, in catalog order. An English UI on an
    /// English-only device checks nothing.
    func testFreshChecksTheUIAndDeviceLanguages() {
        XCTAssertEqual(fresh(ui: "en", device: ["en-US", "en-GB"]), PackOffer.Sheet(kind: .fresh, checked: []))
        XCTAssertEqual(fresh(ui: "es", device: ["en-US"]), PackOffer.Sheet(kind: .fresh, checked: [.spa]))
        XCTAssertEqual(fresh(ui: "en", device: ["el-GR", "ru", "zh-Hans-CN"])?.checked, [.rus, .ell],
                       "a device language without a pack adds nothing")
        XCTAssertEqual(fresh(ui: "ar", device: ["es-MX", "ar-EG"])?.checked, [.spa, .arb])
        XCTAssertEqual(fresh(ui: "el", device: [])?.checked, [.ell])
        XCTAssertEqual(fresh(ui: "ru", device: ["en"])?.checked, [.rus])
    }

    /// An update from 1.x or the alpha, from each sign: the packs of every
    /// dictionary when `enabled_sources` is absent (all were on). A stored
    /// order of English only is what a fresh 2.0 install stores itself.
    func testUpgradeFromEachSign() {
        let signs: [(String, PackOffer.Signals)] = [
            ("a 1.x file", PackOffer.Signals(legacyDatabaseFound: true)),
            ("the move's marker", PackOffer.Signals(legacyMarker: true)),
            ("user rows", PackOffer.Signals(userRows: true)),
            ("a stored order with a pack's dictionary", PackOffer.Signals(storedOrder: ["wordnet", "openrussian"])),
        ]
        for (sign, signals) in signs {
            XCTAssertEqual(decide(signals), PackOffer.Sheet(kind: .upgrade, checked: languagePacks), sign)
        }
        XCTAssertEqual(decide(PackOffer.Signals(storedOrder: ["wordnet", "my_glossary"]))?.kind, .fresh,
                       "an order without a pack's dictionary is no sign")
        XCTAssertEqual(decide(PackOffer.Signals(storedOrder: []))?.kind, .fresh)
    }

    /// The upgrade checks the packs of the dictionaries that were enabled,
    /// whatever the UI language: a 1.3.0-style set without Greek leaves
    /// Greek unchecked; a set of English and imports checks nothing.
    func testUpgradeChecksThePacksOfTheEnabledDictionaries() {
        func upgrade(enabled: Set<String>) -> [PackID]? {
            decide(PackOffer.Signals(legacyDatabaseFound: true, enabledSources: enabled, uiLanguageCode: "el",
                                     preferredLanguages: ["ru"]))?.checked
        }
        XCTAssertEqual(upgrade(enabled: ["wordnet", "openrussian", "freedict-eng-spa", "wordnet-spa-eng",
                                         "wordnet-arb-eng"]), [.spa, .rus, .arb])
        XCTAssertEqual(upgrade(enabled: ["wordnet", "freedict-eng-ell"]), [.ell], "one dictionary of a pack checks it")
        XCTAssertEqual(upgrade(enabled: ["wordnet", "my_glossary"]), [], "the sheet shows, with nothing checked")
        XCTAssertEqual(upgrade(enabled: []), [])
    }

    /// Installed packs without a usable file are offered again, even after
    /// the sheet was answered, and before an upgrade's offer; nothing is
    /// offered once the sheet was answered and every pack is usable.
    func testMissingPacksAreOfferedAgain() {
        let restored = PackOffer.Signals(packsOffered: true, packsInstalled: [.spa, .ell, .engLists], usable: [.spa])
        XCTAssertEqual(decide(restored), PackOffer.Sheet(kind: .missing, checked: [.ell, .engLists]))
        let upgrading = PackOffer.Signals(packsInstalled: [.rus], legacyDatabaseFound: true)
        XCTAssertEqual(decide(upgrading), PackOffer.Sheet(kind: .missing, checked: [.rus]))
        XCTAssertNil(decide(PackOffer.Signals(packsOffered: true, packsInstalled: [.spa], usable: [.spa, .rus])))
        XCTAssertNil(decide(PackOffer.Signals(packsOffered: true, legacyDatabaseFound: true, userRows: true)),
                     "the sheet shows once")
        XCTAssertNil(decide(PackOffer.Signals(packsOffered: true)))
    }

    /// Download or Not now sets `packs_offered`; a missing sheet's answer
    /// also drops the packs it offered, so it shows once too.
    func testRecordAnswersTheSheetOnce() {
        let settings = SettingsService(store: InMemoryKeyValueStore())
        settings.packsInstalled = [.spa, .ell]
        PackOffer.record(PackOffer.Sheet(kind: .upgrade, checked: languagePacks), in: settings)
        XCTAssertTrue(settings.packsOffered)
        XCTAssertEqual(settings.packsInstalled, [.spa, .ell], "an upgrade's answer keeps the installed packs")

        let missing = PackOffer.Sheet(kind: .missing, checked: [.ell])
        PackOffer.record(missing, in: settings)
        XCTAssertEqual(settings.packsInstalled, [.spa])
        XCTAssertNil(decide(PackOffer.Signals(packsOffered: settings.packsOffered,
                                              packsInstalled: settings.packsInstalled, usable: [.spa])))
    }
}

// MARK: - Issue #244: the signals launch reads for the offer

/// `PackOffer.atLaunch` on real services: the user database, the settings
/// and the pack service's files feed `decide` (QA #244).
@MainActor
final class PackOfferLaunchTests: XCTestCase {
    private var tempDir: URL!
    private var sharedCatalog: PackCatalog!
    private var settings: SettingsService!
    private var packs: PackService!
    private var db: DatabaseService { .shared }
    private let languagePacks: [PackID] = [.spa, .rus, .arb, .ell]

    override func setUp() async throws {
        try await super.setUp()
        await DictAppTests.waitForHostAppLaunch()
        sharedCatalog = PackCatalog.shared
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        let bundle = try TestDictionary.bundledURL()
        try await db.setup(userPath: tempDir.appendingPathComponent("user.sqlite").path, dictionaryURL: bundle)
        settings = SettingsService(store: InMemoryKeyValueStore())
        settings.selectedUILanguageCode = "en"
        packs = PackService(folder: tempDir.appendingPathComponent("Packs", isDirectory: true),
                            downloads: tempDir.appendingPathComponent("Downloads", isDirectory: true),
                            database: db, settings: settings, status: PackStatusModel(),
                            localization: LocalizationManager(settingsService: settings, bundle: .main))
        try await packs.prepare()
    }

    override func tearDown() async throws {
        PackCatalog.shared = sharedCatalog
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    private func sheet(legacyFound: Bool = false) async throws -> PackOffer.Sheet? {
        try await PackOffer.atLaunch(legacyDatabaseFound: legacyFound, settings: settings, database: db,
                                     packs: packs,
                                     localization: LocalizationManager(settingsService: settings, bundle: .main))
    }

    /// A new user database, no stored preferences, no pack: the fresh
    /// sheet, with the UI language's pack checked.
    func testFreshInstall() async throws {
        let english = try await sheet()
        XCTAssertEqual(english?.kind, .fresh)
        XCTAssertFalse(english?.checked.contains(.spa) ?? true, "precondition: English UI")
        settings.selectedUILanguageCode = "es"
        let spanish = try await sheet()
        XCTAssertEqual(spanish?.kind, .fresh)
        XCTAssertEqual(spanish?.checked.contains(.spa), true, "the Spanish UI checks Spanish")
    }

    /// Each sign launch reads: a 1.x file, History, imports alone, a stored
    /// order holding a pack's dictionary; the enabled set picks the packs;
    /// an answered sheet shows no more.
    func testUpgradeReadsTheUserDatabaseAndSettings() async throws {
        let legacy = try await sheet(legacyFound: true)
        XCTAssertEqual(legacy, PackOffer.Sheet(kind: .upgrade, checked: languagePacks), "a 1.x file, nothing stored")

        try await db.addToHistory(word: "σπίτι", source: "freedict-ell-eng")
        settings.enabledSources = ["wordnet", "freedict-ell-eng", "wordnet-ell-eng", "freedict-eng-ell", "wordnet-eng-ell"]
        let alpha = try await sheet()
        XCTAssertEqual(alpha, PackOffer.Sheet(kind: .upgrade, checked: [.ell]), "History; Greek only was on")
        try await db.clearHistory()
        let cleared = try await sheet()
        XCTAssertEqual(cleared?.kind, .fresh, "precondition: no sign left")

        let json = tempDir.appendingPathComponent("glossary.json")
        try Data(#"[{"word": "zorblat", "definition": "a test word"}]"#.utf8).write(to: json)
        let added = try await db.importJSON(at: json, source: "my_glossary")
        XCTAssertEqual(added, 1, "precondition")
        let imported = try await sheet()
        XCTAssertEqual(imported?.kind, .upgrade, "an import alone is a sign")
        try await db.clearEntries(fromSource: "my_glossary")

        settings.dictionaryOrder = ["wordnet", "my_glossary"]
        let englishOrder = try await sheet()
        XCTAssertEqual(englishOrder?.kind, .fresh, "an order without a pack's dictionary is no sign")
        settings.dictionaryOrder = ["openrussian", "wordnet"]
        let order = try await sheet()
        XCTAssertEqual(order?.kind, .upgrade, "a stored order with a pack's dictionary")

        settings.packsOffered = true
        let answered = try await sheet(legacyFound: true)
        XCTAssertNil(answered, "the sheet shows once")
    }

    /// Usable packs come from the pack service: an installed Greek offers
    /// nothing; a pack recorded as installed without a file is offered
    /// again, before an upgrade's offer.
    func testMissingReadsThePackFiles() async throws {
        try await packs.install([.ell], fromAssetsIn: PackFixtures.assets)
        XCTAssertEqual(settings.packsInstalled, [.ell], "precondition: the install records Greek")
        settings.packsOffered = true
        let installed = try await sheet()
        XCTAssertNil(installed, "Greek is usable")

        settings.packsInstalled = [.ell, .rus]
        let missing = try await sheet(legacyFound: true)
        XCTAssertEqual(missing, PackOffer.Sheet(kind: .missing, checked: [.rus]))
        PackOffer.record(try XCTUnwrap(missing), in: settings)
        let answered = try await sheet()
        XCTAssertNil(answered, "answered once")
        XCTAssertEqual(settings.packsInstalled, [.ell])
    }
}

// MARK: - Issue #244: Dictionary Order keeps the catalog's dictionaries

/// `DictionarySelection` on the bundle and every pack: a pack that is not
/// installed (removed, or not downloaded yet after an update) keeps its
/// dictionaries' place and switch in the stored order, and they are listed
/// again where they were once it is installed (0237, "Update from 1.x").
@MainActor
final class DictionarySelectionPackTests: XCTestCase {
    private var tempDir: URL!
    private var db: DatabaseService { .shared }

    override func setUp() async throws {
        try await super.setUp()
        await DictAppTests.waitForHostAppLaunch()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        try await db.setup(userPath: tempDir.appendingPathComponent("user.sqlite").path,
                           dictionaryURL: try TestDictionary.bundledURL(), packFiles: try PackFixtures.all())
    }

    override func tearDown() async throws {
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    func testRemovedPackKeepsItsPlaceAndSwitch() async throws {
        let catalog = try PackFixtures.catalog()
        let greek = catalog.sources(of: .ell).map(\.source)
        let store = InMemoryKeyValueStore()
        let settings = SettingsService(store: store)
        settings.selectedUILanguageCode = "en"
        let localization = LocalizationManager(settingsService: settings, bundle: .main)
        let selection = DictionarySelection(settings: settings, localization: localization,
                                            catalogSources: { catalog.sources.map(\.source) })
        await selection.load()
        let greekIndex = try XCTUnwrap(selection.pairs.firstIndex { $0.id == "ell-eng" }, "precondition")
        selection.move(from: IndexSet(integer: greekIndex), to: 1)
        XCTAssertEqual(selection.pairs.map(\.id), ["eng", "ell-eng", "eng-spa", "eng-rus", "arb-eng"], "precondition")
        let ordered = try XCTUnwrap(settings.dictionaryOrder)
        XCTAssertNil(settings.enabledSources, "precondition: every dictionary on")

        // Greek is removed: the stub is attached under its name. A stale ID
        // in the stored order is still dropped.
        try await db.attachPacks([.ell: nil])
        settings.dictionaryOrder = ordered + ["ghost"]
        await selection.load()
        XCTAssertEqual(selection.pairs.map(\.id), ["eng", "eng-spa", "eng-rus", "arb-eng"], "only installed ones are listed")
        XCTAssertEqual(settings.dictionaryOrder, ordered, "the Greek dictionaries keep their place")

        // A switch and a reorder while Greek is gone keep its switch and place.
        selection.setEnabled(false, pair: "eng-rus")
        XCTAssertEqual(settings.enabledSources?.isSuperset(of: greek), true, "Greek stays on")
        XCTAssertEqual(settings.enabledSources?.contains("openrussian"), false)
        selection.move(from: IndexSet(integer: 2), to: 0)   // Russian first
        XCTAssertEqual(selection.pairs.map(\.id), ["eng-rus", "eng", "eng-spa", "arb-eng"])
        let order = try XCTUnwrap(settings.dictionaryOrder)
        XCTAssertEqual(order, ["openrussian", "wordnet"] + ordered.filter(greek.contains)
                       + ["freedict-eng-spa", "wordnet-spa-eng", "wordnet-arb-eng"],
                       "Greek stays right after English, the dictionary it followed")

        // Greek returns where it was, switched on.
        try await db.attachPacks([.ell: try PackFixtures.file(.ell)])
        await selection.load()
        XCTAssertEqual(selection.pairs.map(\.id), ["eng-rus", "eng", "ell-eng", "eng-spa", "arb-eng"])
        XCTAssertEqual(selection.pairs.first { $0.id == "ell-eng" }?.isEnabled, true)
        XCTAssertEqual(settings.dictionaryOrder, order, "nothing to store")
    }

    /// The pure rule behind a reorder: each source that is not listed stays
    /// right after the listed source it followed, or first; a member of a
    /// listed pair (an import named like a missing pack's source) stays
    /// with it, so grouping keeps the order the user dropped.
    func testOrderKeepsUnlistedSourcesAfterTheirNeighbour() {
        XCTAssertEqual(DictionaryGrouping.order(["b", "a"], keepingUnlistedOf: ["a", "x", "b", "y"]),
                       ["b", "y", "a", "x"])
        XCTAssertEqual(DictionaryGrouping.order(["b", "a"], keepingUnlistedOf: ["x", "a", "b"]), ["x", "b", "a"])
        XCTAssertEqual(DictionaryGrouping.order(["a", "b"], keepingUnlistedOf: []), ["a", "b"])
        XCTAssertEqual(DictionaryGrouping.order(["a", "b"], keepingUnlistedOf: ["a", "b"]), ["a", "b"])
        let kept = DictionaryGrouping.order(["wordnet", "freedict-eng-spa"],
                                            keepingUnlistedOf: ["wordnet-spa-eng", "freedict-eng-spa", "wordnet"])
        XCTAssertEqual(kept, ["wordnet", "freedict-eng-spa", "wordnet-spa-eng"])
        XCTAssertEqual(DictionaryGrouping.groupedOrder(kept), kept, "English stays first")
    }
}

// MARK: - Issue #141: Greek word forms in the dictionary file

/// The forms tables `Scripts/build_forms.py` writes into the bundled
/// `dictionaries.sqlite` (0136-word-forms.md, "Data" and "Pipeline: Greek
/// forms"). They read the real file, as the app attaches it.
final class WordFormsLookupTests: XCTestCase {

    /// The Greek pack, which holds the forms tables since #237.
    private func readDictionaryFile<T>(_ body: (Database) throws -> T) throws -> T {
        var config = Configuration()
        config.readonly = true
        return try DatabaseQueue(path: PackFixtures.file(.ell).path, configuration: config).read(body)
    }

    /// The lemmas a query maps to, looked up as Search will: the folded query
    /// as the `form_lookup` primary-key prefix.
    private func lemmas(of query: String, pos: String? = nil, in db: Database) throws -> [String] {
        try String.fetchAll(db, sql: """
            SELECT l.word FROM form_lookup AS f JOIN lemma AS l ON l.id = f.lemma_id
            WHERE f.form_norm = ? AND (? IS NULL OR l.pos = ?)
            ORDER BY l.word
            """, arguments: [Search.foldGreek(query), pos, pos])
    }

    /// #141: the source and license of the forms are a `dict.data_source`
    /// row (Credits reads it), never a `dict_metadata` row, which would add a
    /// dictionary to Dictionary Order.
    func testWiktionaryDataSourceRow() throws {
        try readDictionaryFile { db in
            let rows = try Row.fetchAll(db, sql: "SELECT * FROM data_source WHERE kind = 'word_forms'")
            XCTAssertEqual(rows.count, 1, "one word-forms data source")
            let row = try XCTUnwrap(rows.first)
            XCTAssertEqual(row["id"] as String, "wiktionary-ell-forms")
            XCTAssertEqual(row["display_name"] as String, "Wiktionary (Greek word forms)")
            XCTAssertEqual(row["license"] as String, "CC BY-SA 4.0")
            XCTAssertEqual(row["url"] as String, "https://kaikki.org/dictionary/")
            let version: String = row["version"]
            XCTAssertNotNil(version.range(of: #"^enwiktionary \d{4}-\d{2}-\d{2}$"#, options: .regularExpression),
                            "the snapshot date: \(version)")
            XCTAssertEqual(try Int.fetchOne(db, sql: """
                SELECT COUNT(*) FROM dict_metadata
                WHERE source LIKE '%wiktionary%' OR display_name LIKE '%Wiktionary%'
                """), 0, "the forms are no dictionary")
        }
    }

    /// #141, #136: closed-class words are no forms of any verb (the article ο
    /// sat in καλύπτω's table), and the stoplist that drops them leaves real
    /// forms alone: κάνεις → κάνω (κανείς folds the same), the 2-letter δω →
    /// βλέπω, έγραψα → γράφω.
    func testStoplistFormsMapToNoVerb() throws {
        let closedClass = ["ο", "η", "το", "οι", "τα", "του", "της", "των", "τον", "την", "τους", "τις",
                           "αν", "όταν", "είτε", "και", "ή", "ότι", "να", "θα", "ας", "δεν", "μην",
                           "σε", "στο", "στη", "με", "για", "από", "μου", "σου", "μας", "σας"]
        try readDictionaryFile { db in
            for word in closedClass {
                XCTAssertEqual(try lemmas(of: word, pos: "verb", in: db), [], "\(word) is no form of a verb")
            }
            XCTAssertTrue(try lemmas(of: "κάνεις", pos: "verb", in: db).contains("κάνω"))
            XCTAssertTrue(try lemmas(of: "δω", pos: "verb", in: db).contains("βλέπω"))
            XCTAssertTrue(try lemmas(of: "έγραψα", pos: "verb", in: db).contains("γράφω"))
        }
    }

    /// #141, spec step 5 for every open class: a closed-class word is no cell
    /// of a verb, noun, adjective or adverb table unless it is that lemma's
    /// own headword or `Scripts/data/forms-allowlist.tsv` re-admits it (παρά
    /// in the table of παράς). Compared as the build does: lowercase, never
    /// folded. The list is `STOPLIST` in `Scripts/build_forms.py`.
    func testStoplistedWordsAreNoCellOfAnOpenClassTable() throws {
        let stoplist = Set("""
            ο η το οι τα του της των τον την τη τους τις ένας μία μια ένα ενός μιας έναν
            και κι αν όταν είτε ή ότι πως που αλλά μα ενώ ούτε ουδέ όμως γιατί επειδή αφού ώστε μήπως
            να θα ας δεν δε μην μη
            σε στο στη στην στον στα στους στις στου στης με για από προς χωρίς κατά μετά παρά ως ώς
            μου σου μας σας εγώ εσύ εμείς εσείς
            """.split(whereSeparator: \.isWhitespace).map(String.init))
        try readDictionaryFile { db in
            var hits = Set<String>()
            var cells = 0
            let rows = try Row.fetchCursor(db, sql: """
                SELECT p.form, l.word, l.pos FROM paradigm AS p JOIN lemma AS l ON l.id = p.lemma_id
                WHERE l.pos IN ('verb', 'noun', 'adj', 'adv')
                """)
            while let row = try rows.next() {
                cells += 1
                let form = (row["form"] as String).lowercased(), word: String = row["word"]
                if stoplist.contains(form) && form != word.lowercased() {
                    hits.insert("\(row["form"] as String) in \(word) (\(row["pos"] as String))")
                }
            }
            XCTAssertGreaterThan(cells, 300_000, "the open-class tables were read")
            XCTAssertEqual(hits, ["παρά in παράς (noun)"], "only the allowlisted stoplist hit stays")
        }
    }

    /// #141 "Data": the four forms tables with the spec's keys. Search looks a
    /// form up by the `form_lookup` primary-key prefix, a lemma's text key
    /// `(lang, word, pos)` is unique, and `paradigm` keeps the table order
    /// 1…n. Every row points at a lemma and a tag set. Counts are lower bounds
    /// ("all Greek lemmas, ~26k"), so a reviewed snapshot refresh keeps this
    /// test as it is.
    func testFormsTablesFollowTheSpec() throws {
        try readDictionaryFile { db in
            func primaryKey(_ table: String) throws -> [String] {
                try Row.fetchAll(db, sql: "PRAGMA table_info(\(table.quotedDatabaseIdentifier))")
                    .filter { ($0["pk"] as Int) > 0 }
                    .sorted { ($0["pk"] as Int) < ($1["pk"] as Int) }
                    .map { $0["name"] as String }
            }
            func indexedColumns(_ table: String, unique: Bool) throws -> [[String]] {
                try Row.fetchAll(db, sql: "PRAGMA index_list(\(table.quotedDatabaseIdentifier))")
                    .filter { ($0["unique"] as Int) == (unique ? 1 : 0) }
                    .map { index in
                        try Row.fetchAll(db, sql: "PRAGMA index_info(\((index["name"] as String).quotedDatabaseIdentifier))")
                            .map { $0["name"] as String }
                    }
            }
            XCTAssertEqual(try primaryKey("form_lookup"), ["form_norm", "lemma_id"])
            XCTAssertEqual(try primaryKey("paradigm"), ["lemma_id", "ord"])
            XCTAssertEqual(try primaryKey("lemma"), ["id"])
            XCTAssertEqual(try primaryKey("tagset"), ["id"])
            for table in ["form_lookup", "paradigm"] {
                let sql = try XCTUnwrap(String.fetchOne(db, sql: "SELECT sql FROM sqlite_master WHERE name = ?",
                                                        arguments: [table]))
                XCTAssertTrue(sql.contains("WITHOUT ROWID"), "\(table) is WITHOUT ROWID: \(sql)")
            }
            XCTAssertTrue(try indexedColumns("lemma", unique: true).contains(["lang", "word", "pos"]), "the text key is unique")
            XCTAssertTrue(try indexedColumns("lemma", unique: false).contains(["word_normalized"]), "the table lookup by folded word")
            XCTAssertTrue(try indexedColumns("tagset", unique: true).contains(["tags"]))

            func count(_ sql: String) throws -> Int { try Int.fetchOne(db, sql: sql) ?? -1 }
            XCTAssertGreaterThan(try count("SELECT COUNT(*) FROM lemma"), 25_000, "all Greek lemmas")
            XCTAssertGreaterThan(try count("SELECT COUNT(*) FROM paradigm"), 300_000)
            XCTAssertGreaterThan(try count("SELECT COUNT(*) FROM form_lookup"), 200_000)
            XCTAssertGreaterThan(try count("SELECT COUNT(*) FROM tagset"), 100)
            XCTAssertEqual(try String.fetchAll(db, sql: "SELECT DISTINCT lang FROM lemma"), ["ell"])
            XCTAssertEqual(try count("""
                SELECT COUNT(*) FROM (SELECT MAX(ord) AS last, COUNT(*) AS n FROM paradigm GROUP BY lemma_id)
                WHERE last != n
                """), 0, "each table's ord runs 1…n")
            XCTAssertEqual(try count("""
                SELECT (SELECT COUNT(*) FROM paradigm WHERE lemma_id NOT IN (SELECT id FROM lemma)
                                                         OR tagset_id NOT IN (SELECT id FROM tagset))
                     + (SELECT COUNT(*) FROM form_lookup WHERE lemma_id NOT IN (SELECT id FROM lemma)
                                                            OR tagset_id NOT IN (SELECT id FROM tagset))
                """), 0, "every row points at a lemma and a tag set")
        }
    }

    /// #141, #87: Python's `normalize_greek` wrote `word_normalized` and
    /// `form_norm`, and Search folds the query with `Search.foldGreek`. They
    /// must agree byte for byte, as SQLite compares them, or a stored form is
    /// never found. Over the whole file: every lemma's `word_normalized` is its
    /// folded word, and every head form and table cell has the lookup row of
    /// its folded form for its lemma (spec step 6).
    func testLookupKeysAreTheAppsFolding() throws {
        struct Key: Hashable { let form: [UInt8]; let lemma: Int64 }
        try readDictionaryFile { db in
            var keys = Set<Key>()
            let lookups = try Row.fetchCursor(db, sql: "SELECT form_norm, lemma_id FROM form_lookup")
            while let row = try lookups.next() {
                keys.insert(Key(form: Array((row["form_norm"] as String).utf8), lemma: row["lemma_id"]))
            }
            var mismatches: [String] = []
            var lemmas = 0, cells = 0
            let lemmaRows = try Row.fetchCursor(db, sql: "SELECT id, word, word_normalized FROM lemma")
            while let row = try lemmaRows.next() {
                lemmas += 1
                let word: String = row["word"], folded = Search.foldGreek(word)
                if !folded.utf8.elementsEqual((row["word_normalized"] as String).utf8) {
                    mismatches.append("lemma \(word): word_normalized '\(row["word_normalized"] as String)', Swift '\(folded)'")
                }
                if !keys.contains(Key(form: Array(folded.utf8), lemma: row["id"])) {
                    mismatches.append("no head-form lookup row for \(word)")
                }
            }
            let cellRows = try Row.fetchCursor(db, sql: "SELECT lemma_id, form FROM paradigm")
            while let row = try cellRows.next() {
                cells += 1
                let form: String = row["form"]
                if !keys.contains(Key(form: Array(Search.foldGreek(form).utf8), lemma: row["lemma_id"])) {
                    mismatches.append("no lookup row for the cell \(form) of lemma \(row["lemma_id"] as Int64)")
                }
            }
            XCTAssertGreaterThan(lemmas, 25_000)
            XCTAssertGreaterThan(cells, 300_000)
            XCTAssertTrue(mismatches.isEmpty, "\(mismatches.count) mismatches, e.g. \(mismatches.prefix(5))")
        }
    }

    /// #141 junk filter on the shipped file (spec step 2): every lemma word,
    /// table cell and lookup key is one Greek word, i.e. Greek letters with
    /// their combining marks and nothing else: no empty string, space,
    /// hyphen, apostrophe, digit, Latin letter (`Αναξιμένoυς` with a Latin o)
    /// or placeholder (`-`, `‑η`, `➤`). No cell is tagged `error-*` or
    /// single-word `future`. No cell carries two accents (`γόνιμός`) or a
    /// final sigma inside the word (`άφυλλοςος`), Wiktionary template errors.
    func testFormsAreOneGreekWord() throws {
        let letters: Set<Unicode.GeneralCategory> = [.uppercaseLetter, .lowercaseLetter, .titlecaseLetter,
                                                     .modifierLetter, .otherLetter]
        func isOneGreekWord(_ s: String) -> Bool {
            guard let first = s.unicodeScalars.first, first.properties.generalCategory != .nonspacingMark else { return false }
            return s.unicodeScalars.allSatisfy { scalar in
                scalar.properties.generalCategory == .nonspacingMark
                    || (Search.isGreek(scalar) && letters.contains(scalar.properties.generalCategory))
            }
        }
        for junk in ["", "-", "‑η", "➤", "Αναξιμένoυς", "θα γράψω", "γράφ'", "λύσω²", "\u{0301}α"] {
            XCTAssertFalse(isOneGreekWord(junk), "the check rejects '\(junk)'")
        }
        for word in ["δω", "ΐ", "Ἀθῆναι", "γράφω"] {
            XCTAssertTrue(isOneGreekWord(word), "the check accepts \(word)")
        }
        // Acute (tonos), grave and circumflex count as accents; breathings and the diaeresis do not.
        func isMisspelt(_ s: String) -> Bool {
            let accents = s.decomposedStringWithCanonicalMapping.unicodeScalars
                .filter { [0x0301, 0x0300, 0x0342].contains($0.value) }.count
            return accents > 1 || s.dropLast().contains("ς")
        }
        for junk in ["γόνιμός", "εκστρατεύόμαστε", "άφυλλοςος"] {
            XCTAssertTrue(isMisspelt(junk), "the check rejects '\(junk)'")
        }
        for word in ["δω", "ΐ", "Ἀθῆναι", "γράφω", "λόγος"] {
            XCTAssertFalse(isMisspelt(word), "the check accepts \(word)")
        }

        try readDictionaryFile { db in
            var junk: [String] = []
            var misspelt: [String] = []
            for (table, column) in [("lemma", "word"), ("paradigm", "form"), ("form_lookup", "form_norm")] {
                var values = 0
                let cursor = try String.fetchCursor(db, sql: "SELECT \(column) FROM \(table)")
                while let value = try cursor.next() {
                    values += 1
                    if !isOneGreekWord(value) { junk.append("\(table).\(column) '\(value)'") }
                    if table == "paradigm" && isMisspelt(value) { misspelt.append(value) }
                }
                XCTAssertGreaterThan(values, 25_000, "\(table) was read")
            }
            XCTAssertTrue(junk.isEmpty, "\(junk.count) values are not one Greek word, e.g. \(junk.prefix(10))")
            XCTAssertTrue(misspelt.isEmpty, "\(misspelt.count) cells are misspelt, e.g. \(misspelt.prefix(10))")
            XCTAssertEqual(try Int.fetchOne(db, sql: """
                SELECT COUNT(*) FROM paradigm AS p JOIN tagset AS t ON t.id = p.tagset_id
                WHERE ' ' || t.tags || ' ' LIKE '% future %' OR ' ' || t.tags LIKE '% error-%'
                """), 0, "no cell tagged error-* or single-word future")
        }
    }

    /// #141 links and guards on the real snapshot, with the tag set Search
    /// captions (the first cell in table order, else the first link): table
    /// cells (έγραψα and ΈΓΡΑΨΑ → γράφω, aorist 1sg; σπιτιού → σπίτι,
    /// genitive singular), `form_of` (ξέρεις → ξέρω), `alt_of` without a cell
    /// (δω → εδώ, alternative), a cell that is also an `alt_of` page (πάω →
    /// πηγαίνω). The pronoun template guard: the pronouns τα, εγώ and εσύ keep
    /// no table, so σας and μας are forms of no other pronoun. The template
    /// error rules: a note no longer drops a cell (κάνω (κάμνω →) is κάνω's
    /// present 1sg); suppletive forms keep their lemma (πήγα → πάω, whose
    /// link takes perfective from its gloss "simple past"); a table declined
    /// from another word is dropped (κρεατομηχανή held μηχανή's forms), as
    /// are bare endings (ει was a form of σαλπάρω). Also: " - " variants are
    /// split (θυμάμαι - θυμούμαι), a nested note is stripped (σκέφτομαι), a
    /// suppletive table stays (βλέπω: είδα, δω), αισώπειος's bare endings are
    /// gone and the link γάτος → γάτα, tagged `error-lua-exec`, gives no row.
    func testLinksAndPronounGuardOnTheSnapshot() throws {
        try readDictionaryFile { db in
            func tags(_ form: String, of lemma: String) throws -> String? {
                try String.fetchOne(db, sql: """
                    SELECT t.tags FROM form_lookup AS f JOIN lemma AS l ON l.id = f.lemma_id
                    JOIN tagset AS t ON t.id = f.tagset_id WHERE f.form_norm = ? AND l.word = ?
                    """, arguments: [Search.foldGreek(form), lemma])
            }
            let aorist1sg = "active first-person indicative past perfective singular"
            XCTAssertEqual(try tags("έγραψα", of: "γράφω"), aorist1sg)
            XCTAssertEqual(try tags("ΈΓΡΑΨΑ", of: "γράφω"), aorist1sg, "case and accents fold")
            XCTAssertEqual(try tags("σπιτιού", of: "σπίτι"), "genitive singular")
            XCTAssertEqual(try tags("ξέρεις", of: "ξέρω"), "active imperfective indicative present second-person singular")
            XCTAssertEqual(try tags("δω", of: "εδώ"), "alternative")
            XCTAssertEqual(try tags("πάω", of: "πηγαίνω"), "active first-person imperfective indicative present singular")
            XCTAssertNil(try tags("έγραψα", of: "γραφή"), "no link to a lemma it is no form of")

            XCTAssertEqual(try tags("κάνω", of: "κάνω"), "active first-person imperfective indicative present singular",
                           "κάνω (κάμνω →) is κάνω's present 1sg")
            XCTAssertEqual(try tags("πήγα", of: "πάω"), "first-person past perfective singular")
            XCTAssertEqual(try tags("πήγα", of: "πηγαίνω"), aorist1sg)
            XCTAssertEqual(try Int.fetchOne(db, sql: """
                SELECT COUNT(*) FROM paradigm AS p JOIN lemma AS l ON l.id = p.lemma_id WHERE l.word = 'κρεατομηχανή'
                """), 0, "κρεατομηχανή keeps no table of μηχανή's forms")
            XCTAssertEqual(try lemmas(of: "μηχανή", pos: "noun", in: db), ["μηχανή"])
            XCTAssertFalse(try lemmas(of: "ει", in: db).contains("σαλπάρω"), "the bare ending ει is gone")

            // QA, round 2: the other template-error rules on the shipped file.
            func cellTags(_ form: String, of verb: String) throws -> [String] {
                try String.fetchAll(db, sql: """
                    SELECT t.tags FROM paradigm AS p JOIN lemma AS l ON l.id = p.lemma_id
                    JOIN tagset AS t ON t.id = p.tagset_id WHERE p.form = ? AND l.word = ? AND l.pos = 'verb'
                    """, arguments: [form, verb])
            }
            let passivePresent1sg = "first-person imperfective indicative passive present singular"
            XCTAssertEqual(try cellTags("θυμάμαι", of: "θυμάμαι"), [passivePresent1sg], "θυμάμαι - θυμούμαι is split")
            XCTAssertEqual(try cellTags("θυμούμαι", of: "θυμάμαι"), [passivePresent1sg], "both variants are cells")
            XCTAssertEqual(try tags("σκέφτομαι", of: "σκέφτομαι"), passivePresent1sg,
                           "a nested note is stripped: σκέφτομαι (→ σκέπτομαι (sképtomai))")
            XCTAssertEqual(try cellTags("είδα", of: "βλέπω"), [aorist1sg], "a suppletive table holds its headword, so it stays")
            XCTAssertEqual(try cellTags("δω", of: "βλέπω"), ["active dependent first-person indicative perfective singular"])
            XCTAssertEqual(try Int.fetchOne(db, sql: """
                SELECT COUNT(*) FROM paradigm AS p JOIN lemma AS l ON l.id = p.lemma_id WHERE l.word = 'αισώπειος'
                """), 0, "αισώπειος held only bare endings (ος, α, ου)")
            XCTAssertFalse(try lemmas(of: "ου", in: db).contains("αισώπειος"))
            XCTAssertFalse(try lemmas(of: "γάτος", in: db).contains("γάτα"), "the link γάτος → γάτα is tagged error-lua-exec")

            for pronoun in ["τα", "εγώ", "εσύ"] {
                XCTAssertEqual(try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM lemma WHERE word = ? AND pos = 'pron'",
                                               arguments: [pronoun]), 1, "\(pronoun) is a pronoun lemma")
                XCTAssertEqual(try Int.fetchOne(db, sql: """
                    SELECT COUNT(*) FROM paradigm AS p JOIN lemma AS l ON l.id = p.lemma_id
                    WHERE l.word = ? AND l.pos = 'pron'
                    """, arguments: [pronoun]), 0, "\(pronoun): the shared personal-pronoun template is dropped")
            }
            XCTAssertEqual(try lemmas(of: "σας", pos: "pron", in: db), ["σας"], "σας → τα is gone")
            XCTAssertEqual(try lemmas(of: "μας", pos: "pron", in: db), ["μας"])
        }
    }
}

// MARK: - Issue #142: search by inflected Greek form (0136-word-forms.md)

/// The merge of lemma rows into a ranked bucket and the form step's gate
/// (0136, "Search path"): pure, no database.
extension SearchAssembleTests {
    private func ranked(_ id: Int64, exact: Bool = false) -> Search.RankedEntry {
        Search.RankedEntry(entry: entry(id, "A"), isExact: exact)
    }

    private func lemmaRow(_ id: Int64, lemma: String = "γράφω") -> SearchResult {
        SearchResult(entry: entry(id, "A"), formMatch: FormMatch(lemma: lemma, analysis: .greek(tags: ["present"])))
    }

    /// Exact rows, then the lemma rows with their match, then the prefix and
    /// FTS rows.
    func testLemmaRowsFollowExactRowsAndPrecedeTheRest() {
        let out = Search.mergeLemmaBucket(ranked: [ranked(1, exact: true), ranked(2, exact: true), ranked(3), ranked(4)],
                                          lemmaRows: [lemmaRow(10), lemmaRow(11)], limit: 50)
        XCTAssertEqual(out.map(\.id), [1, 2, 10, 11, 3, 4])
        XCTAssertEqual(out.map { $0.formMatch != nil }, [false, false, true, true, false, false])

        let noExact = Search.mergeLemmaBucket(ranked: [ranked(3), ranked(4)], lemmaRows: [lemmaRow(10)], limit: 50)
        XCTAssertEqual(noExact.map(\.id), [10, 3, 4], "without exact rows the lemma rows lead")
    }

    /// A lemma row that is an exact row stays one, without a match; a lemma
    /// row further down moves up with its match; no row repeats.
    func testLemmaRowsAreNeverRepeated() {
        let out = Search.mergeLemmaBucket(ranked: [ranked(1, exact: true), ranked(2), ranked(3)],
                                          lemmaRows: [lemmaRow(1), lemmaRow(3), lemmaRow(3)], limit: 50)
        XCTAssertEqual(out.map(\.id), [1, 3, 2])
        XCTAssertNil(out[0].formMatch, "the exact row keeps its place and gets no caption")
        XCTAssertNotNil(out[1].formMatch, "the lemma row moved up with its caption")
    }

    /// The merge is cut to the bucket's limit after the lemma rows join, so
    /// they push base rows out.
    func testMergeCutsToTheLimit() {
        let rows = [ranked(1, exact: true), ranked(2), ranked(3)]
        let lemmas = [lemmaRow(10), lemmaRow(11)]
        XCTAssertEqual(Search.mergeLemmaBucket(ranked: rows, lemmaRows: lemmas, limit: 3).map(\.id), [1, 10, 11])
        XCTAssertEqual(Search.mergeLemmaBucket(ranked: rows, lemmaRows: lemmas, limit: 2).map(\.id), [1, 10])
        XCTAssertEqual(Search.mergeLemmaBucket(ranked: rows, lemmaRows: lemmas, limit: 0), [])
    }

    /// No candidates: the rows, their order and the cut are today's, also for
    /// a rank-ordered list whose exact rows are not in front (the
    /// preferred-mode tail).
    func testNoLemmaRowsKeepsTheRankedRows() {
        let rows = [ranked(5), ranked(1, exact: true), ranked(2), ranked(3, exact: true)]
        let out = Search.mergeLemmaBucket(ranked: rows, lemmaRows: [], limit: 50)
        XCTAssertEqual(out.map(\.id), [5, 1, 2, 3])
        XCTAssertTrue(out.allSatisfy { $0.formMatch == nil })
        XCTAssertEqual(Search.mergeLemmaBucket(ranked: rows, lemmaRows: [], limit: 2).map(\.id), [5, 1])
    }

    /// In a rank-ordered tail the lemma rows go after its leading exact rows
    /// (none here) and no other row moves.
    func testLemmaRowsJoinARankOrderedTailWithoutReorderingIt() {
        let out = Search.mergeLemmaBucket(ranked: [ranked(5), ranked(1, exact: true), ranked(2)],
                                          lemmaRows: [lemmaRow(10)], limit: 50)
        XCTAssertEqual(out.map(\.id), [10, 5, 1, 2])
    }

    /// `assemble` takes search results as it takes entries, and keeps the matches.
    func testAssembleKeepsFormMatches() {
        let out = Search.assemble(buckets: ["0": [lemmaRow(1), SearchResult(entry: entry(2, "A"))]],
                                  tail: [lemmaRow(1), SearchResult(entry: entry(3, "B"))], order: ["0"])
        XCTAssertEqual(out.map(\.id), [1, 2, 3])
        XCTAssertEqual(out[0].formMatch?.lemma, "γράφω")
    }

    /// Up to 5 lemmas: every row of the first five stays, a sixth lemma's go.
    func testCapLemmasKeepsFiveLemmas() {
        let rows = [lemmaRow(1, lemma: "a"), lemmaRow(2, lemma: "a"), lemmaRow(3, lemma: "b"), lemmaRow(4, lemma: "c"),
                    lemmaRow(5, lemma: "d"), lemmaRow(6, lemma: "e"), lemmaRow(7, lemma: "f"), lemmaRow(8, lemma: "b")]
        XCTAssertEqual(Search.capLemmas(rows).map(\.id), [1, 2, 3, 4, 5, 6, 8])
        XCTAssertEqual(Search.maximumFormLemmas, 5)
        XCTAssertEqual(Search.maximumLemmaRows, 10)
    }

    /// The form step: one Greek word of 2+ letters, with or without accents,
    /// in any case, precomposed or not. Several words, other or mixed
    /// scripts, digits and one letter get none (a–z: `MorphyTests`, #143).
    func testFormStepNeedsOneGreekWordOfTwoLetters() {
        XCTAssertEqual(Search.formStep(for: "έγραψα"), .greek(key: "εγραψα"))
        XCTAssertEqual(Search.formStep(for: "εγραψα"), .greek(key: "εγραψα"))
        XCTAssertEqual(Search.formStep(for: "ΈΓΡΑΨΑ"), .greek(key: "εγραψα"))
        XCTAssertEqual(Search.formStep(for: "γρα\u{0301}φω"), .greek(key: "γραφω"), "decomposed accent")
        XCTAssertEqual(Search.formStep(for: "κάνεις"), .greek(key: "κανεισ"), "final sigma folds")
        XCTAssertEqual(Search.formStep(for: "δω"), .greek(key: "δω"), "two letters are enough")
        for query in ["", "ά", "έγραψα σήμερα", "έγραψα1", "abγρ", "дом", "ماء"] {
            XCTAssertNil(Search.formStep(for: query), "'\(query)' gets no form step")
        }
    }
}

/// `FormCaption`: the caption of a lemma row, pure (0136, "Caption").
final class FormCaptionTests: XCTestCase {
    private let ltrCodes = ["en", "ru", "es", "el"]
    private let bidiControls: [Unicode.Scalar] = ["\u{200F}", "\u{2066}", "\u{2067}", "\u{2068}", "\u{2069}"]

    private func tags(_ s: String) -> Set<String> {
        Set(s.split(separator: " ").map(String.init))
    }

    private func greek(_ lemma: String, _ tagString: String) -> FormMatch {
        FormMatch(lemma: lemma, analysis: .greek(tags: tags(tagString)))
    }

    /// The bundled file's caption tag sets of έγραψα, ήταν, έχεις, πήγα,
    /// σπιτιού and της.
    private let aorist1sg = "active first-person indicative past perfective singular"
    private let imperfect3sg = "active imperfect imperfective indicative informal singular third-person"
    private let present2sg = "active imperfective indicative present second-person singular"

    /// The spec table's rows.
    func testSpecTableLabels() {
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags(aorist1sg)), [.aorist, .firstSingular])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags(imperfect3sg)), [.imperfect, .thirdSingular])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags(present2sg)), [.present, .secondSingular])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("first-person past perfective singular")),
                       [.aorist, .firstSingular], "πήγα → πάω has no indicative tag")
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("genitive singular")), [.genitive, .singular])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("definite feminine genitive singular")),
                       [.genitive, .singular, .feminine])
    }

    func testEnglishCaptions() {
        let en = Locale(identifier: "en")
        XCTAssertEqual(FormCaption.text(for: greek("γράφω", aorist1sg), locale: en), "aorist 1sg of γράφω")
        XCTAssertEqual(FormCaption.text(for: greek("είμαι", imperfect3sg), locale: en), "imperfect 3sg of είμαι")
        XCTAssertEqual(FormCaption.text(for: greek("έχω", present2sg), locale: en), "present 2sg of έχω")
        XCTAssertEqual(FormCaption.text(for: greek("σπίτι", "genitive singular"), locale: en), "genitive singular of σπίτι")
        XCTAssertEqual(FormCaption.text(for: greek("ο", "definite feminine genitive singular"), locale: en),
                       "genitive singular feminine of ο")
    }

    func testCaptionsInRussianSpanishAndGreek() {
        let match = greek("γράφω", aorist1sg)
        XCTAssertEqual(FormCaption.text(for: match, locale: Locale(identifier: "ru")), "аорист 1 л. ед. ч. от γράφω")
        XCTAssertEqual(FormCaption.text(for: match, locale: Locale(identifier: "es")), "aoristo 1.ª sing. de γράφω")
        XCTAssertEqual(FormCaption.text(for: match, locale: Locale(identifier: "el")), "αόριστος α\u{0384} ενικ. του γράφω")
        XCTAssertEqual(FormCaption.text(for: greek("σπίτι", "genitive singular"), locale: Locale(identifier: "ru")),
                       "родительный ед. ч. от σπίτι")
    }

    /// Arabic: the caption starts with U+200F and the lemma is isolated
    /// (FSI … PDI), as in #119; the LTR languages get no bidi control.
    func testArabicCaptionReadsRightToLeft() {
        let caption = FormCaption.text(for: greek("γράφω", aorist1sg), locale: Locale(identifier: "ar"))
        XCTAssertEqual(caption.unicodeScalars.first, "\u{200F}", caption)
        XCTAssertTrue(caption.contains("\u{2068}γράφω\u{2069}"), "the Greek lemma is isolated: \(caption.unicodeScalars.map(\.value))")
        let visible = String(caption.unicodeScalars.filter { !bidiControls.contains($0) })
        XCTAssertEqual(visible, "الماضي البسيط المتكلم المفرد من γράφω")
        let spoken = FormCaption.accessibilityText(for: greek("γράφω", aorist1sg), locale: Locale(identifier: "ar"))
        XCTAssertEqual(spoken.unicodeScalars.first, "\u{200F}", spoken)

        for code in ltrCodes {
            let locale = Locale(identifier: code)
            for output in [FormCaption.text(for: greek("γράφω", aorist1sg), locale: locale),
                           FormCaption.accessibilityText(for: greek("γράφω", aorist1sg), locale: locale)] {
                XCTAssertFalse(output.unicodeScalars.contains { bidiControls.contains($0) },
                               "\(code): '\(output)' must carry no bidi control")
            }
        }
    }

    /// Passive, dependent, imperative, participle and infinitive forms.
    func testVerbLabels() {
        let en = Locale(identifier: "en")
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("first-person indicative passive past perfective singular")),
                       [.aorist, .passive, .firstSingular])
        XCTAssertEqual(FormCaption.text(for: greek("γράφω", "first-person indicative passive past perfective singular"),
                                        locale: en), "aorist passive 1sg of γράφω")
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("dependent first-person indicative passive perfective singular")),
                       [.dependent, .passive, .firstSingular])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("active imperative imperfective second-person singular")),
                       [.imperative, .continuous, .secondSingular])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("active imperative perfective plural second-person")),
                       [.imperative, .simple, .secondPlural])
        XCTAssertEqual(FormCaption.text(for: greek("γράφω", "active imperative perfective plural second-person"),
                                        locale: en), "imperative simple 2pl of γράφω")
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("active first-person imperfect imperfective indicative plural")),
                       [.imperfect, .firstPlural])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("active participle present")), [.participle])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("participle passive past")), [.participle])
        XCTAssertEqual(FormCaption.text(for: greek("γράφω", "active infinitive-aorist"), locale: en),
                       "aorist infinitive of γράφω")
    }

    /// Nominals: degree, case, number, then gender when tagged.
    func testNominalLabels() {
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("masculine nominative plural")),
                       [.nominative, .plural, .masculine])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("accusative comparative masculine plural superlative")),
                       [.comparative, .accusative, .plural, .masculine])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("feminine nominative singular superlative")),
                       [.superlative, .nominative, .singular, .feminine])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("singular vocative")), [.vocative, .singular])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("absolute superlative")), [.superlative])
    }

    /// `alternative` → "alternative form"; nothing recognised → "form".
    func testAlternativeAndUnknownTags() {
        let en = Locale(identifier: "en")
        XCTAssertEqual(FormCaption.text(for: greek("αγαπάω", "alternative"), locale: en), "alternative form of αγαπάω")
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("alternative masculine")), [.alternative])
        XCTAssertEqual(FormCaption.text(for: greek("γράφω", ""), locale: en), "form of γράφω")
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("Katharevousa dative singular")), [.form])
        XCTAssertEqual(FormCaption.labels(forGreekTags: tags("indeclinable")), [.form])
    }

    /// VoiceOver reads the person as the Greek pronoun of the tables.
    func testVoiceOverReadsThePersonAsTheGreekPronoun() {
        let en = Locale(identifier: "en")
        XCTAssertEqual(FormCaption.accessibilityText(for: greek("γράφω", aorist1sg), locale: en), "aorist, εγώ of γράφω")
        XCTAssertEqual(FormCaption.accessibilityText(for: greek("είμαι", imperfect3sg), locale: en),
                       "imperfect, αυτός of είμαι")
        XCTAssertEqual(FormCaption.accessibilityText(for: greek("σπίτι", "genitive singular"), locale: en),
                       "genitive, singular of σπίτι")
        let persons: [(FormCaption.Label, String)] = [(.firstSingular, "εγώ"), (.secondSingular, "εσύ"),
                                                      (.thirdSingular, "αυτός"), (.firstPlural, "εμείς"),
                                                      (.secondPlural, "εσείς"), (.thirdPlural, "αυτοί")]
        for (label, pronoun) in persons {
            XCTAssertEqual(label.pronoun, pronoun)
        }
        XCTAssertNil(FormCaption.Label.aorist.pronoun)
    }

    /// Every label and the caption format resolve in every UI language.
    func testEveryLabelResolvesInEveryUILanguage() throws {
        let codes = try DictAppTests.shippedUILanguages().map(\.code)
        XCTAssertEqual(Set(codes), ["en", "ru", "es", "ar", "el"])
        for code in codes {
            let path = try XCTUnwrap(Bundle.main.path(forResource: code, ofType: "lproj"), code)
            let bundle = try XCTUnwrap(Bundle(path: path))
            for key in FormCaption.Label.allCases.map(\.rawValue) + ["forms.caption %@ %@"] {
                let value = bundle.localizedString(forKey: key, value: "\u{0}MISSING", table: nil)
                XCTAssertNotEqual(value, "\u{0}MISSING", "'\(key)' missing in \(code).lproj")
                XCTAssertFalse(value.isEmpty, "'\(key)' is empty in \(code).lproj")
            }
        }
    }
}

/// Search with the form step on the real bundled dictionary file (0136,
/// "Search by any form" and the #142 test plan rows).
@MainActor
final class WordFormsSearchTests: XCTestCase {
    private var tempDir: URL!
    private var db: DatabaseService { .shared }
    private static let greekHeadwordSources: Set<String> = ["freedict-ell-eng", "wordnet-ell-eng"]

    override func setUp() async throws {
        try await super.setUp()
        await DictAppTests.waitForHostAppLaunch()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        try await db.setup(userPath: tempDir.appendingPathComponent("user.sqlite").path,
                           dictionaryURL: try TestDictionary.bundledURL(), packFiles: try PackFixtures.all())
    }

    override func tearDown() async throws {
        DatabaseService.lemmaStepEnabled = true
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    /// The rows the form step added, as (source, word, lemma).
    private func lemmaRows(_ results: [SearchResult]) -> [SearchResult] {
        results.filter { $0.formMatch != nil }
    }

    /// Checks that the lemma rows of `query` are `lemma`'s headwords in both
    /// Greek → English dictionaries with `labels`, right after the exact
    /// rows and before every other row.
    private func assertLemmaRows(_ query: String, lemma: String, labels: [FormCaption.Label],
                                 file: StaticString = #filePath, line: UInt = #line) async throws {
        let results = try await db.searchResults(query: query)
        let key = Search.foldGreek(query)
        let first = try XCTUnwrap(results.firstIndex { $0.formMatch != nil }, "'\(query)' adds no lemma row",
                                  file: file, line: line)
        XCTAssertTrue(results[..<first].allSatisfy { Search.foldGreek($0.entry.word) == key },
                      "'\(query)': only exact rows precede the lemma rows: \(results[..<first].map(\.entry.word))",
                      file: file, line: line)
        let added = lemmaRows(results)
        XCTAssertEqual(results[first..<(first + added.count)].map(\.id), added.map(\.id),
                       "'\(query)': the lemma rows are one block", file: file, line: line)
        let ofLemma = added.filter { $0.formMatch?.lemma == lemma }
        XCTAssertEqual(Set(ofLemma.map(\.entry.source)), Self.greekHeadwordSources,
                       "'\(query)' shows \(lemma) from both Greek → English dictionaries", file: file, line: line)
        for row in ofLemma {
            XCTAssertEqual(Search.foldGreek(row.entry.word), Search.foldGreek(lemma), file: file, line: line)
            XCTAssertEqual(FormCaption.labels(for: try XCTUnwrap(row.formMatch)), labels, "'\(query)'",
                           file: file, line: line)
        }
    }

    /// #142: έγραψα → γράφω, ήταν → είμαι, έχεις → έχω, also without
    /// accents and in capitals; the lemma rows come right after the exact
    /// rows, with the caption tags.
    func testInflectedGreekFindsLemma() async throws {
        for query in ["έγραψα", "εγραψα", "ΈΓΡΑΨΑ"] {
            try await assertLemmaRows(query, lemma: "γράφω", labels: [.aorist, .firstSingular])
        }
        try await assertLemmaRows("ήταν", lemma: "είμαι", labels: [.imperfect, .thirdSingular])
        try await assertLemmaRows("ηταν", lemma: "είμαι", labels: [.imperfect, .thirdSingular])
        try await assertLemmaRows("έχεις", lemma: "έχω", labels: [.present, .secondSingular])
        try await assertLemmaRows("σπιτιού", lemma: "σπίτι", labels: [.genitive, .singular])

        // της: the exact row τής (FreeDict) first, then the article ο.
        let tis = try await db.searchResults(query: "της")
        XCTAssertEqual(tis.first?.entry.word, "τής")
        XCTAssertNil(tis.first?.formMatch)
        let article = lemmaRows(tis).filter { $0.formMatch?.lemma == "ο" }
        XCTAssertFalse(article.isEmpty, "της shows ο")
        XCTAssertEqual(article.first.map { FormCaption.text(for: $0.formMatch!, locale: Locale(identifier: "en")) },
                       "genitive singular feminine of ο")
    }

    /// #142, #136: frequent subtitle words that are no headword but a form of
    /// one (OpenSubtitles 2018 top 5,000, `forms-qa.md`) find their lemma.
    func testFindabilitySpotList() async throws {
        let spots: [(form: String, lemma: String)] = [
            ("ήταν", "είμαι"), ("είσαι", "είμαι"), ("έχει", "έχω"), ("ξέρεις", "ξέρω"), ("έχεις", "έχω"),
            ("κάνεις", "κάνω"), ("όλα", "όλος"), ("μπορεί", "μπορώ"), ("κάνει", "κάνω"), ("έλα", "έρχομαι"),
            ("υπάρχει", "υπάρχω"), ("μπορείς", "μπορώ"), ("πάμε", "πάω"), ("έχουμε", "έχω"), ("είμαστε", "είμαι"),
            ("πω", "λέω"), ("είπε", "λέω"), ("όλοι", "όλος"), ("είχε", "έχω"), ("την", "ο"),
        ]
        for spot in spots {
            let results = try await db.searchResults(query: spot.form)
            XCTAssertTrue(lemmaRows(results).contains { $0.formMatch?.lemma == spot.lemma },
                          "\(spot.form) finds \(spot.lemma); lemma rows: \(lemmaRows(results).compactMap(\.formMatch?.lemma))")
        }
    }

    /// #142: lemma rows come only from enabled dictionaries, so they follow
    /// the chips, and a base form adds none.
    func testLemmaRowsFollowEnabledDictionaries() async throws {
        let wordNetOnly = try await db.searchResults(query: "έγραψα", enabledSources: ["wordnet-ell-eng"])
        XCTAssertEqual(lemmaRows(wordNetOnly).map(\.entry.source), ["wordnet-ell-eng"])
        let englishOnly = try await db.searchResults(query: "έγραψα", enabledSources: ["wordnet"])
        XCTAssertEqual(lemmaRows(englishOnly), [], "no Greek dictionary, no lemma row")
        for query in ["γράφω", "γραφω", "σπίτι", "είμαι"] {
            let results = try await db.searchResults(query: query)
            XCTAssertEqual(lemmaRows(results), [], "the base form \(query) adds no lemma row")
        }
    }

    /// Preferred mode on the real file: the Greek bucket starts with γράφω,
    /// captioned, and no row repeats in the tail.
    func testPreferredModePutsLemmaRowsInTheirPairBucket() async throws {
        let groups = DictionaryGrouping.sourceGroups(order: ["wordnet"] + DictAppTests.greekSourceIDs)
        let results = try await db.searchPreferredResults(query: "έγραψα", groups: groups,
                                                          enabledSources: Set(groups.joined()))
        XCTAssertEqual(Set(results.compactMap(\.id)).count, results.count, "no row repeats")
        let greekBucket = results.prefix { DictAppTests.greekSourceIDs.contains($0.entry.source) }
        XCTAssertGreaterThanOrEqual(greekBucket.count, 2, "\(results.map(\.entry.word))")
        XCTAssertEqual(greekBucket.prefix(2).map(\.formMatch?.lemma), ["γράφω", "γράφω"],
                       "no exact row, so the lemma rows lead the Greek bucket")
        XCTAssertLessThanOrEqual(greekBucket.count, Search.preferredDictionaryTopN, "top N after the merge")
    }

    /// #142, #143: base forms, and every probe query of #129, give the same
    /// results with the form step on and off. #143 adds go, mouse, good,
    /// goose and well. On the main actor, as its assertions sit between
    /// awaits (#229).
    @MainActor
    func testBaseFormResultsUnchanged() async throws {
        let queries = ["house", "a", "the", "ice cream", "dog", "water", "run", "entry", "light", "дом", "вод",
                       "говорить", "casa", "comer", "agua", "perro", "كتاب", "ماء", "بيت", "γράφω", "γραφω", "νερο",
                       "σκυλος", "σπίτι", "είμαι", "νερό", "ποτέ", "πότε", "go", "mouse", "good", "goose", "well"]
        var withStep: [String: [SearchResult]] = [:]
        for query in queries {
            withStep[query] = try await db.searchResults(query: query)
        }
        DatabaseService.lemmaStepEnabled = false
        for query in queries {
            let without = try await db.searchResults(query: query)
            XCTAssertEqual(withStep[query], without, "'\(query)' changed with the form step")
        }
    }
}

/// #142 on made-up rows: the preferred-mode merge per bucket, the tail and an
/// import outside every pair group (0136, "Search path", step 4).
extension WordFormsSearchTests {
    /// A dictionary file with `rows` and one Greek lemma, γράφω, of which
    /// έγραψα is the aorist 1sg and γράφω the present 1sg; the service
    /// attaches it.
    private func openFormsFixture(_ rows: [TestDictionary.Row]) async throws {
        let url = try TestDictionary.make(rows: rows, at: tempDir.appendingPathComponent("forms.sqlite"))
        try await DatabaseQueue(path: url.path).write { db in
            try db.execute(sql: """
                INSERT INTO lemma(id, lang, word, word_normalized, pos) VALUES (1, 'ell', 'γράφω', 'γραφω', 'verb');
                INSERT INTO tagset(id, tags) VALUES
                    (1, 'active first-person indicative past perfective singular'),
                    (2, 'active first-person imperfective indicative present singular');
                INSERT INTO form_lookup(form_norm, lemma_id, tagset_id) VALUES ('εγραψα', 1, 1), ('γραφω', 1, 2);
                """)
        }
        // #237: the app reads the forms from the Greek pack: the same file.
        try await db.setup(userPath: tempDir.appendingPathComponent("forms-user.sqlite").path, dictionaryURL: url,
                           packFiles: [.ell: url])
    }

    func testPreferredModeMergesLemmaRowsPerBucketBeforeTheTail() async throws {
        let fd = "freedict-ell-eng", wn = "wordnet-ell-eng", custom = "custom_greek"
        try await openFormsFixture([
            TestDictionary.Row(word: "έγραψα", normalized: "εγραψα", definition: "I wrote", source: fd),
            TestDictionary.Row(word: "γράφω", normalized: "γραφω", definition: "to write", source: fd),
            TestDictionary.Row(word: "έγραψαν", normalized: "εγραψαν", definition: "they wrote", source: fd),
            TestDictionary.Row(word: "έγραψας", normalized: "εγραψασ", definition: "you wrote", source: fd),
            TestDictionary.Row(word: "γράφω", normalized: "γραφω", definition: "write", source: wn),
            TestDictionary.Row(word: "έγραψαν", normalized: "εγραψαν", definition: "wrote (they)", source: wn),
        ])
        let json = tempDir.appendingPathComponent("custom.json")
        try Data(#"[{"word": "γράφω", "definition": "to write, imported"}]"#.utf8).write(to: json)
        _ = try await db.importJSON(at: json, source: custom)
        let enabled: Set<String> = [fd, wn, custom]
        func key(_ row: SearchResult) -> String { "\(row.entry.source)/\(row.entry.word)\(row.formMatch == nil ? "" : "*")" }

        // Relevance: the exact row, the three γράφω rows, then the prefix rows.
        let relevance = try await db.searchResults(query: "έγραψα", enabledSources: enabled)
        XCTAssertEqual(relevance.first.map(key), "\(fd)/έγραψα")
        XCTAssertEqual(Set(relevance.dropFirst().prefix(3).map(key)), ["\(fd)/γράφω*", "\(wn)/γράφω*", "\(custom)/γράφω*"])
        XCTAssertEqual(Set(relevance.dropFirst(4).map(key)), ["\(fd)/έγραψαν", "\(fd)/έγραψας", "\(wn)/έγραψαν"])

        // Preferred, top 2: each bucket merges its lemma rows and then takes
        // its top 2; the tail excludes them and carries the import's lemma row.
        let preferred = try await db.searchPreferredResults(query: "έγραψα", groups: [[fd], [wn]],
                                                            enabledSources: enabled, topN: 2)
        XCTAssertEqual(Array(preferred.prefix(4).map(key)),
                       ["\(fd)/έγραψα", "\(fd)/γράφω*", "\(wn)/γράφω*", "\(wn)/έγραψαν"])
        XCTAssertEqual(preferred.dropFirst(4).first.map(key), "\(custom)/γράφω*",
                       "a lemma row outside every group leads the tail")
        XCTAssertEqual(Set(preferred.dropFirst(5).map(key)), ["\(fd)/έγραψαν", "\(fd)/έγραψας"],
                       "the FreeDict rows the merge pushed out of the bucket are in the tail")
        XCTAssertEqual(Set(preferred.compactMap(\.id)).count, preferred.count, "no row repeats")

        // The lemma itself adds nothing.
        let base = try await db.searchResults(query: "γράφω", enabledSources: enabled)
        XCTAssertTrue(base.allSatisfy { $0.formMatch == nil }, "\(base.map(key))")
    }
}

/// QA, #142: the form step's edge cases on the real file (0136, "Search by
/// any form"): lemmas that fold alike, queries the step skips, a form that is
/// also a headword, the chips in preferred mode (#145) and an import.
extension WordFormsSearchTests {
    private func caption(_ row: SearchResult, _ code: String = "en") -> String? {
        row.formMatch.map { FormCaption.text(for: $0, locale: Locale(identifier: code)) }
    }

    /// "source/word: caption" of each lemma row.
    private func captioned(_ results: [SearchResult]) -> [String] {
        lemmaRows(results).map { "\($0.entry.source)/\($0.entry.word): \(caption($0) ?? "")" }
    }

    /// Every lemma word `form_lookup` holds for the folded `query`.
    private func lemmaWords(of query: String) async throws -> Set<String> {
        let key = Search.foldGreek(query)
        return Set(try await BundledDictionary(url: try PackFixtures.file(.ell)).read { db in
            try String.fetchAll(db, sql: """
                SELECT l.word FROM form_lookup AS f JOIN lemma AS l ON l.id = f.lemma_id WHERE f.form_norm = ?
                """, arguments: [key])
        })
    }

    @MainActor
    private func waitUntilIdle(_ vm: SearchViewModel, file: StaticString = #filePath, line: UInt = #line) async throws {
        let deadline = Date().addingTimeInterval(5)
        while vm.isSearching, Date() < deadline {
            try await Task.sleep(nanoseconds: 20_000_000)
        }
        XCTAssertFalse(vm.isSearching, "the search did not finish", file: file, line: line)
        XCTAssertNil(vm.errorMessage, file: file, line: line)
    }

    /// Lemmas that fold alike but are spelt apart share a search key: γέρου
    /// is a form of γέρος (old man) and γερός (sturdy), δουλειές of δουλειά
    /// (work) and δουλεία (slavery), παιδιά of παιδί (child) and παΐδι
    /// (chop). Each row is captioned with the lemma it spells, never with its
    /// accent twin, and a word of two parts of speech shows once (κύριος).
    func testFoldAlikeLemmasCaptionTheirOwnRows() async throws {
        let geros = try await db.searchResults(query: "γέρου")
        let douleies = try await db.searchResults(query: "δουλειές")
        let paidia = try await db.searchResults(query: "παιδιά")
        let kyrie = try await db.searchResults(query: "κύριε")
        XCTAssertEqual(Set(captioned(geros)), [
            "freedict-ell-eng/γέρος: genitive singular of γέρος",
            "wordnet-ell-eng/γέρος: genitive singular of γέρος",
            "wordnet-ell-eng/γερός: genitive singular masculine of γερός",
        ])
        XCTAssertEqual(Set(captioned(douleies)), [
            "freedict-ell-eng/δουλειά: nominative plural of δουλειά",
            "wordnet-ell-eng/δουλειά: nominative plural of δουλειά",
            "freedict-ell-eng/δουλεία: nominative plural of δουλεία",
            "wordnet-ell-eng/δουλεία: nominative plural of δουλεία",
        ])
        XCTAssertEqual(Set(captioned(paidia)), [
            "freedict-ell-eng/παιδί: nominative plural of παιδί",
            "wordnet-ell-eng/παιδί: nominative plural of παιδί",
        ])
        XCTAssertEqual(Set(captioned(kyrie)), [
            "freedict-ell-eng/Κύριος: vocative singular of Κύριος",
            "freedict-ell-eng/κύριος: vocative singular of κύριος",
            "wordnet-ell-eng/κύριος: vocative singular of κύριος",
        ])

        // Frequent subtitle forms with accent twins: a row whose headword is
        // one of the query's lemmas names that lemma.
        for query in ["γέρου", "δουλειές", "παιδιά", "καλό", "νόμο", "κύριε", "θεού", "πολιτική", "μόνο",
                      "στοιχεία", "ουρανό", "έρωτα"] {
            let words = try await lemmaWords(of: query)
            let rows = lemmaRows(try await db.searchResults(query: query))
            XCTAssertFalse(rows.isEmpty, "'\(query)' adds lemma rows")
            for row in rows where words.contains(row.entry.word) {
                XCTAssertEqual(row.formMatch?.lemma, row.entry.word, "'\(query)': \(row.entry.source)/\(row.entry.word)")
            }
        }
    }

    /// The step adds rows and moves none: without the lemma rows, the
    /// results are the step-off list without them, in its order, cut to 50.
    /// Also for a form that is a headword itself (είναι, της, το), whose
    /// exact row stays first and uncaptioned.
    func testFormStepOnlyInsertsLemmaRows() async throws {
        let queries = ["έγραψα", "ήταν", "είναι", "της", "το", "τα", "δω", "κανείς", "γέρου", "δουλειές"]
        var withStep: [String: [SearchResult]] = [:]
        for query in queries {
            withStep[query] = try await db.searchResults(query: query)
        }
        DatabaseService.lemmaStepEnabled = false
        for query in queries {
            let on = try XCTUnwrap(withStep[query]), off = try await db.searchResults(query: query)
            let added = Set(lemmaRows(on).compactMap(\.id))
            XCTAssertFalse(added.isEmpty, "'\(query)' adds lemma rows")
            XCTAssertEqual(on.filter { $0.formMatch == nil }.map(\.id),
                           Array(off.map(\.id).filter { !added.contains($0 ?? -1) }.prefix(50 - added.count)),
                           "'\(query)': the other rows keep their order")
        }
        for (query, headword, lemma) in [("είναι", "είναι", "present 3sg of είμαι"), ("της", "τής", "genitive singular feminine of ο"),
                                         ("το", "το", "nominative singular neuter of ο")] {
            let on = try XCTUnwrap(withStep[query])
            XCTAssertEqual(on.first?.entry.word, headword, "'\(query)': the exact row first")
            XCTAssertNil(on.first?.formMatch)
            XCTAssertEqual(on.dropFirst().first.flatMap { caption($0) }, lemma, "'\(query)': then the lemma row")
        }
    }

    /// Queries the step skips give exactly today's results: one letter (α, ο
    /// and η are forms of many lemmas), several words, Greek with a digit or
    /// a Latin letter. Final sigma, capitals, σ typed last, spaces and the
    /// Greek question mark give κάνεις's lemma rows.
    func testFormStepEdgeQueriesOnTheFile() async throws {
        let skipped = ["α", "ο", "η", "ά", "έγραψα σήμερα", "του γέρου", "έγραψα2", "έγραψαs"]
        var withStep: [String: [SearchResult]] = [:]
        for query in skipped {
            withStep[query] = try await db.searchResults(query: query)
        }
        DatabaseService.lemmaStepEnabled = false
        for query in skipped {
            let without = try await db.searchResults(query: query)
            XCTAssertEqual(withStep[query], without, "'\(query)' gets no form step")
        }
        XCTAssertFalse(try XCTUnwrap(withStep["α"]).isEmpty, "precondition: α finds rows")
        DatabaseService.lemmaStepEnabled = true

        let reference = lemmaRows(try await db.searchResults(query: "κάνεις"))
        XCTAssertEqual(Set(reference.compactMap(\.formMatch?.lemma)), ["κάνω", "κανένας"])
        for query in ["κανεις", "ΚΆΝΕΙΣ", "κανεισ", "  κάνεις ", "κάνεις\u{037E}", "κα\u{0301}νεις"] {
            let rows = lemmaRows(try await db.searchResults(query: query))
            XCTAssertEqual(rows, reference, "'\(query)' finds κάνεις's lemmas")
        }
    }

    /// #145: in preferred mode the chips decide which pairs are searched,
    /// and so which lemma rows show. Greek on: the Greek bucket leads with
    /// γράφω, captioned. Greek off: no Greek row and no lemma row. "Only
    /// this" on Greek: Greek rows only, γράφω first.
    @MainActor
    func testPreferredModeFollowsTheChips() async throws {
        let order = DictAppTests.greekSourceIDs + ["wordnet", "freedict-eng-spa", "wordnet-spa-eng", "openrussian",
                                                   "wordnet-arb-eng"]
        let (selection, settings, _, _) = QuickSwitchFixture.makeSelection(storedOrder: order)
        settings.resultSortMode = .preferredDictionary
        await selection.load()
        let vm = SearchViewModel(settings: settings, selection: selection)
        vm.query = "έγραψα"
        vm.onQueryChanged()
        try await waitUntilIdle(vm)
        XCTAssertEqual(vm.results.prefix(2).map { $0.formMatch?.lemma }, ["γράφω", "γράφω"])
        XCTAssertEqual(vm.results.first.flatMap { caption($0) }, "aorist 1sg of γράφω")

        selection.setEnabled(false, pair: "ell-eng")
        try await waitUntilIdle(vm)
        XCTAssertFalse(vm.results.contains { $0.formMatch != nil }, "Greek off: no lemma row")
        XCTAssertTrue(Set(vm.results.map(\.entry.source)).isDisjoint(with: DictAppTests.greekSourceIDs))
        XCTAssertFalse(vm.showsNoDictionariesHint, "other pairs are on")

        selection.enableOnly(pair: "ell-eng")
        try await waitUntilIdle(vm)
        XCTAssertTrue(Set(vm.results.map(\.entry.source)).isSubset(of: DictAppTests.greekSourceIDs))
        XCTAssertEqual(vm.results.prefix(2).map { $0.formMatch?.lemma }, ["γράφω", "γράφω"])
    }

    /// An imported Greek dictionary (headwords as typed, NFC) gets lemma rows
    /// in relevance and preferred mode, also with the bundled Greek pair
    /// off; its exact row stays first and uncaptioned.
    func testImportedGreekDictionaryGetsLemmaRows() async throws {
        let custom = "qa_greek_import"
        let json = tempDir.appendingPathComponent("\(custom).json")
        try Data(#"""
            [{"word": "γράφω", "definition": "to write, imported"},
             {"word": "είμαι", "definition": "to be, imported"},
             {"word": "έγραψα", "definition": "I wrote, imported"}]
            """#.utf8).write(to: json)
        let count = try await db.importJSON(at: json, source: custom)
        XCTAssertEqual(count, 3)
        func key(_ row: SearchResult) -> String { "\(row.entry.source)/\(row.entry.word)\(row.formMatch == nil ? "" : "*")" }

        let imported = try await db.searchResults(query: "έγραψα", enabledSources: [custom])
        XCTAssertEqual(imported.map(key), ["\(custom)/έγραψα", "\(custom)/γράφω*"])
        XCTAssertEqual(imported.last.flatMap { caption($0) }, "aorist 1sg of γράφω")
        let itan = try await db.searchResults(query: "ηταν", enabledSources: [custom])
        XCTAssertEqual(itan.map(key), ["\(custom)/είμαι*"])

        let everything = try await db.searchResults(query: "έγραψα")
        XCTAssertEqual(everything.first.map(key), "\(custom)/έγραψα")
        XCTAssertEqual(Set(everything.dropFirst().prefix(3).map(key)),
                       ["freedict-ell-eng/γράφω*", "wordnet-ell-eng/γράφω*", "\(custom)/γράφω*"])

        // The import has its own chip; the bundled Greek pair is off.
        let preferred = try await db.searchPreferredResults(query: "έγραψα", groups: [["wordnet"], [custom]],
                                                            enabledSources: ["wordnet", custom])
        XCTAssertEqual(preferred.map(key), ["\(custom)/έγραψα", "\(custom)/γράφω*"])
    }
}

/// QA, local only (0136, "Performance"): search time on #129's probe set plus
/// the inflected probes, against 1.4.0 on the same simulator. 1.4.0 is its
/// database of a fresh English install, built by `build_140_database` in
/// `Scripts/make_search_probe.py`, searched with v1.4.0's SQL; its path comes
/// from `LIBREDICT_SEARCH_140_DB` (passed as
/// `TEST_RUNNER_LIBREDICT_SEARCH_140_DB`), and the test is skipped without
/// it. Each round runs every probe once on 1.4.0, on this build with the
/// form step and without it; the gate is the median round ≤ 1.10 × 1.4.0's.
extension WordFormsSearchTests {
    private static let probeQueries = ["house", "a", "the", "ice cream", "dog", "water", "run", "entry", "light",
                                       "дом", "вод", "говорить", "casa", "comer", "agua", "perro", "كتاب", "ماء",
                                       "بيت", "γράφω", "γραφω", "νερο", "σκυλος", "έγραψα", "ήταν", "went", "mice"]
    private static let preferredQueries = ["house", "casa", "νερο", "έγραψα"]
    /// A fresh English install's pair groups (`make_search_probe.py`).
    nonisolated private static let englishGroups = [["wordnet"], ["freedict-eng-spa", "wordnet-spa-eng"], ["openrussian"],
                                        ["freedict-ell-eng", "wordnet-eng-ell", "freedict-eng-ell", "wordnet-ell-eng"],
                                        ["wordnet-arb-eng"]]

    /// v1.4.0's `DatabaseService.search` and `searchPreferred` SQL.
    private static func search140(_ queue: DatabaseQueue, _ query: String, preferred: Bool) async throws -> Int {
        let sanitized = String(query.unicodeScalars.filter { CharacterSet.alphanumerics.union(.whitespaces).contains($0) })
            .trimmingCharacters(in: .whitespaces)
        let fts = Search.ftsQuery(sanitized: sanitized)
        let order = """
            (e.word_normalized = ? COLLATE NOCASE OR e.word_normalized = ? COLLATE NOCASE) DESC,
            (e.word_normalized LIKE ? COLLATE NOCASE OR e.word_normalized LIKE ? COLLATE NOCASE) DESC, rank
            """
        let orderArguments: StatementArguments = [fts.rankKey, fts.rawKey, fts.rankKey + "%", fts.rawKey + "%"]
        return try await queue.read { db in
            guard preferred else {
                return try DictionaryEntry.fetchAll(db, sql: """
                    SELECT e.* FROM entries_fts fts JOIN entries e ON e.id = fts.rowid
                    WHERE entries_fts MATCH ? ORDER BY \(order) LIMIT ?
                    """, arguments: [fts.match] + orderArguments + [50]).count
            }
            var taken: [Int64] = []
            for members in englishGroups {
                let marks = members.map { _ in "?" }.joined(separator: ", ")
                taken += try DictionaryEntry.fetchAll(db, sql: """
                    SELECT e.* FROM entries_fts fts JOIN entries e ON e.id = fts.rowid
                    WHERE entries_fts MATCH ? AND e.source IN (\(marks)) ORDER BY \(order) LIMIT ?
                    """, arguments: [fts.match] + StatementArguments(members) + orderArguments + [4]).compactMap(\.id)
            }
            let enabled = Array(Set(englishGroups.joined())).sorted()
            let tail = try DictionaryEntry.fetchAll(db, sql: """
                SELECT e.* FROM entries_fts fts JOIN entries e ON e.id = fts.rowid
                WHERE entries_fts MATCH ? AND e.source IN (\(enabled.map { _ in "?" }.joined(separator: ", ")))
                  AND e.id NOT IN (\(taken.map { _ in "?" }.joined(separator: ", "))) ORDER BY rank LIMIT ?
                """, arguments: [fts.match] + StatementArguments(enabled) + StatementArguments(taken) + [50 - taken.count])
            return taken.count + tail.count
        }
    }

    func testProbeTimingAgainst140() async throws {
        guard let path = ProcessInfo.processInfo.environment["LIBREDICT_SEARCH_140_DB"] else {
            throw XCTSkip("LIBREDICT_SEARCH_140_DB is not set")
        }
        var config = Configuration()
        config.readonly = true
        let old = try DatabaseQueue(path: path, configuration: config)
        let groups = Self.englishGroups, enabled = Set(Self.englishGroups.joined())
        let probes = Self.probeQueries.map { ($0, false) } + Self.preferredQueries.map { ($0, true) }

        func time(_ body: () async throws -> Void) async rethrows -> Double {
            let start = DispatchTime.now().uptimeNanoseconds
            try await body()
            return Double(DispatchTime.now().uptimeNanoseconds - start) / 1_000_000
        }
        func runApp(step: Bool) async throws -> [Double] {
            DatabaseService.lemmaStepEnabled = step
            defer { DatabaseService.lemmaStepEnabled = true }
            var times: [Double] = []
            for (query, preferred) in probes {
                times.append(try await time {
                    if preferred {
                        _ = try await db.searchPreferredResults(query: query, groups: groups, enabledSources: enabled)
                    } else {
                        _ = try await db.searchResults(query: query)
                    }
                })
            }
            return times
        }
        func run140() async throws -> [Double] {
            var times: [Double] = []
            for (query, preferred) in probes {
                times.append(try await time { _ = try await Self.search140(old, query, preferred: preferred) })
            }
            return times
        }
        func median(_ values: [Double]) -> Double {
            let sorted = values.sorted()
            return sorted.count % 2 == 1 ? sorted[sorted.count / 2] : (sorted[sorted.count / 2 - 1] + sorted[sorted.count / 2]) / 2
        }

        _ = try await run140(); _ = try await runApp(step: true); _ = try await runApp(step: false)   // warm caches
        let rounds = Int(ProcessInfo.processInfo.environment["LIBREDICT_SEARCH_ROUNDS"] ?? "") ?? 5
        var v140: [[Double]] = [], on: [[Double]] = [], off: [[Double]] = []
        for _ in 0..<rounds {
            v140.append(try await run140())
            on.append(try await runApp(step: true))
            off.append(try await runApp(step: false))
        }
        let totals = (v140: median(v140.map { $0.reduce(0, +) }), on: median(on.map { $0.reduce(0, +) }),
                      off: median(off.map { $0.reduce(0, +) }))
        for (index, (query, preferred)) in probes.enumerated() {
            print(String(format: "probe %@%@: 1.4.0 %.1f ms, step on %.1f ms, step off %.1f ms", query,
                         preferred ? " (preferred)" : "", median(v140.map { $0[index] }),
                         median(on.map { $0[index] }), median(off.map { $0[index] })))
        }
        print(String(format: "probe set, median of %d rounds: 1.4.0 %.1f ms, step on %.1f ms (%.3f×), step off %.1f ms (%.3f×)",
                     rounds, totals.v140, totals.on, totals.on / totals.v140, totals.off, totals.off / totals.v140))
        XCTAssertLessThanOrEqual(totals.on, totals.v140 * 1.10, "search with the form step is within 10% of 1.4.0")
    }
}

/// #142: the form lookup reads the primary-key prefix of `form_lookup`, so
/// it never scans the table, and an accent-fold collision returns every
/// lemma.
extension WordFormsLookupTests {
    /// `EXPLAIN QUERY PLAN` of the app's Greek candidate query, of the
    /// morphy lookups and of the `form_link` check of table links (#143):
    /// primary-key searches, no `SCAN` (the prototype's 6× slowdown), and no
    /// sort for the exceptions.
    @MainActor
    func testLookupsUsePrimaryKey() async throws {
        await DictAppTests.waitForHostAppLaunch()
        let url = try TestDictionary.bundledURL()
        let bases = Morphy.ruleBases(of: "cities")
        let queries: [(String, StatementArguments)] = [
            (DatabaseService.greekLemmaCandidatesSQL, ["εγραψα", "εγραψα"]),
            (DatabaseService.morphyExceptionSQL, ["went"]),
            (DatabaseService.morphyLemmaSQL(count: bases.count), StatementArguments(bases)),
            (DatabaseService.linkedLemmasSQL, ["στύλος", "στύλος", "στυλοσ", -1, "noun"]),
        ]
        let greek = try PackFixtures.file(.ell)
        let plans = try DatabaseQueue().inDatabase { db -> [[String]] in
            try db.execute(sql: "ATTACH DATABASE ? AS dict", arguments: [DatabaseService.dictionaryURI(url)])
            try db.execute(sql: "ATTACH DATABASE ? AS ell", arguments: [DatabaseService.dictionaryURI(greek)])
            return try queries.map { sql, arguments in
                try Row.fetchAll(db, sql: "EXPLAIN QUERY PLAN " + sql, arguments: arguments).map { $0["detail"] as String }
            }
        }
        XCTAssertTrue(plans[0].contains { $0.contains("SEARCH f USING PRIMARY KEY (form_norm=?)") }, "\(plans[0])")
        XCTAssertTrue(plans[1].contains { $0.hasPrefix("SEARCH") && $0.hasSuffix("morphy_exception USING PRIMARY KEY (form=?)") }, "\(plans[1])")
        XCTAssertTrue(plans[2].contains { $0.hasPrefix("SEARCH") && $0.hasSuffix("morphy_lemma USING PRIMARY KEY (word=?)") }, "\(plans[2])")
        XCTAssertTrue(plans[3].contains { $0.hasSuffix("SEARCH k USING PRIMARY KEY (form=? AND lemma_id=?)") },
                      "form_link by its whole key: \(plans[3])")
        for plan in plans {
            XCTAssertFalse(plan.contains { $0.hasPrefix("SCAN") }, "no table scan: \(plan)")
        }
        XCTAssertFalse(plans[1].contains { $0.contains("TEMP B-TREE") }, "the key orders the exceptions: \(plans[1])")
    }

    /// κανείς and κάνεις both fold to κανεισ: the query shows κάνω and κανένας.
    @MainActor
    func testFoldCollisionReturnsAllLemmas() async throws {
        try readDictionaryFile { db in
            XCTAssertEqual(Set(try lemmas(of: "κανείς", in: db)), ["κάνω", "κανένας"])
        }
        await DictAppTests.waitForHostAppLaunch()
        let tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: tempDir) }
        try await DatabaseService.shared.setup(userPath: tempDir.appendingPathComponent("user.sqlite").path,
                                               dictionaryURL: try TestDictionary.bundledURL(), packFiles: try PackFixtures.all())
        for query in ["κανείς", "κάνεις", "κανεις"] {
            let results = try await DatabaseService.shared.searchResults(query: query)
            var lemmas: [String] = []
            for lemma in results.compactMap(\.formMatch?.lemma) where !lemmas.contains(lemma) {
                lemmas.append(lemma)
            }
            XCTAssertEqual(lemmas, ["κάνω", "κανένας"], "'\(query)': the verb first, then the pronoun")
        }
    }
}

// MARK: - Issue #143: search by inflected English form (0136-word-forms.md)

/// `Morphy`, the WordNet 3.0 morphy port (0136, "Morphy (#143)"): pure, on
/// fixtures copied from the bundled file's `morphy_exception` lines and
/// `morphy_lemma` parts of speech for these words.
final class MorphyTests: XCTestCase {
    private static let noun = 1, verb = 2, adjective = 4, adverb = 8

    /// WordNet's exception lines: form → (pos, base).
    private static let exceptions: [String: [Morphy.Exception]] = [
        "went": [.init(pos: .verb, base: "go")],
        "mice": [.init(pos: .noun, base: "mouse")],
        "better": [.init(pos: .adjective, base: "good"), .init(pos: .adjective, base: "well"),
                   .init(pos: .adverb, base: "well")],
        "best": [.init(pos: .adjective, base: "good"), .init(pos: .adverb, base: "well")],
        "running": [.init(pos: .verb, base: "run")],
        "geese": [.init(pos: .noun, base: "goose")],
        "was": [.init(pos: .verb, base: "be")],
        "has": [.init(pos: .verb, base: "have")],
        "goes": [.init(pos: .noun, base: "go")],
        "axes": [.init(pos: .noun, base: "ax"), .init(pos: .noun, base: "axis")],
        "leaves": [.init(pos: .noun, base: "leaf"), .init(pos: .noun, base: "leave")],
    ]

    /// Single-word WordNet lemmas → `pos_mask`.
    private static let lemmas: [String: Int] = [
        "go": noun | verb | adjective, "mouse": noun | verb, "good": noun | adjective | adverb,
        "well": noun | verb | adjective | adverb, "run": noun | verb, "goose": noun | verb, "be": noun | verb,
        "have": noun | verb, "dog": noun | verb, "box": noun | verb, "city": noun, "walk": noun | verb,
        "new": adjective | adverb, "news": noun, "wa": noun, "u": noun | adjective, "us": noun, "ha": noun,
        "a": noun, "as": noun | adverb, "ax": noun | verb, "axe": noun | verb, "axis": noun,
        "leaf": noun | verb, "leave": noun | verb, "hope": noun | verb, "hop": noun | verb,
        "plane": noun | verb | adjective, "plan": noun | verb, "scare": noun | verb, "scar": noun | verb,
    ]

    /// Morphy as `DatabaseService` runs it: the word's exception lines and
    /// the lemmas among its rule bases.
    private func analyses(_ token: String) -> [Morphy.Analysis] {
        let word = token.lowercased()
        let bases = Set(Morphy.ruleBases(of: word))
        return Morphy.analyses(of: token, exceptions: Self.exceptions[word] ?? [],
                               lemmas: Self.lemmas.filter { bases.contains($0.key) })
    }

    private func exception(_ base: String, _ pos: Morphy.PartOfSpeech, suffix: String = "") -> Morphy.Analysis {
        Morphy.Analysis(base: base, pos: pos, rule: nil, suffix: suffix)
    }

    private func rule(_ base: String, _ pos: Morphy.PartOfSpeech, _ detach: String, _ attach: String = "") -> Morphy.Analysis {
        Morphy.Analysis(base: base, pos: pos, rule: Morphy.Rule(detach: detach, attach: attach), suffix: "")
    }

    /// #143's cases: went → go, mice → mouse, better → good and well,
    /// running → run, geese → goose, from the exception lists, each with the
    /// ending its caption names.
    func testSpecCases() {
        XCTAssertEqual(analyses("went"), [exception("go", .verb)])
        XCTAssertEqual(analyses("mice"), [exception("mouse", .noun)])
        XCTAssertEqual(analyses("better"), [exception("good", .adjective, suffix: "er"),
                                            exception("well", .adjective, suffix: "er")],
                       "well is an adjective and an adverb of better: once, as the adjective")
        XCTAssertEqual(analyses("running"), [exception("run", .verb, suffix: "ing")])
        XCTAssertEqual(analyses("geese"), [exception("goose", .noun)])
        XCTAssertEqual(analyses("best"), [exception("good", .adjective, suffix: "est"),
                                          exception("well", .adverb, suffix: "est")])
    }

    /// Step 0: the token is lowercased first.
    func testCapitalsAreLowercased() {
        for (token, word) in [("WENT", "went"), ("Went", "went"), ("RUNNING", "running"), ("Mice", "mice"),
                              ("DOGS", "dogs")] {
            XCTAssertEqual(analyses(token), analyses(word), token)
            XCTAssertFalse(analyses(token).isEmpty, token)
        }
    }

    /// Regular forms through the detachment rules, kept only when the base is
    /// a WordNet lemma of that part of speech. A base that several parts of
    /// speech give comes once, in the order verb, noun, adjective.
    func testDetachmentRules() {
        XCTAssertEqual(analyses("dogs"), [rule("dog", .verb, "s")], "dog is a verb and a noun: the verb comes first")
        XCTAssertEqual(analyses("boxes"), [rule("box", .verb, "es")])
        XCTAssertEqual(analyses("cities"), [rule("city", .noun, "ies", "y")], "city is no verb")
        XCTAssertEqual(analyses("walked"), [rule("walk", .verb, "ed")])
        XCTAssertEqual(Morphy.analyses(of: "walking", exceptions: [], lemmas: ["walk": Self.noun | Self.verb]),
                       [Morphy.Analysis(base: "walk", pos: .verb, rule: Morphy.Rule(detach: "ing", attach: ""), suffix: "ing")])
        XCTAssertEqual(Morphy.analyses(of: "taller", exceptions: [], lemmas: ["tall": Self.adjective]),
                       [Morphy.Analysis(base: "tall", pos: .adjective, rule: Morphy.Rule(detach: "er", attach: ""), suffix: "er")])
        XCTAssertEqual(Morphy.analyses(of: "nicest", exceptions: [], lemmas: ["nice": Self.adjective]),
                       [Morphy.Analysis(base: "nice", pos: .adjective, rule: Morphy.Rule(detach: "est", attach: "e"), suffix: "est")])
    }

    /// The noise guard: a noun or adjective base needs 3+ letters, so was,
    /// has, us and as find no two-letter noun; a verb base may be shorter
    /// (goes → go). news is no form of new, which is no noun.
    func testNoiseGuard() {
        XCTAssertEqual(analyses("news"), [], "new is an adjective and an adverb, not a noun or verb")
        XCTAssertEqual(analyses("was"), [exception("be", .verb)], "not wa (Washington)")
        XCTAssertEqual(analyses("has"), [exception("have", .verb)], "not ha")
        XCTAssertEqual(analyses("us"), [], "not u")
        XCTAssertEqual(analyses("as"), [], "not a")
        XCTAssertEqual(Morphy.analyses(of: "goes", exceptions: [], lemmas: ["go": Self.noun | Self.verb]),
                       [rule("go", .verb, "es")], "a verb keeps its two-letter base")
        XCTAssertEqual(Morphy.analyses(of: "gos", exceptions: [], lemmas: ["go": Self.noun | Self.verb]),
                       [rule("go", .verb, "s")], "the noun's go is guarded, the verb's is not")
        XCTAssertEqual(Morphy.minimumNominalBaseLength, 3)
    }

    /// Parts of speech in the order verb, noun, adjective, adverb, each with
    /// its exceptions if it has any, else its rules (Kirill, 2026-11-01); a
    /// base keeps its first part of speech; the word itself is dropped.
    func testOrderAndRepeats() {
        XCTAssertEqual(analyses("axes"), [rule("axe", .verb, "s"), exception("ax", .noun), exception("axis", .noun)],
                       "the verb's first hit (s → axe), then the noun's exceptions; the noun's rules are skipped")
        XCTAssertEqual(analyses("goes"), [rule("go", .verb, "es")],
                       "the verb's es → go comes before noun.exc's goes → go (the plural of the noun go)")
        XCTAssertEqual(analyses("leaves"), [rule("leave", .verb, "s"), exception("leaf", .noun)])
        XCTAssertEqual(Morphy.analyses(of: "bars", exceptions: [Morphy.Exception(pos: .noun, base: "barium")],
                                       lemmas: ["bar": Self.noun | Self.verb]),
                       [rule("bar", .verb, "s"), exception("barium", .noun)],
                       "the noun has an exception, so its s → bar does not run; the verb's does")
        XCTAssertEqual(Morphy.analyses(of: "news", exceptions: [Morphy.Exception(pos: .noun, base: "news")], lemmas: [:]),
                       [], "a line that names the word itself adds nothing")
        XCTAssertEqual(Morphy.analyses(of: "went", exceptions: [Morphy.Exception(pos: .adverb, base: "a"),
                                                                Morphy.Exception(pos: .verb, base: "go")], lemmas: [:]).map(\.base),
                       ["go", "a"], "exceptions in the order verb, noun, adjective, adverb")
    }

    /// Within a part of speech without an exception, only the first rule
    /// whose base is a lemma of it counts, as NLTK's morphy() takes it
    /// (Kirill, 2026-11-02): hoping is hope, not also hop; planes plane, not
    /// plan; scared scare, not scar. A later rule still counts when the
    /// earlier ones give no lemma (walked: walke is none, walk is).
    func testFirstRuleHitOnly() {
        XCTAssertEqual(analyses("hoping"), [Morphy.Analysis(base: "hope", pos: .verb,
                                                            rule: Morphy.Rule(detach: "ing", attach: "e"), suffix: "ing")])
        XCTAssertEqual(analyses("planes"), [rule("plane", .verb, "s")], "the noun's s → plane repeats plane")
        XCTAssertEqual(analyses("scared"), [rule("scare", .verb, "ed", "e")])
        XCTAssertEqual(analyses("walked"), [rule("walk", .verb, "ed")])
        XCTAssertEqual(Morphy.analyses(of: "hopes", exceptions: [], lemmas: ["hope": Self.verb, "hop": Self.verb]).map(\.base),
                       ["hope"], "s → hope comes before es → hop")
    }

    /// The captions the order gives (Kirill, 2026-11-01): goes and dogs are
    /// verb forms, mice a plural, better the comparative of good and well.
    func testCaptionsFollowTheOrder() {
        func captions(_ token: String) -> [String] {
            analyses(token).map { analysis in
                FormCaption.text(for: FormMatch(lemma: analysis.base, analysis: .english(
                    pos: analysis.pos, rule: analysis.rule, suffix: analysis.suffix)), locale: Locale(identifier: "en"))
            }
        }
        XCTAssertEqual(captions("goes"), ["form of go"])
        XCTAssertEqual(captions("dogs"), ["form of dog"])
        XCTAssertEqual(captions("mice"), ["plural of mouse"])
        XCTAssertEqual(captions("better"), ["comparative of good", "comparative of well"])
        XCTAssertEqual(captions("running"), ["-ing form of run"])
        XCTAssertEqual(captions("went"), ["form of go"])
    }

    /// What `DatabaseService` asks `morphy_lemma` for: every rule base once,
    /// after the noise guard.
    func testRuleBases() {
        XCTAssertEqual(Morphy.ruleBases(of: "cities"), ["citie", "city", "citi"])
        XCTAssertEqual(Morphy.ruleBases(of: "better"), ["bett", "bette"])
        XCTAssertEqual(Morphy.ruleBases(of: "us"), ["u"], "the verb's u; the noun's is guarded")
        XCTAssertEqual(Morphy.ruleBases(of: "go"), [])
        XCTAssertEqual(Morphy.ruleBases(of: "es"), ["e"], "the verb's s → e; es → leaves nothing")
        XCTAssertEqual(Morphy.ruleBases(of: "s"), [], "no empty base")
    }

    /// The form step sends one word of 2+ letters a–z, in any case, to
    /// Morphy, lowercased; other queries keep the Greek step or none.
    func testFormStepTakesOneEnglishWordOfTwoLetters() {
        XCTAssertEqual(Search.formStep(for: "went"), .english(word: "went"))
        XCTAssertEqual(Search.formStep(for: "WENT"), .english(word: "went"))
        XCTAssertEqual(Search.formStep(for: "Geese"), .english(word: "geese"))
        XCTAssertEqual(Search.formStep(for: "us"), .english(word: "us"), "two letters are enough")
        XCTAssertEqual(Search.formStep(for: "έγραψα"), .greek(key: "εγραψα"))
        for query in ["", "a", "ice cream", "went2", "café", "cafe\u{0301}", "naïve", "wentά", "дом", "ماء"] {
            XCTAssertNil(Search.formStep(for: query), "'\(query)' gets no form step")
        }
    }
}

/// #143: English captions, from Morphy's part of speech and the query's
/// ending (0136, "Morphy (#143)", Caption).
extension FormCaptionTests {
    private func english(_ lemma: String, _ pos: Morphy.PartOfSpeech, suffix: String = "") -> FormMatch {
        FormMatch(lemma: lemma, analysis: .english(pos: pos, rule: nil, suffix: suffix))
    }

    /// The spec table's captions; VoiceOver reads them as shown.
    func testEnglishMorphyCaptions() {
        let en = Locale(identifier: "en")
        let cases: [(FormMatch, String)] = [
            (english("go", .verb), "form of go"),
            (english("mouse", .noun), "plural of mouse"),
            (english("goose", .noun), "plural of goose"),
            (english("good", .adjective, suffix: "er"), "comparative of good"),
            (english("well", .adjective, suffix: "er"), "comparative of well"),
            (english("good", .adjective, suffix: "est"), "superlative of good"),
            (english("hard", .adverb, suffix: "est"), "superlative of hard"),
            (english("run", .verb, suffix: "ing"), "-ing form of run"),
            (english("bad", .adjective), "form of bad"),
            (FormMatch(lemma: "walk", analysis: .english(pos: .verb, rule: Morphy.Rule(detach: "ed", attach: ""), suffix: "")),
             "form of walk"),
        ]
        for (match, caption) in cases {
            XCTAssertEqual(FormCaption.text(for: match, locale: en), caption)
            XCTAssertEqual(FormCaption.accessibilityText(for: match, locale: en), caption, "VoiceOver reads it as shown")
        }
        XCTAssertEqual(FormCaption.labels(forEnglish: .noun, suffix: ""), [.plural])
        XCTAssertEqual(FormCaption.labels(forEnglish: .adverb, suffix: "er"), [.comparative])
        XCTAssertEqual(FormCaption.labels(forEnglish: .verb, suffix: "er"), [.form], "a verb in -er is a form")
        XCTAssertEqual(FormCaption.labels(forEnglish: .adjective, suffix: "ing"), [.form])
    }

    /// "-ing form of run" and "form of go" in the other UI languages; Arabic
    /// starts with U+200F and isolates the lemma.
    func testEnglishCaptionsInEveryUILanguage() {
        let run = english("run", .verb, suffix: "ing"), go = english("go", .verb)
        XCTAssertEqual(FormCaption.text(for: run, locale: Locale(identifier: "ru")), "форма на -ing от run")
        XCTAssertEqual(FormCaption.text(for: run, locale: Locale(identifier: "es")), "forma en -ing de run")
        XCTAssertEqual(FormCaption.text(for: run, locale: Locale(identifier: "el")), "τύπος σε -ing του run")
        XCTAssertEqual(FormCaption.text(for: go, locale: Locale(identifier: "ru")), "форма от go")
        XCTAssertEqual(FormCaption.text(for: english("mouse", .noun), locale: Locale(identifier: "es")), "pl. de mouse")

        let arabic = FormCaption.text(for: run, locale: Locale(identifier: "ar"))
        XCTAssertEqual(arabic.unicodeScalars.first, "\u{200F}", arabic)
        XCTAssertTrue(arabic.contains("\u{2068}run\u{2069}"), "the lemma is isolated: \(arabic.unicodeScalars.map(\.value))")
        XCTAssertEqual(String(arabic.unicodeScalars.filter { !bidiControls.contains($0) }), "صيغة ing من run")
    }
}

/// #143 on the real file: inflected English forms find their lemmas
/// through Morphy, right after the exact rows (0136, "Search by any form").
extension WordFormsSearchTests {
    private static let englishHeadwordSources: Set<String> = ["wordnet", "freedict-eng-spa", "freedict-eng-ell",
                                                              "wordnet-eng-ell"]

    /// Checks that the lemma rows of `query` are `lemmas`' headwords in the
    /// four dictionaries with English headwords, in this order, each with its
    /// caption, right after the exact rows and before every other row.
    @MainActor
    private func assertEnglishLemmaRows(_ query: String, _ lemmas: [(lemma: String, text: String)],
                                        file: StaticString = #filePath, line: UInt = #line) async throws {
        let results = try await db.searchResults(query: query)
        let first = try XCTUnwrap(results.firstIndex { $0.formMatch != nil }, "'\(query)' adds no lemma row",
                                  file: file, line: line)
        XCTAssertTrue(results[..<first].allSatisfy { $0.entry.word.lowercased() == query.lowercased() },
                      "'\(query)': only exact rows precede the lemma rows: \(results[..<first].map(\.entry.word))",
                      file: file, line: line)
        let added = lemmaRows(results)
        XCTAssertEqual(results[first..<(first + added.count)].map(\.id), added.map(\.id),
                       "'\(query)': the lemma rows are one block", file: file, line: line)
        var order: [String] = []
        for lemma in added.compactMap(\.formMatch?.lemma) where !order.contains(lemma) {
            order.append(lemma)
        }
        XCTAssertEqual(order, lemmas.map(\.lemma), "'\(query)': the lemmas in Morphy's order", file: file, line: line)
        for (lemma, text) in lemmas {
            let rows = added.filter { $0.formMatch?.lemma == lemma }
            XCTAssertEqual(Set(rows.map(\.entry.source)), Self.englishHeadwordSources,
                           "'\(query)' shows \(lemma) from every dictionary with English headwords", file: file, line: line)
            for row in rows {
                XCTAssertEqual(row.entry.word.lowercased(), lemma, file: file, line: line)
                XCTAssertEqual(caption(row), text, "'\(query)'", file: file, line: line)
            }
        }
    }

    /// #143: went → go, mice → mouse, better → good and well, running →
    /// run, geese → goose, also in capitals, plus regular forms (goes and
    /// dogs as verb forms); a form that is a headword keeps its exact rows
    /// first.
    @MainActor
    func testEnglishIrregularForms() async throws {
        for query in ["went", "WENT", "Went"] {
            try await assertEnglishLemmaRows(query, [("go", "form of go")])
        }
        try await assertEnglishLemmaRows("mice", [("mouse", "plural of mouse")])
        try await assertEnglishLemmaRows("better", [("good", "comparative of good"), ("well", "comparative of well")])
        for query in ["running", "RUNNING"] {
            try await assertEnglishLemmaRows(query, [("run", "-ing form of run")])
        }
        try await assertEnglishLemmaRows("geese", [("goose", "plural of goose")])
        try await assertEnglishLemmaRows("cities", [("city", "plural of city")])
        try await assertEnglishLemmaRows("walked", [("walk", "form of walk")])
        // Verb first (Kirill, 2026-11-01): goes is the verb's form, though
        // noun.exc lists it as the plural of the noun go.
        try await assertEnglishLemmaRows("goes", [("go", "form of go")])
        try await assertEnglishLemmaRows("dogs", [("dog", "form of dog")])

        let went = try await db.searchResults(query: "went")
        XCTAssertEqual(went.first.map { "\($0.entry.source)/\($0.entry.word)" }, "freedict-eng-ell/went",
                       "went's own row comes first, uncaptioned")
        XCTAssertNil(went.first?.formMatch)
        for query in ["running", "better"] {
            let rows = try await db.searchResults(query: query)
            let exact = rows.prefix { $0.formMatch == nil }
            XCTAssertEqual(Set(exact.map(\.entry.source)), Self.englishHeadwordSources, "'\(query)': its own rows first")
            XCTAssertTrue(exact.allSatisfy { $0.entry.word == query })
        }
    }

    /// The English step adds rows and moves none: without its lemma rows the
    /// results are the step-off list, in its order, cut to 50; a query
    /// Morphy finds nothing for is unchanged.
    @MainActor
    func testEnglishFormStepOnlyInsertsLemmaRows() async throws {
        let queries = ["went", "mice", "better", "running", "geese", "dogs", "cities", "walked", "was", "news", "us"]
        var withStep: [String: [SearchResult]] = [:]
        for query in queries {
            withStep[query] = try await db.searchResults(query: query)
        }
        DatabaseService.lemmaStepEnabled = false
        for query in queries {
            let on = try XCTUnwrap(withStep[query]), off = try await db.searchResults(query: query)
            let added = Set(lemmaRows(on).compactMap(\.id))
            XCTAssertEqual(on.filter { $0.formMatch == nil }.map(\.id),
                           Array(off.map(\.id).filter { !added.contains($0 ?? -1) }.prefix(50 - added.count)),
                           "'\(query)': the other rows keep their order")
        }
        let newsOff = try await db.searchResults(query: "news")
        XCTAssertEqual(withStep["news"], newsOff, "news ↛ new")
        XCTAssertEqual(Set(lemmaRows(try XCTUnwrap(withStep["was"])).compactMap(\.formMatch?.lemma)), ["be"], "not wa")
        XCTAssertEqual(lemmaRows(try XCTUnwrap(withStep["us"])), [], "not u")
    }
}

/// #143 (Kirill, 2026-11-02): English lemma rows come only from
/// dictionaries whose headwords are English, and Morphy takes the first rule
/// hit per part of speech; on the real file.
extension WordFormsSearchTests {
    private static let englishSources: Set<String> = ["wordnet", "freedict-eng-spa", "freedict-eng-ell", "wordnet-eng-ell"]

    func testEnglishLemmaSourcesAreTheEnabledEnglishOnes() {
        let english: Set<String> = ["wordnet", "freedict-eng-spa"]
        XCTAssertEqual(Search.englishLemmaSources(enabled: nil, english: english), ["freedict-eng-spa", "wordnet"])
        XCTAssertEqual(Search.englishLemmaSources(enabled: ["wordnet-spa-eng", "wordnet"], english: english), ["wordnet"])
        XCTAssertEqual(Search.englishLemmaSources(enabled: ["wordnet-spa-eng"], english: english), [])
    }

    /// doing, ideas and doctors: Spanish WordNet has do, idea and doctor as
    /// headwords, which read as English forms before; now their lemma rows
    /// come from the English dictionaries only, and a Spanish WordNet row
    /// carries no caption. With only Spanish WordNet on, no lemma row.
    @MainActor
    func testEnglishLemmaRowsComeOnlyFromEnglishDictionaries() async throws {
        for (query, lemma) in [("doing", "do"), ("ideas", "idea"), ("doctors", "doctor")] {
            let results = try await db.searchResults(query: query)
            let rows = lemmaRows(results)
            XCTAssertEqual(Set(rows.compactMap(\.formMatch?.lemma)), [lemma], "'\(query)'")
            XCTAssertEqual(Set(rows.map(\.entry.source)), Self.englishSources, "'\(query)': every English dictionary, no other")
            XCTAssertTrue(results.filter { $0.entry.source == "wordnet-spa-eng" }.allSatisfy { $0.formMatch == nil },
                          "'\(query)': no Spanish WordNet row is captioned as an English form")
            let spanishOnly = try await db.searchResults(query: query, enabledSources: ["wordnet-spa-eng"])
            XCTAssertTrue(spanishOnly.allSatisfy { $0.formMatch == nil }, "'\(query)' with only Es–En · WN on")
        }
    }

    /// The first rule hit only: hoping → hope, planes → plane (a Spanish-looking
    /// a–z query keeps its English rows), on the file.
    @MainActor
    func testEnglishFirstRuleHitOnTheFile() async throws {
        for (query, lemma, caption) in [("hoping", "hope", "-ing form of hope"), ("planes", "plane", "form of plane"),
                                        ("scared", "scare", "form of scare")] {
            let rows = lemmaRows(try await db.searchResults(query: query))
            XCTAssertEqual(Set(rows.compactMap(\.formMatch?.lemma)), [lemma], "'\(query)'")
            XCTAssertEqual(Set(rows.compactMap { self.caption($0) }), [caption], "'\(query)'")
        }
    }

    /// An import records no language yet (`imported_sources.from_lang` is
    /// NULL until #208), so it gets no English lemma rows; one named like a
    /// bundled English source shares that source's language and does.
    @MainActor
    func testImportsGetEnglishLemmaRowsOnlyAsAnEnglishSource() async throws {
        for source in ["qa_en_custom", "freedict-eng-spa"] {
            let file = tempDir.appendingPathComponent("\(source).json")
            try Data(#"[{"word": "adjudge", "definition": "to judge, imported"}]"#.utf8).write(to: file)
            let count = try await db.importJSON(at: file, source: source)
            XCTAssertEqual(count, 1, "\(source): FreeDict lacks adjudge, WordNet has it")
        }
        let rows = lemmaRows(try await db.searchResults(query: "adjudges"))
        XCTAssertEqual(Set(rows.map(\.entry.source)), Self.englishSources,
                       "the bundled English rows plus the import named like En–Es · FD; qa_en_custom is not English")
        XCTAssertEqual(Set(rows.compactMap(\.formMatch?.lemma)), ["adjudge"])
        let customOnly = try await db.searchResults(query: "adjudges", enabledSources: ["qa_en_custom"])
        XCTAssertTrue(customOnly.allSatisfy { $0.formMatch == nil }, "no English lemma row from an import of unknown language")
    }
}

/// QA, #143: more English forms through the search path on the real file:
/// irregular nouns and adjectives, regular -ing and -men forms, forms that
/// are headwords themselves, several lemmas in Morphy's order, and words
/// that are no form of anything.
extension WordFormsSearchTests {
    @MainActor
    func testEnglishFormsMatrixOnTheFile() async throws {
        let cases: [(query: String, lemmas: [(lemma: String, caption: String)])] = [
            ("children", [("child", "plural of child")]),
            ("women", [("woman", "plural of woman")]),
            ("data", [("datum", "plural of datum")]),
            ("best", [("good", "superlative of good"), ("well", "superlative of well")]),
            ("bigger", [("big", "comparative of big")]),
            ("walking", [("walk", "-ing form of walk")]),
            ("saw", [("see", "form of see")]),
            ("is", [("be", "form of be")]),
            ("axes", [("axe", "form of axe"), ("ax", "plural of ax"), ("axis", "plural of axis")]),
            ("leaves", [("leave", "form of leave"), ("leaf", "plural of leaf")]),
        ]
        for (query, lemmas) in cases {
            let results = try await db.searchResults(query: query)
            let first = try XCTUnwrap(results.firstIndex { $0.formMatch != nil }, "'\(query)' adds no lemma row")
            XCTAssertTrue(results[..<first].allSatisfy { $0.entry.word.lowercased() == query },
                          "'\(query)': only its own rows precede the lemma rows: \(results[..<first].map(\.entry.word))")
            let added = lemmaRows(results)
            XCTAssertEqual(results[first..<(first + added.count)].map(\.id), added.map(\.id), "'\(query)': one block")
            var order: [String] = []
            for lemma in added.compactMap(\.formMatch?.lemma) where !order.contains(lemma) {
                order.append(lemma)
            }
            XCTAssertEqual(order, lemmas.map(\.lemma), "'\(query)': the lemmas in Morphy's order")
            for row in added {
                XCTAssertEqual(row.entry.word.lowercased(), row.formMatch?.lemma, "'\(query)': \(row.entry.source)/\(row.entry.word)")
                let expected = lemmas.first { $0.lemma == row.formMatch?.lemma }?.caption
                XCTAssertEqual(caption(row), expected, "'\(query)': \(row.entry.source)/\(row.entry.word)")
            }
        }
        // Words that are no form of anything: no lemma row, today's results.
        let plain = ["this", "his", "yes", "its", "always", "perhaps", "people", "thus", "less", "unless", "series",
                     "hers", "ours"]
        var withStep: [String: [SearchResult]] = [:]
        for query in plain {
            withStep[query] = try await db.searchResults(query: query)
        }
        DatabaseService.lemmaStepEnabled = false
        for query in plain {
            let off = try await db.searchResults(query: query)
            XCTAssertEqual(withStep[query], off, "'\(query)' gains no lemma row")
        }
    }

    /// planes typed as Spanish (Kirill, 2026-11-02: an a–z query keeps its
    /// English rows). With the Spanish – English pair only, its one English
    /// dictionary gives plane, "form of plane"; Spanish WordNet's plan is no
    /// lemma row. In preferred mode with the Spanish pair first, that row
    /// leads the Spanish bucket, and every English dictionary keeps its own.
    @MainActor
    func testSpanishLookingQueryKeepsItsEnglishRows() async throws {
        func key(_ row: SearchResult) -> String {
            "\(row.entry.source)/\(row.entry.word)\(row.formMatch.map { ": " + FormCaption.text(for: $0, locale: Locale(identifier: "en")) } ?? "")"
        }
        let spanishPair: Set<String> = ["freedict-eng-spa", "wordnet-spa-eng"]
        let pairOnly = try await db.searchResults(query: "planes", enabledSources: spanishPair)
        XCTAssertEqual(lemmaRows(pairOnly).map(key), ["freedict-eng-spa/plane: form of plane"])
        XCTAssertEqual(pairOnly.first.map(key), "freedict-eng-spa/plane: form of plane", "no row of its own, so it leads")

        let groups = [["freedict-eng-spa", "wordnet-spa-eng"], ["wordnet"], ["openrussian"], DictAppTests.greekSourceIDs,
                      ["wordnet-arb-eng"]]
        let preferred = try await db.searchPreferredResults(query: "planes", groups: groups,
                                                            enabledSources: Set(groups.joined()))
        XCTAssertEqual(preferred.first.map(key), "freedict-eng-spa/plane: form of plane")
        XCTAssertEqual(Set(lemmaRows(preferred).map(key)), [
            "freedict-eng-spa/plane: form of plane", "wordnet/plane: form of plane",
            "freedict-eng-ell/plane: form of plane", "wordnet-eng-ell/plane: form of plane",
        ])
        XCTAssertEqual(Set(preferred.compactMap(\.id)).count, preferred.count, "no row repeats")
    }
}

/// #143: the morphy tables in the bundled file (0136, "Data"), and Morphy's
/// cases on them.
extension WordFormsLookupTests {
    func testMorphyTablesFollowTheSpec() throws {
        // Read first, assert after (see `DictionaryFileTests.testDictionaryFileFormat`).
        let file = try BundledDictionary().read { db in
            func primaryKey(_ table: String) throws -> [String] {
                try Row.fetchAll(db, sql: "PRAGMA table_info(\(table.quotedDatabaseIdentifier))")
                    .filter { ($0["pk"] as Int) > 0 }
                    .sorted { ($0["pk"] as Int) < ($1["pk"] as Int) }
                    .map { $0["name"] as String }
            }
            return (exceptionKey: try primaryKey("morphy_exception"), lemmaKey: try primaryKey("morphy_lemma"),
                    schema: try String.fetchAll(db, sql: """
                        SELECT sql FROM sqlite_master WHERE tbl_name IN ('morphy_exception', 'morphy_lemma') ORDER BY name
                        """),
                    exceptions: try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM morphy_exception"),
                    lemmas: try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM morphy_lemma"),
                    partsOfSpeech: try String.fetchAll(db, sql: "SELECT DISTINCT pos FROM morphy_exception ORDER BY pos"),
                    badLemmas: try String.fetchAll(db, sql: """
                        SELECT word FROM morphy_lemma
                        WHERE pos_mask NOT BETWEEN 1 AND 15 OR word <> lower(word)
                           OR instr(word, '_') > 0 OR instr(word, '-') > 0 OR instr(word, ' ') > 0
                        LIMIT 5
                        """),
                    specLines: try String.fetchAll(db, sql: """
                        SELECT form || ' ' || pos || ' ' || base FROM morphy_exception
                        WHERE form IN ('went', 'mice', 'better', 'running', 'geese') ORDER BY form, pos, base
                        """),
                    masks: try Dictionary(uniqueKeysWithValues: Row.fetchAll(db, sql: """
                        SELECT word, pos_mask FROM morphy_lemma WHERE word IN ('go', 'mouse', 'good', 'well', 'run', 'goose', 'new', 'wa')
                        """).map { ($0["word"] as String, $0["pos_mask"] as Int) }),
                    credits: try Int.fetchOne(db, sql: """
                        SELECT (SELECT COUNT(*) FROM data_source WHERE id LIKE '%morphy%' OR display_name LIKE '%WordNet%')
                             + (SELECT COUNT(*) FROM dict_metadata WHERE source LIKE '%morphy%')
                        """))
        }
        XCTAssertEqual(file.exceptionKey, ["form", "pos", "base"])
        XCTAssertEqual(file.lemmaKey, ["word"])
        XCTAssertEqual(file.schema.count, 2, "the two tables, no extra index: \(file.schema)")
        XCTAssertTrue(file.schema.allSatisfy { $0.contains("WITHOUT ROWID") }, "\(file.schema)")
        XCTAssertEqual(file.exceptions, 6_050, "WordNet 3.0's exception lines, one row per base; noun.exc repeats 3")
        XCTAssertEqual(file.lemmas, 77_898, "WordNet 3.0's lemmas without _ or -")
        XCTAssertEqual(file.partsOfSpeech, ["a", "n", "r", "v"])
        XCTAssertEqual(file.badLemmas, [], "single lowercase words with a mask of 1, 2, 4 and 8")
        XCTAssertEqual(file.specLines, ["better a good", "better a well", "better r well", "geese n goose", "mice n mouse",
                                        "running v run", "went v go"])
        XCTAssertEqual(file.masks, ["go": 7, "mouse": 3, "good": 13, "well": 15, "run": 3, "goose": 3, "new": 12, "wa": 1])
        XCTAssertEqual(file.credits, 0, "WordNet is credited as the wordnet dictionary; morphy adds no row")
    }

    /// #141 data fixes (Kirill, 2026-11-01, #143): a link page's own spelling
    /// is stored when it is no cell of its lemma's table, so a word that only
    /// folds like it (στύλος, βολέ) can be told apart; a synonym gloss is no
    /// form link, so υποδηματοποιός and ψωμάς keep their own tables.
    func testLinkPagesKeepTheirSpelling() throws {
        let file = try BundledDictionary(url: try PackFixtures.file(.ell)).read { db in
            (schema: try String.fetchOne(db, sql: "SELECT sql FROM sqlite_master WHERE name = 'form_link'"),
             key: try Row.fetchAll(db, sql: "PRAGMA table_info(form_link)")
                .filter { ($0["pk"] as Int) > 0 }.sorted { ($0["pk"] as Int) < ($1["pk"] as Int) }.map { $0["name"] as String },
             rows: try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM form_link"),
             spelled: try Set(Row.fetchAll(db, sql: """
                SELECT f.form, l.word FROM form_link f JOIN lemma l ON l.id = f.lemma_id
                WHERE f.form IN ('στυλός', 'βόλε', 'βόλος', 'μέρα', 'στύλος', 'βολέ', 'υποδηματοποιός')
                """).map { "\($0["form"] as String) → \($0["word"] as String)" }),
             cellsOrOrphans: try Int.fetchOne(db, sql: """
                SELECT COUNT(*) FROM form_link f
                WHERE f.lemma_id NOT IN (SELECT id FROM lemma)
                   OR EXISTS (SELECT 1 FROM paradigm p WHERE p.lemma_id = f.lemma_id AND p.form = f.form)
                """),
             withoutLookupRow: try Row.fetchAll(db, sql: "SELECT form, lemma_id FROM form_link").filter { row in
                 try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM form_lookup WHERE form_norm = ? AND lemma_id = ?",
                                  arguments: [Search.foldGreek(row["form"] as String), row["lemma_id"] as Int64]) == 0
             }.map { $0["form"] as String },
             ownTables: try String.fetchAll(db, sql: """
                SELECT l.word FROM lemma l WHERE l.word IN ('υποδηματοποιός', 'ψωμάς') AND l.pos = 'noun'
                  AND EXISTS (SELECT 1 FROM paradigm p WHERE p.lemma_id = l.id) ORDER BY l.word
                """),
             synonymLinks: try String.fetchAll(db, sql: """
                SELECT f.form_norm || ' → ' || l.word FROM form_lookup f JOIN lemma l ON l.id = f.lemma_id
                WHERE (f.form_norm, l.word) IN (VALUES ('υποδηματοποιοσ', 'τσαγκάρης'), ('παχυσ', 'χοντρός'),
                                                      ('ψωμασ', 'αρτοποιός'), ('σιδεριτησ', 'τσάι'))
                """))
        }
        XCTAssertEqual(file.key, ["form", "lemma_id"])
        XCTAssertTrue(file.schema?.contains("WITHOUT ROWID") == true, "\(file.schema ?? "no form_link")")
        XCTAssertGreaterThan(file.rows ?? 0, 8_000, "every link page that is no cell of its lemma's table")
        XCTAssertEqual(file.spelled, ["στυλός → στυλό", "βόλε → βώλος", "βόλος → βώλος", "μέρα → ημέρα"],
                       "στύλος (pillar) and βολέ (volley) only fold like link pages")
        XCTAssertEqual(file.cellsOrOrphans, 0, "a spelling that is a cell is in paradigm already; no orphan rows")
        XCTAssertEqual(file.withoutLookupRow, [], "every link spelling has its folded lookup row")
        XCTAssertEqual(file.ownTables, ["υποδηματοποιός", "ψωμάς"], "synonym pages are lemmas with their own tables")
        XCTAssertEqual(file.synonymLinks, [], "a synonym gloss is no form link")
    }
}

/// #143: a table link needs the word itself, a cell of the linked table or
/// the link page's own spelling (`form_link`), on the real file. #144's
/// `chooseLink` and `linkFits` still apply after it.
extension InflectionLookupTests {
    @MainActor
    func testLinksNeedTheWordsOwnSpelling() async throws {
        let none: [(word: String, source: String)] = [
            ("στύλος", "freedict-ell-eng"), ("στύλος", "wordnet-ell-eng"), ("βολέ", "freedict-ell-eng"),
        ]
        for item in none {
            let paradigm = try await InflectionFixture.paradigm(item.word, pos: "noun", source: item.source)
            XCTAssertNil(paradigm, "\(item.word) (\(item.source)) only folds like a link page; it shows \(paradigm?.word ?? "")'s table")
        }
        let linked: [(word: String, pos: String, lemma: String)] = [
            ("μέρα", "noun", "ημέρα"), ("πάω", "verb", "πηγαίνω"), ("αγαπώ", "verb", "αγαπάω"),
        ]
        for item in linked {
            let paradigm = try await InflectionFixture.paradigm(item.word, pos: item.pos)
            XCTAssertEqual(paradigm?.word, item.lemma, "\(item.word): a link page's spelling or a cell keeps the link")
            XCTAssertEqual(paradigm?.isLinked, true, item.word)
        }
        let own = try await InflectionFixture.paradigm("υποδηματοποιός", pos: "noun")
        XCTAssertEqual(own?.word, "υποδηματοποιός", "a synonym gloss is no link: the word's own table")
        XCTAssertEqual(own?.isLinked, false)
    }
}

// MARK: - Issue #213: reopen the dictionary file after the system invalidates it

/// The system invalidates the open dictionary file, as the removal of the old
/// bundle's link after an install over the app does, and the service
/// recovers by reopening it (0129, "Invalidated dictionary file"). Each test
/// follows the spec's reproduction:
/// 1. `dictionary.sqlite` holds 2,000 rows in two sources, and a hard link
///    `staging.sqlite` stands for the old bundle's link in containermanagerd's
///    `Dead` folder;
/// 2. the service attaches `dictionary.sqlite`, and `fetchMetadata()` opens
///    a reader, so the writer and the readers cache only the schema and
///    `dict_metadata`;
/// 3. a control connection of the test's own attaches the file with the
///    app's URI;
/// 4. one link is removed (iOS SQLite logs "vnode unlinked while in use");
/// 5. every 100 ms, for up to 10 s, the control connection reads
///    `dict.entries`, until the read fails with SQLITE_IOERR. It keeps no
///    page cache for `dict` (`cache_size = 0`), so every read goes to the
///    file: on iOS 17.5 `sqlite3_db_release_memory` leaves the pages of the
///    immutable file cached. If the read never fails, this OS does not
///    invalidate the file and the test skips;
/// 6. the service's connections now hold invalid descriptors.
@MainActor
final class DictionaryReopenTests: XCTestCase {
    private static let sources = ["alpha", "beta"]
    /// The My words row added before step 4.
    private static let myWord = EntryKey(source: "alpha", word: "house7")

    private var tempDir: URL!
    private var db: DatabaseService { .shared }
    private var dictionaryURL: URL { tempDir.appendingPathComponent("dictionary.sqlite") }
    private var stagingURL: URL { tempDir.appendingPathComponent("staging.sqlite") }
    private var userPath: String { tempDir.appendingPathComponent("user.sqlite").path }
    /// Step 3: an in-memory connection with the file attached as `dict` and
    /// no page cache for it.
    private var control: DatabaseQueue?

    override func setUp() async throws {
        try await super.setUp()
        await DictAppTests.waitForHostAppLaunch()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        // Step 1.
        let rows = Self.sources.flatMap { source in
            (0..<1000).map { i in
                TestDictionary.Row(word: "house\(i)", definition: "house number \(i) of \(source), a dwelling",
                                   pos: "noun", source: source)
            }
        }
        try TestDictionary.make(rows: rows, at: dictionaryURL)
        try FileManager.default.linkItem(at: dictionaryURL, to: stagingURL)
    }

    override func tearDown() async throws {
        control = nil
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    // MARK: Helpers

    /// What the reads under test return.
    private struct Reads {
        var search: [DictionaryEntry]
        var preferred: [DictionaryEntry]
        var entry: DictionaryEntry?
        var myWords: [DictionaryEntry]
        var stats: [SourceStat]
        var metadata: [DictMetadata]
    }

    /// Search first: it is the call that meets the invalid file.
    private func reads() async throws -> Reads {
        Reads(
            search: try await db.search(query: "house"),
            preferred: try await db.searchPreferred(query: "dwelling", groups: [["beta"], ["alpha"]],
                                                    enabledSources: Set(Self.sources)),
            entry: try await db.entry(for: EntryKey(source: "beta", word: "house999")),
            myWords: try await db.fetchMyWords(),
            stats: try await db.fetchSourceStats(),
            metadata: try await db.fetchMetadata())
    }

    /// Adds the My words row and returns the reads under test, on a pool of
    /// their own: step 2 opens a new one, which has cached nothing else.
    private func readsBeforeInvalidation() async throws -> Reads {
        try await db.setup(userPath: userPath, dictionaryURL: dictionaryURL)
        try await db.addToMyWords(Self.myWord)
        let reads = try await reads()
        XCTAssertFalse(reads.search.isEmpty)
        XCTAssertFalse(reads.preferred.isEmpty)
        XCTAssertNotNil(reads.entry)
        XCTAssertEqual(reads.myWords.map { EntryKey($0) }, [Self.myWord])
        XCTAssertEqual(reads.stats.map(\.count), [1000, 1000])
        XCTAssertEqual(reads.metadata.map(\.source), Self.sources)
        return reads
    }

    /// Steps 2 to 6, removing `link` in step 4. Step 2 runs
    /// `concurrentReads` `fetchMetadata()` calls at once: more than one
    /// leaves the pool with several readers.
    private func openAndInvalidate(removing link: URL, concurrentReads: Int = 1) async throws {
        try await db.setup(userPath: userPath, dictionaryURL: dictionaryURL)
        try await withThrowingTaskGroup(of: Void.self) { group in
            for _ in 0..<concurrentReads {
                group.addTask { _ = try await DatabaseService.shared.fetchMetadata() }
            }
            try await group.waitForAll()
        }
        try await invalidate(removing: link)
    }

    /// Steps 3 to 5 alone, on a new control connection. A test calls it
    /// again to invalidate the connections a reopen opened.
    private func invalidate(removing link: URL) async throws {
        let control = try DatabaseQueue()
        let uri = DatabaseService.dictionaryURI(dictionaryURL)
        try control.inDatabase { db in
            try db.execute(sql: "ATTACH DATABASE ? AS dict", arguments: [uri])
            try db.execute(sql: "PRAGMA dict.cache_size = 0")
        }
        self.control = control
        XCTAssertNil(controlReadError(), "the control connection reads the file before step 4")

        try FileManager.default.removeItem(at: link)
        let deadline = Date().addingTimeInterval(10)
        while controlReadError()?.resultCode != .SQLITE_IOERR {
            if Date() > deadline {
                throw XCTSkip("The file stayed readable 10 s after \(link.lastPathComponent) was removed: "
                              + "this OS does not invalidate it. Note the OS in 0129 History.")
            }
            try await Task.sleep(nanoseconds: 100_000_000)
        }
    }

    /// Reads every `dict.entries` row from the file on the control
    /// connection: `nil`, or the SQLite error.
    private func controlReadError() -> DatabaseError? {
        guard let control else { return nil }
        do {
            _ = try control.inDatabase { db in
                try Int.fetchOne(db, sql: "SELECT SUM(LENGTH(definition)) FROM dict.entries")
            }
            return nil
        } catch {
            return error as? DatabaseError
        }
    }

    // MARK: Tests

    /// #213: after the file is invalidated, the next search returns results
    /// without a restart, and every read returns what it returned before
    /// step 4. Exactly one reopen did it: the control connection, which is
    /// not reopened, still fails.
    func testReadsRecoverAfterTheFileIsInvalidated() async throws {
        let expected = try await readsBeforeInvalidation()
        try await openAndInvalidate(removing: stagingURL)
        let reopens = await db.dictionaryReopenCount

        let recovered = try await reads()
        XCTAssertEqual(recovered.search, expected.search, "search")
        XCTAssertEqual(recovered.preferred, expected.preferred, "searchPreferred")
        XCTAssertEqual(recovered.entry, expected.entry, "entry(for:)")
        XCTAssertEqual(recovered.myWords, expected.myWords, "fetchMyWords")
        XCTAssertEqual(recovered.stats, expected.stats, "fetchSourceStats")
        XCTAssertEqual(recovered.metadata, expected.metadata, "fetchMetadata")
        let after = await db.dictionaryReopenCount
        XCTAssertEqual(after - reopens, 1, "one reopen")
        XCTAssertEqual(controlReadError()?.resultCode, .SQLITE_IOERR,
                       "the file itself is still invalid for the old descriptors: the reopen recovered")
    }

    /// #213: an import of one word the file has and one it lacks stores only
    /// the second: its key check fails on the writer, which reads
    /// `dict.entries` again after the re-attach.
    func testImportRecoversAfterTheFileIsInvalidated() async throws {
        try await openAndInvalidate(removing: stagingURL)
        let reopens = await db.dictionaryReopenCount
        let file = tempDir.appendingPathComponent("alpha.json")
        try JSONSerialization.data(withJSONObject: [
            ["word": "house5", "definition": "already in the dictionary file"],
            ["word": "gazebo", "definition": "a garden house"],
        ]).write(to: file)

        let imported = try await db.importJSON(at: file, source: "alpha")
        XCTAssertEqual(imported, 2, "both rows were read")
        let afterImport = await db.dictionaryReopenCount
        XCTAssertEqual(afterImport - reopens, 1, "the key check failed on the writer and reopened the file")

        let gazebo = try await db.entry(for: EntryKey(source: "alpha", word: "gazebo"))
        XCTAssertGreaterThanOrEqual(try XCTUnwrap(gazebo?.id), Int64(1) << 40, "gazebo is an imported row")
        let house5 = try await db.entry(for: EntryKey(source: "alpha", word: "house5"))
        XCTAssertEqual(house5?.definition, "house number 5 of alpha, a dwelling", "house5 stays the file's row")
        let count = try await db.entryCount(source: "alpha")
        XCTAssertEqual(count, 1001, "only gazebo was stored")
        let after = await db.dictionaryReopenCount
        XCTAssertEqual(after - reopens, 1, "no further reopen")
    }

    /// #213: 8 searches at once on several invalid readers all return
    /// results, with one reopen.
    func testConcurrentFailuresReopenOnce() async throws {
        try await openAndInvalidate(removing: stagingURL, concurrentReads: 16)
        let reopens = await db.dictionaryReopenCount

        let results = try await withThrowingTaskGroup(of: [DictionaryEntry].self) { group in
            for i in 0..<8 {
                group.addTask { try await DatabaseService.shared.search(query: "house\(i)") }
            }
            var all: [[DictionaryEntry]] = []
            for try await rows in group { all.append(rows) }
            return all
        }
        XCTAssertEqual(results.count, 8)
        XCTAssertTrue(results.allSatisfy { !$0.isEmpty }, "every search returns results")
        let after = await db.dictionaryReopenCount
        XCTAssertEqual(after - reopens, 1, "one reopen for all failures")
    }

    /// #213: one retry only. Step 4 removes `dictionary.sqlite` itself, so
    /// the re-attach finds no file: Search throws after one reopen, and
    /// History, which does not read `dict`, still writes.
    func testASecondFailureSurfaces() async throws {
        try await openAndInvalidate(removing: dictionaryURL)
        let reopens = await db.dictionaryReopenCount

        do {
            let rows = try await db.search(query: "house")
            XCTFail("search must fail without the file, got \(rows.count) rows")
        } catch {
            XCTAssertEqual((error as? DatabaseError)?.resultCode, .SQLITE_CANTOPEN,
                           "the retry's new reader finds no file: \(error)")
        }
        let after = await db.dictionaryReopenCount
        XCTAssertEqual(after - reopens, 1, "one reopen, no loop")

        try await db.addToHistory(word: "house3", source: "alpha")
        var config = Configuration()
        config.readonly = true
        let words = try await DatabaseQueue(path: userPath, configuration: config).read { db in
            try String.fetchAll(db, sql: "SELECT word FROM history")
        }
        XCTAssertEqual(words, ["house3"], "History writes without the dictionary file")
    }

    /// #213: the reopen is not one-shot ("the next failing call would recover
    /// it the same way"). A second link removed under the connections that
    /// the first reopen opened invalidates them too; the next failing call
    /// reopens once more, and the writer, attached again, reads the file for
    /// an import's key check.
    func testASecondInvalidationRecoversAgain() async throws {
        let expected = try await readsBeforeInvalidation()
        try await openAndInvalidate(removing: stagingURL)
        let reopens = await db.dictionaryReopenCount

        // First recovery: a lookup that reads a few `entries` pages only.
        let entry = try await db.entry(for: EntryKey(source: "beta", word: "house999"))
        XCTAssertEqual(entry, expected.entry, "entry(for:) after the first invalidation")
        let afterFirst = await db.dictionaryReopenCount
        XCTAssertEqual(afterFirst - reopens, 1, "the first invalidation reopened the file")
        // The writer has run its re-attach before the second link goes.
        try await db.writeForTesting { _ in }

        let secondLink = tempDir.appendingPathComponent("staging-2.sqlite")
        try FileManager.default.linkItem(at: dictionaryURL, to: secondLink)
        try await invalidate(removing: secondLink)

        let search = try await db.search(query: "house")
        XCTAssertEqual(search, expected.search, "search after the second invalidation")
        let afterSecond = await db.dictionaryReopenCount
        XCTAssertEqual(afterSecond - reopens, 2, "the second invalidation reopened the file once more")

        let file = tempDir.appendingPathComponent("alpha.json")
        try JSONSerialization.data(withJSONObject: [
            ["word": "house5", "definition": "already in the dictionary file"],
            ["word": "gazebo", "definition": "a garden house"],
        ]).write(to: file)
        let imported = try await db.importJSON(at: file, source: "alpha")
        XCTAssertEqual(imported, 2, "both rows were read")
        let count = try await db.entryCount(source: "alpha")
        XCTAssertEqual(count, 1001, "the writer read the file again: only gazebo was stored")
        let afterImport = await db.dictionaryReopenCount
        XCTAssertEqual(afterImport - reopens, 2, "the import needed no reopen of its own")
    }

    /// #213: if the re-attach fails (the file itself is gone, which an
    /// installed app never sees), the writer stays without `dict` until a
    /// restart. Every import then fails with "no such table" and is not
    /// retried, so it causes no further reopen; My words and History writes,
    /// which do not read the file, still work.
    func testImportsFailWithoutRetryAfterAFailedReattach() async throws {
        try await openAndInvalidate(removing: dictionaryURL)
        let reopens = await db.dictionaryReopenCount
        let file = tempDir.appendingPathComponent("alpha.json")
        try JSONSerialization.data(withJSONObject: [["word": "gazebo", "definition": "a garden house"]])
            .write(to: file)

        for attempt in 1...2 {
            do {
                let rows = try await db.importJSON(at: file, source: "alpha")
                XCTFail("import \(attempt) must fail without the dictionary file, read \(rows) rows")
            } catch let error as DatabaseError {
                XCTAssertEqual(error.resultCode, .SQLITE_ERROR, "import \(attempt): \(error)")
                XCTAssertTrue(error.message?.contains("no such table: dict.entries") == true,
                              "import \(attempt): \(error)")
            }
            let after = await db.dictionaryReopenCount
            XCTAssertEqual(after - reopens, 1,
                           "import \(attempt): only the first one's I/O error reopened; a missing table is not retried")
        }

        try await db.addToMyWords(Self.myWord)
        try await db.addToHistory(word: "house7", source: "alpha")
        // Read back on a connection of the test's own: every new reader of
        // the service attaches the file and fails.
        var config = Configuration()
        config.readonly = true
        let stored = try await DatabaseQueue(path: userPath, configuration: config).read { db in
            (myWords: try Row.fetchAll(db, sql: "SELECT source, word FROM my_words")
                .map { EntryKey(source: $0["source"], word: $0["word"]) },
             history: try String.fetchAll(db, sql: "SELECT word FROM history"),
             imported: try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM imported_entries") ?? -1,
             sources: try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM imported_sources") ?? -1)
        }
        XCTAssertEqual(stored.myWords, [Self.myWord], "My words writes without the dictionary file")
        XCTAssertEqual(stored.history, ["house7"], "History writes without the dictionary file")
        XCTAssertEqual(stored.imported, 0, "the failed imports stored no row")
        XCTAssertEqual(stored.sources, 0, "and registered no source")
    }

    /// Counts calls of an SQL function on the writer.
    private final class CallCounter: @unchecked Sendable {
        private let lock = NSLock()
        private var value = 0
        var count: Int { lock.withLock { value } }
        func increment() { lock.withLock { value += 1 } }
    }

    /// #213: only reads and the import retry (Kirill, 2026-10-30).
    /// - With the file invalidated, History and My words writes that fail
    ///   with SQLITE_IOERR throw, run once and reopen nothing: they touch
    ///   only `user.sqlite`. The invalidated file never makes them fail, so
    ///   the error is raised inside SQLite on the writer: a TEMP trigger
    ///   calls a function that throws it.
    /// - An import whose `COMMIT` fails with SQLITE_IOERR throws, runs once,
    ///   reopens nothing and stores nothing: whether a failed `COMMIT` took
    ///   effect is unknown. The failure is real: the user database's WAL is
    ///   invalidated the way the file is, by removing a hard link of it
    ///   while the writer holds it open, then emptied by a checkpoint, so
    ///   `COMMIT` is the only statement that touches it.
    func testUserDataWritesAreNotRetried() async throws {
        try await openAndInvalidate(removing: stagingURL)
        try await db.addToMyWords(Self.myWord)
        let reopens = await db.dictionaryReopenCount
        let ioErrors = CallCounter(), importedRows = CallCounter()
        try await db.writeForTesting { db in
            db.add(function: DatabaseFunction("test_io_error", argumentCount: 0) { _ in
                ioErrors.increment()
                throw DatabaseError(resultCode: .SQLITE_IOERR_WRITE, message: "injected I/O error")
            })
            db.add(function: DatabaseFunction("test_imported_row", argumentCount: 0) { _ in
                importedRows.increment()
                return nil
            })
            try db.execute(sql: """
                CREATE TEMP TRIGGER test_history_io BEFORE INSERT ON history BEGIN SELECT test_io_error(); END;
                CREATE TEMP TRIGGER test_my_words_add_io BEFORE INSERT ON my_words BEGIN SELECT test_io_error(); END;
                CREATE TEMP TRIGGER test_my_words_remove_io BEFORE DELETE ON my_words BEGIN SELECT test_io_error(); END;
                CREATE TEMP TRIGGER test_imported_row AFTER INSERT ON imported_entries BEGIN SELECT test_imported_row(); END;
                """)
        }

        let writes: [(name: String, run: () async throws -> Void)] = [
            ("addToHistory", { try await DatabaseService.shared.addToHistory(word: "house3", source: "alpha") }),
            ("addToMyWords", { try await DatabaseService.shared.addToMyWords(EntryKey(source: "beta", word: "house3")) }),
            ("removeFromMyWords", { try await DatabaseService.shared.removeFromMyWords(Self.myWord) }),
        ]
        for (index, write) in writes.enumerated() {
            do {
                try await write.run()
                XCTFail("\(write.name) must throw the I/O error")
            } catch let error as DatabaseError {
                XCTAssertEqual(error.extendedResultCode, .SQLITE_IOERR_WRITE, "\(write.name): \(error)")
            }
            XCTAssertEqual(ioErrors.count, index + 1, "\(write.name) ran once")
            let after = await db.dictionaryReopenCount
            XCTAssertEqual(after - reopens, 0, "\(write.name) reopened nothing")
        }

        // Reads still retry: a search reopens the file, and the writer
        // attaches it again for the import's key check.
        let rows = try await db.search(query: "house")
        XCTAssertFalse(rows.isEmpty, "the search recovered")
        let afterSearch = await db.dictionaryReopenCount
        XCTAssertEqual(afterSearch - reopens, 1, "the search reopened the file")

        // Invalidate the WAL. A read-only control connection without a page
        // cache reads the My words page from the WAL until that fails.
        var readOnly = Configuration()
        readOnly.readonly = true
        let walControl = try DatabaseQueue(path: userPath, configuration: readOnly)
        try walControl.inDatabase { try $0.execute(sql: "PRAGMA cache_size = 0") }
        func walIsReadable() -> Bool {
            (try? walControl.inDatabase { try Int.fetchOne($0, sql: "SELECT COUNT(*) FROM my_words") }) != nil
        }
        XCTAssertTrue(walIsReadable(), "the control connection reads the WAL before the link goes")
        let walLink = tempDir.appendingPathComponent("user-wal-link.sqlite")
        try FileManager.default.linkItem(at: URL(fileURLWithPath: userPath + "-wal"), to: walLink)
        try FileManager.default.removeItem(at: walLink)
        let deadline = Date().addingTimeInterval(10)
        while walIsReadable() {
            if Date() > deadline {
                throw XCTSkip("The WAL stayed readable 10 s after its link was removed: this OS does not invalidate it.")
            }
            try await Task.sleep(nanoseconds: 100_000_000)
        }
        // Empty the WAL through a new connection, so the writer reads every
        // page from the main file and only `COMMIT` writes the WAL.
        let checkpoint = try DatabaseQueue(path: userPath).inDatabase { db in
            try XCTUnwrap(Row.fetchOne(db, sql: "PRAGMA wal_checkpoint(TRUNCATE)"))
        }
        XCTAssertEqual(checkpoint[0] as Int, 0, "the checkpoint was not blocked: \(checkpoint)")

        let file = tempDir.appendingPathComponent("alpha.json")
        try JSONSerialization.data(withJSONObject: [
            ["word": "house5", "definition": "already in the dictionary file"],
            ["word": "gazebo", "definition": "a garden house"],
        ]).write(to: file)
        do {
            let read = try await db.importJSON(at: file, source: "alpha")
            XCTFail("the import must throw its failed COMMIT, read \(read) rows")
        } catch let error as DatabaseError {
            XCTAssertEqual(error.resultCode, .SQLITE_IOERR, "\(error)")
            XCTAssertEqual(error.sql, "COMMIT TRANSACTION", "GRDB reports the statement that failed: \(error)")
        }
        XCTAssertEqual(importedRows.count, 1, "the import ran once: it inserted gazebo once, then COMMIT failed")
        let afterImport = await db.dictionaryReopenCount
        XCTAssertEqual(afterImport - afterSearch, 0, "a failed COMMIT reopens nothing")
        // A new connection opens the WAL anew.
        let stored = try await DatabaseQueue(path: userPath, configuration: readOnly).read { db in
            try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM imported_entries") ?? -1
        }
        XCTAssertEqual(stored, 0, "the failed COMMIT stored nothing")
    }

    /// #213: each reopen writes one `os.Logger` line (subsystem
    /// `com.kyukhin.DictApp`, category `database`) with SQLite's extended
    /// result code, an I/O error, and the time the reopen took. Never the SQL
    /// or its arguments, which hold the user's query.
    func testAReopenLogsOneLineWithoutTheQuery() async throws {
        try await openAndInvalidate(removing: stagingURL)
        // A marker in the same category goes first: the lines after it are
        // this test's. Log timestamps and `Date()` can differ by tens of
        // milliseconds, so a time filter would not be exact.
        let marker = "DictionaryReopenTests marker \(UUID().uuidString)"
        Logger(subsystem: "com.kyukhin.DictApp", category: "database").notice("\(marker, privacy: .public)")

        let query = "house42"
        let rows = try await db.search(query: query)
        XCTAssertFalse(rows.isEmpty, "the search recovered")
        // The line is written on the writer once the re-attach ends.
        try await db.writeForTesting { _ in }

        // One scan from a minute back: the store is slow to read (up to 8 s
        // on the iOS 17.5 simulator).
        let store = try OSLogStore(scope: .currentProcessIdentifier)
        let predicate = NSPredicate(format: "subsystem == %@ AND category == %@", "com.kyukhin.DictApp", "database")
        let messages = try store.getEntries(at: store.position(date: Date().addingTimeInterval(-60)), matching: predicate)
            .compactMap { ($0 as? OSLogEntryLog)?.composedMessage }
        let sawMarker = messages.contains(marker)
        let lines = Array(messages.drop { $0 != marker }.dropFirst())
        XCTAssertTrue(sawMarker, "the store holds the marker: \(lines)")
        XCTAssertEqual(lines.count, 1, "one line per reopen: \(lines)")
        let line = try XCTUnwrap(lines.first)
        let pattern = try NSRegularExpression(pattern: "^Reopened the dictionary file after SQLite error ([0-9]+) in ([0-9]+) ms$")
        let match = try XCTUnwrap(pattern.firstMatch(in: line, range: NSRange(line.startIndex..., in: line)),
                                  "the line has the result code and the duration only: \(line)")
        let code = try XCTUnwrap(Range(match.range(at: 1), in: line).flatMap { Int32(line[$0]) })
        XCTAssertEqual(ResultCode(rawValue: code).primaryResultCode, .SQLITE_IOERR,
                       "the extended code of an I/O error: \(code)")
        XCTAssertFalse(line.contains(query), "never the user's query")
    }

    /// The unit tests' own reader of a dictionary file, `BundledDictionary`,
    /// survives the same invalidation: a read that fails with SQLITE_IOERR
    /// runs once more on a new connection. Here the link goes while the first
    /// connection has the file open, as an install can do under the seed
    /// tests.
    func testBundledDictionaryReaderRetriesOnANewConnection() throws {
        var attempts = 0
        let count = try BundledDictionary(url: dictionaryURL).read { db -> Int? in
            attempts += 1
            if attempts == 1 {
                try db.execute(sql: "PRAGMA cache_size = 0")
                _ = try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM dict_metadata")
                try FileManager.default.removeItem(at: stagingURL)
                let deadline = Date().addingTimeInterval(10)
                while Date() < deadline {
                    // Throws SQLITE_IOERR once the file is invalidated.
                    _ = try Int.fetchOne(db, sql: "SELECT SUM(LENGTH(definition)) FROM entries")
                    Thread.sleep(forTimeInterval: 0.1)
                }
                throw XCTSkip("The file stayed readable 10 s after staging.sqlite was removed: "
                              + "this OS does not invalidate it. Note the OS in 0129 History.")
            }
            return try Int.fetchOne(db, sql: "SELECT COUNT(*) FROM entries")
        }
        XCTAssertEqual(attempts, 2, "the read failed once and ran again on a new connection")
        XCTAssertEqual(count, 2000, "the new connection reads every row")
    }
}

extension DictionaryReopenTests {
    /// #237 (0237 "Connection layout", Test plan "No regression"): the
    /// reopen after the bundle is invalidated attaches every name again,
    /// the packs too. New readers find a pack's rows, the writer's key
    /// check sees them, and the writer has every name on its file.
    func testAReopenReattachesThePacks() async throws {
        let pack = tempDir.appendingPathComponent("spa-pack.sqlite")
        try TestDictionary.make(rows: (0..<10).map {
            TestDictionary.Row(word: "casa\($0)", definition: "pack row \($0)", pos: "noun", source: "wordnet-spa-eng")
        }, at: pack)
        try await db.setup(userPath: userPath, dictionaryURL: dictionaryURL, packFiles: [.spa: pack])
        let before = try await db.search(query: "casa3")
        XCTAssertEqual(before.map(\.word), ["casa3"])
        try await withThrowingTaskGroup(of: Void.self) { group in
            for _ in 0..<4 {
                group.addTask { _ = try await DatabaseService.shared.fetchMetadata() }
            }
            try await group.waitForAll()
        }
        try await invalidate(removing: stagingURL)
        let reopens = await db.dictionaryReopenCount

        let house = try await db.search(query: "house")
        XCTAssertFalse(house.isEmpty, "the bundle reads again")
        let afterReopen = await db.dictionaryReopenCount
        XCTAssertEqual(afterReopen - reopens, 1, "one reopen")
        let casa = try await db.search(query: "casa3")
        XCTAssertEqual(casa, before, "the pack reads on the new readers")

        let json = tempDir.appendingPathComponent("wordnet-spa-eng.json")
        try JSONSerialization.data(withJSONObject: [
            ["word": "casa5", "definition": "already in the pack"],
            ["word": "mesa", "definition": "a table"],
        ]).write(to: json)
        let read = try await db.importJSON(at: json, source: "wordnet-spa-eng")
        XCTAssertEqual(read, 2)
        let count = try await db.entryCount(source: "wordnet-spa-eng")
        XCTAssertEqual(count, 11, "the writer's key check read the re-attached pack: only mesa was stored")
        let afterImport = await db.dictionaryReopenCount
        XCTAssertEqual(afterImport - reopens, 1, "no further reopen")

        let attached = try await db.writeForTesting { conn in
            try Row.fetchAll(conn, sql: "PRAGMA database_list").map { ($0["name"] as String, $0["file"] as String) }
        }
        let files = Dictionary(uniqueKeysWithValues: attached.filter { $0.0 != "temp" })
        XCTAssertEqual(Set(files.keys), Set(["main"] + DictionarySchemas.all), "every name on the writer")
        XCTAssertEqual(files["dict"].map { URL(fileURLWithPath: $0).lastPathComponent }, dictionaryURL.lastPathComponent)
        XCTAssertEqual(files["spa"].map { URL(fileURLWithPath: $0).lastPathComponent }, "spa-pack.sqlite")
        for schema in ["rus", "arb", "ell", "eng_lists"] {
            XCTAssertEqual(files[schema].map { URL(fileURLWithPath: $0).lastPathComponent }, "empty-pack.sqlite", schema)
        }
    }
}

// MARK: - Issue #144: inflection tables on the Definition screen
//
// 0136-word-forms.md, "Inflection tables (#144)" and "Tables (#144)". The
// layout is pure; the paradigms come from the real bundled
// `dictionaries.sqlite` through `DatabaseService.inflection(for:)`, so the
// lookup rule is exercised too. Synthetic cells cover what the snapshot
// does not pin down.

/// The real dictionary file on `DatabaseService.shared`, and the paradigm
/// and English table of a Greek entry.
private enum InflectionFixture {
    static let en = Locale(identifier: "en")

    static func open(in directory: URL) async throws {
        await DictAppTests.waitForHostAppLaunch()
        try await DatabaseService.shared.setup(userPath: directory.appendingPathComponent("user.sqlite").path,
                                               dictionaryURL: try TestDictionary.bundledURL(), packFiles: try PackFixtures.all())
    }

    static func entry(_ word: String, pos: String, source: String = "freedict-ell-eng") -> DictionaryEntry {
        DictionaryEntry(id: nil, word: word, definition: "", phonetic: "", pos: pos, source: source)
    }

    static func paradigm(_ word: String, pos: String, source: String = "freedict-ell-eng") async throws -> LemmaParadigm? {
        try await DatabaseService.shared.inflection(for: entry(word, pos: pos, source: source))
    }

    @MainActor
    static func table(_ word: String, pos: String, locale: Locale = en) async throws -> InflectionTable {
        let found = try await paradigm(word, pos: pos)
        let paradigm = try XCTUnwrap(found, "\(word) has a paradigm")
        return try XCTUnwrap(ParadigmLayout.table(for: paradigm, locale: locale), "\(word) has a table")
    }

    static func cells(_ cells: [(String, String)]) -> [ParadigmCell] {
        cells.map { ParadigmCell(form: $0.0, tags: $0.1) }
    }
}

private extension InflectionTable {
    func section(_ id: String) -> Section? { sections.first { $0.id == id } }

    /// Every cell by its accessibility identifier.
    var cellsByID: [String: Cell] {
        Dictionary(uniqueKeysWithValues: sections.flatMap { $0.rows.flatMap(\.cells) }.map { ($0.id, $0) })
    }

    func forms(_ id: String) -> [String]? { cellsByID[id]?.forms }
}

private extension InflectionTable.Section {
    var columnIDs: [String] { columns.map(\.id) }
    var rowIDs: [String] { rows.map(\.id) }
}

/// `ParadigmLayout`: slots, generated forms, empty rows and columns, labels.
final class ParadigmLayoutTests: XCTestCase {
    private var tempDir: URL!

    override func setUp() async throws {
        try await super.setUp()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        try await InflectionFixture.open(in: tempDir)
    }

    override func tearDown() async throws {
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    /// γράφω, default view: the persons × Present, Imperfect, Aorist, Future
    /// (θα γράψω) in grammar-book order, then the 2×2 imperative. Rare
    /// cells are hidden, variants share a cell.
    @MainActor
    func testVerbMainViewInGrammarBookOrder() async throws {
        let table = try await InflectionFixture.table("γράφω", pos: "verb")
        XCTAssertEqual(table.kind, .conjugation)
        XCTAssertNil(table.linkedLemma)
        XCTAssertEqual(table.mainSections.map(\.id), ["active_indicative", "active_imperative"])

        let main = try XCTUnwrap(table.section("active_indicative"))
        XCTAssertEqual(main.columnIDs, ["present", "imperfect", "aorist", "future"])
        XCTAssertEqual(main.columns.map(\.title), ["Present", "Imperfect", "Aorist", "Future"])
        XCTAssertEqual(main.rowIDs, ["1sg", "2sg", "3sg", "1pl", "2pl", "3pl"])
        XCTAssertEqual(main.rows.compactMap(\.header?.title), ["εγώ", "εσύ", "αυτός", "εμείς", "εσείς", "αυτοί"])
        XCTAssertNil(main.title)
        XCTAssertNil(main.heading)
        XCTAssertEqual(table.forms("inflection_cell_active_present_1sg"), ["γράφω"])
        XCTAssertEqual(table.forms("inflection_cell_active_imperfect_1sg"), ["έγραφα"])
        XCTAssertEqual(table.forms("inflection_cell_active_aorist_1sg"), ["έγραψα"])
        XCTAssertEqual(table.forms("inflection_cell_active_future_1sg"), ["θα γράψω"])
        XCTAssertEqual(table.forms("inflection_cell_active_present_1pl"), ["γράφουμε"], "rare γράφομε is hidden")
        XCTAssertEqual(table.forms("inflection_cell_active_imperfect_3pl"), ["έγραφαν", "γράφαν", "γράφανε"])
        XCTAssertEqual(table.cellsByID["inflection_cell_active_imperfect_3pl"]?.text, "έγραφαν / γράφαν / γράφανε")
        XCTAssertEqual(table.forms("inflection_cell_active_future_3pl"), ["θα γράψουν", "θα γράψουνε"])

        let imperative = try XCTUnwrap(table.section("active_imperative"))
        XCTAssertEqual(imperative.title, "Imperative")
        XCTAssertEqual(imperative.columnIDs, ["imperative_continuous", "imperative_simple"])
        XCTAssertEqual(imperative.columns.map(\.title), ["Continuous", "Simple"])
        XCTAssertEqual(imperative.rowIDs, ["2sg", "2pl"])
        XCTAssertEqual(table.forms("inflection_cell_active_imperative_continuous_2sg"), ["γράφε"])
        XCTAssertEqual(table.forms("inflection_cell_active_imperative_simple_2sg"), ["γράψε"])
        XCTAssertEqual(table.forms("inflection_cell_active_imperative_continuous_2pl"), ["γράφετε"])
        XCTAssertEqual(table.forms("inflection_cell_active_imperative_simple_2pl"), ["γράψτε", "γράφτε"])
    }

    /// γράφω, "All forms": the rest of the active (future continuous, perfect,
    /// pluperfect, future perfect, να-forms, participles, infinitive), then
    /// everything of the passive under a "Passive" heading.
    @MainActor
    func testAllFormsAddTheRestThenThePassive() async throws {
        let table = try await InflectionFixture.table("γράφω", pos: "verb")
        XCTAssertEqual(table.moreSections.map(\.id), [
            "active_more", "active_subjunctive", "active_nonfinite",
            "passive_indicative", "passive_imperative", "passive_more", "passive_subjunctive", "passive_nonfinite",
        ])
        let more = try XCTUnwrap(table.section("active_more"))
        XCTAssertEqual(more.columnIDs, ["future_continuous", "perfect", "pluperfect", "future_perfect"])
        XCTAssertEqual(table.forms("inflection_cell_active_future_continuous_1sg"), ["θα γράφω"])
        XCTAssertEqual(table.forms("inflection_cell_active_perfect_1sg"), ["έχω γράψει"])
        XCTAssertEqual(table.forms("inflection_cell_active_perfect_3pl"), ["έχουν γράψει"])
        XCTAssertEqual(table.forms("inflection_cell_active_pluperfect_2sg"), ["είχες γράψει"])
        XCTAssertEqual(table.forms("inflection_cell_active_future_perfect_1sg"), ["θα έχω γράψει"])

        let subjunctive = try XCTUnwrap(table.section("active_subjunctive"))
        XCTAssertEqual(subjunctive.title, "Subjunctive")
        XCTAssertEqual(subjunctive.columnIDs, ["subjunctive_continuous", "subjunctive_simple"])
        XCTAssertEqual(table.forms("inflection_cell_active_subjunctive_continuous_1sg"), ["να γράφω"])
        XCTAssertEqual(table.forms("inflection_cell_active_subjunctive_simple_1sg"), ["να γράψω"])

        let nonfinite = try XCTUnwrap(table.section("active_nonfinite"))
        XCTAssertEqual(nonfinite.rowIDs, ["present_participle", "perfect_participle", "infinitive"])
        XCTAssertFalse(nonfinite.showsColumnHeaders)
        XCTAssertEqual(table.forms("inflection_cell_active_present_participle"), ["γράφοντας"])
        XCTAssertEqual(table.forms("inflection_cell_active_perfect_participle"), ["έχοντας γράψει"])
        XCTAssertEqual(table.forms("inflection_cell_active_infinitive"), ["γράψει"])

        let passive = try XCTUnwrap(table.section("passive_indicative"))
        XCTAssertEqual(passive.heading, "Passive")
        XCTAssertEqual(passive.columnIDs, ["present", "imperfect", "aorist", "future"], "the main voice's shape")
        XCTAssertEqual(table.section("passive_more")?.columnIDs,
                       ["future_continuous", "perfect", "pluperfect", "future_perfect"])
        XCTAssertEqual(table.sections.filter { $0.heading != nil }.map(\.id), ["passive_indicative"])
        XCTAssertEqual(table.forms("inflection_cell_passive_present_1sg"), ["γράφομαι"])
        XCTAssertEqual(table.forms("inflection_cell_passive_imperfect_1sg"), ["γραφόμουν", "γραφόμουνα"])
        XCTAssertEqual(table.forms("inflection_cell_passive_aorist_1sg"), ["γράφτηκα", "γράφηκα"])
        XCTAssertEqual(table.forms("inflection_cell_passive_future_1sg"), ["θα γραφτώ", "θα γραφώ"])
        XCTAssertEqual(table.forms("inflection_cell_passive_perfect_1sg"), ["έχω γραφτεί", "έχω γραφεί"])
        XCTAssertEqual(table.forms("inflection_cell_passive_future_perfect_1sg"), ["θα έχω γραφτεί", "θα έχω γραφεί"])
        XCTAssertEqual(table.forms("inflection_cell_passive_imperative_simple_2sg"), ["γράψου"])
        XCTAssertEqual(table.forms("inflection_cell_passive_past_participle"), ["γραμμένος"])
        XCTAssertEqual(table.forms("inflection_cell_passive_perfect_participle"), ["έχοντας γραφτεί", "έχοντας γραφεί"])
        XCTAssertNil(table.forms("inflection_cell_passive_present_participle"), "γράφω has no passive present participle")
    }

    /// έρχομαι has no active present: its main voice is the passive, with
    /// no voice heading, and nothing of the active follows.
    @MainActor
    func testDeponentShowsThePassiveAsItsMainVoice() async throws {
        let table = try await InflectionFixture.table("έρχομαι", pos: "verb")
        XCTAssertEqual(table.mainSections.map(\.id), ["passive_indicative", "passive_imperative"])
        XCTAssertFalse(table.sections.contains { $0.id.hasPrefix("active_") })
        XCTAssertTrue(table.sections.allSatisfy { $0.heading == nil })
        XCTAssertEqual(table.forms("inflection_cell_passive_present_1sg"), ["έρχομαι"])
        XCTAssertEqual(table.forms("inflection_cell_passive_aorist_1sg"), ["ήρθα", "ήλθα"])
        XCTAssertEqual(table.forms("inflection_cell_passive_future_1sg"), ["θα έρθω", "θα έλθω"])
        XCTAssertEqual(table.forms("inflection_cell_passive_imperative_simple_2sg"), ["έλα"])
        XCTAssertEqual(table.forms("inflection_cell_passive_present_participle"), ["ερχόμενος"])
        XCTAssertEqual(table.cellsByID["inflection_cell_passive_aorist_1sg"]?.accessibilityText,
                       "aorist, εγώ, ήρθα / ήλθα", "the main voice is not named")
    }

    /// είμαι has no aorist, no dependent and only archaic imperatives: those
    /// columns and the imperative go; θα είμαι is under "All forms".
    @MainActor
    func testDefectiveVerbDropsEmptyColumns() async throws {
        let table = try await InflectionFixture.table("είμαι", pos: "verb")
        XCTAssertEqual(table.mainSections.map(\.id), ["active_indicative"])
        XCTAssertEqual(table.section("active_indicative")?.columnIDs, ["present", "imperfect"])
        XCTAssertEqual(table.forms("inflection_cell_active_present_3sg"), ["είναι"], "rare, dated έναι is hidden")
        XCTAssertEqual(table.forms("inflection_cell_active_imperfect_1sg"), ["ήμουν", "ήμουνα"])
        XCTAssertEqual(table.section("active_more")?.columnIDs, ["future_continuous"])
        XCTAssertEqual(table.forms("inflection_cell_active_future_continuous_1sg"), ["θα είμαι"])
        XCTAssertEqual(table.forms("inflection_cell_active_present_participle"), ["όντας"])
        XCTAssertNil(table.section("active_imperative"))
    }

    /// πρέπει has third persons only, so only αυτός and αυτοί rows remain;
    /// προκύπτει's periphrastic perfect is built for its persons only.
    @MainActor
    func testImpersonalVerbsKeepOnlyTheirPersons() async throws {
        let prepei = try await InflectionFixture.table("πρέπει", pos: "verb")
        XCTAssertEqual(prepei.section("active_indicative")?.rowIDs, ["3sg", "3pl"])
        XCTAssertEqual(prepei.section("active_indicative")?.columnIDs, ["present", "imperfect"])
        XCTAssertEqual(prepei.forms("inflection_cell_active_present_3sg"), ["πρέπει"])

        let prokyptei = try await InflectionFixture.table("προκύπτει", pos: "verb")
        XCTAssertEqual(prokyptei.section("active_more")?.rowIDs, ["3sg", "3pl"])
        XCTAssertEqual(prokyptei.forms("inflection_cell_active_perfect_3sg"), ["έχει προκύψει"])
        XCTAssertNil(prokyptei.forms("inflection_cell_active_perfect_1sg"), "no έχω προκύψει")
    }

    /// Wiktionary's present-only template tags its cells `present` without
    /// `indicative`: πρόκειται (rank 286 of the subtitle list), αφορά and
    /// οφείλω still show their present, the headword included.
    @MainActor
    func testPresentWithoutAMoodTagFillsThePresent() async throws {
        let prokeitai = try await InflectionFixture.table("πρόκειται", pos: "verb")
        XCTAssertEqual(prokeitai.section("active_indicative")?.columnIDs, ["present", "imperfect"])
        XCTAssertEqual(prokeitai.section("active_indicative")?.rowIDs, ["3sg"])
        XCTAssertEqual(prokeitai.forms("inflection_cell_active_present_3sg"), ["πρόκειται"])
        XCTAssertEqual(prokeitai.forms("inflection_cell_active_imperfect_3sg"), ["επρόκειτο"])

        let afora = try await InflectionFixture.table("αφορά", pos: "verb")
        XCTAssertEqual(afora.forms("inflection_cell_active_present_3pl"), ["αφορούν", "αφορούνε"])

        let ofeilo = try await InflectionFixture.table("οφείλω", pos: "verb")
        XCTAssertEqual(ofeilo.mainSections.first?.columnIDs, ["present", "imperfect"])
        XCTAssertEqual(ofeilo.forms("inflection_cell_active_present_1sg"), ["οφείλω"])
        XCTAssertEqual(ofeilo.forms("inflection_cell_active_present_1pl"), ["οφείλουμε"], "rare οφείλομε is hidden")
        XCTAssertEqual(ofeilo.forms("inflection_cell_passive_present_1sg"), ["οφείλομαι"])
        XCTAssertEqual(ofeilo.forms("inflection_cell_active_future_continuous_1sg"), ["θα οφείλω"])

        // Other moods keep out of the Present column.
        XCTAssertEqual(ParadigmLayout.verbSlot(of: ["present", "first-person", "singular"])?.slot,
                       .finite(.present, .firstSingular))
        XCTAssertNil(ParadigmLayout.verbSlot(of: ["present", "subjunctive", "first-person", "singular"]))
    }

    /// Every table of the shipped file, built from its lemma's own cells, is
    /// well formed: each cell id once, one cell per column in every row, no
    /// row or column without a form, and a default view. Every noun, name
    /// and adjective lemma with cells has a table, and every shown form of a
    /// table's plain slots is in it: the present (any person and voice), a
    /// noun's case and number, an adjective's case, number and gender.
    func testEveryShippedTableIsWellFormed() throws {
        let rows: [(id: Int64, word: String, pos: String, form: String, tags: String)] = try BundledDictionary(url: try PackFixtures.file(.ell)).read { db in
            try Row.fetchAll(db, sql: """
                SELECT l.id, l.word, l.pos, p.form, t.tags
                FROM lemma l JOIN paradigm p ON p.lemma_id = l.id JOIN tagset t ON t.id = p.tagset_id
                WHERE l.pos IN ('verb', 'noun', 'adj', 'name') ORDER BY l.id, p.ord
                """).map { ($0["id"], $0["word"], $0["pos"], $0["form"], $0["tags"]) }
        }
        var lemmas: [(word: String, pos: String, cells: [ParadigmCell])] = []
        var lastID: Int64?
        for row in rows {
            let cell = ParadigmCell(form: row.form, tags: row.tags)
            if row.id == lastID {
                lemmas[lemmas.count - 1].cells.append(cell)
            } else {
                lemmas.append((row.word, row.pos, [cell]))
                lastID = row.id
            }
        }
        XCTAssertGreaterThan(lemmas.count, 20_000, "the snapshot's verb, noun, adjective and name lemmas with cells")

        let hidden = ParadigmLayout.hiddenTags
        let persons = ["first-person", "second-person", "third-person"]
        let cases: Set<String> = ["nominative", "genitive", "accusative", "vocative"]
        let genders: Set<String> = ["masculine", "feminine", "neuter"]
        var tables: [String: Int] = [:], withCells: [String: Int] = [:]
        var failures: [String] = []
        for lemma in lemmas {
            withCells[lemma.pos, default: 0] += 1
            guard let table = ParadigmLayout.table(for: LemmaParadigm(word: lemma.word, pos: lemma.pos,
                                                                       cells: lemma.cells, isLinked: false),
                                                   locale: InflectionFixture.en) else { continue }
            tables[lemma.pos, default: 0] += 1
            var ids = Set<String>(), shown = Set<String>()
            if table.mainSections.isEmpty { failures.append("\(lemma.word): no default view") }
            for section in table.sections {
                for row in section.rows {
                    if row.cells.count != section.columns.count { failures.append("\(lemma.word) \(section.id) \(row.id): cells ≠ columns") }
                    if row.cells.allSatisfy(\.forms.isEmpty) { failures.append("\(lemma.word) \(section.id): empty row \(row.id)") }
                    for cell in row.cells {
                        if !ids.insert(cell.id).inserted { failures.append("\(lemma.word): \(cell.id) twice") }
                        if cell.forms.contains(where: \.isEmpty) { failures.append("\(lemma.word): empty form in \(cell.id)") }
                        let isPresent = cell.id.range(of: "_present_[123](sg|pl)$", options: .regularExpression) != nil
                        if lemma.pos != "verb" || isPresent { shown.formUnion(cell.forms) }
                    }
                }
                for (index, column) in section.columns.enumerated() where section.rows.allSatisfy({ $0.cells[index].forms.isEmpty }) {
                    failures.append("\(lemma.word) \(section.id): empty column \(column.id)")
                }
            }
            // The plain slots: each such form of the lemma is in its table.
            for cell in lemma.cells where cell.tags.isDisjoint(with: hidden) {
                let tags = cell.tags
                let expected: Bool
                switch lemma.pos {
                case "verb":
                    expected = tags.contains("present") && persons.filter(tags.contains).count == 1
                        && tags.contains("singular") != tags.contains("plural")
                        && tags.isDisjoint(with: ["imperative", "dependent", "imperfect", "participle", "subjunctive"])
                case "adj":
                    expected = tags.intersection(cases).count == 1 && tags.intersection(genders).count == 1
                        && tags.contains("singular") != tags.contains("plural")
                        && tags.isDisjoint(with: ["comparative", "superlative"])
                default:
                    expected = tags.intersection(cases).count == 1 && tags.contains("singular") != tags.contains("plural")
                        && tags.isDisjoint(with: ["comparative", "superlative"])
                }
                if expected, !shown.contains(cell.form) {
                    failures.append("\(lemma.word) (\(lemma.pos)): \(cell.form) [\(cell.tags.sorted().joined(separator: " "))] not shown")
                }
            }
        }
        XCTAssertEqual(failures.count, 0, failures.prefix(20).joined(separator: "\n"))
        for pos in ["noun", "name", "adj"] {
            XCTAssertEqual(tables[pos], withCells[pos], "every \(pos) lemma with cells has a table")
        }
        // Verbs without a table hold only cells no slot takes: participles
        // tagged as verbs (αγαπημένος), measured 340 of 2,204 (#141).
        XCTAssertGreaterThanOrEqual(tables["verb"] ?? 0, 1_860)
    }

    /// Hidden tags, variants, a single missing cell ("—"), a declined
    /// participle, an active "past participle" (template noise) and a verb
    /// with nothing for the default view.
    func testCellRulesOnMadeUpCells() throws {
        let cells = InflectionFixture.cells([
            ("λύνω", "active first-person imperfective indicative present singular"),
            ("λύνεις", "active imperfective indicative present second-person singular"),
            ("λύνομε", "active first-person imperfective indicative plural present rare"),
            ("έλυνα", "active first-person imperfect imperfective indicative singular"),
            ("έλυα", "active archaic first-person imperfect imperfective indicative singular"),
            ("ελύνατε", "active dated imperfect imperfective indicative plural second-person"),
            ("έλυσα", "active first-person indicative past perfective singular"),
            ("λύσα", "active first-person indicative past perfective singular"),
            ("λυμένος", "masculine nominative singular participle passive past"),
            ("λυμένη", "feminine nominative singular participle passive past"),
            ("λύσει", "active participle past"),
            ("λύσει", "active infinitive-aorist"),
        ])
        let table = try XCTUnwrap(ParadigmLayout.table(
            for: LemmaParadigm(word: "λύνω", pos: "verb", cells: cells, isLinked: false), locale: InflectionFixture.en))
        let main = try XCTUnwrap(table.section("active_indicative"))
        XCTAssertEqual(main.columnIDs, ["present", "imperfect", "aorist"], "no dependent: no Future column")
        XCTAssertEqual(main.rowIDs, ["1sg", "2sg"], "the plural rows hold only hidden cells")
        XCTAssertEqual(table.forms("inflection_cell_active_imperfect_1sg"), ["έλυνα"], "archaic έλυα is hidden")
        XCTAssertEqual(table.forms("inflection_cell_active_aorist_1sg"), ["έλυσα", "λύσα"])
        XCTAssertEqual(table.cellsByID["inflection_cell_active_aorist_1sg"]?.text, "έλυσα / λύσα")
        let missing = try XCTUnwrap(table.cellsByID["inflection_cell_active_aorist_2sg"])
        XCTAssertEqual(missing.forms, [])
        XCTAssertEqual(missing.text, "—")
        XCTAssertEqual(missing.accessibilityText, "aorist, εσύ, no form")
        XCTAssertEqual(table.forms("inflection_cell_passive_past_participle"), ["λυμένος"],
                       "a declined participle shows its nominative masculine singular")
        XCTAssertNil(table.forms("inflection_cell_active_past_participle"), "the active has no past participle")
        XCTAssertEqual(table.forms("inflection_cell_active_perfect_1sg"), ["έχω λύσει"])
        XCTAssertNil(table.forms("inflection_cell_active_perfect_1pl"), "no finite 1pl, so no έχουμε λύσει")

        let participleOnly = try XCTUnwrap(ParadigmLayout.table(
            for: LemmaParadigm(word: "χ", pos: "verb", cells: InflectionFixture.cells([
                ("χιονισμένος", "indeclinable participle passive perfect"),
            ]), isLinked: false), locale: InflectionFixture.en))
        XCTAssertEqual(participleOnly.moreSections, [], "nothing for the default view: everything shows at once")
        XCTAssertEqual(participleOnly.forms("inflection_cell_passive_past_participle"), ["χιονισμένος"])

        XCTAssertNil(ParadigmLayout.table(
            for: LemmaParadigm(word: "χ", pos: "verb", cells: InflectionFixture.cells([
                ("χ", "masculine nominative singular"), ("χα", "active rare first-person present indicative singular"),
            ]), isLinked: false), locale: InflectionFixture.en), "no slot filled: no table")
    }

    /// σπίτι: case × number, 4 × 2.
    @MainActor
    func testNounTableIsCaseByNumber() async throws {
        let table = try await InflectionFixture.table("σπίτι", pos: "noun")
        XCTAssertEqual(table.kind, .declension)
        XCTAssertEqual(table.sections.map(\.id), ["declension"])
        XCTAssertEqual(table.moreSections, [], "nouns have no \"All forms\"")
        let grid = try XCTUnwrap(table.section("declension"))
        XCTAssertEqual(grid.columnIDs, ["singular", "plural"])
        XCTAssertEqual(grid.columns.map(\.title), ["Singular", "Plural"])
        XCTAssertEqual(grid.rowIDs, ["nominative", "genitive", "accusative", "vocative"])
        XCTAssertEqual(grid.rows.compactMap(\.header?.title), ["Nominative", "Genitive", "Accusative", "Vocative"])
        XCTAssertEqual(table.forms("inflection_cell_genitive_singular"), ["σπιτιού"])
        XCTAssertEqual(table.forms("inflection_cell_genitive_plural"), ["σπιτιών"])
        XCTAssertEqual(table.forms("inflection_cell_vocative_plural"), ["σπίτια"])
    }

    /// καλός: case × gender, once for the singular and once for the plural.
    /// Degrees: ωραίος has both, γόνιμος keeps only them (no positive grid),
    /// κακός and παλιός have irregular and double forms.
    @MainActor
    func testAdjectiveTablesAndDegrees() async throws {
        let kalos = try await InflectionFixture.table("καλός", pos: "adjective")
        XCTAssertEqual(kalos.sections.map(\.id), ["singular", "plural"])
        for number in ["singular", "plural"] {
            let block = try XCTUnwrap(kalos.section(number))
            XCTAssertEqual(block.title, number.capitalized)
            XCTAssertEqual(block.columnIDs, ["masculine", "feminine", "neuter"])
            XCTAssertEqual(block.rowIDs, ["nominative", "genitive", "accusative", "vocative"])
        }
        XCTAssertEqual(kalos.forms("inflection_cell_nominative_singular_feminine"), ["καλή"])
        XCTAssertEqual(kalos.forms("inflection_cell_genitive_singular_masculine"), ["καλού"])
        XCTAssertEqual(kalos.forms("inflection_cell_accusative_plural_masculine"), ["καλούς"])
        XCTAssertEqual(kalos.forms("inflection_cell_vocative_singular_masculine"), ["καλέ"])

        let oraios = try await InflectionFixture.table("ωραίος", pos: "adjective")
        XCTAssertEqual(oraios.sections.map(\.id), ["singular", "plural", "degrees"])
        XCTAssertEqual(oraios.forms("inflection_cell_nominative_singular_masculine"), ["ωραίος"],
                       "degree cells never fill the positive grid")
        XCTAssertEqual(oraios.forms("inflection_cell_comparative"), ["ωραιότερος"])
        XCTAssertEqual(oraios.forms("inflection_cell_superlative"), ["ωραιότατος"])
        XCTAssertEqual(oraios.section("degrees")?.rows.compactMap(\.header?.title), ["Comparative", "Superlative"])

        let gonimos = try await InflectionFixture.table("γόνιμος", pos: "adjective")
        XCTAssertEqual(gonimos.sections.map(\.id), ["degrees"], "only its comparative tables: no positive grid")
        XCTAssertEqual(gonimos.forms("inflection_cell_comparative"), ["γονιμότερος"])
        XCTAssertEqual(gonimos.forms("inflection_cell_superlative"), ["γονιμότατος"])

        let kakos = try await InflectionFixture.table("κακός", pos: "adjective")
        XCTAssertEqual(kakos.forms("inflection_cell_comparative"), ["χειρότερος"])
        XCTAssertEqual(kakos.forms("inflection_cell_superlative"), ["κάκιστος", "χείριστος"])
        let palios = try await InflectionFixture.table("παλιός", pos: "adjective")
        XCTAssertEqual(palios.forms("inflection_cell_comparative"), ["παλαιότερος", "παλιότερος"])
        XCTAssertEqual(palios.forms("inflection_cell_superlative"), ["παλαιότατος"])
    }

    /// The degree of a cell tagged both ways is read from its ending.
    func testDegreeOfCellsTaggedBothWays() {
        func degree(_ form: String, _ tags: String) -> FormLabel? {
            ParadigmLayout.degree(of: ParadigmCell(form: form, tags: tags))
        }
        let both = "comparative masculine nominative singular superlative"
        XCTAssertEqual(degree("μεγαλύτερος", both), .comparative)
        XCTAssertEqual(degree("ΜΕΓΑΛΥΤΕΡΟΣ", both), .comparative)
        XCTAssertEqual(degree("μέγιστος", both), .superlative)
        XCTAssertEqual(degree("ακρότατος", both), .superlative)
        XCTAssertEqual(degree("κάκιστος", "masculine nominative singular superlative"), .superlative)
        XCTAssertEqual(degree("καλύτερος", "comparative masculine nominative singular"), .comparative)
        XCTAssertNil(degree("μεγαλύτερη", "comparative feminine nominative singular superlative"))
        XCTAssertNil(degree("μεγάλος", "masculine nominative singular"))
    }

    /// VoiceOver reads "column, row, form", Greek parts in Greek; the other
    /// voice names itself first; Arabic uses its comma.
    @MainActor
    func testCellAccessibilityLabel() async throws {
        let grafo = try await InflectionFixture.table("γράφω", pos: "verb")
        let aorist = try XCTUnwrap(grafo.cellsByID["inflection_cell_active_aorist_1sg"])
        XCTAssertEqual(aorist.accessibilityText, "aorist, εγώ, έγραψα")
        let greekRuns = aorist.accessibilityLabel.runs.filter { $0.languageIdentifier == "el" }
            .map { String(aorist.accessibilityLabel[$0.range].characters) }
        XCTAssertEqual(greekRuns, ["εγώ", "έγραψα"], "the pronoun and the form carry the el attribute")
        XCTAssertEqual(grafo.cellsByID["inflection_cell_active_imperative_simple_2pl"]?.accessibilityText,
                       "imperative, simple, εσείς, γράψτε / γράφτε")
        XCTAssertEqual(grafo.cellsByID["inflection_cell_passive_aorist_1sg"]?.accessibilityText,
                       "passive, aorist, εγώ, γράφτηκα / γράφηκα")
        XCTAssertEqual(grafo.cellsByID["inflection_cell_active_present_participle"]?.accessibilityText,
                       "present participle, γράφοντας")

        let spiti = try await InflectionFixture.table("σπίτι", pos: "noun")
        XCTAssertEqual(spiti.cellsByID["inflection_cell_genitive_singular"]?.accessibilityText, "genitive, singular, σπιτιού")
        let kalos = try await InflectionFixture.table("καλός", pos: "adjective")
        XCTAssertEqual(kalos.cellsByID["inflection_cell_genitive_singular_masculine"]?.accessibilityText,
                       "genitive, singular, masculine, καλού")

        let arabic = try await InflectionFixture.table("γράφω", pos: "verb", locale: Locale(identifier: "ar"))
        XCTAssertEqual(arabic.cellsByID["inflection_cell_active_aorist_1sg"]?.accessibilityText,
                       "الماضي البسيط\u{060C} εγώ\u{060C} έγραψα")
        let greek = try await InflectionFixture.table("γράφω", pos: "verb", locale: Locale(identifier: "el"))
        XCTAssertEqual(greek.cellsByID["inflection_cell_active_aorist_1sg"]?.accessibilityText, "αόριστος, εγώ, έγραψα")
        XCTAssertEqual(greek.section("active_indicative")?.columns.map(\.title),
                       ["Ενεστώτας", "Παρατατικός", "Αόριστος", "Μέλλοντας"])
    }
}

/// `InflectionLookup` and `DatabaseService.inflection(for:)`: which lemma's
/// table an entry shows.
final class InflectionLookupTests: XCTestCase {
    private var tempDir: URL!

    override func setUp() async throws {
        try await super.setUp()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        try await InflectionFixture.open(in: tempDir)
    }

    override func tearDown() async throws {
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    /// The labels keep the entry's own order (Kirill, 2026-10-31).
    func testEntryPOSLabelsMapToLemmaPOS() {
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: "verb"), ["verb"])
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: "adjective, noun"), ["adj", "noun"])
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: "adjective satellite, noun"), ["adj", "noun"])
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: "adjective, adjective satellite, noun"), ["adj", "noun"])
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: "noun, verb"), ["noun", "verb"])
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: "adverb, noun"), ["noun"])
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: "proper noun"), ["name"])
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: "adverb"), [])
        XCTAssertEqual(InflectionLookup.lemmaPOS(forEntryPOS: ""), [])
    }

    private typealias Lemma = InflectionLookup.Lemma

    /// κάλος (noun), καλός (adj), καλός (noun): each with a table named after it.
    private let kalos = [Lemma(id: 1, word: "κάλος", pos: "noun"), Lemma(id: 2, word: "καλός", pos: "adj"),
                         Lemma(id: 3, word: "καλός", pos: "noun")]

    /// `links`: the table each part of speech's single link gives (none when absent).
    private func choose(_ word: String, _ pos: String, tables: [Int64: String] = [1: "κάλος", 2: "adj", 3: "noun"],
                        candidates: [Lemma]? = nil, links: [String: String] = [:]) -> String? {
        InflectionLookup.choose(entryWord: word, entryPOS: pos, candidates: candidates ?? kalos,
                                table: { tables[$0.id] }, link: { links[$0] })
    }

    func testChooseTheExactWordThenANearOne() {
        XCTAssertEqual(choose("καλός", "adjective"), "adj")
        XCTAssertEqual(choose("κάλος", "noun"), "κάλος")
        XCTAssertEqual(choose("Καλός", "adjective"), "adj", "the only adjective that differs in case")
        XCTAssertEqual(choose("ΚΑΛΌΣ", "adjective"), "adj", "capitals with Σ for the final sigma")
        XCTAssertNil(choose("καλος", "adjective"), "an accent missing: another word")
        XCTAssertNil(choose("καλος", "noun"), "both nouns differ in accent: none")
        let alpha = [Lemma(id: 40, word: "άλφα", pos: "noun"), Lemma(id: 41, word: "Άλφα", pos: "noun")]
        XCTAssertNil(choose("ΆΛΦΑ", "noun", tables: [40: "άλφα", 41: "Άλφα"], candidates: alpha),
                     "two nouns differ only in case, both with a table: none")
        XCTAssertEqual(choose("ΆΛΦΑ", "noun", tables: [40: "άλφα"], candidates: alpha), "άλφα")
        XCTAssertNil(choose("καλός", "verb"))
        XCTAssertNil(choose("καλός", "adverb"), "a part of speech without tables")
        XCTAssertEqual(choose("καλός".decomposedStringWithCanonicalMapping, "noun"), "noun", "NFD equals NFC")
    }

    /// Kirill, 2026-11-01: a lemma spelled exactly as the headword beats one
    /// matched by folding, across the parts of speech the entry allows, the
    /// proper noun included for a noun label. A lemma whose accent differs
    /// never matches; one that differs only in case or a diaeresis still does
    /// when no lemma is spelled as the headword.
    @MainActor
    func testExactSpellingBeatsANearOrFoldedMatch() async throws {
        XCTAssertEqual(InflectionLookup.match("Κίνα", "Κίνα"), .exact)
        XCTAssertEqual(InflectionLookup.match("ταύρος", "Ταύρος"), .near)
        XCTAssertEqual(InflectionLookup.match("Μάιος", "Μάϊος"), .near, "a diaeresis is no other word")
        XCTAssertNil(InflectionLookup.match("σοφία", "Σόφια"), "the accent elsewhere: another word")
        XCTAssertNil(InflectionLookup.match("άλκη", "αλκή"))
        XCTAssertEqual(InflectionLookup.match("ελιά", "ΕΛΙΑ"), .near, "capitals are written without accents")
        XCTAssertEqual(InflectionLookup.match("ΛΑΟΣ", "Λάος"), .near)

        let kina = [Lemma(id: 50, word: "Κίνα", pos: "name"), Lemma(id: 51, word: "κίνα", pos: "noun"),
                    Lemma(id: 52, word: "κινά", pos: "noun")]
        XCTAssertEqual(choose("Κίνα", "noun", tables: [50: "Κίνα", 51: "κίνα"], candidates: kina), "Κίνα",
                       "the proper noun spelled as the headword beats the common noun in another case")
        XCTAssertEqual(choose("κίνα", "noun", tables: [50: "Κίνα", 51: "κίνα"], candidates: kina), "κίνα")
        let laos = [Lemma(id: 53, word: "Λάος", pos: "name"), Lemma(id: 54, word: "λαός", pos: "noun")]
        XCTAssertNil(choose("Λάος", "noun", tables: [54: "λαός"], candidates: laos),
                     "Λάος has no table, and λαός is another word")
        let tavros = [Lemma(id: 55, word: "Ταύρος", pos: "name"), Lemma(id: 56, word: "ταύρος", pos: "noun")]
        XCTAssertEqual(choose("Ταύρος", "noun", tables: [56: "ταύρος"], candidates: tavros), "ταύρος",
                       "the exact lemma has no table: the noun in another case stays")
        let sofia = [Lemma(id: 57, word: "Σοφία", pos: "name"), Lemma(id: 58, word: "σοφία", pos: "noun")]
        XCTAssertNil(choose("Σόφια", "noun", tables: [57: "Σοφία", 58: "σοφία"], candidates: sofia))
        XCTAssertNil(choose("Σόφια", "proper noun", tables: [57: "Σοφία", 58: "σοφία"], candidates: sofia))
        XCTAssertEqual(choose("Κίνα", "", tables: [50: "Κίνα", 51: "κίνα"], candidates: kina), "Κίνα",
                       "without a part of speech the exact lemma comes first too")
        XCTAssertEqual(choose("Κίνα", "adjective, noun", tables: [50: "Κίνα", 51: "κίνα"], candidates: kina), "Κίνα",
                       "an exact lemma of a later label beats a near one of an earlier label")

        // The real file: WordNet labels these proper nouns "noun".
        let exact: [(word: String, lemma: String)] = [("Κίνα", "Κίνα"), ("Γεωργία", "Γεωργία"), ("Άγκυρα", "Άγκυρα")]
        for item in exact {
            let paradigm = try await InflectionFixture.paradigm(item.word, pos: "noun", source: "wordnet-ell-eng")
            XCTAssertEqual(paradigm?.word, item.lemma, "\(item.word) shows its own proper noun's table")
            XCTAssertEqual(paradigm?.pos, "name")
        }
        for word in ["Λάος", "Σόφια", "Καμπανία", "Μαλάκια", "αλκή"] {
            let paradigm = try await InflectionFixture.paradigm(word, pos: "noun", source: "wordnet-ell-eng")
            XCTAssertNil(paradigm, "\(word) shows \(paradigm?.word ?? "")'s table")
        }
        let sofiaFD = try await InflectionFixture.paradigm("Σόφια", pos: "proper noun")
        XCTAssertNil(sofiaFD, "FreeDict's Σόφια (the city) is not Σοφία")
        for (word, lemma) in [("Ταύρος", "ταύρος"), ("Ελληνικά", "ελληνικά")] {
            let paradigm = try await InflectionFixture.paradigm(word, pos: "noun", source: "wordnet-ell-eng")
            XCTAssertEqual(paradigm?.word, lemma, "\(word): a match in another case stays")
        }
    }

    /// Kirill, 2026-11-01: a form link of a noun, adjective or proper noun
    /// counts only when the headword is a nominative of the linked lemma: καφέ
    /// (café) is the genitive of καφές, μικρό the accusative of the noun μικρός.
    /// Verbs link as before; a link from the word's own page holds no form.
    @MainActor
    func testFormLinkNeedsANominative() async throws {
        let kafes = [ParadigmCell(form: "καφές", tags: "nominative singular"),
                     ParadigmCell(form: "καφέ", tags: "genitive singular"),
                     ParadigmCell(form: "καφέ", tags: "accusative singular"),
                     ParadigmCell(form: "καφέδες", tags: "nominative plural")]
        XCTAssertFalse(InflectionLookup.linkFits(word: "καφέ", pos: "noun", cells: kafes))
        XCTAssertTrue(InflectionLookup.linkFits(word: "καφέδες", pos: "noun", cells: kafes))
        XCTAssertTrue(InflectionLookup.linkFits(word: "καφέ", pos: "verb", cells: kafes), "verbs link as before")
        XCTAssertTrue(InflectionLookup.linkFits(word: "μέρα", pos: "noun",
                                                cells: [ParadigmCell(form: "ημέρα", tags: "nominative singular")]),
                      "μέρα is no form of ημέρα's table: its own page links it")
        XCTAssertFalse(InflectionLookup.linkFits(word: "μετρό", pos: "noun",
                                                 cells: [ParadigmCell(form: "μέτρο", tags: "nominative singular")]),
                       "a fold collision still never links")

        let lost: [(word: String, source: String)] = [
            ("μικρό", "wordnet-ell-eng"), ("καφέ", "freedict-ell-eng"), ("καφέ", "wordnet-ell-eng"),
            ("κολιέ", "freedict-ell-eng"), ("πόλο", "freedict-ell-eng"), ("χημικό", "wordnet-ell-eng"),
            ("σάκε", "freedict-ell-eng"), ("χούμους", "freedict-ell-eng"),
            // Right links that go with them: oblique headwords.
            ("κόμματος", "freedict-ell-eng"), ("κτιρίων", "wordnet-ell-eng"), ("περίμετρο", "freedict-ell-eng"),
            ("τίγρης", "wordnet-ell-eng"),
        ]
        for item in lost {
            let paradigm = try await InflectionFixture.paradigm(item.word, pos: "noun", source: item.source)
            XCTAssertNil(paradigm, "\(item.word) shows \(paradigm?.word ?? "")'s table")
        }
        let kept: [(word: String, pos: String, lemma: String)] = [
            ("πράγματα", "noun", "πράγμα"), ("άνθρωποι", "noun", "άνθρωπος"), ("μέρα", "noun", "ημέρα"),
            ("αρέσει", "verb", "αρέσω"), ("γίνεται", "verb", "γίνομαι"),
        ]
        for item in kept {
            let paradigm = try await InflectionFixture.paradigm(item.word, pos: item.pos, source: "wordnet-ell-eng")
            XCTAssertEqual(paradigm?.word, item.lemma, "\(item.word) keeps \(item.lemma)'s table")
        }
    }

    /// Kirill, 2026-10-31: the first label of the entry's own `pos` whose
    /// lemma has a table.
    func testLabelsAreTriedInTheEntrysOrder() {
        XCTAssertEqual(choose("καλός", "adjective, noun"), "adj", "FreeDict's καλός: the adjective first")
        XCTAssertEqual(choose("καλός", "noun, adjective"), "noun")
        XCTAssertEqual(choose("καλός", "noun, adjective", tables: [1: "κάλος", 2: "adj"]), "adj",
                       "a label whose lemma has no table gives way to the next")
        XCTAssertEqual(choose("καλός", "adverb, adjective"), "adj", "labels without tables are skipped")
    }

    /// Kirill, 2026-10-31: an entry without a `pos` shows the table when
    /// exactly one lemma of any part of speech has one.
    func testEntryWithoutPartOfSpeech() {
        XCTAssertNil(choose("καλός", ""), "the adjective and the noun both have a table: none")
        XCTAssertEqual(choose("καλός", "", tables: [2: "adj"]), "adj", "one table: shown")
        XCTAssertEqual(choose("καλός", " ", tables: [3: "noun"]), "noun")
        XCTAssertNil(choose("καλός", "", tables: [:]), "no table")
        XCTAssertNil(choose("καλος", "", tables: [1: "κάλος", 3: "noun"]),
                     "two folded nouns with tables: none")
        let shared = [Lemma(id: 4, word: "πάω", pos: "verb"), Lemma(id: 5, word: "πάω", pos: "noun")]
        XCTAssertEqual(choose("πάω", "", tables: [4: "πηγαίνω", 5: "πηγαίνω"], candidates: shared), "πηγαίνω",
                       "one table reached twice counts once")
    }

    /// Kirill, 2026-10-31: a word Wiktionary has only as a form or an
    /// alternative page (μέρα of ημέρα, αγαπώ of αγαπάω) shows the table of
    /// the one lemma of its part of speech it belongs to.
    func testWordWithoutALemmaFollowsItsSingleLink() {
        XCTAssertEqual(choose("μέρα", "noun", candidates: [], links: ["noun": "ημέρα"]), "ημέρα")
        XCTAssertEqual(choose("αγαπώ", "verb", candidates: [], links: ["verb": "αγαπάω"]), "αγαπάω")
        XCTAssertNil(choose("φράκτης", "noun", candidates: [], links: [:]),
                     "several lemmas, so the link gives none: no table")
        XCTAssertEqual(choose("ζητώ", "verb", candidates: [Lemma(id: 7, word: "ζήτω", pos: "intj")],
                              links: ["verb": "ζητάω"]), "ζητάω", "a lemma of another part of speech does not count")
        XCTAssertEqual(choose("x", "adverb, verb", candidates: [], links: ["verb": "linked"]), "linked")
        XCTAssertEqual(choose("καλός", "noun", links: ["noun": "linked"]), "noun",
                       "a word with a lemma of its own never takes a link")
        XCTAssertNil(choose("καλός", "noun", tables: [1: "κάλος"], links: ["noun": "linked"]),
                     "its lemma has no table: the per-lemma link is the table closure's, not this one")
        XCTAssertNil(choose("γρήγορα", "adverb", candidates: [], links: ["noun": "linked", "verb": "linked"]),
                     "an adverb has no table")
        XCTAssertNil(choose("μέρα", "", candidates: [], links: ["noun": "ημέρα"]),
                     "an entry without a part of speech follows no link")
    }

    /// Kirill, 2026-10-31: WordNet labels proper nouns "noun" (Αθήνα): a noun
    /// entry with no noun lemma takes the proper-noun lemma, before any link.
    func testNounFallsBackToTheProperNoun() {
        let athina = [Lemma(id: 10, word: "Αθήνα", pos: "name"), Lemma(id: 11, word: "Αθηνά", pos: "name")]
        XCTAssertEqual(choose("Αθήνα", "noun", tables: [10: "Αθήνα", 11: "Αθηνά"], candidates: athina), "Αθήνα",
                       "the exact name, not the folded Αθηνά")
        XCTAssertEqual(choose("Αθήνα", "proper noun", tables: [10: "Αθήνα", 11: "Αθηνά"], candidates: athina), "Αθήνα")
        let cairo = [Lemma(id: 12, word: "Κάιρο", pos: "name")]
        XCTAssertEqual(choose("Κάιρο", "noun", tables: [12: "Κάιρο"], candidates: cairo, links: ["noun": "καιρός"]),
                       "Κάιρο", "the proper noun comes before a link of the folded word")
        XCTAssertEqual(choose("Κάιρο", "noun", tables: [:], candidates: cairo, links: ["noun": "καιρός"]),
                       "καιρός", "a proper noun without a table gives way to the link")
        XCTAssertNil(choose("Κάιρο", "verb", tables: [12: "Κάιρο"], candidates: cairo),
                     "only a noun label falls back to the proper noun")
        XCTAssertNil(choose("Αθηνα", "noun", tables: [10: "Αθήνα", 11: "Αθηνά"], candidates: athina),
                     "two names match only by folded word: no table")
    }

    /// A proper noun stands only for a capitalized word or its own spelling:
    /// the lowercase common noun ρώμη (vigour) does not show Ρώμη (Rome).
    @MainActor
    func testProperNounNeedsACapitalOrItsOwnSpelling() async throws {
        let romi = [Lemma(id: 20, word: "Ρώμη", pos: "name")]
        XCTAssertNil(choose("ρώμη", "noun", tables: [20: "Ρώμη"], candidates: romi))
        XCTAssertEqual(choose("Ρώμη", "noun", tables: [20: "Ρώμη"], candidates: romi), "Ρώμη")
        XCTAssertEqual(choose("Μάϊος", "noun", tables: [21: "Μάιος"], candidates: [Lemma(id: 21, word: "Μάιος", pos: "name")]),
                       "Μάιος", "a capitalized word takes the proper noun it folds to")
        XCTAssertEqual(choose("τιτάνας", "noun", tables: [22: "τιτάνας"], candidates: [Lemma(id: 22, word: "τιτάνας", pos: "name")]),
                       "τιτάνας", "a lowercase proper noun of the same spelling")

        // The real file: WordNet and FreeDict label these common nouns
        // "noun"; their capitalized namesakes are a city, a town and a place.
        for (word, source) in [("ρώμη", "wordnet-ell-eng"), ("παραμυθία", "wordnet-ell-eng"), ("κάμινος", "wordnet-ell-eng"),
                               ("λίβανος", "freedict-ell-eng"), ("σαρία", "freedict-ell-eng")] {
            let paradigm = try await InflectionFixture.paradigm(word, pos: "noun", source: source)
            XCTAssertNil(paradigm, "\(word) shows \(paradigm?.word ?? "")'s table")
        }
        let maios = try await InflectionFixture.paradigm("Μάϊος", pos: "noun", source: "wordnet-ell-eng")
        XCTAssertEqual(maios?.word, "Μάιος")
        XCTAssertEqual(maios?.pos, "name")
    }

    /// A link must hold the word itself or come from the word's own page: a
    /// table that only holds another word folded alike is not the word's.
    /// Both the table-less lemma (μετρό, ναζί) and the word without a lemma
    /// (πορνό, συνεδρία, Ινδία) showed such a table before.
    @MainActor
    func testLinksNeverFollowAFoldCollision() async throws {
        XCTAssertTrue(InflectionLookup.linkFits(word: "αγαπώ", forms: ["αγαπάω", "αγαπώ", "αγάπησα"]))
        XCTAssertTrue(InflectionLookup.linkFits(word: "μέρα", forms: ["ημέρα", "ημέρας", "ημέρες"]),
                      "no form folds like μέρα: the link comes from its own page")
        XCTAssertFalse(InflectionLookup.linkFits(word: "μετρό", forms: ["μέτρο", "μέτρου", "μέτρα"]))
        XCTAssertFalse(InflectionLookup.linkFits(word: "Ινδία", forms: ["ίνδιο", "ινδίου", "ίνδια"]))

        let collisions: [(word: String, pos: String, source: String)] = [
            ("μετρό", "noun", "freedict-ell-eng"), ("ναζί", "noun", "freedict-ell-eng"),
            ("πορνό", "noun", "freedict-ell-eng"), ("συνεδρία", "noun", "freedict-ell-eng"),
            ("μελανιά", "noun", "freedict-ell-eng"), ("Ινδία", "noun", "wordnet-ell-eng"),
            ("εξαιρώ", "verb", "freedict-ell-eng"),
        ]
        for item in collisions {
            let paradigm = try await InflectionFixture.paradigm(item.word, pos: item.pos, source: item.source)
            XCTAssertNil(paradigm, "\(item.word) shows \(paradigm?.word ?? "")'s table")
        }
        let kept: [(word: String, pos: String, source: String, lemma: String)] = [
            ("μέρα", "noun", "freedict-ell-eng", "ημέρα"), ("αγαπώ", "verb", "wordnet-ell-eng", "αγαπάω"),
            ("πάω", "verb", "wordnet-ell-eng", "πηγαίνω"), ("παιδιά", "noun", "freedict-ell-eng", "παιδί"),
        ]
        for item in kept {
            let paradigm = try await InflectionFixture.paradigm(item.word, pos: item.pos, source: item.source)
            XCTAssertEqual(paradigm?.word, item.lemma, "\(item.word) keeps \(item.lemma)'s table")
        }
    }

    func testChooseLink() {
        let a = InflectionLookup.Lemma(id: 1, word: "παιδί", pos: "noun")
        let b = InflectionLookup.Lemma(id: 2, word: "παΐδι", pos: "noun")
        XCTAssertEqual(InflectionLookup.chooseLink([.init(lemma: a, holdsHeadword: false)]), a)
        XCTAssertEqual(InflectionLookup.chooseLink([.init(lemma: a, holdsHeadword: true),
                                                    .init(lemma: b, holdsHeadword: false)]), a)
        XCTAssertNil(InflectionLookup.chooseLink([.init(lemma: a, holdsHeadword: false),
                                                  .init(lemma: b, holdsHeadword: false)]))
        XCTAssertNil(InflectionLookup.chooseLink([]))
    }

    /// The real file: Greek entries find their lemma's table; πάω shows
    /// πηγαίνω's; other sources, adverbs and entries without a part of
    /// speech get none.
    @MainActor
    func testInflectionForEntries() async throws {
        let grafo = try await InflectionFixture.paradigm("γράφω", pos: "verb")
        XCTAssertEqual(grafo?.word, "γράφω")
        XCTAssertEqual(grafo?.pos, "verb")
        XCTAssertEqual(grafo?.isLinked, false)
        XCTAssertEqual(grafo?.cells.first, ParadigmCell(form: "γράφω",
                                                        tags: "active first-person imperfective indicative present singular"))
        let wn = try await InflectionFixture.paradigm("γράφω", pos: "verb", source: "wordnet-ell-eng")
        XCTAssertEqual(wn?.word, "γράφω")

        // The real labels: WordNet's καλός is "adjective", FreeDict's
        // "adjective, noun" (good; darling). The entry's own order decides.
        let kalosWN = try await InflectionFixture.paradigm("καλός", pos: "adjective", source: "wordnet-ell-eng")
        XCTAssertEqual(kalosWN?.pos, "adj")
        let kalosFD = try await InflectionFixture.paradigm("καλός", pos: "adjective, noun")
        XCTAssertEqual(kalosFD?.pos, "adj", "FreeDict's καλός shows the adjective's table")
        let kalosNoun = try await InflectionFixture.paradigm("καλός", pos: "noun, adjective")
        XCTAssertEqual(kalosNoun?.pos, "noun")

        // Without a part of speech: άδωρος has one table (adj), καλός two.
        let adoros = try await InflectionFixture.paradigm("άδωρος", pos: "")
        XCTAssertEqual(adoros?.word, "άδωρος")
        XCTAssertEqual(adoros?.pos, "adj")
        let kalosNoPOS = try await InflectionFixture.paradigm("καλός", pos: "")
        XCTAssertNil(kalosNoPOS, "καλός has an adjective and a noun table: none")

        // Kirill, 2026-10-31: form and alternative pages follow their single
        // link; WordNet's "noun" Αθήνα takes the proper noun.
        let linked: [(word: String, pos: String, source: String, lemma: String)] = [
            ("μέρα", "noun", "freedict-ell-eng", "ημέρα"), ("βδομάδα", "noun", "freedict-ell-eng", "εβδομάδα"),
            ("αγαπώ", "verb", "wordnet-ell-eng", "αγαπάω"), ("αρέσει", "verb", "wordnet-ell-eng", "αρέσω"),
            ("ζητώ", "verb", "wordnet-ell-eng", "ζητάω"), ("γίνεται", "verb", "wordnet-ell-eng", "γίνομαι"),
        ]
        for item in linked {
            let paradigm = try await InflectionFixture.paradigm(item.word, pos: item.pos, source: item.source)
            XCTAssertEqual(paradigm?.word, item.lemma, "\(item.word) shows \(item.lemma)'s table")
            XCTAssertEqual(paradigm?.isLinked, true, "\(item.word): the title names \(item.lemma)")
        }
        for (word, cells) in [("Αθήνα", 4), ("Αγγλία", 4), ("Απρίλιος", 4)] {
            let paradigm = try await InflectionFixture.paradigm(word, pos: "noun", source: "wordnet-ell-eng")
            XCTAssertEqual(paradigm?.word, word, "WordNet's noun \(word) shows its proper-noun table")
            XCTAssertEqual(paradigm?.pos, "name")
            XCTAssertEqual(paradigm?.isLinked, false)
            XCTAssertEqual(paradigm?.cells.count, cells)
        }
        // #143: φράκτης folds like a form of φρακτή too, but only φράχτης's
        // link page is spelled φράκτης (`form_link`); the ambiguity rule is
        // `testChooseLink`'s.
        let fraktis = try await InflectionFixture.paradigm("φράκτης", pos: "noun")
        XCTAssertEqual(fraktis?.word, "φράχτης", "φράκτης is the alternative form of φράχτης")
        XCTAssertEqual(fraktis?.isLinked, true)

        let paoParadigm = try await InflectionFixture.paradigm("πάω", pos: "verb")
        let pao = try XCTUnwrap(paoParadigm)
        XCTAssertEqual(pao.word, "πηγαίνω")
        XCTAssertTrue(pao.isLinked)
        let paoTable = try XCTUnwrap(ParadigmLayout.table(for: pao, locale: InflectionFixture.en))
        XCTAssertEqual(paoTable.linkedLemma, "πηγαίνω")
        // παιδιά (a table-less noun lemma) is a form of παιδί and of παΐδι;
        // only παιδί's table holds παιδιά itself.
        let paidia = try await InflectionFixture.paradigm("παιδιά", pos: "noun")
        XCTAssertEqual(paidia?.word, "παιδί")
        XCTAssertEqual(paidia?.isLinked, true)

        let none: [(String, String, String)] = [
            ("γράφω", "verb", "freedict-eng-ell"), ("write", "verb", "wordnet"),
            ("γρήγορα", "adverb", "freedict-ell-eng"),
            ("σπίτι", "verb", "freedict-ell-eng"),
        ]
        for (word, pos, source) in none {
            let paradigm = try await InflectionFixture.paradigm(word, pos: pos, source: source)
            XCTAssertNil(paradigm, "\(word) (\(pos), \(source)) has no table")
        }
    }

    /// Every table read goes through an index or a primary-key prefix.
    func testInflectionQueriesUseIndexes() throws {
        let queue = try DatabaseQueue()
        try queue.writeWithoutTransaction { db in
            try db.execute(sql: "ATTACH DATABASE ? AS dict",
                           arguments: [DatabaseService.dictionaryURI(try TestDictionary.bundledURL())])
            // #237: the forms tables are in the Greek pack.
            try db.execute(sql: "ATTACH DATABASE ? AS ell",
                           arguments: [DatabaseService.dictionaryURI(try PackFixtures.file(.ell))])
        }
        let plans = try queue.read { db in
            try [DatabaseService.lemmaCandidatesSQL, DatabaseService.paradigmSQL, DatabaseService.linkedLemmasSQL]
                .map { sql in
                    try Row.fetchAll(db, sql: "EXPLAIN QUERY PLAN " + sql,
                                     arguments: StatementArguments(Array(repeating: "x", count: sql.filter { $0 == "?" }.count)))
                        .map { $0["detail"] as String }
                }
        }
        for plan in plans {
            XCTAssertFalse(plan.isEmpty)
            for step in plan {
                XCTAssertFalse(step.hasPrefix("SCAN"), "no table scan: \(plan)")
            }
        }
    }

    /// The view model reads a table for Greek entries only.
    @MainActor
    func testDefinitionViewModelLoadsTheTable() async throws {
        let greek = DefinitionViewModel(entry: InflectionFixture.entry("γράφω", pos: "verb"), hasVoice: { _ in false })
        await greek.loadInflection(locale: InflectionFixture.en)
        XCTAssertEqual(greek.inflectionTable?.kind, .conjugation)

        let noPOS = DefinitionViewModel(entry: InflectionFixture.entry("άδωρος", pos: ""), hasVoice: { _ in false })
        await noPOS.loadInflection(locale: InflectionFixture.en)
        XCTAssertEqual(noPOS.inflectionTable?.kind, .declension, "άδωρος (no part of speech) shows its table")

        let english = DefinitionViewModel(entry: InflectionFixture.entry("write", pos: "verb", source: "wordnet"),
                                          hasVoice: { _ in false })
        await english.loadInflection(locale: InflectionFixture.en)
        XCTAssertNil(english.inflectionTable)
    }
}

/// Every label of the tables resolves in the five UI languages.
final class FormLabelTests: XCTestCase {
    private static let codes = ["en", "ru", "es", "ar", "el"]
    private static let otherKeys = [
        "forms.section.conjugation", "forms.section.declension", "forms.section.nonfinite",
        "forms.button.allForms", "forms.button.mainForms", "forms.source", "forms.a11y.noForm",
    ]

    func testEveryLabelResolvesInEveryLanguage() {
        for code in Self.codes {
            let locale = Locale(identifier: code)
            var seen: [String: FormLabel] = [:]
            for label in FormLabel.allCases {
                let text = label.text(locale: locale)
                XCTAssertNotEqual(text, label.key, "\(code): \(label.key) is missing")
                XCTAssertFalse(text.isEmpty)
                if let other = seen[text] {
                    XCTFail("\(code): \(label) and \(other) read the same, '\(text)'")
                }
                seen[text] = label
            }
            for key in Self.otherKeys {
                XCTAssertNotEqual(SettingsViewModel.localizedString(key, locale: locale), key, "\(code): \(key)")
            }
        }
        XCTAssertEqual(FormLabel.aorist.text(locale: Locale(identifier: "ru")), "аорист")
        XCTAssertEqual(FormLabel.genitive.text(locale: Locale(identifier: "es")), "genitivo")
        XCTAssertEqual(FormLabel.aorist.text(locale: Locale(identifier: "el")), "αόριστος")
    }

    func testTitlesCapitalizeOnlyTheFirstLetter() {
        XCTAssertEqual(FormLabel.futureContinuous.title(locale: Locale(identifier: "en")), "Future continuous")
        XCTAssertEqual(FormLabel.aorist.title(locale: Locale(identifier: "el")), "Αόριστος")
        XCTAssertEqual(FormLabel.passive.title(locale: Locale(identifier: "ru")), "Страдательный залог")
        XCTAssertEqual(FormLabel.genitive.title(locale: Locale(identifier: "ar")), "المجرور")
        XCTAssertEqual(FormLabel.singular.title(locale: Locale(identifier: "ru")), "Ед. ч.")
    }
}

// MARK: - Issue #145: quick dictionary switching (0146-quick-switch.md)

/// The nine bundled sources on a test dictionary file. Each has one row that
/// "apple" finds (headword or definition) plus distinct filler rows, so the
/// `en` default order is fixed: eng, eng-rus, eng-spa, arb-eng, ell-eng.
private enum QuickSwitchFixture {
    static let pairIDs = ["eng", "eng-rus", "eng-spa", "arb-eng", "ell-eng"]
    static let sources = DictAppTests.allBundledSourceIDs
    static let greekSources = Set(DictAppTests.greekSourceIDs)

    static var rows: [TestDictionary.Row] {
        let apples: [TestDictionary.Row] = [
            .init(word: "apple", definition: "a round fruit", source: "wordnet"),
            .init(word: "яблоко", definition: "apple", source: "openrussian"),
            .init(word: "apple", definition: "manzana", source: "freedict-eng-spa"),
            .init(word: "manzana", definition: "apple", source: "wordnet-spa-eng"),
            .init(word: "تفاحة", definition: "apple", source: "wordnet-arb-eng"),
            .init(word: "μήλο", definition: "apple", source: "freedict-ell-eng"),
            .init(word: "μηλιά", definition: "apple tree", source: "wordnet-ell-eng"),
            .init(word: "apple", definition: "μήλο", source: "freedict-eng-ell"),
            .init(word: "apple", definition: "μήλο, φρούτο", source: "wordnet-eng-ell"),
        ]
        return apples + sources.enumerated().flatMap { index, source in
            TestDictionary.rows(source: source, count: 20 - index)
        }
    }

    /// A fresh user database in `directory` with the fixture attached.
    static func open(in directory: URL) async throws -> TestDictionaryFixture {
        await DictAppTests.waitForHostAppLaunch()
        let dictionary = TestDictionaryFixture(directory: directory)
        try await dictionary.add(rows)
        return dictionary
    }

    /// A selection over its own in-memory store, with the UI language pinned.
    @MainActor
    static func makeSelection(languageCode: String = "en", storedOrder: [String]? = nil,
                              storedEnabled: Set<String>? = nil)
        -> (selection: DictionarySelection, settings: SettingsService, store: InMemoryKeyValueStore,
            localization: LocalizationManager) {
        let store = InMemoryKeyValueStore()
        let settings = SettingsService(store: store)
        settings.selectedUILanguageCode = languageCode
        settings.dictionaryOrder = storedOrder
        settings.enabledSources = storedEnabled
        let localization = LocalizationManager(settingsService: settings, bundle: .main)
        return (DictionarySelection(settings: settings, localization: localization), settings, store, localization)
    }

    static func writes(_ store: InMemoryKeyValueStore, of key: String, since start: Int) -> Int {
        store.writeLog.dropFirst(start).filter { $0 == key }.count
    }
}

/// `DictionarySelection`: the pair list shared by the Search chips and the
/// Dictionary Order screen, one write per change, store before publish.
final class DictionarySelectionTests: XCTestCase {
    private var tempDir: URL!
    private var dictionary: TestDictionaryFixture!
    private var cancellables: Set<AnyCancellable> = []

    override func setUp() async throws {
        try await super.setUp()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        dictionary = try await QuickSwitchFixture.open(in: tempDir)
    }

    override func tearDown() async throws {
        cancellables.removeAll()
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    /// A stored order gives the pair order; with none, the `en` default is
    /// derived and stored once. `loadIfNeeded` loads only the first time.
    @MainActor
    func testPairsFollowStoredOrder() async throws {
        let stored = DictAppTests.greekSourceIDs + ["wordnet-arb-eng", "freedict-eng-spa", "wordnet-spa-eng",
                                                    "openrussian", "wordnet"]
        let (selection, settings, store, _) = QuickSwitchFixture.makeSelection(storedOrder: stored)
        XCTAssertFalse(selection.isLoaded)
        XCTAssertFalse(selection.noneEnabled, "no pairs yet: not 'none enabled'")
        let start = store.writeLog.count

        await selection.loadIfNeeded()

        XCTAssertTrue(selection.isLoaded)
        XCTAssertEqual(selection.pairs.map(\.id), ["ell-eng", "arb-eng", "eng-spa", "eng-rus", "eng"])
        XCTAssertEqual(selection.pairs.map(\.displayName),
                       ["Greek – English", "Arabic – English", "Spanish – English", "Russian – English", "English"],
                       "chip labels are the Dictionary Order titles")
        XCTAssertTrue(selection.allEnabled)
        XCTAssertEqual(settings.dictionaryOrder, stored, "an already grouped order is kept")
        XCTAssertEqual(store.writeLog.count, start, "a load of a valid stored state writes nothing")

        // Loads once: a later change to the store is not picked up by
        // `loadIfNeeded`, only by `load`.
        settings.dictionaryOrder = QuickSwitchFixture.sources
        await selection.loadIfNeeded()
        XCTAssertEqual(selection.pairs.first?.id, "ell-eng")
        await selection.load()
        XCTAssertEqual(selection.pairs.map(\.id), QuickSwitchFixture.pairIDs)

        // No stored order: the #74 `en` default, stored on the first load.
        let (fresh, freshSettings, _, _) = QuickSwitchFixture.makeSelection()
        await fresh.load()
        XCTAssertEqual(fresh.pairs.map(\.id), QuickSwitchFixture.pairIDs)
        XCTAssertEqual(freshSettings.dictionaryOrder.map(DictionaryGrouping.sourceGroups(order:))?.count, 5)
        XCTAssertNil(freshSettings.enabledSources, "a load never materialises 'everything on'")
    }

    /// `move` reorders the pairs and stores the flattened order in one write,
    /// before it publishes. A no-op move writes and publishes nothing.
    @MainActor
    func testMoveReordersPairsAndStoredOrder() async throws {
        let (selection, settings, store, _) = QuickSwitchFixture.makeSelection()
        await selection.load()
        XCTAssertEqual(selection.pairs.map(\.id), QuickSwitchFixture.pairIDs, "precondition")
        var storedAtPublish: [[String]?] = []
        selection.$pairs.dropFirst()
            .sink { _ in storedAtPublish.append(settings.dictionaryOrder) }
            .store(in: &cancellables)
        let start = store.writeLog.count

        selection.move(from: IndexSet(integer: 4), to: 0)   // Greek to the top

        XCTAssertEqual(selection.pairs.map(\.id), ["ell-eng", "eng", "eng-rus", "eng-spa", "arb-eng"])
        let expectedOrder = selection.pairs.flatMap(\.pair.sourceIDs)
        XCTAssertEqual(settings.dictionaryOrder, expectedOrder)
        XCTAssertEqual(Array(expectedOrder.prefix(4)).sorted(), DictAppTests.greekSourceIDs.sorted(),
                       "the four Greek sources move as one slot")
        XCTAssertEqual(Array(store.writeLog.dropFirst(start)), ["dictionary_order"], "one write")
        XCTAssertEqual(storedAtPublish, [expectedOrder], "the store holds the new order when pairs publish")

        selection.move(from: IndexSet(integer: 2), to: 2)
        XCTAssertEqual(Array(store.writeLog.dropFirst(start)), ["dictionary_order"], "a no-op move writes nothing")
        XCTAssertEqual(storedAtPublish.count, 1, "and publishes nothing")

        // A reload reads the moved order back.
        await selection.load()
        XCTAssertEqual(selection.pairs.map(\.id), ["ell-eng", "eng", "eng-rus", "eng-spa", "arb-eng"])
    }

    /// One setting: a Settings switch changes the chips' list, a chip
    /// changes the Settings list, one store write each.
    @MainActor
    func testSettingsAndSearchShareOneState() async throws {
        let (selection, settings, store, localization) = QuickSwitchFixture.makeSelection()
        let vm = SettingsViewModel(settingsService: settings, localization: localization, selection: selection)
        await vm.loadDictionaries()
        XCTAssertEqual(vm.dictionaries.map(\.id), QuickSwitchFixture.pairIDs)
        var enabledAtPublish: [Set<String>?] = []
        selection.$pairs.dropFirst()
            .sink { _ in enabledAtPublish.append(settings.enabledSources) }
            .store(in: &cancellables)
        var start = store.writeLog.count

        // Settings switch → chips.
        vm.togglePair(id: "eng-rus")
        XCTAssertEqual(selection.pairs.first { $0.id == "eng-rus" }?.isEnabled, false)
        XCTAssertFalse(selection.allEnabled)
        XCTAssertEqual(QuickSwitchFixture.writes(store, of: "enabled_sources", since: start), 1)
        XCTAssertEqual(store.writeLog.count, start + 1)
        XCTAssertEqual(enabledAtPublish.last??.contains("openrussian"), false,
                       "the store is written before the chips publish")

        // Chip → Settings switch.
        start = store.writeLog.count
        selection.setEnabled(false, pair: "eng-spa")
        XCTAssertEqual(vm.dictionaries.map(\.isEnabled), [true, false, false, true, true])
        XCTAssertFalse(vm.binding(for: "eng-spa").wrappedValue)
        XCTAssertEqual(Array(store.writeLog.dropFirst(start)), ["enabled_sources"], "one write for both sources")
        XCTAssertFalse(settings.isEnabled(source: "freedict-eng-spa"))
        XCTAssertFalse(settings.isEnabled(source: "wordnet-spa-eng"))

        // Setting a chip to its current state, or an unknown pair, writes nothing.
        start = store.writeLog.count
        selection.setEnabled(false, pair: "eng-spa")
        selection.setEnabled(true, pair: "custom:ghost")
        XCTAssertEqual(store.writeLog.count, start)

        // A reorder in Settings reorders the chips.
        vm.movePair(from: IndexSet(integer: 0), to: vm.dictionaries.count)
        XCTAssertEqual(selection.pairs.map(\.id), ["eng-rus", "eng-spa", "arb-eng", "ell-eng", "eng"])
        XCTAssertEqual(vm.orderedDictionaries.map(\.id), selection.pairs.map(\.id))
    }

    /// "Only this" stores exactly the pair's sources (Greek: all four), in
    /// one write, and writes nothing when that is already the stored set.
    @MainActor
    func testEnableOnlyKeepsExactlyThePair() async throws {
        let (selection, settings, store, _) = QuickSwitchFixture.makeSelection()
        await selection.load()
        var publishes = 0
        selection.$pairs.dropFirst().sink { _ in publishes += 1 }.store(in: &cancellables)
        let start = store.writeLog.count

        selection.enableOnly(pair: "ell-eng")

        XCTAssertEqual(settings.enabledSources, QuickSwitchFixture.greekSources)
        XCTAssertEqual(selection.pairs.filter(\.isEnabled).map(\.id), ["ell-eng"])
        XCTAssertFalse(selection.allEnabled)
        XCTAssertFalse(selection.noneEnabled)
        XCTAssertEqual(Array(store.writeLog.dropFirst(start)), ["enabled_sources"])
        XCTAssertEqual(publishes, 1)

        selection.enableOnly(pair: "ell-eng")
        selection.enableOnly(pair: "custom:ghost")
        XCTAssertEqual(Array(store.writeLog.dropFirst(start)), ["enabled_sources"], "no write when nothing changes")
        XCTAssertEqual(publishes, 1, "and no publish")

        // The last chip off: none enabled, an explicit empty set.
        selection.setEnabled(false, pair: "ell-eng")
        XCTAssertTrue(selection.noneEnabled)
        XCTAssertEqual(settings.enabledSources, [])

        // From a stored set that is not exactly the pair (another pair on too).
        selection.setEnabled(true, pair: "eng")
        selection.setEnabled(true, pair: "eng-rus")
        selection.enableOnly(pair: "eng-rus")
        XCTAssertEqual(settings.enabledSources, ["openrussian"])
        XCTAssertEqual(selection.pairs.filter(\.isEnabled).map(\.id), ["eng-rus"])
    }

    /// "All" removes `enabled_sources`, as on a fresh install: every pair on,
    /// one write, no write when already absent. An explicit set that holds
    /// every source (what the Settings switches leave) is removed too.
    @MainActor
    func testEnableAllRemovesStoredSet() async throws {
        let (selection, settings, store, _) = QuickSwitchFixture.makeSelection(
            storedEnabled: ["wordnet", "openrussian"])
        await selection.load()
        XCTAssertEqual(selection.pairs.filter(\.isEnabled).map(\.id), ["eng", "eng-rus"], "precondition")
        var start = store.writeLog.count

        selection.enableAll()

        XCTAssertNil(settings.enabledSources)
        XCTAssertFalse(store.keys.contains("enabled_sources"), "the key is absent, not an explicit set")
        XCTAssertTrue(selection.allEnabled)
        XCTAssertEqual(Array(store.writeLog.dropFirst(start)), ["enabled_sources"])

        start = store.writeLog.count
        selection.enableAll()
        XCTAssertEqual(store.writeLog.count, start, "no write when the key is already absent")

        // Pair by pair back to everything on: an explicit full set.
        selection.setEnabled(false, pair: "arb-eng")
        selection.setEnabled(true, pair: "arb-eng")
        XCTAssertEqual(settings.enabledSources, Set(QuickSwitchFixture.sources))
        XCTAssertTrue(selection.allEnabled)
        var publishes = 0
        selection.$pairs.dropFirst().sink { _ in publishes += 1 }.store(in: &cancellables)
        start = store.writeLog.count

        selection.enableAll()
        XCTAssertNil(settings.enabledSources, "stored as 'everything on'")
        XCTAssertEqual(Array(store.writeLog.dropFirst(start)), ["enabled_sources"])
        XCTAssertEqual(publishes, 0, "nothing changes on screen")
    }

    /// An import reloads the selection: its chip is appended, switched on,
    /// with no manual reload; a pair that was off stays off.
    @MainActor
    func testImportReloadAppendsPairOn() async throws {
        let allButRussian = Set(QuickSwitchFixture.sources).subtracting(["openrussian"])
        let (selection, settings, _, localization) = QuickSwitchFixture.makeSelection(storedEnabled: allButRussian)
        await selection.load()
        XCTAssertEqual(selection.pairs.map(\.id), QuickSwitchFixture.pairIDs, "precondition")
        let url = try XCTUnwrap(Bundle.main.url(forResource: "test_import_fixture", withExtension: "json"))
        let manage = ManageDictionariesViewModel(settingsService: settings, localization: localization,
                                                 selection: selection)

        await manage.performImport(url: url)

        XCTAssertEqual(manage.importResult, "Imported 10 entries from test_import_fixture")
        XCTAssertEqual(selection.pairs.map(\.id), QuickSwitchFixture.pairIDs + ["custom:test_import_fixture"],
                       "the import's chip is last")
        XCTAssertEqual(selection.pairs.last?.isEnabled, true)
        XCTAssertEqual(selection.pairs.last?.displayName, "test_import_fixture", "an import shows its source name")
        XCTAssertEqual(selection.pairs.first { $0.id == "eng-rus" }?.isEnabled, false)
        XCTAssertEqual(settings.dictionaryOrder?.last, "test_import_fixture")

        // The chip switches the import off like any other pair.
        selection.setEnabled(false, pair: "custom:test_import_fixture")
        XCTAssertFalse(settings.isEnabled(source: "test_import_fixture"))
        await selection.load()
        XCTAssertEqual(selection.pairs.last?.id, "custom:test_import_fixture", "an import that is off keeps its chip")
        XCTAssertEqual(selection.pairs.last?.isEnabled, false)
    }

    /// A language change re-titles the pairs; ids, order and states stay.
    @MainActor
    func testTitlesFollowLanguageChange() async throws {
        let (selection, _, store, localization) = QuickSwitchFixture.makeSelection()
        await selection.load()
        selection.setEnabled(false, pair: "eng-rus")
        XCTAssertEqual(selection.pairs.first?.displayName, "English")
        let start = store.writeLog.count

        let russian = try XCTUnwrap(localization.supportedLanguages.first { $0.code == "ru" })
        localization.setLanguage(russian)

        XCTAssertEqual(selection.pairs.map(\.displayName),
                       ["Английский", "Русский – Английский", "Испанский – Английский",
                        "Арабский – Английский", "Греческий – Английский"])
        XCTAssertEqual(selection.pairs.map(\.id), QuickSwitchFixture.pairIDs)
        XCTAssertEqual(selection.pairs.map(\.isEnabled), [true, false, true, true, true])
        XCTAssertEqual(store.writeLog.dropFirst(start).filter { $0 != "ui_language" }, [],
                       "re-titling writes no dictionary key")

        let arabic = try XCTUnwrap(localization.supportedLanguages.first { $0.code == "ar" })
        localization.setLanguage(arabic)
        XCTAssertEqual(selection.pairs.first?.displayName, "الإنجليزية")
        XCTAssertEqual(selection.pairs.last?.displayName.unicodeScalars.first, "\u{200F}",
                       "Arabic pair titles read right to left (#119)")
    }

    /// The app wiring: Search and Settings use one shared selection, and a
    /// test's own store never reaches it.
    @MainActor
    func testAppViewModelsShareOneSelection() {
        XCTAssertTrue(DictionarySelection.owning(.shared) === DictionarySelection.shared,
                      "the app's settings own the shared selection")
        XCTAssertTrue(SearchViewModel().selection === DictionarySelection.shared,
                      "Search renders the selection Settings forwards to")

        let ownStore = SettingsService(store: InMemoryKeyValueStore())
        let own = DictionarySelection.owning(ownStore)
        XCTAssertFalse(own === DictionarySelection.shared, "a test's own store gets its own selection")
        XCTAssertFalse(SearchViewModel(settings: ownStore).selection === DictionarySelection.shared)
        XCTAssertFalse(own.isLoaded)
        XCTAssertEqual(own.pairs, [])
        XCTAssertFalse(own.noneEnabled, "no pairs: not 'none enabled', so no hint before the first load")
    }
}

/// The Search side: chip changes re-run the current query, the hint, and
/// preferred mode following the chips.
final class QuickSwitchSearchTests: XCTestCase {
    private var tempDir: URL!
    private var dictionary: TestDictionaryFixture!

    override func setUp() async throws {
        try await super.setUp()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
        dictionary = try await QuickSwitchFixture.open(in: tempDir)
    }

    override func tearDown() async throws {
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    /// Waits until the debounced query has finished.
    @MainActor
    private func waitUntilIdle(_ vm: SearchViewModel, file: StaticString = #filePath, line: UInt = #line) async throws {
        let deadline = Date().addingTimeInterval(5)
        while vm.isSearching, Date() < deadline {
            try await Task.sleep(nanoseconds: 20_000_000)
        }
        XCTAssertFalse(vm.isSearching, "the search did not finish", file: file, line: line)
        XCTAssertNil(vm.errorMessage, file: file, line: line)
    }

    @MainActor
    private func search(_ vm: SearchViewModel, for query: String) async throws {
        vm.query = query
        vm.onQueryChanged()
        try await waitUntilIdle(vm)
    }

    private func sources(_ results: [SearchResult]) -> Set<String> {
        Set(results.map(\.entry.source))
    }

    /// A chip change re-runs the same query at once: new results, no keystroke.
    @MainActor
    func testChipChangeReRunsQuery() async throws {
        let (selection, settings, _, _) = QuickSwitchFixture.makeSelection()
        await selection.load()
        let vm = SearchViewModel(settings: settings, selection: selection)
        try await search(vm, for: "apple")
        XCTAssertEqual(sources(vm.results), Set(QuickSwitchFixture.sources), "precondition: every source")

        selection.setEnabled(false, pair: "eng-rus")
        XCTAssertTrue(vm.isSearching, "the change starts a search at once")
        try await waitUntilIdle(vm)
        XCTAssertEqual(vm.query, "apple", "the query stays")
        XCTAssertFalse(sources(vm.results).contains("openrussian"))
        XCTAssertEqual(sources(vm.results).count, 8)

        // Quick taps fold into one query; the last state wins.
        selection.setEnabled(true, pair: "eng-rus")
        selection.enableOnly(pair: "eng-spa")
        try await waitUntilIdle(vm)
        XCTAssertEqual(sources(vm.results), ["freedict-eng-spa", "wordnet-spa-eng"])

        selection.enableAll()
        try await waitUntilIdle(vm)
        XCTAssertEqual(sources(vm.results), Set(QuickSwitchFixture.sources))

        // A reorder re-runs too (preferred mode reads the order).
        selection.move(from: IndexSet(integer: 0), to: 2)
        XCTAssertTrue(vm.isSearching)
        try await waitUntilIdle(vm)
    }

    /// With an empty field a chip change runs nothing; a title-only change
    /// (language switch) runs nothing either.
    @MainActor
    func testNoRunOnEmptyField() async throws {
        let (selection, settings, _, localization) = QuickSwitchFixture.makeSelection()
        await selection.load()
        let vm = SearchViewModel(settings: settings, selection: selection)

        selection.setEnabled(false, pair: "eng-rus")
        selection.enableOnly(pair: "eng")
        selection.enableAll()
        XCTAssertFalse(vm.isSearching)
        XCTAssertEqual(vm.results, [])

        try await search(vm, for: "apple")
        let spanish = try XCTUnwrap(localization.supportedLanguages.first { $0.code == "es" })
        localization.setLanguage(spanish)
        XCTAssertEqual(selection.pairs.first?.displayName, "Inglés", "precondition: the titles changed")
        XCTAssertFalse(vm.isSearching, "a title-only change re-runs nothing")
    }

    /// Every pair off: the hint shows only while the field holds a query.
    @MainActor
    func testAllOffShowsHintOnlyWithQuery() async throws {
        let (selection, settings, _, _) = QuickSwitchFixture.makeSelection()
        let vm = SearchViewModel(settings: settings, selection: selection)
        vm.query = "apple"
        XCTAssertFalse(vm.showsNoDictionariesHint, "not before the list has loaded")
        await selection.load()
        XCTAssertFalse(vm.showsNoDictionariesHint)

        selection.enableOnly(pair: "eng")
        selection.setEnabled(false, pair: "eng")
        XCTAssertTrue(selection.noneEnabled)
        XCTAssertTrue(vm.showsNoDictionariesHint)
        try await waitUntilIdle(vm)
        XCTAssertEqual(vm.results, [], "and no results")

        vm.query = ""
        XCTAssertFalse(vm.showsNoDictionariesHint, "an empty field keeps Recent words")
        vm.query = "   "
        XCTAssertFalse(vm.showsNoDictionariesHint)

        vm.query = "apple"
        selection.enableAll()
        XCTAssertFalse(vm.showsNoDictionariesHint)
        try await waitUntilIdle(vm)
        XCTAssertFalse(vm.results.isEmpty, "results return")
    }

    /// An import named like an enabled bundled source joins its pair (#105)
    /// and adds no chip; the current query still runs again and finds it.
    @MainActor
    func testImportJoiningAnEnabledPairReRunsQuery() async throws {
        let (selection, settings, _, localization) = QuickSwitchFixture.makeSelection()
        await selection.load()
        let vm = SearchViewModel(settings: settings, selection: selection)
        try await search(vm, for: "qjoinword")
        XCTAssertEqual(vm.results, [], "precondition: not imported yet")

        let file = tempDir.appendingPathComponent("wordnet-spa-eng.json")
        try Data(#"[{"word": "qjoinword", "definition": "a word the import adds"}]"#.utf8).write(to: file)
        let manage = ManageDictionariesViewModel(settingsService: settings, localization: localization,
                                                 selection: selection)
        await manage.performImport(url: file)

        XCTAssertEqual(selection.pairs.map(\.id), QuickSwitchFixture.pairIDs, "the import joins eng-spa, no new chip")
        try await waitUntilIdle(vm)
        XCTAssertEqual(vm.query, "qjoinword", "no keystroke")
        XCTAssertEqual(vm.results.map { EntryKey($0.entry) }, [EntryKey(source: "wordnet-spa-eng", word: "qjoinword")],
                       "the query ran again and finds the imported row")
    }

    /// Preferred mode: the chips decide which pairs get a bucket, Dictionary
    /// Order decides the bucket order.
    @MainActor
    func testPreferredModeFollowsChips() async throws {
        let order = DictAppTests.greekSourceIDs + ["openrussian", "wordnet", "freedict-eng-spa",
                                                   "wordnet-spa-eng", "wordnet-arb-eng"]
        let (selection, settings, _, _) = QuickSwitchFixture.makeSelection(storedOrder: order)
        settings.resultSortMode = .preferredDictionary
        await selection.load()
        let vm = SearchViewModel(settings: settings, selection: selection)

        selection.enableOnly(pair: "ell-eng")
        try await search(vm, for: "apple")
        XCTAssertFalse(vm.results.isEmpty)
        XCTAssertTrue(sources(vm.results).isSubset(of: QuickSwitchFixture.greekSources),
                      "only Greek sources; got \(sources(vm.results))")

        selection.setEnabled(true, pair: "eng-rus")
        try await waitUntilIdle(vm)
        let resultSources = vm.results.map(\.entry.source)
        XCTAssertEqual(Set(resultSources), QuickSwitchFixture.greekSources.union(["openrussian"]))
        let firstRussian = try XCTUnwrap(resultSources.firstIndex(of: "openrussian"))
        XCTAssertTrue(resultSources[..<firstRussian].allSatisfy(QuickSwitchFixture.greekSources.contains),
                      "the Greek bucket comes first, as in Dictionary Order; got \(resultSources)")

        // "All" removes the stored set; preferred mode then uses every ordered source.
        selection.enableAll()
        try await waitUntilIdle(vm)
        XCTAssertNil(settings.enabledSources)
        XCTAssertEqual(sources(vm.results), Set(QuickSwitchFixture.sources))
        XCTAssertTrue(QuickSwitchFixture.greekSources.contains(try XCTUnwrap(vm.results.first?.entry.source)))
    }

    /// The chips filter Search only (0129): with every pair off, Recent words
    /// and History still list a word read in Russian, no hint shows with an
    /// empty field, and the stored source still opens.
    @MainActor
    func testRecentWordsAndHistoryIgnoreTheChips() async throws {
        try await DatabaseService.shared.addToHistory(word: "яблоко", source: "openrussian")
        let (selection, settings, _, _) = QuickSwitchFixture.makeSelection()
        await selection.load()
        let vm = SearchViewModel(settings: settings, selection: selection)
        selection.enableOnly(pair: "eng")
        selection.setEnabled(false, pair: "eng")
        XCTAssertTrue(selection.noneEnabled, "precondition: every chip off")
        XCTAssertEqual(settings.enabledSources, [])

        await vm.loadRecent()

        XCTAssertEqual(vm.recentWords.map(\.word), ["яблоко"], "Recent words are not filtered")
        XCTAssertEqual(vm.recentWords.first?.source, "openrussian")
        XCTAssertFalse(vm.showsNoDictionariesHint, "an empty field keeps Recent words and shows no hint")
        let history = try await DatabaseService.shared.fetchHistory()
        XCTAssertEqual(history.map(\.word), ["яблоко"], "History is not filtered")
        let entry = try await DatabaseService.shared.entry(for: EntryKey(source: "openrussian", word: "яблоко"))
        XCTAssertEqual(entry?.definition, "apple", "a Recent word opens its stored source while that source is off")

        // The same word typed as a query finds nothing and shows the hint.
        try await search(vm, for: "яблоко")
        XCTAssertEqual(vm.results, [])
        XCTAssertTrue(vm.showsNoDictionariesHint)
    }
}

// MARK: - Issue #151: word lists, the data model (0130-word-lists.md)

/// Dictionary files with word lists for unit tests: `TestDictionary.make`,
/// whose schema (the bundle's) has the list tables since #240, or else
/// `Scripts/wordlists_schema.sql`, read through `#filePath`, so the DDL
/// exists once (0130, "List data").
enum WordListFixture {
    struct List {
        var id: String
        var lang: String
        var series: String
        var level: String
        var levelOrd: Int
    }

    /// A word of a built-in series (`series`) or an imported list.
    struct Item {
        var series = ""
        var term: String
        var headword: String?
        var translation = ""
        var level = ""
        var levelOrd = 0
        var rank: Int?
        var seq: Int
    }

    static var schemaURL: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()  // DictAppTests
            .deletingLastPathComponent()  // DictApp
            .deletingLastPathComponent()  // the repository
            .appendingPathComponent("Scripts/wordlists_schema.sql")
    }

    /// Writes a dictionary file at `url` with `rows`, `metadata`, `lists`
    /// (each `word_count` its items) and `items`.
    @discardableResult
    static func make(rows: [TestDictionary.Row], metadata: [TestDictionary.Metadata] = [], lists: [List],
                     items: [Item], at url: URL) throws -> URL {
        try TestDictionary.make(rows: rows, metadata: metadata, at: url)
        let schema = try String(contentsOf: schemaURL, encoding: .utf8)
        let queue = try DatabaseQueue(path: url.path)
        try queue.write { db in
            if try !db.tableExists("wordlist") { try db.execute(sql: schema) }
            for list in lists {
                let count = items.filter { $0.series == list.series && $0.levelOrd == list.levelOrd }.count
                try db.execute(sql: """
                    INSERT INTO wordlist(id, lang, series, level, level_ord, word_count, data_source)
                    VALUES (?, ?, ?, ?, ?, ?, 'test')
                    """, arguments: [list.id, list.lang, list.series, list.level, list.levelOrd, count])
            }
            for item in items {
                try db.execute(sql: """
                    INSERT INTO wordlist_item(series, term, headword, translation, level, level_ord, rank, seq, sort_key)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """, arguments: [item.series, item.term, item.headword, item.translation, item.level,
                                     item.levelOrd, item.rank, item.seq, WordListItem.sortKey(of: item.term)])
            }
        }
        return url
    }

    /// Saves an imported list into the shared service's user database, as
    /// #155's save will.
    static func saveUserList(_ id: String, title: String, lang: String, createdAt: String, items: [Item]) async throws {
        try await DatabaseService.shared.writeForTesting { db in
            try db.execute(sql: "INSERT INTO user_list(id, title, lang, origin, created_at) VALUES (?, ?, ?, 'file', ?)",
                           arguments: [id, title, lang, createdAt])
            for item in items {
                try db.execute(sql: """
                    INSERT INTO user_list_item(list_id, term, headword, translation, level, level_ord, rank, seq, sort_key)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """, arguments: [id, item.term, item.headword, item.translation, item.level, item.levelOrd,
                                     item.rank, item.seq, WordListItem.sortKey(of: item.term)])
            }
        }
    }

    /// Adds a My words row with its date.
    static func addMyWord(source: String, word: String, addedAt: String) async throws {
        try await DatabaseService.shared.writeForTesting { db in
            try db.execute(sql: "INSERT INTO my_words(source, word, added_at) VALUES (?, ?, ?)",
                           arguments: [source, word, addedAt])
        }
    }
}

/// `ListLinking` on made-up data (0130, "Linking a word to the
/// dictionaries"): every rule and its order.
final class ListLinkingTests: XCTestCase {
    /// Linking against `headwords` and the form table `forms` (a spelling →
    /// its lemmas, in order).
    private func link(_ term: String, lang: String = "ell", headwords: [String],
                      forms: [String: [String]] = [:]) throws -> ListLinking.Link? {
        let lookup = ListLinking.Lookup(
            headwords: { spelling in
                headwords.filter { WordKey(lang: "", word: $0).word == WordKey(lang: "", word: spelling).word }
            },
            nearCandidates: { spelling in headwords.filter { Search.foldGreek($0) == Search.foldGreek(spelling) } },
            formLemmas: { spelling in forms[spelling] ?? [] })
        return try ListLinking.link(term, lang: lang, lookup: lookup)
    }

    func testExactMatchFoldsOnlyAToZ() throws {
        XCTAssertEqual(try link("σπίτι", headwords: ["σπίτι"]), .init(headword: "σπίτι", rule: .exact))
        XCTAssertEqual(try link("House", lang: "eng", headwords: ["house"]), .init(headword: "house", rule: .exact))
        XCTAssertEqual(try link("house", lang: "eng", headwords: ["House", "house"]), .init(headword: "house", rule: .exact),
                       "the spelling of the term wins among NOCASE twins")
    }

    func testCleanedVariants() {
        XCTAssertEqual(ListLinking.cleanedVariants(of: "Ευχαριστώ!"), ["Ευχαριστώ"])
        XCTAssertEqual(ListLinking.cleanedVariants(of: "Τι κάνεις;"), ["Τι κάνεις"])
        XCTAssertEqual(ListLinking.cleanedVariants(of: "(Σαουδική) Αραβία"), ["Αραβία", "Σαουδική Αραβία"])
        XCTAssertEqual(ListLinking.cleanedVariants(of: "«ναι»"), ["ναι"])
        XCTAssertEqual(ListLinking.cleanedVariants(of: "\u{201C}yes!\u{201D}"), ["yes"])
        XCTAssertEqual(ListLinking.cleanedVariants(of: "'yes'"), ["yes"])
        XCTAssertEqual(ListLinking.cleanedVariants(of: "σ'"), [], "an apostrophe of elision stays")
        XCTAssertEqual(ListLinking.cleanedVariants(of: "σπίτι"), [])
    }

    func testCleanedVariantsLinkInOrder() throws {
        XCTAssertEqual(try link("(Σαουδική) Αραβία", headwords: ["Αραβία", "Σαουδική Αραβία"]),
                       .init(headword: "Αραβία", rule: .cleaned))
        XCTAssertEqual(try link("(Σαουδική) Αραβία", headwords: ["Σαουδική Αραβία"]),
                       .init(headword: "Σαουδική Αραβία", rule: .cleaned))
        XCTAssertEqual(try link("«ναι»", headwords: ["ναι"]), .init(headword: "ναι", rule: .cleaned))
    }

    func testNearIgnoresCaseAndDiaeresis() throws {
        XCTAssertEqual(try link("Ευχαριστώ!", headwords: ["ευχαριστώ"]), .init(headword: "ευχαριστώ", rule: .near))
        XCTAssertEqual(try link("Μάϊος", headwords: ["Μάιος"]), .init(headword: "Μάιος", rule: .near))
        XCTAssertEqual(try link("Καλή όρεξη!", headwords: ["καλή όρεξη"]), .init(headword: "καλή όρεξη", rule: .near))
    }

    func testAccentFoldedMatchNeverLinks() throws {
        XCTAssertNil(try link("νομός", headwords: ["νόμος"]), "prefecture is not law")
        XCTAssertNil(try link("μονός", headwords: ["μόνος"]))
    }

    func testSeveralNearHeadwordsTakeTheLowercasedOne() throws {
        XCTAssertEqual(try link("Ελιά", headwords: ["ελιά", "ΕΛΙΑ"]), .init(headword: "ελιά", rule: .near))
        XCTAssertNil(try link("ΕΛΙΑ", headwords: ["ελιά", "έλια"]), "two near headwords, neither the lowercased term")
    }

    func testFormsOfOneWordOnly() throws {
        XCTAssertEqual(try link("λίγοι", headwords: ["λίγος"], forms: ["λίγοι": ["λίγος"]]),
                       .init(headword: "λίγος", rule: .form))
        XCTAssertEqual(try link("σπουδές", headwords: ["σπουδή"], forms: ["σπουδές": ["σπουδάζω", "σπουδή"]]),
                       .init(headword: "σπουδή", rule: .form), "one of the lemmas is a headword")
        XCTAssertNil(try link("αυτοί", headwords: ["αυτός", "του"], forms: ["αυτοί": ["αυτός", "του"]]),
                     "Greek: a form of two headwords links nowhere")
        XCTAssertNil(try link("λίγοι φίλοι", headwords: ["λίγος"], forms: ["λίγοι φίλοι": ["λίγος"]]),
                     "several words take no form")
        XCTAssertEqual(try link("went", lang: "eng", headwords: ["go"], forms: ["went": ["go"]]),
                       .init(headword: "go", rule: .form))
        XCTAssertEqual(try link("xs", lang: "eng", headwords: ["noun-base", "verb-base"],
                                forms: ["xs": ["verb-base", "noun-base"]]),
                       .init(headword: "verb-base", rule: .form), "English: the first base in Morphy's order")
        XCTAssertEqual(try link("xs", lang: "eng", headwords: ["noun-base"], forms: ["xs": ["verb-base", "noun-base"]]),
                       .init(headword: "noun-base", rule: .form), "English: the first base that is a headword")
    }

    func testRulesInOrder() throws {
        XCTAssertEqual(try link("went", lang: "eng", headwords: ["went", "go"], forms: ["went": ["go"]]),
                       .init(headword: "went", rule: .exact), "exact before form")
        XCTAssertEqual(try link("Ευχαριστώ!", headwords: ["Ευχαριστώ", "ευχαριστώ"]),
                       .init(headword: "Ευχαριστώ", rule: .cleaned), "cleaned before near")
        XCTAssertEqual(try link("Λίγοι", headwords: ["λίγοι", "λίγος"], forms: ["Λίγοι": ["λίγος"]]),
                       .init(headword: "λίγοι", rule: .near), "near before form")
    }

    func testOtherLanguagesLinkOnlyExactOrCleaned() throws {
        XCTAssertNil(try link("casas", lang: "spa", headwords: ["casa"], forms: ["casas": ["casa"]]))
        XCTAssertNil(try link("Ευχαριστώ", lang: "eng", headwords: ["ευχαριστώ"]), "near is Greek only")
        XCTAssertEqual(try link("¿casa?", lang: "spa", headwords: ["¿casa"]), .init(headword: "¿casa", rule: .cleaned))
        XCTAssertNil(try link("έχει αέρα", headwords: ["έχω", "αέρας"]), "a standalone word")
    }

    func testSortKey() {
        XCTAssertEqual(WordListItem.sortKey(of: "(ένα) σωρό"), "σωρο", "parentheses go, Greek folds")
        XCTAssertEqual(WordListItem.sortKey(of: "Άγγλος"), "αγγλοσ")
        XCTAssertEqual(WordListItem.sortKey(of: "a.m."), "am")
        XCTAssertEqual(WordListItem.sortKey(of: "Ice  Cream"), "ice cream")
    }

    /// Every script sorts without its diacritics (0130, "List data"):
    /// `árbol` with `arbol`, as `build_wordlists.py` writes it.
    func testSortKeyDropsDiacriticsInEveryScript() {
        XCTAssertEqual(WordListItem.sortKey(of: "Árbol"), "arbol")
        XCTAssertEqual(WordListItem.sortKey(of: "árbol"), WordListItem.sortKey(of: "arbol"))
        XCTAssertEqual(WordListItem.sortKey(of: "Ñandú"), "nandu")
        XCTAssertEqual(WordListItem.sortKey(of: "café crème"), "cafe creme")
        XCTAssertEqual(WordListItem.sortKey(of: "Ёлка"), "елка")
        XCTAssertEqual(WordListItem.sortKey(of: "Ταΐζω"), "ταιζω", "Greek still folds as Search.foldGreek")
        let sorted = ["azul", "árbol", "abeja"].sorted { WordListItem.sortKey(of: $0) < WordListItem.sortKey(of: $1) }
        XCTAssertEqual(sorted, ["abeja", "árbol", "azul"])
    }

    func testWordKeyLowercasesOnlyAToZ() {
        XCTAssertEqual(WordKey(lang: "eng", word: "House"), WordKey(lang: "eng", word: "house"))
        XCTAssertEqual(WordKey(lang: "ell", word: "Σπίτι").word, "Σπίτι", "SQLite's lower() and NOCASE fold A–Z only")
        XCTAssertNotEqual(WordKey(lang: "ell", word: "σπίτι"), WordKey(lang: "und", word: "σπίτι"))
    }
}

/// `LearningOrder` (0130, "Order of new words"): pure, on made-up words.
final class LearningOrderTests: XCTestCase {
    private func word(_ term: String, list: WordListID = "ky-ell-a1", lang: String = "ell", level: Int = 1,
                      rank: Int? = nil, seq: Int = 0) -> WordListItem {
        WordListItem(listID: list, key: WordKey(lang: lang, word: term), term: term, headword: nil, translation: "",
                     endings: "", partOfSpeech: "", tags: "", level: level == 0 ? "" : "L\(level)", levelOrder: level,
                     rank: rank, seq: seq, sortKey: WordListItem.sortKey(of: term))
    }

    /// `count` words `<prefix>000`… in alphabetical (list) order, ranked by
    /// a permutation unrelated to the alphabet, or unranked.
    private func words(_ count: Int, prefix: String = "w", list: WordListID = "ky-ell-a1", level: Int = 1,
                       ranked: Bool = true) -> [WordListItem] {
        (0..<count).map { i in
            word(prefix + String(format: "%03d", i), list: list, level: level,
                 rank: ranked ? (i * 37) % count + 1 : nil, seq: i)
        }
    }

    /// The pairs where a word is followed by the next word of its level in
    /// alphabetical order, except into a last run of one word.
    static func neighbourPairs(_ items: [WordListItem]) -> [String] {
        var pairs: [String] = []
        for level in Set(items.map(\.levelOrder)) {
            let words = items.filter { $0.levelOrder == level }
            let sorted = words.sorted { ($0.sortKey, $0.term) < ($1.sortKey, $1.term) }
            var position: [WordKey: Int] = [:]
            for (index, word) in sorted.enumerated() { position[word.key] = index }
            for i in 0..<max(0, words.count - 1) {
                let last = words.count - 1
                let intoLastSingleRun: Bool = i + 1 == last && last % LearningOrder.window == 0
                let current: Int = position[words[i].key] ?? -2
                let following: Int = position[words[i + 1].key] ?? -2
                if current + 1 == following && !intoLastSingleRun {
                    pairs.append("\(words[i].term) → \(words[i + 1].term)")
                }
            }
        }
        return pairs
    }

    /// Kendall's tau between the places of `terms` and their alphabetical order.
    private func kendallTau(_ terms: [String]) -> Double {
        let alphabetical = terms.sorted()
        let ranks = terms.map { alphabetical.firstIndex(of: $0)! }
        var score = 0
        for i in ranks.indices {
            for j in (i + 1)..<ranks.count { score += ranks[i] < ranks[j] ? 1 : -1 }
        }
        return Double(score) / Double(ranks.count * (ranks.count - 1) / 2)
    }

    func testSeedHashAndGeneratorAreFixed() {
        XCTAssertEqual(LearningOrder.fnv1a64(""), 0xcbf2_9ce4_8422_2325)
        XCTAssertEqual(LearningOrder.fnv1a64("a"), 0xaf63_dc4c_8601_ec8c)
        var generator = LearningOrder.SplitMix64(seed: 0)
        XCTAssertEqual(generator.next(), 0xe220_a839_7b1d_cdaf)
    }

    func testFrequencyKeepsTopTenInFirstTen() {
        let level = words(100)
        for seed in 0..<50 as Range<UInt64> {
            let order = LearningOrder.arrange(level, order: .frequency, seed: seed)
            XCTAssertEqual(order.count, 100)
            XCTAssertEqual(Set(order.prefix(10).compactMap(\.rank)), Set(1...10), "seed \(seed)")
            XCTAssertEqual(Set(order.prefix(20).compactMap(\.rank)), Set(1...20), "seed \(seed)")
        }
    }

    func testUnrankedFollowRankedInListOrder() {
        let level = words(20, prefix: "u", ranked: false) + words(20, prefix: "r")
        let order = LearningOrder.arrange(level, order: .frequency, seed: 7)
        XCTAssertTrue(order.prefix(20).allSatisfy { $0.rank != nil }, "ranked words first")
        XCTAssertEqual(Set(order[20..<30].map(\.term)), Set(level.prefix(10).map(\.term)),
                       "unranked words in their list's order, shuffled within each run of 10")
        XCTAssertEqual(Set(order[30..<40].map(\.term)), Set(level[10..<20].map(\.term)))
    }

    func testLevelsInOrder() {
        let items = words(15, prefix: "b", list: "ky-ell-a2", level: 2) + words(15, prefix: "n", level: 0)
            + words(15, prefix: "a", level: 1)
        for order in NewWordOrder.allCases {
            let levels = LearningOrder.arrange(items, order: order, seed: 3).map(\.levelOrder)
            XCTAssertEqual(levels, Array(repeating: 1, count: 15) + Array(repeating: 2, count: 15)
                           + Array(repeating: 0, count: 15), "\(order): A1, then A2, then words without a level")
        }
    }

    func testRandomShufflesWithinLevel() {
        let items = words(40, prefix: "a") + words(40, prefix: "b", level: 2)
        let random = LearningOrder.arrange(items, order: .random, seed: 11)
        let frequency = LearningOrder.arrange(items, order: .frequency, seed: 11)
        XCTAssertEqual(Set(random.prefix(40).map(\.term)), Set(items.prefix(40).map(\.term)), "A1 still first")
        XCTAssertNotEqual(random.map(\.term), frequency.map(\.term))
        XCTAssertNotEqual(Set(random.prefix(10).compactMap(\.rank)), Set(1...10), "random ignores frequency")
    }

    func testSameSeedSameOrder() {
        let items = words(60) + words(30, prefix: "z", ranked: false)
        XCTAssertEqual(LearningOrder.arrange(items, order: .frequency, seed: 42),
                       LearningOrder.arrange(items, order: .frequency, seed: 42))
        XCTAssertEqual(LearningOrder.arrange(items, order: .random, seed: 42),
                       LearningOrder.arrange(items, order: .random, seed: 42))
    }

    func testSeedDiffersPerSetAndInstall() {
        let a1: [WordListID] = ["ky-ell-a1"]
        let base = LearningOrder.seed(installSeed: 1, lists: a1, order: .frequency)
        XCTAssertNotEqual(base, LearningOrder.seed(installSeed: 2, lists: a1, order: .frequency))
        XCTAssertNotEqual(base, LearningOrder.seed(installSeed: 1, lists: a1 + ["ky-ell-a2"], order: .frequency))
        XCTAssertNotEqual(base, LearningOrder.seed(installSeed: 1, lists: a1, order: .random))
        XCTAssertEqual(LearningOrder.seed(installSeed: 1, lists: ["ky-ell-a2", "ky-ell-a1"], order: .frequency),
                       LearningOrder.seed(installSeed: 1, lists: ["ky-ell-a1", "ky-ell-a2"], order: .frequency),
                       "the ids are sorted")
        let items = words(100)
        XCTAssertNotEqual(LearningOrder.arrange(items, order: .frequency, seed: base).map(\.term),
                          LearningOrder.arrange(items, order: .frequency,
                                                seed: LearningOrder.seed(installSeed: 2, lists: a1, order: .frequency)).map(\.term))
    }

    /// With A, X, B, where B follows A alphabetically, and X excluded, A and
    /// B are not side by side; the other places keep their order.
    func testExcludedKeysDropOut() {
        let a = word("alpha"), x = word("zeta"), b = word("beta")
        XCTAssertEqual(LearningOrder.separateNeighbours([a, x, b]).map(\.term), ["alpha", "zeta", "beta"],
                       "nothing to separate before")
        XCTAssertEqual(LearningOrder.separateNeighbours([a, b]).map(\.term), ["beta", "alpha"])
        let items = words(40)
        let arranged = LearningOrder.arrange(items, order: .frequency, seed: 5)
        let excluded = Set(arranged.enumerated().filter { $0.offset % 3 == 1 }.map(\.element.key))
        let rest = LearningOrder.separateNeighbours(arranged.filter { !excluded.contains($0.key) })
        XCTAssertEqual(Set(rest.map(\.key)), Set(items.map(\.key)).subtracting(excluded))
        XCTAssertEqual(Self.neighbourPairs(rest), [])
    }

    func testNoAlphabeticalRun() {
        let order = LearningOrder.arrange(words(300), order: .frequency, seed: 9)
        XCTAssertLessThan(abs(kendallTau(order.prefix(100).map(\.term))), 0.2)
    }

    func testNoWordFollowedByItsAlphabeticalNeighbour() {
        // A level of unranked words in alphabetical list order (51 words: a
        // last run of one word), then a ranked level.
        let items = words(51, prefix: "a", ranked: false) + words(100, prefix: "b", level: 2)
        for seed in 0..<50 as Range<UInt64> {
            let order = LearningOrder.arrange(items, order: .frequency, seed: seed)
            XCTAssertEqual(Self.neighbourPairs(order), [], "seed \(seed)")
            let ranked = order.filter { $0.levelOrder == 2 }
            XCTAssertEqual(Set(ranked.prefix(10).compactMap(\.rank)), Set(1...10), "seed \(seed)")
            XCTAssertEqual(Set(ranked.prefix(20).compactMap(\.rank)), Set(1...20), "seed \(seed)")
            XCTAssertEqual(Set(order.prefix(10).map(\.seq)), Set(0..<10), "unranked: each run of 10 keeps its words")
        }
    }

    /// Greek A2, a Greek import with A1 and "Lesson 1" (7) levels, and a
    /// Greek import without levels: every A1 word before every A2 word, then
    /// "Lesson 1", then the words without a level.
    func testCheckedListsInLevelOrder() {
        let a2 = words(12, prefix: "c", list: "ky-ell-a2", level: 2)
        let imported = words(12, prefix: "a", list: "user-1", level: 1) + words(12, prefix: "l", list: "user-1", level: 7)
        let unlevelled = words(12, prefix: "n", list: "user-2", level: 0, ranked: false)
        let order = LearningOrder.arrange(a2 + imported + unlevelled, order: .frequency, seed: 1)
        XCTAssertEqual(order.map(\.levelOrder), Array(repeating: 1, count: 12) + Array(repeating: 2, count: 12)
                       + Array(repeating: 7, count: 12) + Array(repeating: 0, count: 12))
        XCTAssertEqual(Set(order.prefix(10).compactMap(\.rank)), Set(1...10), "frequency within the level")
        XCTAssertEqual(Set(order.prefix(12).map(\.listID)), ["user-1"], "the import's A1 words lead")
        XCTAssertEqual(Set(order[12..<22].compactMap(\.rank)), Set(1...10), "Greek A2 by frequency too")
        XCTAssertEqual(Set(order[24..<34].compactMap(\.rank)), Set(1...10), "Lesson 1 by frequency too")
        XCTAssertEqual(Set(order[36..<46].map(\.term)), Set(unlevelled.prefix(10).map(\.term)),
                       "unranked words in list order, shuffled only within their run of 10")
        XCTAssertEqual(Self.neighbourPairs(order), [])
    }

    func testWordInTwoListsComesOnce() {
        let inA2 = word("σπίτι", list: "ky-ell-a2", level: 2, rank: 5)
        let inImport = word("σπίτι", list: "user-1", level: 1, rank: 5)
        let unlevelled = word("σπίτι", list: "user-2", level: 0)
        let order = LearningOrder.arrange([inA2, word("νερό", list: "ky-ell-a2", level: 2), unlevelled, inImport],
                                          order: .frequency, seed: 1)
        XCTAssertEqual(order.filter { $0.term == "σπίτι" }.count, 1)
        XCTAssertEqual(order.first?.listID, "user-1", "at its lowest level, from that list")
        XCTAssertEqual(order.first?.levelOrder, 1)
    }
}

/// The model and queries on test dictionaries and the user database
/// (0130, "Swift" and "User database").
@MainActor
final class WordListModelTests: XCTestCase {
    private var tempDir: URL!
    private var db: DatabaseService { .shared }
    private var userPath: String { tempDir.appendingPathComponent("user.sqlite").path }

    private static let metadata: [TestDictionary.Metadata] = [
        .init(source: "wordnet", displayName: "WordNet", fromLang: "eng", toLang: "eng"),
        .init(source: "freedict-eng-spa", displayName: "En–Es", fromLang: "eng", toLang: "spa"),
        .init(source: "freedict-ell-eng", displayName: "El–En FD", fromLang: "ell", toLang: "eng"),
        .init(source: "wordnet-ell-eng", displayName: "El–En WN", fromLang: "ell", toLang: "eng"),
    ]

    private static let rows: [TestDictionary.Row] = [
        .init(word: "house", definition: "a building", source: "wordnet"),
        .init(word: "house", definition: "casa", source: "freedict-eng-spa"),
        .init(word: "Dog", definition: "perro", source: "freedict-eng-spa"),
        .init(word: "dog", definition: "a canine", source: "wordnet"),
        .init(word: "σπίτι", normalized: "σπιτι", definition: "house", source: "freedict-ell-eng"),
        .init(word: "σπίτι", normalized: "σπιτι", definition: "home", source: "wordnet-ell-eng"),
        .init(word: "γράφω", normalized: "γραφω", definition: "write", source: "freedict-ell-eng"),
        .init(word: "γράφω", normalized: "γραφω", definition: "write", source: "wordnet-ell-eng"),
    ]

    private static let lists: [WordListFixture.List] = [
        .init(id: "ky-ell-a1", lang: "ell", series: "ky-ell", level: "A1", levelOrd: 1),
        .init(id: "ky-ell-a2", lang: "ell", series: "ky-ell", level: "A2", levelOrd: 2),
        .init(id: "cefr-eng-c2", lang: "eng", series: "cefr-eng", level: "C2", levelOrd: 6),
    ]

    /// Greek A1 and A2 of one series, 12 words each with a few ranked, and English C2.
    private static let items: [WordListFixture.Item] = {
        var items: [WordListFixture.Item] = [
            .init(series: "ky-ell", term: "σπίτι", headword: "σπίτι", translation: "house", level: "A1", levelOrd: 1,
                  rank: 3, seq: 0),
            .init(series: "ky-ell", term: "έχει αέρα", translation: "it is windy", level: "A1", levelOrd: 1, seq: 1),
            .init(series: "cefr-eng", term: "house", headword: "house", level: "C2", levelOrd: 6, rank: 1, seq: 0),
            .init(series: "cefr-eng", term: "sesquipedalian", level: "C2", levelOrd: 6, seq: 1),
        ]
        for i in 0..<10 {
            items.append(.init(series: "ky-ell", term: "αλφα\(i)", level: "A1", levelOrd: 1, rank: 10 + i, seq: 2 + i))
            items.append(.init(series: "ky-ell", term: "βήτα\(i)", level: "A2", levelOrd: 2, rank: i % 2 == 0 ? 5 + i : nil,
                               seq: 12 + i))
        }
        return items
    }()

    override func setUp() async throws {
        try await super.setUp()
        await DictAppTests.waitForHostAppLaunch()
        tempDir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        try FileManager.default.createDirectory(at: tempDir, withIntermediateDirectories: true)
    }

    override func tearDown() async throws {
        try? FileManager.default.removeItem(at: tempDir)
        try await super.tearDown()
    }

    /// Opens the service on the test dictionary with the lists.
    private func open() async throws {
        let url = try WordListFixture.make(rows: Self.rows, metadata: Self.metadata, lists: Self.lists, items: Self.items,
                                           at: tempDir.appendingPathComponent("dictionary.sqlite"))
        try await db.setup(userPath: userPath, dictionaryURL: url)
    }

    /// #151: built-in and user lists share one model and one query API.
    func testOneModelForEveryKind() async throws {
        try await open()
        try await WordListFixture.addMyWord(source: "freedict-ell-eng", word: "σπίτι", addedAt: "2026-11-01 10:00:00")
        try await WordListFixture.addMyWord(source: "wordnet", word: "house", addedAt: "2026-11-02 10:00:00")
        try await WordListFixture.saveUserList("user-1", title: "Greek lesson 1", lang: "ell", createdAt: "2026-11-03 10:00:00",
                                               items: [.init(term: "νερό", translation: "water", level: "A1", levelOrd: 1, seq: 0),
                                                       .init(term: "σπίτι", headword: "σπίτι", seq: 1)])

        let lists = try await db.wordLists()
        XCTAssertEqual(lists.map(\.id), ["ky-ell-a1", "ky-ell-a2", "cefr-eng-c2", "my-words", "user-1"])
        XCTAssertEqual(lists.map(\.kind), [.builtIn, .builtIn, .builtIn, .myWords, .user])
        XCTAssertEqual(lists.map(\.count), [12, 10, 2, 2, 2])
        XCTAssertEqual(lists.map(\.lang), ["ell", "ell", "eng", WordList.myWordsLanguage, "ell"])
        XCTAssertEqual(lists.map(\.level), ["A1", "A2", "C2", "", ""])
        XCTAssertEqual(lists.last?.title, "Greek lesson 1")

        let a1 = try await db.wordListItems("ky-ell-a1")
        XCTAssertEqual(a1.count, 12)
        XCTAssertEqual(a1.first?.term, "αλφα0", "alphabetical by sort key")
        let windy = try XCTUnwrap(a1.first { $0.term == "έχει αέρα" })
        XCTAssertNil(windy.headword)
        XCTAssertEqual(windy.translation, "it is windy", "an unmatched word keeps its translation")
        XCTAssertEqual(windy.key, WordKey(lang: "ell", word: "έχει αέρα"))
        XCTAssertEqual(Set(a1.map(\.listID)), ["ky-ell-a1"])

        let imported = try await db.wordListItems("user-1")
        XCTAssertEqual(imported.map(\.term), ["νερό", "σπίτι"])
        XCTAssertEqual(imported.map(\.levelOrder), [1, 0])
        XCTAssertEqual(imported.first?.key, WordKey(lang: "ell", word: "νερό"))

        let myWords = try await db.wordListItems(.myWords)
        XCTAssertEqual(myWords.map(\.term), ["house", "σπίτι"], "newest first")
        XCTAssertEqual(myWords.map(\.key), [WordKey(lang: "eng", word: "house"), WordKey(lang: "ell", word: "σπίτι")])
        XCTAssertEqual(myWords.map(\.headword), ["house", "σπίτι"])

        let unknown = try await db.wordListItems("ky-ell-z9")
        XCTAssertEqual(unknown, [])
    }

